window.__HRC_SHARD({"shard":"ffm-sudan","builtAt":"2026-10-23T22:07:26+00:00","documents":[{"rec_id":"recMNz9d8dOUBoYFy","doc_id":"FFM Sudan - Unofficial Annex - 23.10.2024","symbol":"A/HRC/57/CRP.6","title":"Findings of the investigations conducted by the Independent\nInternational Fact-Finding Mission for the Sudan into\nviolations of international human rights law and international\nhumanitarian law, and related crimes, committed in the Sudan\nin the context of the conflict that erupted in mid-April 2023","type":"Unofficial Annex","date":"2024-10-23","year":2024,"bodies":["FFM Sudan"],"paragraphCount":348,"unnumbered":false,"gaps":[],"misprints":[{"n":221,"printed":"224"}],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/FFM Sudan - 23-10-2024 - CRP - A_HRC_57_CRP.6 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recLRvyVbuv1l48E2","doc_id":"FFM Sudan - Official report - 07.11.2024","symbol":"A/HRC/57/23","title":"Report of the independent international fact-finding mission\nfor the Sudan","type":"Official report","date":"2024-11-07","year":2024,"bodies":["FFM Sudan"],"paragraphCount":123,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Sudan - 07-11-2024 - Official document - A_HRC_57_23 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recB6EAjiAHMbgWF7","doc_id":"FFM Sudan - Official report - 05.09.2025","symbol":"A/HRC/60/22","title":"Sudan: A War of Atrocities","type":"Official report","date":"2025-09-05","year":2025,"bodies":["FFM Sudan"],"paragraphCount":136,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Sudan - 05-09-2025 - Official report - A_HRC_60_22 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recBDiuLvlb1i3NNY","doc_id":"FFM Sudan - Unofficial Annex - 24.10.2025","symbol":"A/HRC/60/CRP.7","title":"Paths to justice: accountability for atrocities in the Sudan","type":"Unofficial Annex","date":"2025-10-24","year":2025,"bodies":["FFM Sudan"],"paragraphCount":71,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/FFM Sudan - 24-10-2025 - CRP - A_HRC_60_CRP.7 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recHPTNMHsLNQ2vIp","doc_id":"FFM Sudan - Official report - 10.03.2026","symbol":"A/HRC/61/77","title":"Report of the independent international fact-finding mission for the Sudan","type":"Official report","date":"2026-03-10","year":2026,"bodies":["FFM Sudan"],"paragraphCount":128,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Sudan - 10-03-2026 - Official report - A_HRC_61_77 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recXQq4WYpTlyv0k3","doc_id":"FFM Sudan - Unofficial Annex - 08.07.2026","symbol":"A/HRC/62/CRP.4","title":"Information supplementing the report \"Sudan: hallmarks of genocide in El Fasher\"","type":"Unofficial Annex","date":"2026-07-08","year":2026,"bodies":["FFM Sudan"],"paragraphCount":119,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/FFM Sudan - 08-07-2026 - CRP - A_HRC_62_CRP.4 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recBkIQQWg1W4lclp","doc_id":"FFM Sudan - Official report - 01.09.2026","symbol":"A/HRC/63/23","title":"Fuelling Sudan's conflict: weapons, fighters and external support networks — Report of the independent international fact-finding mission for the Sudan","type":"Official report","date":"2026-09-01","year":2026,"bodies":["FFM Sudan"],"paragraphCount":133,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Sudan - 01-09-2026 - Official report - A_HRC_63_23 - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-hrc-57-crp-6-u0000","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":null,"seq":0,"section":null,"text":"Findings of the investigations conducted by the Independent\nInternational Fact-Finding Mission for the Sudan into\nviolations of international human rights law and international\nhumanitarian law, and related crimes, committed in the Sudan\nin the context of the conflict that erupted in mid-April 2023*","unnumbered":true},{"id":"a-hrc-57-crp-6-u0001","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":null,"seq":1,"section":null,"text":"Summary\nThe conflict that erupted in mid-April 2023 in the Sudan, now in its second year, continues\nto have a severe impact on civilians. It has engulfed most of the Sudan, resulting in thousands of\nkillings, injuries, extensive displacement and destruction of residential homes, hospitals, schools\nand other critical infrastructure. The evidence collected by the Fact-Finding Mission shows that\nboth the Sudanese Armed Forces (SAF) and the Rapid Response Forces (RSF), and their\nrespective allied militias, have committed large-scale human rights and international\nhumanitarian law violations, many of which may amount to war crimes and/or crimes against\nhumanity.","unnumbered":true},{"id":"a-hrc-57-crp-6-u0002","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":null,"seq":2,"section":null,"text":"Both the SAF and the RSF have attacked civilians and civilian objects, including through\nairstrikes and heavy artillery shelling in densely populated areas, notably in Khartoum and\nDarfur. Both are responsible for violating children’s rights, including through killing and\nmaiming. Both have engaged in a pattern of arbitrary arrest and detention as well as torture and\nill-treatment in areas under their control, also amounting to war crimes. Both have imposed broad\ninternet shutdowns and curtailed freedom of information and expression, including through\nattacks on media, journalists and human rights defenders. Both obstructed access to humanitarian\naid for civilians in need.","unnumbered":true},{"id":"a-hrc-57-crp-6-u0003","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":null,"seq":3,"section":null,"text":"The RSF and its allied militias have also committed other war crimes and crimes against\nhumanity. These include widespread sexual and gender-based violence, rape, sexual slavery,\nabduction, and recruitment and use of children in hostilities. The RSF and its allied militias have\nalso systematically engaged in pillage and looting. They have further committed large-scale\nattacks based on intersecting ethnicity and gender grounds, especially against the Masalit\ncommunity in El Geneina, including killings, torture, rape, and other forms of sexual violence,\namounting to persecution.","unnumbered":true},{"id":"a-hrc-57-crp-6-u0004","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":null,"seq":4,"section":null,"text":"The situation remains grim as the conflict rages on, causing civilians immense suffering.\nMore than 10.7 million are displaced, and 2.1 million have fled the country. Nearly half of the\npopulation (25.6 million) is facing hunger.","unnumbered":true},{"id":"a-hrc-57-crp-6-u0005","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":null,"seq":5,"section":null,"text":"To protect civilians in the Sudan and prevent further violations, the Fact-Finding Mission\nhas made a number of urgent recommendations, including the following:\n(i)      an immediate and sustainable ceasefire;\n(ii)     effective delivery of humanitarian assistance;\n(iii)    deployment of an independent and impartial force with a mandate to protect\ncivilians in the Sudan;\n(iv)     compliance with the existing arms embargo imposed in Darfur pursuant to\nSecurity Council Resolution 1556 (2004) and the expansion of this embargo to\ncover the whole of the Sudan;\n(v)      increased financial and other support for the refugees and the host communities;\n(vi)     ending sexual violence, and enabling women, and youth to meaningfully\nparticipate in any peace negotiations or initiatives;\n(vii)    protecting children and ending their recruitment and use in the conflict;\n(viii)   pursuing a comprehensive approach to transitional justice based on inclusive\ndialogue and genuine consultations;\n(ix)     expanding the existing jurisdiction of the International Criminal Court over\nDarfur to cover the entire Sudan; Sudan should cooperate with the Court through\nsurrendering to it all indicted persons, including former President Omar Al-\nBashir;\n(x)      establishing a separate international judicial mechanism working in tandem and\ncomplementarity with the International Criminal Court, as well as a truth\ncommission, and a dedicated victim’s support and reparations office.","unnumbered":true},{"id":"a-hrc-57-crp-6-p0001","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"1","seq":6,"section":"I. Introduction","text":"In its resolution 54/2 of 11 October 2023, the Human Rights Council established the\nIndependent International Fact-Finding Mission for the Sudan (hereinafter “the Fact-Finding\nMission”) composed of three experts, for an initial period of one year. The Fact-Finding\nMission is mandated inter alia to investigate and establish the facts, circumstances and root\ncauses of all alleged human rights violations and abuses and violations of international\nhumanitarian law, and related crimes, in the context of the ongoing armed conflict that began\non 15 April 2023, between the Sudanese Armed Forces (SAF) and the Rapid Support Forces\n(RSF), as well as other warring parties.1 The resolution also mandates the Fact-Finding\nMission to collect, consolidate and preserve evidence of such violations and abuses; to\nidentify, where possible, those individuals and entities responsible with a view to ensuring\nthey are held accountable; and to make recommendations, in particular on accountability\nmeasures and access to justice for victims. 2 The Human Rights Council requested the Fact-\nFinding Mission to present a comprehensive report of its findings at its fifty-seventh session.3"},{"id":"a-hrc-57-crp-6-p0002","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"2","seq":7,"section":"I. Introduction","text":"On 18 December 2023, the President of the Human Rights Council appointed\nMohamed Chande Othman (Tanzania) (Chairperson), Mona Rishmawi (Jordan/ Switzerland)\nand Joy Ngozi Ezeilo (Nigeria) to serve as the three independent experts of the Fact-Finding\nMission."},{"id":"a-hrc-57-crp-6-p0003","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"3","seq":8,"section":"I. Introduction","text":"Despite the best efforts of the Office of the United Nations High Commissioner for\nHuman Rights (OHCHR), there was a considerable delay in establishing the Secretariat of\nthe Fact-Finding Mission due to the liquidity crisis experienced by the United Nations\nSecretariat in 2023/2024. The Secretariat was eventually established in May 2024 in Nairobi,\nKenya, with approximately two-thirds of the staff that was allocated to it.4 Prior to the\nestablishment of the Secretariat, the OHCHR provided a small team of experienced Geneva-\nbased staff to support its initial investigations. The Fact-Finding Mission is grateful to the\nHigh Commissioner and the Deputy High Commissioner for their efforts in facilitating the\nimplementation of its mandate."},{"id":"a-hrc-57-crp-6-p0004","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"4","seq":9,"section":"I. Introduction","text":"The Fact-Finding Mission presented an oral update to the Human Rights Council on\n18 and 19 June at its fifty-fourth session, providing details relating to its work and an\noverview of its initial observations regarding areas under investigation.5"},{"id":"a-hrc-57-crp-6-p0005","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"5","seq":10,"section":"I. Introduction","text":"On 10 September 2024, the Fact-Finding Mission presented its report to the Human\nRights Council (A/HRC/57/23). This Conference Room Paper (CRP) elaborates on the\nfindings of the investigations conducted by the Fact-Finding Mission. It provides a more\ndetailed description of the patterns of human rights violations and abuses and violations of\ninternational humanitarian law in the Sudan since mid-April 2023 and related crimes. It also\ndevelops accountability pathways, conclusions, and recommendations. The draft CRP was\nsent to the Government of the Sudan on 16 October 2024 for its views by 22 October 2024.\nNo response was received."},{"id":"a-hrc-57-crp-6-p0006","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"6","seq":11,"section":"II. Scope of the Mandate","text":"The mandate of the Fact-Finding Misson, pursuant to Human Rights Council\nresolution 54/2, contains five key elements. First, the Fact-Finding Mission is mandated to\n“investigate and establish the facts, circumstances and root causes” of all alleged human\nrights violations and abuses and violations of international humanitarian law and related\ncrimes. In line with this requirement, the Fact-Finding Mission conducted investigations into\nallegations of human rights violations and abuses, and violations of international\nhumanitarian law, including those that may amount to international crimes."},{"id":"a-hrc-57-crp-6-p0007","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"7","seq":12,"section":"II. Scope of the Mandate","text":"Second, the Fact-Finding Mission is mandated to collect, consolidate and analyze\nevidence of violations and abuses. In this regard, the Fact-Finding Mission has systematically\ncompiled, analyzed and securely preserved information and evidence collected while\nensuring that the established protocols on preserving such information and its chain of\ncustody are followed. The Fact-Finding Mission is safeguarding all information submitted to\nit in line with applicable United Nations regulations, rules, policies and procedures, in\nparticular the Secretary-General’s bulletins on data protection, on information sensitivity,\nclassification and handling, and on recordkeeping and the management of United Nations\narchives.6 All information collected is preserved in the Fact-Finding Mission’s secure\nplatforms."},{"id":"a-hrc-57-crp-6-p0008","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"8","seq":13,"section":"II. Scope of the Mandate","text":"Third, the resolution mandates the Fact-Finding Mission to document and verify\nrelevant information and evidence, including through field engagement, and to cooperate\nwith judicial and other entities, as appropriate. In discharging this aspect of the mandate,\napart from documenting the accounts of victims and witnesses of violations of human rights\nand international humanitarian law, the Fact-Finding Mission prioritized field visits to the\nSudan and to its neighbouring countries, including Chad, Central African Republic, Egypt,\nEritrea, Ethiopia, Kenya, South Sudan and Uganda in order to obtain, document and verify\ninformation and evidence, including from those who had fled from the Sudan to other\nlocations following the outbreak of the violence. The Fact-Finding Mission has approached\nall those States requesting visits and has so far conducted visits to Chad, Kenya and Uganda.\nThe Fact-Finding Mission also initiated engagement with relevant judicial mechanisms,\nincluding the International Criminal Court."},{"id":"a-hrc-57-crp-6-p0009","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"9","seq":14,"section":"II. Scope of the Mandate","text":"Fourth, the Fact-Finding Mission is mandated to identify, where possible, those\nindividuals and entities responsible for violations and abuses of human rights and violations\nof international humanitarian law, and related crimes, in the Sudan, to ensure that they are\nheld accountable. At this stage, the Fact-Finding Mission has mapped out internal\ninstitutional command-and-control structures and identified specific units responsible for\nviolations. The Fact-Finding Mission is also in the process of gathering and analyzing\ninformation linking individuals to specific incidents. It maintains a confidential list of persons\nof interest with a view to preparing confidential dossiers in relation to any individual who\nmay be responsible for violations of human rights and international humanitarian law,\nincluding those that may amount to international crimes."},{"id":"a-hrc-57-crp-6-p0010","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"10","seq":15,"section":"II. Scope of the Mandate","text":"Finally, the Fact-Finding Mission is mandated to make recommendations, in particular\non accountability measures and access to justice for victims. To fulfil this part of the mandate,\nthe Fact-Finding Mission has consulted with stakeholders on the recommendations presented\nin this report, including with victims, their families, Sudanese professionals, civil society\norganizations, international and regional organizations, and other experts in accountability\nmechanisms."},{"id":"a-hrc-57-crp-6-p0011","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"11","seq":16,"section":"A. Engagements and Consultations","text":"Pursuant to its mandate, the Fact-Finding Mission has engaged with Sudanese\ncommunity leaders, civil society organizations, Sudanese victims and survivors,7experts,\norganizations and entities involved in the situation in the Sudan, including United Nations\nentities, and diplomatic missions. These engagements were conducted both online and in\nperson during missions to Chad, Kenya, Switzerland and Uganda."},{"id":"a-hrc-57-crp-6-p0012","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"12","seq":17,"section":"A. Engagements and Consultations","text":"The Experts conducted an initial mission to Geneva from 14 to 17 January 2024, a\nsecond mission from 13 to 20 June 2024, and a third mission from 4 to 11 September 2024.\nDuring these missions, they held consultations with the United Nations High Commissioner\nfor Human Rights, his Deputy and his Office,8 and the President of the Human Rights\nCouncil.9 The Experts also held discussions with the designated Expert on human rights in\nthe Sudan10, the United Nations Secretary-General’s Personal Envoy on the Sudan,11 the\nUnder-Secretary-General and Special Advisor on the Prevention of Genocide,12 the Special\nRepresentative of the Secretary-General on Sexual Violence in Conflict, the Special\nRepresentative of the Secretary-General on Children and Armed Conflict,13 the Panel of\nExperts on the Sudan,14 and other senior United Nations officials. The Fact-Finding Mission\nfurther engaged with the Sudan Country Rapporteur of the African Commission on Human\nand Peoples' Rights,15 the African Union Special Envoy for the Prevention of Genocide and\nother Mass Atrocities16 and the International Criminal Court.17 It also reached out to the\nLeague of Arab States,18 the Intergovernmental Authority on Development (IGAD), 19 and the\nOrganization of Islamic Cooperation20 with requests for dialogue and cooperation, to\ncoordinate efforts and ensure complementarity, as required by Resolution 54/2.21"},{"id":"a-hrc-57-crp-6-p0013","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"13","seq":18,"section":"A. Engagements and Consultations","text":"As per its mandate, the Fact-Finding Mission reached out to the Government of Sudan\non four occasions. On 3 and 29 January 2024, the Fact-Finding Mission sent correspondence\nto the Permanent Mission of the Sudan to the United Nations Office in Geneva requesting a\nmeeting, and to visit the Sudan during the month of February 2024. On 7 June 2024, the Fact-\nFinding Mission sent another correspondence to the Government of the Sudan requesting a\nmeeting in Geneva. On 9 August 2024, the Fact-Finding Mission reiterated its request to visit\nthe Sudan. On 23 August 2024, the Fact-Finding Mission sent the draft report A/HRC/57/23\nto the Sudan requesting comments on any factual errors or inaccuracies by 1 September 2024.\nAll these communications remain unanswered. On 2 September 2024, Sudan sent a letter to\nthe President of the Human Rights Council regarding the draft report. 22 The Fact-Finding\nMission considers it important to engage with the Sudanese authorities and to visit the Sudan\nin accordance with its mandate."},{"id":"a-hrc-57-crp-6-p0014","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"14","seq":19,"section":"A. Engagements and Consultations","text":"The RSF sent correspondence to the President of the Human Rights Council, through\nOHCHR, on 20 December 2023, offering full cooperation with the Fact-Finding Mission.\nThe RSF followed up on this letter in July 2024, informally requesting for a meeting with the\nFact-Finding Mission, following which there was some informal communication with the\nSecretariat of the Fact-Finding Mission, which, on 28 August 2024, offered the RSF an\nopportunity to engage with it about the allegations. On 10 September 2024, the RSF\naddressed a letter to the Chair of the Fact-Finding Mission, expressing appreciation for the\nwork of the Fact-Finding Mission, reiterating its commitment to cooperate and expressing\nregret for the absence of engagement and an opportunity to respond to certain allegations."},{"id":"a-hrc-57-crp-6-p0015","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"15","seq":20,"section":"A. Engagements and Consultations","text":"The Fact-Finding Mission expresses its readiness to engage with all parties to the\nconflict, in accordance with its mandate."},{"id":"a-hrc-57-crp-6-p0016","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"16","seq":21,"section":"A. Engagements and Consultations","text":"As mentioned earlier, the Fact-Finding Mission also reached out to the Governments\nof the Sudan’s neighbouring countries: Central African Republic,23 Chad,24 Egypt,25 Eritrea,26\nEthiopia,27 Kenya,28 South Sudan,29 and Uganda,30 requesting their cooperation and access\nto their territories in order to gather first-hand testimonies and other information from victims\nof the conflict. Following positive responses from the Governments of Chad, Kenya, and\nUganda, for which the Fact-Finding Mission is grateful, the Fact-Finding Mission was able\nto carry out visits to these three States. The Fact-Finding Mission is still in dialogue with the\nother neighbouring States. The Fact-Finding Mission has met with several States, in the\ncourse of discharging its mandate, to seek their cooperation, support, and where relevant,\naccess to their countries. The African Union,31 Cameroon,32 Canada,33 Central African\nRepublic,34 Egypt,35 European Union,36 Germany, 37 Ghana,38 Japan,39 Kyrgyzstan,40\nNigeria,41 Norway,42 the Organization of Islamic Cooperation,43 Sierra Leone, 44 South\nAfrica,45 South Korea,46 South Sudan,47 Switzerland, 48 United Kingdom,49 and United States\nof America50 responded positively, and meetings were held, in Chad, Kenya and Switzerland."},{"id":"a-hrc-57-crp-6-p0017","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"17","seq":22,"section":"B. Investigations and verification of information","text":"The Fact-Finding Mission gathered information through the following methods."},{"id":"a-hrc-57-crp-6-p0018","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"18","seq":23,"section":"1. Submissions","text":"In January 2024, the Fact-Finding Mission issued a public call for written\nsubmissions,51 and subsequently received substantial information and documentation from\nindividuals and organizations. Overall, the Fact-Finding Mission received 686 submissions\nby the deadline set on 31 July 2024, which it carefully examined."},{"id":"a-hrc-57-crp-6-p0019","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"19","seq":24,"section":"2. Reports of International, Regional and Non-Governmental Organizations","text":"The Fact-Finding Mission examined information contained in reports from various\nsources, including United Nations entities, regional and international bodies and non-\ngovernmental organizations. Considering that the Fact-Finding Mission began its work\nseveral months into the conflict, it found these reports useful especially in understanding the\nbackground to the conflict, the timeline of various developments, and providing valuable\nleads for the investigations of the Fact-Finding Mission."},{"id":"a-hrc-57-crp-6-p0020","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"20","seq":25,"section":"3. Consultations","text":"The Fact-Finding Mission held extensive in-person and online consultations with\nexperts, regional non-governmental organizations, Sudanese civil society organizations, and\nvictims and survivors, on the situation in the Sudan, including the impact of the conflict on\nwomen’s rights and women human rights defenders with Sudanese women human rights\ndefenders and feminist activists;52 the violations of the rights of children in the Sudan,\nincluding child recruitment and use in armed groups, child detention and in internally\ndisplaced persons camps;53 root causes;54 and the enhancement of justice and accountability,\nas well as victim reparations for Sudanese victims.55"},{"id":"a-hrc-57-crp-6-p0021","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"21","seq":26,"section":"4. Interviews","text":"The Fact-Finding Mission obtained first-hand information through direct interviews\nwith victims, their families, eyewitnesses, first-line responders and other sources. As of 31\nJuly 2024, the Fact-Finding Mission had conducted in-depth interviews with 182 individuals\n(67 women and 115 men)."},{"id":"a-hrc-57-crp-6-p0022","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"22","seq":27,"section":"1. Visits to Kenya","text":"The Fact-Finding Mission conducted two visits to Kenya, the first from 20 to 25 May,\nand the second from 14 to 18 August 2024. During these visits, it held meetings with\nindividuals, organizations and diplomatic missions, and obtained vital information on the\nsituation in the Sudan, and allegations of violations of human rights law and international\nhumanitarian law, which it subsequently investigated."},{"id":"a-hrc-57-crp-6-p0023","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"23","seq":28,"section":"2. Visit to Chad","text":"The Fact-Finding Mission also undertook a visit to Chad from 30 June to 18 July 2024.\nAt the time of the Fact-Finding Mission’s visit, Chad hosted more than 620,000 refugees\nfrom the Sudan and continued to receive new arrivals daily. The Fact-Finding Mission met\nwith various groups and entities in N’Djamena, including the United Nations country team,\nhumanitarian organizations and diplomats. The Fact-Finding Mission also travelled to the\neastern part of the country, where it visited Abeche, Adré and Farchana. At the refugee camps\nin Adré and Farchana, the Fact-Finding Mission engaged directly with refugees who had fled\nfrom the Sudan since the outbreak of the conflict, obtaining first-hand accounts of their lived\nexperiences."},{"id":"a-hrc-57-crp-6-p0024","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"24","seq":29,"section":"3. Visit to Uganda","text":"The Fact-Finding Mission visited Uganda from 18 to 21 August 2024 to consult with\nSudanese experts and civil society and managed to fill important evidence gaps in the\ninformation it had collected on allegations of violations of human rights law and international\nhumanitarian law, committed in the Sudan since mid-April 2023."},{"id":"a-hrc-57-crp-6-p0025","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"25","seq":30,"section":"3. Visit to Uganda","text":"During all field missions, the Fact-Finding Mission also obtained views on justice and\naccountability, and reparations for the victims. The Fact-Finding Mission expresses its\ngratitude to victims and witnesses who shared their accounts, and all the individuals and\norganizations it engaged with."},{"id":"a-hrc-57-crp-6-p0026","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"26","seq":31,"section":"4. Guiding Principles","text":"In discharging its mandate, the Fact-Finding Mission strictly adhered to the principles\nof independence, impartiality, objectivity, transparency, confidentiality, and integrity. The\nFact-Finding Mission also sought to integrate gender considerations in discharging its\nmandate, including by incorporating gender-sensitive methodologies and tools for collecting,\nanalyzing and reflecting the information."},{"id":"a-hrc-57-crp-6-p0027","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"27","seq":32,"section":"4. Guiding Principles","text":"The Fact-Finding Mission attaches the utmost importance to the protection of sources,\nand the ‘do no harm’ principle by taking all measures not to jeopardize the safety, security\nand well-being of victims, witnesses, and other persons cooperating or providing information\nto it. In this regard, the Fact-Finding Mission made efforts to assess the level of risks and\nadopted measures to mitigate any identified risks. The Fact-Finding Mission also ensured it\nhad the informed consent from each person it interviewed to use or share the information\nprovided. As such, the Fact-Finding Mission has included in A/HRC/57/23 and this CRP only\ninformation for which the sources provided consent, and only where such inclusion would\nnot place the sources at risk. It has also anonymized the sources of information and omitted\nany identifying information."},{"id":"a-hrc-57-crp-6-p0028","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"28","seq":33,"section":"4. Guiding Principles","text":"The Fact-Finding Mission also implemented measures at every stage of data handling\nto preserve the security and confidentiality of the information submitted to it and protect the\nprivacy and personal data of the sources. In particular, the Fact-Finding Mission utilized\nsecure submission channels with controlled access to submission portals, and ensured all\nevidence is registered in a secure digital log. By adopting strict guidelines and utilizing\nadvanced technologies, the Fact-Finding Mission ensured that its information remained\nsecure and reliable."},{"id":"a-hrc-57-crp-6-p0029","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"29","seq":34,"section":"5. Standard of Proof","text":"In line with the practice adopted by United Nations investigative bodies, the Fact-\nFinding Mission applied the “reasonable grounds to believe” standard of proof. It has made\nfindings of fact and law only where it was able to obtain sufficient reliable and corroborated\ninformation, based on which a reasonable and ordinarily prudent person would have reason\nto believe that such an incident or pattern of conduct occurred as described. The phrase ‘the\nFact-Finding Mission finds’ as used throughout A/HRC/57/23 and this CRP is reflective of\nthis standard being met. In applying this standard, the Fact-Finding Mission also took into\nconsideration the nature of allegations under investigation,56 the facts it sought to establish,57\nand the sources of information.58"},{"id":"a-hrc-57-crp-6-p0030","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"30","seq":35,"section":"5. Standard of Proof","text":"With regard to documenting and establishing facts, the Fact-Finding Mission based\nitself on at least one credible direct source of information, independently corroborated by at\nleast two or more credible sources of information. Where the Fact-Finding Mission identified\npatterns of conduct, these are based on establishing consistency and similarity of certain types\nof conduct based on information provided by several independently verified credible direct\nsources and corroborated by the overall body of credible information collected. The latter\napproach is applied to the documentation of violations and abuses where a second\nindependent source may not be available because survivors/victims faced their attacker in an\nisolated location, in particular in relation to cases of torture, ill-treatment, rape or other forms\nof sexual violence, including in detention settings."},{"id":"a-hrc-57-crp-6-p0031","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"31","seq":36,"section":"D. Constraints and Limitations","text":"The Fact-Finding Mission’s investigations were affected by various challenges,\nincluding time and resource constraints. The delay in the establishment of the Secretariat, and\nthe lack of adequate staffing impacted the Fact-Finding Mission’s ability to comprehensively\ngather, verify and analyze all the allegations of violations and abuses committed since mid-\nApril 2023 in the Sudan."},{"id":"a-hrc-57-crp-6-p0032","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"32","seq":37,"section":"D. Constraints and Limitations","text":"The work of the Fact-Finding Mission was also affected by the lack of access to the\nSudan and some neighboring countries. This prevented the Fact-Finding Mission from\nreaching victims, survivors and witnesses who fled key conflict zones. Nevertheless, the\nFact-Finding Mission was able to obtain and verify sufficient amounts of relevant\ninformation that enabled it to establish facts and patterns of violations. The Fact-Finding\nMission continues to request the Sudanese authorities and the neighbouring countries to grant\nit access to their territories, which is crucial for the implementation of the mandate."},{"id":"a-hrc-57-crp-6-p0033","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"33","seq":38,"section":"D. Constraints and Limitations","text":"Given these limitations, the Fact-Finding Mission prioritized incidents on the basis of\ncross-cutting thematic violations, while also outlining violations in certain geographical\nlocations, including Darfur and Khartoum. The findings presented in A/HRC/57/23 and this\nCRP are therefore not exhaustive but illustrative of the patterns of violations established by\nthe Fact-Finding Mission."},{"id":"a-hrc-57-crp-6-p0034","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"34","seq":39,"section":"IV. Applicable Law","text":"In pursuance of its mandate, the Fact-Finding Mission has investigated alleged human\nrights violations and abuses, violations of international humanitarian law and related crimes.\nIt considers that the wording ‘related crimes’ should be read as including the three core\ninternational crimes, namely war crimes, crimes against humanity and genocide. To make\nlegal determinations based on its findings of fact, the Fact-Finding Mission has applied\ninternational human rights law, international humanitarian law, and international criminal\nlaw. It has also considered additional commitments undertaken by the Sudan as well as\nregional instruments to which the Sudan is a party, and domestic legislation, as applicable."},{"id":"a-hrc-57-crp-6-p0035","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"35","seq":40,"section":"A. International Human Rights Law","text":"The Sudan is a party to seven of the nine core international human rights treaties,\nincluding the International Covenant on Civil and Political Rights (ICCPR), International\nCovenant on Economic, Social and Cultural Rights (ICESCR), Convention against Torture\nand Other Cruel, Inhuman or Degrading Treatment or Punishment (CAT), International\nConvention for the Protection of All Persons from Enforced Disappearance (CED), and the\nInternational Convention on the Elimination of All Forms of Racial Discrimination (CERD).\nAt the regional level, it is a party to, among others, the African Charter on Human and\nPeople’s Rights (ACHPR) and the African Charter on the Rights and Welfare of the Child\n(ACRWC)."},{"id":"a-hrc-57-crp-6-p0036","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"36","seq":41,"section":"A. International Human Rights Law","text":"Notably, the Sudan has not acceded to the Convention on the Elimination of All Forms\nof Discrimination against Women. It signed, but did not ratify, the Protocol to the African\nCharter on Human and People’s Rights on the Rights of Women in Africa (Maputo Protocol).\nIn line with the 1969 Vienna Convention on the Law of Treaties, the Sudan must however by\nway of this expression to be bound by the Maputo Protocol in good faith refrain from acts\nthat would defeat its object and purpose."},{"id":"a-hrc-57-crp-6-p0037","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"37","seq":42,"section":"A. International Human Rights Law","text":"The Sudan is also a party to the Convention on the Rights of the Child (CRC) and the\nAfrican Charter on the Rights and Welfare of the Child (ACRWC). In 2005, it became a party\nto the Optional Protocol to the CRC on the Involvement of Children in Armed Conflict (OP-\nCRC-AC) prohibiting the compulsory recruitment or use in hostilities of any person below\nthe age of 18.59"},{"id":"a-hrc-57-crp-6-p0038","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"38","seq":43,"section":"A. International Human Rights Law","text":"In addition to its treaty obligations, the Sudan is also bound by relevant rules of\ncustomary international human rights law. These comprise most of the provisions of the\nUniversal Declaration on Human Rights. The body of international human rights law applies\nat all times, including in situations of armed conflict."},{"id":"a-hrc-57-crp-6-p0039","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"39","seq":44,"section":"B. International Humanitarian Law","text":"The Sudan is a state party to the four Geneva Conventions of 1949, as well as their\ntwo Additional Protocols of 1977. It is also a party to, among others, the 1954 Hague\nConvention for the Protection of Cultural Property in the Event of Armed Conflict. Together\nwith customary international humanitarian law, including the principles of necessity,\nhumanity, proportionality, distinction and precaution in an attack, this set of laws applies to\nsituations of armed conflict and seeks to regulate the means and methods of warfare to limit\nhuman suffering and preserve the dignity of the person. International humanitarian law\napplies concurrently with international human rights law."},{"id":"a-hrc-57-crp-6-p0040","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"40","seq":45,"section":"B. International Humanitarian Law","text":"In mid-April 2023, fighting broke out in the Sudan between the SAF and RSF, soon\ninvolving other armed actors. The military confrontations quickly reached a high degree of\nintensity, the RSF seized control of territory in Khartoum and beyond, and have continued to\ncarry out sustained and concerted military operations in the Sudan. The Fact-Finding Mission\ndetermined that the threshold for the existence of a non-international armed conflict to which\nCommon Article 3 to the Geneva Conventions of 1949 and its Additional Protocol II relating\nto the Protection of Victims of Non-International Armed Conflict apply, have been met.\nProtocol II applies to armed conflicts taking place in the territory of a High Contracting Party\nbetween its armed forces and dissident armed forces or other organized armed groups. Along\nwith relevant rules of customary humanitarian law, it is applicable and binding on all parties\nto the conflict."},{"id":"a-hrc-57-crp-6-p0041","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"41","seq":46,"section":"B. International Humanitarian Law","text":"The classification of the RSF as a terrorist organization by the Sudanese authorities\ndoes not alter the application of international humanitarian law or the obligations placed on\nthe parties to the conflict. These obligations entail that all parties to the conflict treat protected\npersons humanely under all circumstances. It prohibits, among others, violence to life and\nperson, outrages upon personal dignity, including rape and indecent assault, slavery and\npillage, and recruitment and use of children below the age of 18.60 It further dictates that\ncivilians shall not be made the object of an attack, threatened with violence for the purpose\nof spreading terror, or ordered to be displaced save for absolute security or military necessity.\nObjects indispensable to the survival of the civilian population are further protected from an\nattack, destruction, removal or rendering useless. Special protections are afforded to\ncategories of vulnerable persons and objects, including women, children, the wounded and\nsick, persons deprived of their liberty, missing persons, hospitals, medical units and\ntransports, humanitarian relief personnel and objects, and cultural property."},{"id":"a-hrc-57-crp-6-p0042","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"42","seq":47,"section":"C. International Criminal Law","text":"The Sudan is a party to the Convention on the Prevention and Punishment of the Crime\nof Genocide of 1948, which obligates it to prevent and punish genocide as a crime under\ninternational law. The Sudan has signed but not ratified the Rome Statute of the International\nCriminal Court. However, taking note of the report of the International Commission of\nInquiry on violations of international humanitarian law and human rights law in Darfur\n(hereinafter “the 2005 Darfur COI”), 61 the Security Council by Resolution 1593 (2005)\nreferred the situation in Darfur since 1 July 2002 to the Prosecutor of the Court. The\ninvestigations by the Office of the Prosecutor into Darfur from 1 July 2002 onwards focus on\nallegations of genocide, crimes against humanity and war crimes.62 In August 2021, a new\nMemorandum of Understanding was signed between the Government of the Sudan and the\nOffice of the Prosecutor of the Court. In July 2023, the Prosecutor announced a new public\ncampaign for information on the situation in Darfur to be submitted to his Office."},{"id":"a-hrc-57-crp-6-p0043","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"43","seq":48,"section":"C. International Criminal Law","text":"The geographical scope of the mandate of the Fact-Finding Mission’s mandate covers\nthe entire territory of the Sudan. It overlaps with but extends beyond the jurisdiction of the\nProsecutor of the International Criminal Court by the Security Council, which is limited to\nDarfur."},{"id":"a-hrc-57-crp-6-p0044","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"44","seq":49,"section":"D. Security Council Resolutions","text":"Acting under Chapter VII, the United Nations Security Council by Resolution 1556\n(2004) imposed an open-ended arms embargo in relation to Darfur and, among others,\ndemanded that “the Government of the Sudan fulfil its commitments to disarm the Janjaweed\nmilitias”.63 It decided that all States should take the necessary measures to prevent by their\nnationals or from their territory or under their jurisdiction the sale, supply or provision of\narms and related materials of all types as well as technical training or assistance on the\nprovision, manufacture, maintenance or use of such items all non-governmental entities and\nindividuals, including the Janjaweed, operating in Darfur.”64 Security Council Resolution\n1591 (2005) expanded this embargo to include all parties to the N'Djamena Ceasefire\nAgreement. The same Resolution imposed sanction measures, including the prevention of\nentry or transit through all States and the freezing of assets of all persons designated to\nimpede the peace process, constitute a threat to stability in Darfur and the region, commit\nviolations of international humanitarian or human rights law or other atrocities, violate the\narms embargo or carry responsibility for offensive military overflights, and established a\nPanel of Experts to monitor implementation thereof."},{"id":"a-hrc-57-crp-6-p0045","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"45","seq":50,"section":"D. Security Council Resolutions","text":"In 2010, the Security Council further strengthened the arms embargo by Resolution\n1945 (2010). It requires all States, including the Sudan, to notify the Committee in advance\nof any assistance and supplies into Darfur as well as to make the sale or supply of any arms\nand related material to the Sudan conditional on necessary end-user documentation to\nascertain consistency with Security Council measures. In March 2023, shortly before the\noutbreak of hostilities, the Security Council by Resolution 2676 (2023) changed the embargo\nfrom open-ended to time-limited until 12 September 2024. By Resolution 2750 (2024), the\nSecurity Council extended the sanctions regime for one year until 12 September 2025. By\nResolution 2750 (2024), the Security Council extended the sanctions regime for one year\nuntil 12 September 2025. These Security Council resolutions therefore remain applicable to\nthe situation in Darfur today."},{"id":"a-hrc-57-crp-6-p0046","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"46","seq":51,"section":"D. Security Council Resolutions","text":"Following the outbreak of the conflict in mid-April 2023, the Security Council, by\nResolution 2724 (2024), called on all parties to the conflict to immediately cease hostilities,\nseek a sustainable solution to the conflict through dialogue, and comply with their obligations\nunder international humanitarian law including to protect civilians and civilian objects, and\nenable full, rapid, safe and unhindered humanitarian access, and their commitments under\nthe Jeddah Declaration. Security Council Resolution 2730 (2024) on the need to promote and\nensure respect for the rules and principles of international humanitarian law, demanded that\nall parties to the armed conflict comply with their obligations under international law,\nincluding to respect and protect humanitarian personnel and United Nations and associated\npersonnel."},{"id":"a-hrc-57-crp-6-p0047","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"47","seq":52,"section":"D. Security Council Resolutions","text":"In June 2024, the Security Council, by Resolution 2736 (2024), demanded amongst\nothers that the RSF halt its siege of El Fasher and that all parties to the conflict ensure the\nprotection of civilians. It further demanded that all parties to the conflict allow civilians to\nmove within and out of El Fasher to safer areas if they wish to do so. It also demanded again\nthat all parties to the conflict comply with their obligations under international law and called\non the parties to seek an immediate cessation of hostilities and called for the full\nimplementation of the Jeddah Declaration and for the parties to facilitate the rapid, safe,\nunhindered and sustained passage of humanitarian relief for civilians in need."},{"id":"a-hrc-57-crp-6-p0048","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"48","seq":53,"section":"E. Jeddah Declaration","text":"Both parties to the conflict have made commitments that stem from binding\nobligations under international law. Co-facilitated by the United States of America and Saudi\nArabia, talks between the SAF and RSF took place in Jeddah, Saudi Arabia, from 6 May\n2023. On 11 May 2023, the SAF and RSF signed the Jeddah Declaration of Commitment to\nProtect the Civilians of the Sudan. Under this agreement, the parties committed to a wide\nrange of measures including: to protect civilians; to respect international humanitarian law\nand international human rights law; to allow humanitarian operations to resume; to allow all\ncivilians to voluntarily and safely leave areas of hostilities and any besieged areas, to respect\nand protect medical personnel and public installations and assets; to refrain from the\nrecruitment of children and the use of children in hostilities; to refrain from engaging in\nforced disappearances and arbitrary detention of civilians; to refrain from any form of torture\nor other cruel, inhumane or degrading treatment, including sexual violence of all kinds; and\nto protect humanitarian personnel and to treat all persons deprived of their liberty in a\nhumane manner and to provide principal humanitarian organizations with regular access to\npersons in detention. They further committed themselves to taking all necessary measures\nto ensure that their respective forces abide by international humanitarian law and to\nscheduling expanded discussions to achieve a permanent cessation of hostilities. The Jeddah\nDeclaration of Commitment was referenced three times in resolution A/HRC/RES/54/2,\nrequesting the parties “to adhere fully” to the commitments they made. As A/HRC/57/23\nand this CRP demonstrate, these commitments remain largely unimplemented."},{"id":"a-hrc-57-crp-6-p0049","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"49","seq":54,"section":"F. National Law","text":"The 2019 Transitional Constitutional Document (Constitutional Decree No. 38),\namended in 2020 by the Juba Peace Agreement, sets out the bill of rights and freedoms. It\nguarantees human rights, including the right to life, dignity and personal safety, personal\nfreedom and security, freedom of movement, equality before the law, fair trial, freedom of\nexpression and of assembly and association, and to be free from torture or harsh, inhumane,\nor degrading treatment or punishment and slavery and forced labour. It further protects the\nrights of the child and the rights of women, including the equal right of men and women to\nenjoy all civil, political, social, cultural and economic rights. Article 42(2) specifically\nprovides for direct implementation of international and regional human rights treaties to\nwhich the Sudan is a party.65"},{"id":"a-hrc-57-crp-6-p0050","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"50","seq":55,"section":"F. National Law","text":"Legislative changes have been introduced since the start of the conflict in April 2023.\nConstitutional Decree No. 7 of 2023 declared the RSF dissolved, 66 and they were classified\na terrorist organization. The Rapid Support Forces Law of 2017, and its 2019 Amendment,\nwas also declared as repealed. Further constitutional decrees relieved Lieutenant General\nMohamed Hamdan Dagalo as Vice-President of the Transitional Sovereignty Council and\nreplaced him with Malik Agar. Constitutional Decree No. 6 of 2024, concerning the Security\nand Defence Council and its committees, set up security committees under a High Technical\nCommittee headed by the Chief of Staff comprising various state agencies dealing with\nintelligence, police, defence, foreign affairs, justice and public prosecution, to maintain peace\nand security and carry out any task as ordered. The General Intelligence Law (Amendment)\n2024 further re-instated extensive investigate powers and immunity from prosecution to\nmembers of the General Intelligence Services.67"},{"id":"a-hrc-57-crp-6-p0051","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"51","seq":56,"section":"F. National Law","text":"Following the eruption of the current conflict, a state of emergency was declared in\nKhartoum State by Constitutional Decree No. 4 of 2024 from the date of signing, 22 April\n2024. States of emergencies were also declared or renewed in other States, including in\nregions of Darfur, Kordofan, Gezira, Gedaref, Sennar, Blue Nile, Northern and Eastern\nSudan.68 Under states of emergency, according to the Emergency and Protection of Public\nSafety Act of 1997, law enforcement activities, including the power to arrest and detain, may\nbe performed by joint security forces, including the SAF, its military intelligence and military\npolice, and regular police forces.69"},{"id":"a-hrc-57-crp-6-p0052","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"52","seq":57,"section":"F. National Law","text":"The Fact-Finding Mission recalls that in time of public emergency that threatens the\nlife of the nation, the Sudan being a State party to the ICCPR, may take measures derogating\nfrom certain obligations under Article 4 “to the extent strictly required by the exigencies of\nthe situation, provided that such measures are not inconsistent with its other obligations under\ninternational law and do not involve discrimination (…).” There are, however, limitations\nplaced on the nature and duration of such derogations. Fundamental human rights that may\nnot be derogated from include the right to life, prohibition of torture, prohibition of slavery,\nslave-trade and servitude and the right to be recognized as a person before the law. Contrary\nto the obligations set out in Article 4 of the ICCPR, the Sudan has not notified the United\nNations Secretary-General of the action it has taken. 70 In this case, the entire ICCPR\ncontinues to apply."},{"id":"a-hrc-57-crp-6-p0053","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"53","seq":58,"section":"A. Timeline of Key Political and Military Developments","text":"In mid-April 2023, hostilities broke out between the SAF and RSF, and their\nrespective allied militias, in Khartoum and quickly spread to other parts of the Sudan.\nTensions between the two warring parties preceded the conflict and had been rising since the\nremoval of former President Omar Al Bashir in 2019, following months of massive popular\nprotests that started in December 2018, triggered by the rising cost of living and a rapidly\ndeclining economy.71 As protests continued, on 11 April 2019, the Sudan military removed\nPresident Al Bashir from his position, dissolved the government and parliament and declared\na state of emergency. On 14 April 2019, Lieutenant General Abdel Fattah Al Burhan took\ncharge of the military-established Transitional Sovereignty Council with Lieutenant General\nMohamed Hamdan Dagalo, also known as Hemedti, as his deputy. The civilian uprising\ncontinued.72"},{"id":"a-hrc-57-crp-6-p0054","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"54","seq":59,"section":"A. Timeline of Key Political and Military Developments","text":"On 17 August 2019, the Sudan adopted a transitional constitution, under which the\ncountry would be jointly governed by a civilian-military coalition for a transitional period of\n39 months. The military agreed to have the protestors nominate a civilian Prime Minister and\nestablish a civilian-run Government. This led to the establishment of a Transitional\nGovernment led by a civilian, Prime Minister Abdalla Hamdok, who was sworn in on 21\nAugust 2019. Attempts at sustaining the transitional period faltered on 25 October 2021,\nwhen the military seized power and asserted military rule, resulting in the dissolution of the\nTransitional Government. This led to a strong condemnation by the Peace and Security\nCouncil of the African Union and immediate suspension, effective as of 26 October 2021, of\nthe participation of the Republic of the Sudan in all African Union activities until the effective\nrestoration of the civilian-led Transitional Authority. 73 One month later, on 21 November\n2021, Al Burhan reinstated Prime Minister Abdalla Hamdok; however, he resigned two\nmonths after his reinstatement, citing fragmentation between the civilian and military\ncomponents of the transition. Widespread protests persisted as political opponents, trade\nunions, women’s associations and businesses, continued rejecting the military-security\nestablishment and demanded complete civilian control over the transition. 74"},{"id":"a-hrc-57-crp-6-p0055","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"55","seq":60,"section":"A. Timeline of Key Political and Military Developments","text":"On 5 December 2022, a Political Framework Agreement was signed,75 following\nnegotiations facilitated by a Trilateral Mechanism (United Nations, African Union and\nIGAD). The Political Framework Agreement contained comprehensive provisions on\nestablishing a transitional civilian government and outlined, among others, security and\nmilitary reforms that would lead to one professional national army. 76 However, General Al\nBurhan and General Mohamed Hamdan Dagalo, disagreed on the timeline of the proposed\nintegration of the RSF into the country’s armed forces.77"},{"id":"a-hrc-57-crp-6-p0056","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"56","seq":61,"section":"A. Timeline of Key Political and Military Developments","text":"In the period immediately preceding the outbreak of the conflict, tensions kept\nsimmering between the SAF and RSF due to the ongoing power struggle between General\nAl Burhan and General Mohamed Hamdan Dagalo. Armed confrontations between the SAF\nand RSF eventually erupted in mid-April in the country’s capital, Khartoum, and quickly\nspread to other regions across the country. RSF forces started to mobilize on 13 April 2023,\nwhich led to a series of clashes with the SAF and the capturing by the RSF of Khartoum\nInternational Airport, the Presidential Palace and several military bases on 15 April 2023.\nThe fighting quickly spread to the suburbs of Khartoum and neighbouring city Omburdman,\nin particular the bridge crossing the White Nile. Heavy fighting continued in Khartoum, Bahri\nand Omdurman during the first weeks of the conflict.78"},{"id":"a-hrc-57-crp-6-p0057","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"57","seq":62,"section":"A. Timeline of Key Political and Military Developments","text":"The fighting soon expanded to Darfur and Kordofan regions, as the RSF sought to\ncapture and take control of various parts of the country. From 24 April 2023, the RSF and\nallied militias launched attacks in El Geneina, the capital of West Darfur State, and eventually\nexerted full control over the city on 15 June 2023, following the killing of the Governor of\nWest Darfur. In October, it captured Nyala in South Darfur and the headquarters of SAF’s\n16th Division as well as Zalingei in Central Darfur and the headquarters of SAF’s 21st\nDivision. In early November 2023, the RSF captured the headquarters of SAF’s 15 th Division\nin Ardamata, at the outskirts of El Geneina. With the withdrawal of the SAF from the\nheadquarters of its 20th Division in El Daein, East Darfur, in late November, the RSF had\ntaken control of four out of five Darfur States, leaving only parts of North Darfur, including\nthe capital El Fasher, in the hands of the SAF and aligned armed groups. The RSF then\nexpanded towards Wad Madani, the capital of Gezira State, taking control of the city on 18\nDecember 2023."},{"id":"a-hrc-57-crp-6-p0058","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"58","seq":63,"section":"A. Timeline of Key Political and Military Developments","text":"In the Kordofan region, violence escalated from January 2024 with other armed actors\njoining the conflict as the Sudan People’s Liberation Movement-North faction of Abdelaziz\nal Hilu (SPLM-N/Al-Hilu) clashed with the SAF in South Kordofan. In June 2024, the RSF\nadvanced towards Sennar State, engaging in armed confrontations with the SAF in Sinja\ntown, which triggered the displacement of a significant number of civilians. 79"},{"id":"a-hrc-57-crp-6-p0059","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"59","seq":64,"section":"A. Timeline of Key Political and Military Developments","text":"By the time of this report, 14 out of the Sudan’s 18 states were affected by the\nhostilities on the ground, with the RSF controlling a large part of the country, including\nKhartoum city, though the SAF recently – on 26 September 2024 - launched an offensive\nagainst the RSF in Khartoum and Bahri in an attempt to regain control of the city. Clashes\nare ongoing with serious consequences for the civilian population residing in this area."},{"id":"a-hrc-57-crp-6-p0060","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"60","seq":65,"section":"A. Timeline of Key Political and Military Developments","text":"Seven states are experiencing sporadic attacks through airstrikes or shelling: White\nNile, East Darfur, South Darfur, Central Darfur, West Darfur, Gedaref, and Blue Nile. Seven\nstates are currently experiencing ongoing hostilities: Khartoum, Gezira, Sennar, North\nKordofan, South Kordofan, West Kordofan and North Darfur. 80"},{"id":"a-hrc-57-crp-6-p0061","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"61","seq":66,"section":"A. Timeline of Key Political and Military Developments","text":"North Darfur, in particular, remains a hotspot for fighting, with the RSF’s continuing\nattempts to capture the capital, El Fasher. The fighting for control of the city has intensified\nin September 2024, leading to severe civilian casualties. As the clashes continue, the\nhumanitarian situation in El Fasher also continues to deteriorate. The United Nations and\nhumanitarian organizations have expressed alarm over the rising civilian toll, worsening food\nshortages, and lack of medical care.81 Famine conditions have already been declared in\nsurrounding displacement camps, and the ongoing conflict makes delivering aid nearly\nimpossible. Despite international calls for a ceasefire, both the SAF and RSF remain locked\nin a bitter struggle, with no sign of de-escalation."},{"id":"a-hrc-57-crp-6-p0062","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"62","seq":67,"section":"A. Timeline of Key Political and Military Developments","text":"These ongoing hostilities have a major impact on the civilian population throughout\nthe Sudan, a large percentage of which is on the run, either from the conflict, or from the\nincreasing hunger due to food deprivation all over the country."},{"id":"a-hrc-57-crp-6-p0063","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"63","seq":68,"section":"B. International and Regional Political Initiatives","text":"Multiple initiatives have been pursued at the regional and international levels to end\nthe conflict in the Sudan. On 16 April 2023, immediately after the outbreak of the conflict,\nthe African Union Peace and Security Council issued a communiqué, in which it condemned\nthe ongoing confrontations; called for an immediate ceasefire, the protection of civilians; and\nprovision of humanitarian support to civilians caught up in the conflict.82 It also requested\nthe Chairperson of the African Union Commission to engage with the parties to the conflict\nin order to facilitate dialogue and peaceful resolution, and to continue consultations with the\nUnited Nations and the IGAD towards a consolidated response by the international\ncommunity within the framework of the African Union, IGAD and United Nations Trilateral\nMechanism on the Sudan’s political transition. On 27 April 2023, the African Union Peace\nand Security Council adopted the African Union Roadmap for the Resolution of the Conflict\nin the Sudan, containing six elements: i) the establishment of a coordination mechanism to\nensure the harmonization of regional and global efforts; ii) an immediate, permanent,\ninclusive and comprehensive cessation of hostilities; iii) effective humanitarian response; iv)\nprotection of civilians and civil infrastructure; v) Strategic role of neighboring states and the\nregion; and vi) resumption of a credible and inclusive political transition process towards a\ndemocratic civilian-led government.83"},{"id":"a-hrc-57-crp-6-p0064","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"64","seq":69,"section":"B. International and Regional Political Initiatives","text":"The African Union Peace and Security Council also underscored the importance of a\nsingle, inclusive and consolidated peace process for the Sudan, coordinated under the joint\nauspices of the African Union, IGAD, League of Arab States, United Nations, and like-\nminded partners, noting that a multiplicity of mediation initiatives would not serve the\ninterests of the Sudanese people. In this regard, it endorsed the Expanded Mechanism on the\nSudan and its Core Group as an all-inclusive platform for providing coordinated engagement\nwithin the international community, to foster political consensus and common global support\nfor the Sudan. The core group of the Expanded Mechanism has convened a series of meetings\nsince its establishment to coordinate the implementation of the African Union Roadmap on\nResolution of the conflict in the Sudan."},{"id":"a-hrc-57-crp-6-p0065","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"65","seq":70,"section":"B. International and Regional Political Initiatives","text":"A separate process towards resolution of the conflict in the Sudan was initiated by the\nIGAD, which resulted in the adoption of a Roadmap on 12 June 2023, whose implementation\nis spearheaded by the IGAD Quartet Group of countries, under the chairmanship of the\nPresident of Kenya. On 10 July 2023, the Quartet expressed concerns about the escalation of\nthe conflict; the repeated violations of the various ceasefire agreements; the spread of\nviolence outside of Khartoum to the other parts of the Sudan; and the degenerating\nhumanitarian situation. The Quartet further condemned the ongoing human rights violations\nand abuses and committed to work closely with the international community to put in place\na robust monitoring and accountability mechanism that would be instrumental in bringing\nperpetrators to justice. The meeting resolved to request the East Africa Standby Force (EASF)\nsummit to convene in order to consider the possible deployment of the EASF to protect\ncivilians and guarantee humanitarian access."},{"id":"a-hrc-57-crp-6-p0066","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"66","seq":71,"section":"B. International and Regional Political Initiatives","text":"On 6 September 2023, the Quartet cautioned that the conflict in the Sudan was\nbecoming increasingly complex and risked taking on a regional dimension with the entry and\nparticipation of other armed movements, in addition to the rapid proliferation of small arms\nand light weapons posing severe security, humanitarian, and political risks for the Sudan and\nthe broader region. The Quartet emphasized the further deterioration of the humanitarian\nsituation and called upon the international community, neighbouring countries and friends of\nthe Republic of the Sudan to scale up and sustain support for humanitarian action. The\nQuartet suggested consolidation of all peace initiatives, calling upon the international actors\nto support a single, all-inclusive IGAD-African Union led platform."},{"id":"a-hrc-57-crp-6-p0067","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"67","seq":72,"section":"B. International and Regional Political Initiatives","text":"On 16 November 2023, the Government of Sudan requested the United Nations\nSecretary-General “to terminate the United Nations Integrated Transition Assistance Mission\nin the Sudan (UNITAMS) with immediate effect.”84 On 1 December 2023, the Security\nCouncil by virtue of resolution 2715 (2023) took note of Sudan’s letter and requested\nUNITAMS to liquidate its presence and “immediately start on 4 December 2023 the cessation\nof its operations and the process of the transfer of its tasks, where appropriate and to the\nextent feasible, to UN agencies, funds and programmes.”"},{"id":"a-hrc-57-crp-6-p0068","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"68","seq":73,"section":"B. International and Regional Political Initiatives","text":"On 21 November 2023, the United Nations Secretary-General appointed as his\nPersonal Envoy for the Sudan the veteran diplomat, Mr. Ramtane Lamamra, former Deputy\nPrime Minister and Minister of Foreign Affairs of Algeria, and former African Union\nCommissioner for Peace and Security.85 Security Council Resolution 2724 (2024) welcomed\nthe appointment of Mr. Lamamra and mandated him to use his good offices with the parties\nin Sudan and neighbouring States, complementing regional peace efforts, including those of\nAfrican Union (AU) and the east African regional bloc, Intergovernmental Authority on\nDevelopment (IGAD)."},{"id":"a-hrc-57-crp-6-p0069","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"69","seq":74,"section":"B. International and Regional Political Initiatives","text":"From 11 to 19 July 2024, the Personal Envoy held proximity talks with representatives\nof the parties to the conflict on measures to ensure the distribution of humanitarian assistance\nto all the Sudanese population in need and options to ensure the protection of civilians across\nthe Sudan. Upon the conclusion of these talks on 19 July 2024, the Envoy considered that the\nGeneva discussions were “an encouraging initial step in a longer and complex process.”86 He\nwelcomed the commitments announced that day by one of the two parties to enhance\nhumanitarian assistance and the protection of civilians. He also stated that he intends to\nremain in close contact with the leadership of the two parties, to follow up on the\nimplementation of commitments and to engage them on critical issues."},{"id":"a-hrc-57-crp-6-p0070","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"70","seq":75,"section":"B. International and Regional Political Initiatives","text":"As mentioned earlier, the United States of America and Saudi Arabia also co-\nfacilitated talks between the SAF and RSF in Jeddah, Saudi Arabia, resulting in the SAF and\nRSF signing the Jeddah Declaration of Commitment to Protect the Civilians of the Sudan on\n11 May 2023. Another round of talks took place in Manama, Bahrain, in January 2024. A\nnew round of talks took place in Geneva, Switzerland, in August 2024, with the participation\nof the United Nations and the AU, leading to an agreement to open the border for\nhumanitarian aid in Adré, Chad.87"},{"id":"a-hrc-57-crp-6-p0071","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"71","seq":76,"section":"C. United Nations and African Union Peacekeeping Initiatives in the Sudan","text":"For the past 20 years, the Sudan has had regional or international peace-keeping presence, mandated\nto protect civilians. In July 2004, following the violent conflict that broke out in Darfur in 2003 between\nthe Government of Sudan and militias, and other armed groups, leading to widespread atrocities and mass\ndisplacement of civilians, the African Union decided to deploy the African Union Mission in Sudan\n(AMIS). AMIS was initially deployed to Darfur as an observer mission, following the signing of the\nN’Djamena Humanitarian Ceasefire Agreement between the Government of Sudan and two rebel\nmovements, the Sudan People’s Liberation Movement/Army (SPLM/ A) and the Justice and Equality\nMovement (JEM). In October 2004, its mandate was extended to include the protection of civilians whom\nit encounters under imminent threat and in the immediate vicinity, within resources and capability, it being\nunderstood that the protection of the civilian population is the responsibility of the Government of Sudan. 88"},{"id":"a-hrc-57-crp-6-p0072","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"72","seq":77,"section":"C. United Nations and African Union Peacekeeping Initiatives in the Sudan","text":"In 2005, having determined that the situation that was prevailing in the Sudan continued to constitute\na threat to international peace and security, the United Nations Security Council, decided to establish the\nUnited Nations Mission in the Sudan (UNMIS).89 UNMIS was mandated to support implementation of the\nComprehensive Peace Agreement signed on 9 January 2005 between the Government of Sudan and the\nSudan People's Liberation Movement/Army (SPLM/A). UNMIS was also mandated to facilitate the\nvoluntary return of refugees and displaced persons; provide demining assistance; and contribute towards\ninternational efforts to protect and promote human rights in the Sudan. Significantly, UNMISS was further\nauthorized, “without prejudice to the responsibility of the Government of the Sudan, to protect civilians\nunder imminent threat of physical violence.”90 The mandate of UNMIS ended on 9 July 2011, following\nthe completion of the interim period agreed upon by the Government of Sudan and SPLM/A during the\nsigning of the CPA."},{"id":"a-hrc-57-crp-6-p0073","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"73","seq":78,"section":"C. United Nations and African Union Peacekeeping Initiatives in the Sudan","text":"In 2007, a United Nations-African Union Hybrid Operation (UNAMID) was deployed in Darfur. 91\nUNAMID, which took over from AMIS, was mandated to facilitate the delivery of humanitarian assistance\nand the safety and security of humanitarian actors; the protection of civilians, without prejudice to the\nresponsibility of the Government of the Sudan; mediation between the Government of the Sudan and the\nnon-signatory armed groups on the basis of the Doha Document for Peace in Darfur; and support to the\nmediation of community conflict, including through measures to address its root causes, in conjunction\nwith the United Nations country team. UNAMID’s mandate ended on 31 December 2020 92 following\nconsideration of the measures taken by the Government of Sudan to address the conflict in Darfur, as well\nas the Government of Sudan’s National Plan for Civilian Protection 93 and its expressed commitment to\nassume full responsibility for the protection of its civilian citizens, to comply strictly with all international\nstandards for the protection of civilians, including proactive monitoring and anticipation, increased army\nand judicial police deployment, and community protection, and to facilitate humanitarian assistance,\nincluding through full and unhindered humanitarian access and ensuring the safety and security of\nhumanitarian personnel.94"},{"id":"a-hrc-57-crp-6-p0074","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"74","seq":79,"section":"C. United Nations and African Union Peacekeeping Initiatives in the Sudan","text":"In June 2020, at the request of the Government of Sudan, the United Nations Security Council\ndecided to establish UNITAMS, a special political mission mandated to assist the political transition,\nprogress towards democratic governance, in the protection and promotion of human rights, and sustainable\npeace; support peace processes and implementation of future peace agreements; assist peacebuilding,\ncivilian protection, and rule of law, and to support the mobilization of economic and development assistance\nand coordination of humanitarian assistance.95 However, as indicated earlier, on 16 November 2023, the\ngovernment of Sudan requested that the United Nations immediately terminate the UNITAMS mission\nciting fundamental change of the circumstances that had led to its establishment.96 Consequently, on 1\nDecember, the Security Council decided to terminate the mandate of the UNITAMS. 97 UNITAMS officially\nexited Sudan on 29 February 2024. Since then, there has been no regional or international presence in the\nSudan responsible for protecting civilians in Sudan, leaving a significant gap in the protection of civilians,\nwhich has been further exacerbated by the current conflict."},{"id":"a-hrc-57-crp-6-p0075","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"75","seq":80,"section":"D. Key actors to the conflict","text":"The two main parties to the armed conflict are the SAF and the RSF. Both sides rely\non regular military and paramilitary forces, auxiliary militias, allied militias, and extensive\nintelligence and security agencies."},{"id":"a-hrc-57-crp-6-p0076","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"76","seq":81,"section":"1. Sudanese Armed Forces Alliance","text":"The SAF alliance is controlled by a small group of senior officers, and SAF\nCommander-in-Chief, Lieutenant General Abdel Fattah Burhan. General Al Burhan sets the\npolitical and military strategy, and his most senior military officers control the Transitional\nSovereignty Council, the SAF, national ministries and state governments, leaving the\ngovernment administration firmly in the hands of the military. In addition to the General\nIntelligence Service, the SAF has its own Military Intelligence that reports directly to General\nAl Burhan. After the 2021 military coup, and exacerbated by the armed conflict, the SAF\nMilitary Intelligence and the General Intelligence Services have gained in influence. They\ndispose of largely unchecked powers to pursue anyone seen as supporting the RSF or\nopposing SAF military rule. 98"},{"id":"a-hrc-57-crp-6-p0077","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"77","seq":82,"section":"1. Sudanese Armed Forces Alliance","text":"The SAF has an Air Force composed of planes and supplemented by newly acquired\narmed drones. SAF’s regular ground forces are organized in military regions that are home\nto corps and divisions, which are further divided into brigades and their garrisons. Even at\nthe outset of the conflict, SAF corps and divisions had an actual troop strength far below the\nsize of those of most other conventional armies. This is due to several factors. Under former\nPresident Al Bashir, auxiliary forces (including the RSF) were prioritized as a counterbalance\nto the SAF. South Sudanese SAF soldiers left the army for South Sudan following its\nindependence in 2011. During the current conflict, the SAF heavily relied on its Air Force,\nand sought to strengthen its ground forces, which prior to the conflict included the RSF,\nthrough a massive mobilization drive, the reactivation of paramilitary forces controlled by\nthe intelligence services and the establishment of new armed groups.99\nMilitary Intelligence and General Intelligence Service"},{"id":"a-hrc-57-crp-6-p0078","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"78","seq":83,"section":"1. Sudanese Armed Forces Alliance","text":"Military intelligence forms part of the SAF, although it seems to operate with\nconsiderable autonomy from the general military chain of command. Military Intelligence\nsections are embedded in SAF’s divisions.100"},{"id":"a-hrc-57-crp-6-p0079","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"79","seq":84,"section":"1. Sudanese Armed Forces Alliance","text":"During the democratic transition, the General Intelligence Service was formed out of\nthe National Intelligence and Security Service (NISS) which was established under former\nPresident Al Bashir. At the time, its functions, resources, personnel strength and legal powers\nwere significantly reduced in an attempt to curb its human rights violations and bring it under\ncivilian control. However, some officials from the Al Bashir-era have remained in influential\npositions.101"},{"id":"a-hrc-57-crp-6-p0080","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"80","seq":85,"section":"1. Sudanese Armed Forces Alliance","text":"Since the outbreak of the armed conflict, GIS has seen a resurgence of its capacity,\ninfluence and powers. Based on a legal amendment from May 2024,102 it regained legal\npowers of interrogation, search, detention and asset seizure, along with immunities shielding\nits personnel from criminal or civil prosecution without approval of its director.103\nCentral Reserve Forces"},{"id":"a-hrc-57-crp-6-p0081","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"81","seq":86,"section":"1. Sudanese Armed Forces Alliance","text":"Although less well-trained and armed, the Central Reserve Forces (CRF) are another\nlarge paramilitary force. While the CRF are formally under the supervision of the Ministry\nof Interior, it is widely considered that they are effectively controlled by the GIS. In the early\nphases of the conflict, the CRF took heavy losses against the more heavily armed RSF forces,\nespecially in Khartoum where RSF overran the CRF headquarters in late June 2023. As a\nresult, CRF has seen a less pronounced role in the ongoing armed conflict compared to\nprevious conflicts.104\nMilitarized state-level administrations"},{"id":"a-hrc-57-crp-6-p0082","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"82","seq":87,"section":"1. Sudanese Armed Forces Alliance","text":"State administrations, including the governors and state security committees chaired\nby them, are increasingly militarized and have been integrated into the efforts to mobilize\nnew forces, neutralize RSF supporters and suppress any opposition to SAF military rule. A\nnumber of State Governors are former SAF officers and regularly appear in military uniform.\nState governors continue to chair state security committees, which existed across the country\neven before the conflict. These committees are composed of the governor, the state director\nof the GIS, the director of state police, SAF senior commanders in the state, reportedly\nincluding senior Military Intelligence officers. The state security committees also include\nsome senior civilian state officials whose functions may have a link to security matters. The\ncommittees coordinate the formulation and implementation of key security policies at state\nlevel.105\nPopular Resistance and Mobilization"},{"id":"a-hrc-57-crp-6-p0083","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"83","seq":88,"section":"1. Sudanese Armed Forces Alliance","text":"The Sudan has a long history of mobilizing and arming civilians to fight as auxiliary\nforces that either support or replace the SAF in the fight against insurgencies in its periphery\nregions. Following this historic pattern, the SAF leadership launched a major effort to\nmobilize recruits.106"},{"id":"a-hrc-57-crp-6-p0084","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"84","seq":89,"section":"1. Sudanese Armed Forces Alliance","text":"Under a “popular resistance” campaign civilians are armed, receive basic military\ntraining and are organized into new units. So far, these new units seem to have been mostly\ndeployed to defend SAF-held areas. In May 2024, SAF General Command issued The\nRegulations of Mobilization and Popular Resistance.107 At the national level, the SAF\nleadership established a National Committee for Mobilization and Popular Resistance to\ncoordinate the mobilization into the SAF and the recruiting, arming and financing of the\npopular resistance. Each state also has its own committees to lead the popular resistance\nmobilization drive. The composition of these popular resistance committees varies and often\nincludes current or former senior military and security officers, local officials, tribal and\nbusiness leaders and also political figures, including a number associated with the Sudanese\nIslamist Movement and the former government of President Al Bashir.108"},{"id":"a-hrc-57-crp-6-p0085","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"85","seq":90,"section":"1. Sudanese Armed Forces Alliance","text":"A minority of the new SAF-aligned armed groups espouse an Islamist ideology. These\ninclude notably the Baraa bin Malik Battalion commanded by Al Misbah Abu Zaid Talha.\nThis armed group has received weapons and training from the SAF, although it has reportedly\nalso its own source of funding linked to Islamist backers. Its existence is well documented –\nnot only because it has engaged in many key battles and taken heavy casualties, but also since\nit extensively publicizes its exploits on social media. There are reportedly other less visible\nIslamist-leaning SAF-aligned armed groups that are at times also referred to as the “shadow\nbattalions” in the Sudanese popular discourse. Overall, however, Islamist armed groups\ncontinue to be only a minority of SAF-aligned armed groups.109\nDarfur Joint Protection Force and other SAF-Allied Armed Groups"},{"id":"a-hrc-57-crp-6-p0086","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"86","seq":91,"section":"1. Sudanese Armed Forces Alliance","text":"In late April 2023, several armed groups, mainly composed of fighters from non-Arab\nDarfuri ethnic groups, established the Darfur Joint Protection Force, in response to the threat\nof the RSF and allied ethnic Arab militias taking control of the Darfur region at the expense\nof their ethnic base. The Joint Force includes the faction of the Sudan Liberation Movement\nheaded by Minni Minnawi (SLM/Minnawi), and the Justice and Equality Movement (JEM)\nof Jibril Ibrahim. In North Darfur, the Joint Force is headed by Lieutenant General Juma\nHagar, SLM-Minnawi’s senior operational commander in Darfur.110"},{"id":"a-hrc-57-crp-6-p0087","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"87","seq":92,"section":"1. Sudanese Armed Forces Alliance","text":"While the Joint Protection Force members initially sought to maintain a neutral\nposition in the conflict between the RSF and SAF, SLM/Minnawi and JEM announced on 16\nNovember 2023 an end to their neutrality and actively aligned with the SAF. Other groups\ndid not follow and announced the establishment of a separate coordination effort. On the\nground, some cooperation seems to have reportedly continued in light of the common threat\nof the RSF advancing into North Darfur, particularly its siege of El Fasher.111"},{"id":"a-hrc-57-crp-6-p0088","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"88","seq":93,"section":"1. Sudanese Armed Forces Alliance","text":"Groups led by Mustafa Tambour (SLM/Tambour), and the late Khamis Abakar\n(SLM/Sudanese Alliance), the Sudan People’s Liberation Movement-North under Malik\nAgar (SPLM-N/Agar) and some groups from eastern Sudan have also aligned their forces\nwith the SAF. Among others, they provided fighters for mobile forces operating jointly with\nSAF and GIS forces in the southeastern Sudanese states of Sennar, Gedaref and Gezira. 112"},{"id":"a-hrc-57-crp-6-p0089","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"89","seq":94,"section":"1. Sudanese Armed Forces Alliance","text":"SPLM-N General Malik Agar Eyre joined the Transitional Sovereignty Council with\nthe 2020 Juba Peace Agreement and, after the outbreak of conflict, replaced RSF leader,\nGeneral Mohamed Hamdan Dagalo as its deputy chair. While General Agar appears to wield\nlittle influence on SAF’s military strategy and operations, fighters of the SPLM-North/Agar\nfight in and along SAF’s 4th Infantry Division. 113"},{"id":"a-hrc-57-crp-6-p0090","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"90","seq":95,"section":"1. Sudanese Armed Forces Alliance","text":"The SAF, often working through its Military Intelligence service, has also pursued\nalliances with other armed groups and militia leaders on the basis of shared political and\nmilitary objectives or in exchange for payment, weapons and officer positions within the\nSAF. These include, for example, the JEM splinter faction headed by Abdelkarim Bakhit\n“Dabajo”, the Sudan Awakening Revolutionary Council (SARF) linked to former RSF ally\nMusa Hilal, and SLM splinter factions headed by Sadiq al-Fuka and Ibrahim Abdullah Al-\nToum “Bahloul”.114"},{"id":"a-hrc-57-crp-6-p0091","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"91","seq":96,"section":"2. Rapid Support Forces Alliance","text":"The RSF is led by First Commander Lieutenant-General Mohamed Hamdan Dagalo.\nHis older brother, Lieutenant-General Abdelrahim Hamdan Dagalo, is the second in\ncommand. The RSF has operated as a highly mobile ground fighting force that combines\nregular RSF units, its own intelligence service and newly recruited RSF-aligned militias into\nan alliance under the overall control of Lieutenant-General Mohamed Hamdan Dagalo.115"},{"id":"a-hrc-57-crp-6-p0092","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"92","seq":97,"section":"2. Rapid Support Forces Alliance","text":"The RSF has its roots in the longstanding practice of the Sudan’s governments of\narming civilians,116 especially of Arab ethnicity, and organizing them into auxiliary militias\nmotivated by the prospect of loot and a measure of ideology. In the early 2000s, the\nGovernment of the Sudan armed civilians to counter an insurgency in Darfur. Arab nomadic\ntribes without a traditional homeland and wishing to settle, given the encroaching\ndesertification, responded to the call and the Government organized them into militias that\nbecame known as “Janjaweed.”117 In 2005, the Janjaweed were found to have committed, in\nconcert with the Government, serious violations of human rights and international\nhumanitarian law amounting to international crimes.118"},{"id":"a-hrc-57-crp-6-p0093","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"93","seq":98,"section":"2. Rapid Support Forces Alliance","text":"From 2013, facing a renewed insurgency, the Government re-organized some of the\nJanjaweed into what became known as the RSF. Lieutenant-General Mohamed Hamdan\nDagalo was appointed as its commander of operations. The RSF was eventually formally\nrecognized under the Rapid Support Forces Act of 2017. Up to the current conflict, the\nSudanese Government provided the RSF with extensive resources and support. The RSF\nincreased its political influence and military capacity through deployments in Darfur, other\nparts of the Sudan and Yemen. From 2015, the RSF contributed troops to fight in Yemen,\nfurther increasing the RSF’s combat experience, organizational prowess and ambition of its\nleadership. The RSF was also repeatedly deployed in Darfur and other parts of the Sudan to\ncontrol unrest (reportedly committing violations in the process), which further augmented its\nnational clout.119 The withdrawal of the United Nations-African Union Operation in Darfur\n(UNAMID) peacekeepers from Darfur at the end of 2020 also created a security vacuum that\nallowed the RSF to increase its power, especially in Darfur.120"},{"id":"a-hrc-57-crp-6-p0094","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"94","seq":99,"section":"2. Rapid Support Forces Alliance","text":"From the outset of the conflict, the RSF has been equipped with 4x4 light vehicles,\nmany of which converted into “technical” combat vehicles with mounted machine guns, anti-\naircraft guns or multiple launch rocket systems. It also disposed of rocket-propelled grenades\nand some mortars as part of its weaponry. The RSF also seems to have built up large stocks\nof small arms and light weapons that it could rapidly distribute among newly recruited\nauxiliary Arab militia. While these militias have traditionally often used a combination of\n4x4 vehicles (including RSF vehicles), horses and camels to move around, the current\nconflict has seen the militia often operate as armed two- or three-person teams on motorcycles\nthat are deployed alongside 4x4 “technical” combat vehicles. This evolution has allowed RSF\nregular units and their aligned militias to move jointly and rapidly across the battlefield,\noutflank slower SAF forces and conduct rapid attacks on SAF garrisons and looting raids on\ntowns, villages and other civilian areas.121"},{"id":"a-hrc-57-crp-6-p0095","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"95","seq":100,"section":"2. Rapid Support Forces Alliance","text":"From its various deployments in the Sudan and Yemen, the RSF also managed to retain\na number of armoured personnel carriers, and reportedly also a very small number of tanks.\nThe RSF gained a significant number of additional armoured vehicles and heavy weapons\nfrom SAF’s stock when it captured several SAF division headquarters and other SAF\ngarrisons from hastily withdrawing SAF forces. A number of victims and witnesses also\nreported to the Fact-Finding Mission that the RSF has prioritized the looting of larger 4x4\ncivilian vehicles when pillaging civilian areas, with the apparent intent of repurposing them\nfor military purposes.122"},{"id":"a-hrc-57-crp-6-p0096","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"96","seq":101,"section":"2. Rapid Support Forces Alliance","text":"The RSF has reportedly established an RSF Supply Office at the central command\nlevel to manage its overall weapons and equipment procurement and distribution efforts. 123\nRSF Intelligence"},{"id":"a-hrc-57-crp-6-p0097","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"97","seq":102,"section":"2. Rapid Support Forces Alliance","text":"The RSF has its own intelligence service. It was built with the help of the SAF and its\nMilitary Intelligence service, which provided resources, training and seconded officers.\nBefore the conflict, a seconded SAF officer headed the RSF intelligence service. He\nrenounced his position and returned to the SAF immediately upon the outbreak of the\nconflict.124"},{"id":"a-hrc-57-crp-6-p0098","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"98","seq":103,"section":"2. Rapid Support Forces Alliance","text":"RSF intelligence is embedded in the RSF combat units, but also has its own offices.\nIt disposes of centralized specialized units, including a signals intelligence unit with\nspecialized equipment, a counterintelligence unit and a unit to monitor civilians and civil\nsociety. RSF intelligence seems to direct raids that target civilians in RSF-held areas. RSF\nintelligence officers are also present in RSF detention and interrogation centres. These are\nestablished in various locations, including police stations and prisons in RSF-captured areas,\nformer SAF installations and re-purposed civilian buildings.125\nRSF civilian governance structures"},{"id":"a-hrc-57-crp-6-p0099","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"99","seq":104,"section":"2. Rapid Support Forces Alliance","text":"As the conflict progressed, RSF has augmented its efforts to build civilian governance\nstructures. Operating under the control of the RSF senior leadership and state-level military\ncommanders, they are meant to stabilize RSF control and governance of areas under its\ncontrol but remain fledgling institutions. 126\nRSF recruitment"},{"id":"a-hrc-57-crp-6-p0100","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"100","seq":105,"section":"2. Rapid Support Forces Alliance","text":"At the outset of the conflict, RSF consisted of a standing core of troops, supplemented\nby a large number of additional trained RSF reserves. Since then, it has suffered large\nnumbers of casualties but also continuously recruited large numbers of new fighters from its\nheartlands in Darfur, other areas captured from the SAF and also from other Sahel states.\nMany of the newly recruited forces have not become directly part of the RSF itself but serve\nin auxiliary militias that remain under the overall command and control of General Mohamed\nHamdan Dagalo and the RSF senior leadership.127"},{"id":"a-hrc-57-crp-6-p0101","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"101","seq":106,"section":"2. Rapid Support Forces Alliance","text":"Owing to its historical development, the RSF officers corps has been traditionally\ndominated by Arab ethnic groups from Darfur, especially the Mahariya Rizeigat to which the\nDagalo family belongs. In more recent years, the RSF has sought to expand and diversify its\ncorps of officers and allied militia commanders by bringing in former military officers and\nmilitia leaders from other parts of the Sudan’s periphery, including some who are not ethnic\nArabs.128"},{"id":"a-hrc-57-crp-6-p0102","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"102","seq":107,"section":"2. Rapid Support Forces Alliance","text":"From the early stages of the conflict, and reportedly also in anticipation of it, 129 RSF\nsenior leaders, directly and through intermediaries, recruited new forces from neighbouring\nstates and the Sudan’s periphery in exchange for money, weapons and other incentives,\nincluding the prospect of loot. In West Darfur, for instance, RSF units fought together with\nethnic Arab militias that were recruited through Arab ethnic leaders of the West Darfur Native\nAdministration.130"},{"id":"a-hrc-57-crp-6-p0103","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"103","seq":108,"section":"2. Rapid Support Forces Alliance","text":"Whether assembled into new RSF militia units or as RSF-aligned militias, the newly\nrecruited men (and also teenage boys) typically fight alongside their ethnic kin and serve\nunder officers from their own ethnic subgroup or clan. In particular in Darfur, this has\nfurthered the intertwining of preexisting localized inter-ethnic violent conflicts with the\narmed conflict between the RSF and SAF.131"},{"id":"a-hrc-57-crp-6-p0104","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"104","seq":109,"section":"2. Rapid Support Forces Alliance","text":"The multiple streams of recruitment, and its often-uncontrolled nature due to the use\nof intermediaries, have resulted in a situation where the RSF leadership’s command and\ncontrol over its new commanders and their fighters may compete with tribal and other\npreexisting loyalties. Furthermore, the broader political and military objectives of the RSF\nleadership are not always aligned with the looting interests and personal ambitions of the new\nfield commanders and their fighters. Both factors create command and control challenges\nthat the RSF has struggled to tackle.132\nRSF allied militias"},{"id":"a-hrc-57-crp-6-p0105","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"105","seq":110,"section":"2. Rapid Support Forces Alliance","text":"General Mohamed Hamdan Dagalo forged an alliance of the RSF with various RSF-\naligned militias. Some of the RSF’s key commanders and officials in charge of intelligence,\nprocurement or recruitment are members of the extended Dagalo family or have close ties to\nit. Units are newly mobilized, largely along ethnic lines, from the Arab ethnic groups of\nwestern Sudan and allegedly neighbouring Sahel states. These are joined by a number of\nmilitia commanders and their fighters from other parts of the Sudan’s periphery and some\ndefecting commanders from SAF and SAF-aligned armed groups. The Arab tribal militias,\nmainly from Darfur and Kordofan States, are allied with and have been fighting alongside\nthe RSF. Several victims and witnesses interviewed by the Fact-Finding Mission said that\nthey saw the Arab tribal leaders and militias engaged in military hostilities, including\nconducting house to house raids and manning checkpoints, alongside RSF in Darfur and\nKhartoum.133"},{"id":"a-hrc-57-crp-6-p0106","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"106","seq":111,"section":"2. Rapid Support Forces Alliance","text":"The Al Jabha al Thalitha-Tamazuj,134 commonly called “Tamazuj” or “Third Front\nTamazuj”, is also allied to the RSF.135 It gained notoriety following the 2020 Juba Agreement\nfor Peace in the Sudan, which it signed as an armed group operating in Darfur and Kordofan\nstates.136 Multiple experts and witnesses told the Fact-Finding Mission that Tamazuj faction\nforces including recognizable military leaders were operating alongside the RSF and the Arab\nmilitia, especially during the violence in El Geneina.137"},{"id":"a-hrc-57-crp-6-p0107","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"107","seq":112,"section":"3. Other Armed Groups","text":"A number of armed groups assert that they are neither aligned with the SAF nor RSF.\nThese include the factions of the Sudan Liberation Movement of Abdul Wahid Mohammed\nal-Nur (SLM/Al-Nur) and El Hadi Idriss (SLM/Transitional Council) and the Gathering of\nthe Sudan Liberation Forces of al-Tahir Hajar in Darfur and the SPLM-N/Al-Hilu, which\ncontrols parts of South Kordofan State and Blue Nile State.138"},{"id":"a-hrc-57-crp-6-p0108","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"108","seq":113,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"The conflict between the SAF and the RSF is often described as a dispute over power\nbetween the two aforementioned commanders, General Al Burhan and General Mohamed\nHamdan Dagalo. There are however deeper roots and complex factors that can be attributed\nto the lack of inclusive and democratic government; vast inequalities, centralization of power\nand resources and marginalization of various communities; and rampant impunity."},{"id":"a-hrc-57-crp-6-p0109","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"109","seq":114,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"Sudan is Africa's third-largest country by area and the third largest by area in the Arab\nLeague. It was the largest country by area in Africa and the Arab League until the secession\nof South Sudan in 2011. Its population of almost 50 million is diverse. Arab speaking\nMuslims are considered the largest single ethnic group at about per cent of the total\npopulation. Other ethnic groups form the majority in certain areas in Sudan including in\nDarfur.139"},{"id":"a-hrc-57-crp-6-p0110","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"110","seq":115,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"Historically, tension exists between the various ethnic groups in the Sudan. Since its\nindependence in 1956, the Sudan has been fragmented and stuck in a cycle of violence, which\nis structural and recurring even during times of peace. It experienced extensive periods of\narmed conflicts and political strife. Many of them had an ethnic component, and armed\ngroups were mostly formed along ethnic lines. The tension goes back to pre-colonial times,\nbut was exacerbated by the colonial rulers, who marginalized the areas outside the Nile basin\nand adopted a centralized governance structures from the capital, Khartoum. Schools,\nhospitals and other state services were predominantly established in Khartoum state. Post-\ncolonial rulers adopted a similar approach and continued neglecting the other parts of the\nSudan.140"},{"id":"a-hrc-57-crp-6-p0111","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"111","seq":116,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"Many of those who took up arms in the prior conflicts belonged to the poorest\ncommunities outside Khartoum. Those areas                 remain massively neglected and\nunderdeveloped, which has resulted in an inequitable distribution of wealth and power,\nfurther increasing tension between different communities.141 Their poverty was caused, in\npart, by neglect from the centre, underdevelopment, discrimination and ecological and\ndemographic changes, in particular the drought and desertification in the 1970s-1980s. As a\nresult, the fight for scarce resources became more intense between agriculturalists and cattle\nherders. In Darfur, for instance, cattle herders in search of pasture and water often invaded\nthe fields and orchards of the agriculturalists, and this led to bloody clashes. Corridors that\nwere agreed upon amongst the tribes to facilitate the movements of cattle for many years\nwere not respected. As fertile land became scarce, settled people’s tolerance of the seasonal\nvisitors diminished.142 The crisis is also influenced by regional factors, most importantly the\ncontinuous supply of weapons and other items that fed the current and earlier conflicts.143"},{"id":"a-hrc-57-crp-6-p0112","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"112","seq":117,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"Moreover, since independence, the Sudan has struggled with internal political\ninstability, leading to several military takeovers and restrictive military rule imposed on the\ncivilian population who were excluded from participation in political processes and were\nrepressed by powerful state security forces. This situation was aggravated under former\nPresident Omar Al Bashir's 30-year rule, during which the State controlled most economic\nresources, which were very poorly distributed, leading to multiple armed conflicts and\nsignificant human rights violations by various actors. Former President Al Bashir’s regime\nalso imposed strict Shari’a laws, initially introduced by his predecessor President Nimeiri in\n1983 as the ‘September Laws’, which aimed to introduce Islamic governance in the entire\ncountry. President Nimeiry was allied with the Muslim Brotherhood led by al-Turabi, who\nopenly supported the introduction of these ‘September Laws’, which imposed harsh penalties\nincluding lashing and amputation. In an attempt to take control of newly discovered oil fields\nin between the border between North and South of the Sudan, President Nimeiri also\nabrogated the Addis Ababa Agreement of 1972, which had granted Southern Sudan, which\nwas predominantly Christian, regional autonomy and recognised the diversity of the\nSudanese society. The southern-based Sudanese People’s Liberation Movement (SPLM), and\nits military wing, the Sudanese People’s Liberation Army (SPLA), which emerged mid-1983,\nopposed these changes and denounced the September Laws and the severe punishments\nfollowing from them. This ultimately led to civil war at the end of 1983. In 1984, President\nNimeiri declared a state of emergency, thereby granting special powers to the military. 144"},{"id":"a-hrc-57-crp-6-p0113","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"113","seq":118,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"The severe drought and desertification, which hit the Sudan in the period from 1983\nto 1985, put fuel on the crisis, as it gravely impacted the agricultural productivity and food\navailability, leading to a famine by the end of 1984.145 Due to the economic crisis in the\ncountry, President Nimeiri was removed from his position after a mass protest in 1985, which\nled to the freeze of the September laws to enhance the Sudan’s transition to democracy. A\nmilitary officer, General Abdel Rahman Suwar al-Dahab seized power from 6 April 1985 to\n6 May 1986, paving the way to general elections in 1986. This led to the only period of\ndemocratic rule from 1986 to 1989. Following elections, he surrendered power to a civilian\ngovernment with Mr. Ahmed al-Mirghani as head of state Mr. Sadiq al-Mahdi as prime\nminister. Several Sudanese that the Fact-Finding Mission spoke to still recall the name of\nGeneral Suwar al-Dahab with respect for stepping aside to enable a civilian rule."},{"id":"a-hrc-57-crp-6-p0114","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"114","seq":119,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"This period did not last long however and the coalition government that was\ncomposed of contradictory allies could not rule effectively. A military coup d’etat led by\nGeneral Omar al Bashir ousted the civilian government, detaining many of its political\nfigures. General Al Bashir became president until his ousting in 2019. Establishing a strict\nIslamic rule, he reinstated the September laws and incorporated them into the 1991 Sudanese\nCriminal Act.146"},{"id":"a-hrc-57-crp-6-p0115","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"115","seq":120,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"The military establishment could not adequately manage the country despite turning\nitself into a civilian government. Human rights groups continued to report serious violations\nof human rights and international humanitarian law in the country and the impunity that\nprevailed. In 1993, the then United Nations Commission on Human Rights, by Resolution\n1993/60, appointed the first Special Rapporteur on the situation of human rights in the Sudan.\nThe mandate continued, with brief interruption, until 2005 when the United Nations\nCommission on Human Rights was replaced by the Human Rights Council.147 The reports of\nthe respective Special Rapporteurs document scores of systematic massive violations of\nhuman rights.148 They include extrajudicial killings and summary executions, enforced or\ninvoluntary disappearances, torture and other cruel, inhuman or degrading treatment,\narbitrary arrest and detention, and freedom of expression, association and peaceful\nassembly.149 The then newly established United Nations Human Rights Council continued to\nengage with the Sudan, using various formula to nudge it to address such violations, but with\nno avail.150 Report after report described how the Government failed to implement\nrecommendations of United Nations experts in areas such as deepening efforts to combat\nimpunity, working with all partners to facilitate humanitarian assistance, preventing the\ninterference of government in the activities of civil society, and enhancing national dialogue\nto realize an inclusive, transparent process.151"},{"id":"a-hrc-57-crp-6-p0116","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"116","seq":121,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"Conflict after conflict also persisted and more than 46 peace agreements have been\nsigned since the Sudan’s independence.152 One key weakness common to all past peace\nprocesses was the focus on ending the conflict without addressing the root causes of the\nconflict or enforcing accountability for mass atrocities. This has persisted, despite\nrecommendations by Sudan-focused international initiatives, including the 2005 Darfur COI\n153\n, and the African Union High-Level Panel on Darfur (AUPD) established by the African\nUnion Peace and Security Council.154 The report of the 2005 Darfur COI highlighted grave\nviolations of human rights and international humanitarian law in Darfur, potentially\namounting to crimes against humanity and war crimes, committed by the government forces\nand Janjaweed militias, and by rebel forces, in particular the SLM/A and JEM, necessitating\nurgent action to ensure accountability and justice for the victims. The report underscored the\nseverity of the crimes committed and the need for robust international intervention to address\nthe ongoing crisis.155 The AUPD similarly stressed the importance of justice for the victims,\nas well lasting peace and reconciliation.156"},{"id":"a-hrc-57-crp-6-p0117","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"117","seq":122,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"While the recommendation of the 2005 Darfur COI for the referral of the situation in\nDarfur to the Prosecutor of the International Criminal Court was implemented, the proposed\ncreation of a compensation commission for victims, a truth and reconciliation commission,\nand other proposed measures to end impunity were not. The AUPD recommended addressing\nthe root causes of the conflict, including the marginalization of Darfur in any political\nprocess; strengthening the Sudan’s national justice system to address the crimes committed\nduring the conflict, the establishment of a hybrid court to deal particularly with the most\nserious crimes; the establishment of a Truth Justice and Reconciliation Commission (TJRC)\nmeasures for reparations for the victims of the conflict. These recommendations were not\nimplemented, ultimately leading to another crisis. Also, in the latest negotiations following\nthe ousting of then-President Al Bashir on 11 April 2019, accountability and root causes were\nnot addressed, and the overall situation did not fundamentally change afterward."},{"id":"a-hrc-57-crp-6-p0118","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"118","seq":123,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"The succeeding period saw no improvement in terms of civilian participation in\npolitical processes, despite the December 2018 civilian popular uprising, which lasted for 10\nmonths, and planned transition to a democratic civilian rule. The civilian movement,\norganized through Resistance Committees, which had evolved from local grassroots groups\nloosely connected to each other since 2013 and further developed in a network since 2019,\nwas perceived as a threat by the military that applied repressive methods to suppress it.157"},{"id":"a-hrc-57-crp-6-p0119","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"119","seq":124,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"Women activists played a leading role in the popular uprising, and continue to play an\nimportant role in activism, which makes them a target during the current conflict. But the\nviolence against women is not new to this conflict. Structural violence against women and\ngirls, including sexual and gender-based violence, is part of a broader spectrum of gender\ninequalities rooted in the Sudan’s patriarchal social norms and culture, which were\nconsolidated and institutionalized by former President Al Bashir’s rule158, denying women\nand girls’ “fundamental rights to decisions over their bodies, freedoms, and participation in\ndecision-making processes.”159 While their leading role in the uprising could have led to an\neffective transformation of patriarchal norms and policies, the transitional civilian\ngovernment did not take significant steps in that direction, and women were marginalized in\nsubsequent decision-making and peace negotiation efforts, notably the Juba Peace Talks in\n2020.160 Continued impunity for acts of sexual and gender-based violence, due to political\nunwillingness to hold perpetrators accountable, inadequate legal tools and sociocultural\nbarriers deterring victims from reporting incidents have also arguably greatly contributed to\ntheir perpetuation.161"},{"id":"a-hrc-57-crp-6-p0120","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"120","seq":125,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"Since the onset of the Darfur conflict in 2003, there have been numerous reports of\nconflict-related sexual violence, but the Sudanese judicial system has largely failed to\nprosecute these crimes domestically.162 The international community has taken some steps\ntowards justice with the opening of the investigations by the International Criminal Court in\n2005163, and the Office of the Prosecutor concluding that “rape is an integral part of the\npattern of destruction that the Government of the Sudan is inflicting upon the target groups\nin Darfur” 164 The Sudan has been notably reluctant to acknowledge the existence of conflict-\nrelated sexual violence, often denying such incidents outright and blaming such crimes on\nindividual moral failings. This stance is also influenced by the fear of international\ncondemnation and the potential legal repercussions, as admitting to such crimes may\nundermine the parties’ legitimacy in peace talks and negotiations."},{"id":"a-hrc-57-crp-6-p0121","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"121","seq":126,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"The Sudan also has a long history of recruitment and use of children in hostilities.\nReports allege, among others, that the Sudanese Armed Forces recruited and used children\nduring the Al Bashir era. They were popularly referred to as \"Jana Army\".165 In Darfur, armed\ngroups active in the conflict that began in 2003 already appeared on the list of the Secretary-\nGeneral’s annual report on children and armed conflict for recruiting and using children in\nhostilities in 2005.166 These included the “Janjaweed”, the JEM and the Sudan Liberation\nMovement/Army (SLM/A). At that time, the Janjaweed were aligned with the central\nGovernment and effectively controlled by its security forces. 167 After the restructuration of\nthe Janjaweed and formation of the RSF, reports alleged that the RSF recruited underage\nboys in Darfur, who were deployed to fight in Yemen alongside the Saudi-led coalition in\n2016 and 2017.168 Under the promise of financial gain, many families encouraged their young\nboys to join the fight. The widespread use of children in the current conflict in the Sudan, as\nfurther elaborated in this report, demonstrates that this decades-old problem is far from being\neradicated. The practice, mostly carried out by militias, feeds on severe and widespread\npoverty, lack of access to basic services or educational opportunities, scarce resources and\nlivelihood opportunities and massive displacement of population generated by decades of\nwar and require greater attention and resources to be devoted to its structural causes."},{"id":"a-hrc-57-crp-6-p0122","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"122","seq":127,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"The community leaders and civil society representatives that the Fact-Finding Mission\nspoke to stressed that political and ideological manipulation, recurring violence without\naccountability, and the policy of divide and rule, particularly during the Al Bashir era, have\nintensified differences among various groups. They stressed the need for an inclusive\ndialogue to enable a deeper understanding of grievances and chart the way forward based on\nequality and justice for all citizens of the Sudan."},{"id":"a-hrc-57-crp-6-p0123","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"123","seq":128,"section":"VI. Root causes of violations in the context of the ongoing armed","text":"Accordingly, any solution for lasting peace must address those multifaceted root causes\nincluding the impunity gap."},{"id":"a-hrc-57-crp-6-p0124","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"124","seq":129,"section":"VII. Findings on violations of international human rights law and","text":"Since the outbreak of the conflict in mid-April 2023 between the SAF and the RSF,\nand their respective allied militias, the violence has led to an estimated over 18,800 persons\nkilled and 33,000 injured.169 A substantial number of those are civilians, who have been\nimpacted by airstrikes, heavy artillery shelling, and ground attacks on their homes and\nvillages. The use of explosives with wide area effects in densely populated areas, particularly\nin Khartoum and Darfur, has resulted in large conflict-related casualties including deaths,\ninjuries, and extensive destruction of homes, hospitals, schools and other critical\ninfrastructure, exacerbating the humanitarian crisis. By July 2024, 10.7 million persons were\ninternally displaced, which includes an estimated 7.9 million persons who have been\ninternally displaced since the start of the conflict.170 More than 2.1 million persons fled to\nneighbouring countries.171\na.      Conduct of Hostilities\nAirstrikes and Bombardments affecting civilians"},{"id":"a-hrc-57-crp-6-p0125","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"125","seq":130,"section":"VII. Findings on violations of international human rights law and","text":"The conflict started in Greater Khartoum, which has been a major battleground since\nthe conflict began in mid-April 2023. The city has seen heavy fighting, with the SAF utilizing\nairstrikes extensively as a part of their military strategy, and the RSF, lacking air power,\nrelying on heavy artillery, including mortar shelling and rocket launchers. With many of these\nattacks taking place in densely populated areas, civilians in Greater Khartoum and other\nmajor cities in the Sudan, particularly in Darfur, have been trapped in the crossfire. This has\nresulted in heavy civilian casualties and affected access to basic necessities, including food,\nwater, and medical care. These airstrikes and bombardments have also caused large-scale\ndestruction of property. The examples below illustrate the impact of airstrikes and\nbombardments in densely populated areas particularly in Khartoum, El Geneina, Nyala,\nZalingei and other parts of Darfur."},{"id":"a-hrc-57-crp-6-p0126","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"126","seq":131,"section":"VII. Findings on violations of international human rights law and","text":"On 15 April 2023, heavy gunfire and explosions shook Khartoum, generating panic in\nthe city and beyond. The exchange of fire between the SAF and RSF led to constant airstrikes\nand artillery shelling across the tri-city area of Khartoum, Omdurman and Bahri (Greater\nKhartoum). Shelling took place across civilian areas and the conflict spread beyond military\nbases to residential neighbourhoods causing civilian deaths and injuries and large-scale\ndestruction, including of critical bridges. Witnesses also told the Fact-Finding Mission that\nthe neighbourhoods of Umbada, East Nile, Dar al-Salam, Abu Saad, Burri al-Mahas, Al-\nSalama al-Qadema, Salama al-Kababesh, al-Azhari, al-Inkaz, and al-Nahda were subjected\nto frequent airstrikes and shelling.172 Analysis of satellite imagery reveals that these areas are\ndensely populated and contain houses, shops, schools, hospitals, and places of worship."},{"id":"a-hrc-57-crp-6-p0127","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"127","seq":132,"section":"VII. Findings on violations of international human rights law and","text":"From mid-April 2023 onwards, frequent shelling and airstrikes in Greater Khartoum\ncontinued, affecting various neighbourhoods.173 Bombs were reportedly dropped at rapid\nintervals in al-Diyum neighbourhood, a residential area, in Khartoum on 22 April 2023,\nresulting in civilian deaths.174 One witness counted six bombings while hiding under the stairs\nof their shattered building. He saw an airplane circling in the skies once he left the building.\nThe witness saw four people lying on the ground, killed as a result of the attack. All were\ncivilian. He does not recall seeing any RSF members in the vicinity of the attack. According\nto another witness, between April and June 2023, the al-Remila neighbourhood in Khartoum\nsuffered shelling from both the SAF and RSF.175 The witness stated that intense shelling was\noccurring between the SAF and RSF in al-Diyum, controlled by the RSF at the time, and the\nSAF base in al-Amarat. Some of the shells landed in al-Remila due to the infighting in those\nareas. The witness recounted those five or six shells landed in al-Remila, including one that\nstruck a mosque, causing deaths and injuries. The civilian death toll continued to rise."},{"id":"a-hrc-57-crp-6-p0128","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"128","seq":133,"section":"VII. Findings on violations of international human rights law and","text":"The shelling and airstrikes continued without signs of abating in Greater Khartoum.\nOn 10 September 2023, an airstrike hit Goro market in the Mayo area south of Khartoum,\nresulting in the death of more than 30 individuals and injuries to many more, including\nwomen and children, and extensive damage to the market.176 A witness of the attack\nrecounted that although vendors affiliated with the RSF may have been present in the market,\nthey were too spread out for the attack to have specifically targeted them, and that the\nmajority of those killed were civilians.177"},{"id":"a-hrc-57-crp-6-p0129","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"129","seq":134,"section":"VII. Findings on violations of international human rights law and","text":"Airstrikes and shelling were so prevalent that one could witness multiple strikes. An\ninterviewee told the Fact-Finding Mission that he witnessed several airstrikes in Haj Youssef\nneighbourhood of East Nile, Khartoum. In August 2023, his brother was killed along with at\nleast five other people, including a child, when two airstrikes landed in the neighbourhood.\nHe witnessed two additional airstrikes in East Nile at the end of 2023 and the beginning of\n2024. One of these airstrikes, carried out by an aircraft, destroyed two houses and killed a\nfamily of seven. The second airstrike resulted in 13 injuries and the death of a child. 178"},{"id":"a-hrc-57-crp-6-p0130","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"130","seq":135,"section":"VII. Findings on violations of international human rights law and","text":"An interviewee recounted how an airplane attack in December 2023 destroyed his\nfamily's three-story house in the Abu Saad neighbourhood of Omdurman. 179 The aerial\nbombing killed his mother, brother, and sister. His other brother heard the plane hovering\noverhead at the time of the attack. According to the interviewee, an RSF vehicle had been in\nthe neighbourhood several days before the attack but had left three to four days prior. The\ninterviewee provided the Fact-Finding Mission with videos and images of the destroyed\nhouse.180 Using the house's coordinates, the Fact-Finding Mission confirmed via satellite\nimagery that the house was damaged following the alleged aerial bombardment. 181"},{"id":"a-hrc-57-crp-6-p0131","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"131","seq":136,"section":"VII. Findings on violations of international human rights law and","text":"The conflict immediately spread to Darfur, widely affecting its towns. In May and\nJune 2023, there was intense artillery shelling of various neighbourhoods in El Geneina, West\nDarfur including al-Jamarek and al-Madares neighbourhoods.182 Mortars fell on civilian\nhouses,183 medical facilities,184 internally displaced persons (IDP) sites and schools.185 The\nshelling reportedly came from west and south of El Geneina, areas which were under the\ncontrol of the RSF. 186 The Fact-Finding Mission also conducted interviews with witnesses\nwho, in the beginning of November 2023, experienced intense shelling of the IDP camp and\nmarketplace in Ardamata, northeast of El Geneina, resulting in many casualties.187 The attack\ncame after fierce battles between the RSF and SAF near SAF’s 15th Infantry Division base\nin Ardamata, which resulted in the withdrawal of the 15th Infantry Division."},{"id":"a-hrc-57-crp-6-p0132","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"132","seq":137,"section":"VII. Findings on violations of international human rights law and","text":"In Nyala, South Darfur, the RSF and their allies engaged in a six-month armed\nconfrontation with the 16th Infantry Division of the SAF for control of the city. During that\nperiod the SAF launched heavy airstrikes; and the RSF constantly shelled the area affecting\ncivilian neighbourhoods. An interviewee told the Fact-Finding Mission that her family house\nin Alemidad neighbourhood was struck in June 2023, killing her pregnant sister-in-law,\nmother, and two brothers.188 Another interviewee told the Fact-Finding Mission that the SAF\nwere launching artillery from their base. A shell fell in his neighbourhood, killing his\nneighbour, the neighbour’s brother and sister.189 The Taiba bridge in Nyala was shelled in\nAugust 2023, causing death and injury to civilians who were seeking shelter near the\nbridge.190 The fighting persisted until 26 October 2023, when the RSF captured SAF’s base\nin Nyala."},{"id":"a-hrc-57-crp-6-p0133","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"133","seq":138,"section":"VII. Findings on violations of international human rights law and","text":"In Zalingei, Central Darfur, armed confrontations ensued between the SAF and RSF\nand their allied militias, from 15 April until 31 October 2023, when the RSF captured the\nSAF base. During that period, the SAF and RSF exchanged shelling affecting civilian\nneighbourhoods, resulting in civilian deaths, injuries and displacement, including in the\nStadium and Kunjumia, neighbourhoods, and Hasahisa IDP camp.191"},{"id":"a-hrc-57-crp-6-p0134","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"134","seq":139,"section":"VII. Findings on violations of international human rights law and","text":"In El-Fasher, North Darfur, since April 2023, the RSF and the SAF, along with their\nallied groups, have been engaged in a continuous battle for the control of the city and its\nsurrounding towns and villages, culminating in a siege around the city and increased shelling.\nThe Fact-Finding Mission documented a series of artillery shelling of populated residential\nareas and IDP sites, in and near El-Fasher between May and July 2024, resulting in several\ncivilian deaths and injuries and forcing thousands to flee their homes.192 As a consequence of\nthe siege and increased violence, the Security Council demanded, inter alia, the RSF to end\nthe siege of El-Fasher and called for an immediate cessation of hostilities and de-escalation\nin and around the city and for the withdrawal of all combatants who posed a threat to the\nsafety and security of civilians.193 The RSF launched its last operation to gain control of the\ncity in September 2024 and managed to advance into central areas, breaching SAF’s outer\ndefences and pushing toward key military positions like the Grand Market and 6th Infantry\nDivision Headquarters.This mirrors previous RSF tactics in cities like Nyala and Zalingei,\nwhich saw prolonged shelling followed by a final concentrated offensive. The SAF, supported\nby a coalition of local militias and ex-rebel groups, including the SLM, JEM, and Zaghawa\nmilitias, have been countering the RSF's offensive. While these forces have shown resilience,\nthey continue to lose ground and the RSF continues to gain ground and encircle SAF’s\npositions in the city. These latest clashes in and around El Fasher has led to significant\ncasualties, which need to be further investigated."},{"id":"a-hrc-57-crp-6-p0135","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"135","seq":140,"section":"VII. Findings on violations of international human rights law and","text":"On 5 June 2024, the village of Wad al-Noura in Sudan's Gezira state was subjected to\na violent attack by the RSF and allied militias. The RSF reportedly used weapons with wide-\narea effects, including artillery shells, which was followed by fighters storming the village.\nAttackers are alleged to have used machine guns, automatic rifles, and other weaponry to fire\nat civilians. The attack reportedly resulted in more than 100 killed, including more than 35\nchildren, and many more injured and displaced.194 The Fact-Finding Mission was able to\nverify and geo-locate some of the videos shared online following the attack that illustrate the\nextent of the attack and its significant death toll.195"},{"id":"a-hrc-57-crp-6-p0136","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"136","seq":141,"section":"VII. Findings on violations of international human rights law and","text":"By August 2023, the fighting had escalated to all three Kordofan states.196 In Kadugli,\nSouth Kordofan, armed clashes in August 2023 between SPLM-N/Al-Huli and the SAF,\nusing heavy artillery shelling, allegedly caused the displacement of many residents. 197 In\nSeptember 2024, dozens of people, including many children, were reportedly killed after\nmultiple shells landed on Sennar city.198"},{"id":"a-hrc-57-crp-6-p0137","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"137","seq":142,"section":"VII. Findings on violations of international human rights law and","text":"Schools were also subjected to airstrikes and bombardments, resulting in the death\nand injury of a significant number of children. For example, in South Kordofan, in the\nmorning of 14 March 2024, the SAF reportedly bombed Hadra elementary school, killing 11\nchildren and two teachers, and injuring 46 pupils. 199 According to an eyewitness, the pupils\nheard the sound of an airplane as they were queuing to enter their classrooms. Then the\nairplane dropped bombs one of which hit the school.200 In a separate incident, the RSF\nallegedly shelled a mosque in Al-Tijaniyah neighbourhood in El-Fasher, killing and injuring\nseveral individuals, mostly children.201"},{"id":"a-hrc-57-crp-6-p0138","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"138","seq":143,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission finds, based on the body of evidence gathered, that both the\nSAF and RSF failed to take sufficient measures to minimize the impact of airstrikes or\nartillery shelling on civilians. It notes that international humanitarian law requires that all\nparties to the conflict strictly abide by the principles of distinction, proportionality and\nprecaution. Attacks are considered indiscriminate when they fail to distinguish between\nmilitary objectives and civilians or civilian objectives, because they are not or cannot be\ndirected at a specific military objective, or their effects cannot be limited. Practices\ninconsistent with international humanitarian law, including indiscriminate attacks posing a\nrisk to the lives of civilians, also violate international human rights law.\nDestruction of civilian objects and infrastructure"},{"id":"a-hrc-57-crp-6-p0139","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"139","seq":144,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission established that civilian infrastructure and objects,\nincluding objects indispensable to the survival of the civilian population, were attacked,\ndamaged or destroyed by both the RSF and SAF. As further detailed below, water treatment\nplants and pumping stations, communication networks and electricity supply lines were\ndestroyed in Khartoum, Darfur and other locations, leaving civilians in dire conditions."},{"id":"a-hrc-57-crp-6-p0140","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"140","seq":145,"section":"VII. Findings on violations of international human rights law and","text":"Large-scale destruction of residential homes through airstrikes and shelling left\nthousands of civilians without shelter, forcing many to flee and seek refuge in other locations.\nCivilians reported that shells fell on residential houses, causing extensive damage.202\nDestruction of critical infrastructure was also reported across all the areas affected by the\nconflict. Satellite images, aerial photographs and videos reviewed by the Fact-Finding\nMission showed extensive destruction and damage to property and infrastructure in various\nlocations.203 In Khartoum, aerial bombardments and explosives affected water pipes and\nwater treatment plants, leaving various neighbourhoods with severe water shortages.204"},{"id":"a-hrc-57-crp-6-p0141","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"141","seq":146,"section":"VII. Findings on violations of international human rights law and","text":"Information received by the Fact-Finding Mission confirmed that civilians were left\nin dire straits with no electricity or water, especially in Greater Khartoum and Darfur. 205 In\nmost cases, both the SAF and RSF employed the kind of weapons incapable of distinguishing\ncivilian objects and critical infrastructure, such as bombs and artillery shells."},{"id":"a-hrc-57-crp-6-p0142","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"142","seq":147,"section":"VII. Findings on violations of international human rights law and","text":"Medical facilities in various locations affected by the conflict were also subjected to\nattacks, causing severe disruptions to the health care system. The Fact-Finding Mission\ndocumented a series of attacks on medical facilities, including through airstrikes and shelling:\nIn Khartoum, Al Shaab Teaching206 and Ibn Sina hospitals on 17 April 2023; Al-Roumy\nMedical Centre on 25 April 2023; East Nile hospital on 15 May 2023; 207 Shuhada Hospital\non 30 June and 9-10 October 2023; Al Nao Hospital on 9 October 2023208 and 19 June\n2024.209 In El-Fasher, the South Hospital was shelled on 25, 26 and 31 May 2024, while the\nSaudi hospital was shelled multiple times between May and July 2024. 210 In El-Daein, the\nTeaching Hospital, was struck by an airstrike on 20 August 2024, resulting in civilian deaths\nand injuries."},{"id":"a-hrc-57-crp-6-p0143","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"143","seq":148,"section":"VII. Findings on violations of international human rights law and","text":"The attacks on medical facilities led to destruction and/or permanent closure of some\nof the facilities. Medical personnel also fled the affected areas. As a result, many civilians\nwere left without access to medical treatment, leading to death and contributing to\ndisplacement to seek medical assistance.211"},{"id":"a-hrc-57-crp-6-p0144","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"144","seq":149,"section":"VII. Findings on violations of international human rights law and","text":"The RSF and allied militias also destroyed a significant part of the civilian\ninfrastructure in these areas. Witnesses in different areas of Darfur observed the burning of\nhouses, schools, water wells, shops, food markets, businesses, government and other official\nbuildings including courthouses, medical centres and hospitals.212"},{"id":"a-hrc-57-crp-6-p0145","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"145","seq":150,"section":"VII. Findings on violations of international human rights law and","text":"Based on the foregoing, the Fact-Finding Mission finds that the RSF and its allied\nmilitias engaged in a pattern of destruction of objects indispensable to the survival of the\ncivilian population, including through intentionally directing attacks against specially\nprotected objects, in violation of international humanitarian law. Under international human\nrights law, it finds that these acts violate the economic, social and cultural rights of the civilian\npopulation, in particular their rights to physical and mental health and to food, water and\nhousing.\nPillage\n“We lost everything”\nWords echoed by multiple survivors from Khartoum and Darfur"},{"id":"a-hrc-57-crp-6-p0146","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"146","seq":151,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission also documented widespread pillage and looting,\npredominantly by the RSF, and allied militias. They were sometimes followed by civilians,\nbandits, and groups of looters including “Kassiba”.213 Multiple incidents of pillage and\nlooting, in numerous instances accompanied by killings and other forms of violence against\ncivilians, were reported in and around Khartoum, Gezira, and Darfur, particularly in and near\nthe towns of El Geneina, Ardamata, Nyala, El Fasher and Zalingei. The RSF routinely raided\nhomes, assaulting civilians and looting their property. Several hospitals were looted by the\nRSF, and their staff and patients assaulted or even killed during the attack. Pillage and looting\nwas also witnessed in governmental buildings, courts, office spaces, schools, IDP camps,\nmarkets, at checkpoints or in the street. The pillage and looting resulted in serious deprivation\nof objects indispensable to the survival of the civilian population, including food and\nmedicine."},{"id":"a-hrc-57-crp-6-p0147","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"147","seq":152,"section":"VII. Findings on violations of international human rights law and","text":"Civilians lost their possessions, including cars, money, gold, clothes and furniture and\nother household items, including refrigerators, gas cylinders and household appliances,\nwhich were seized by the RSF and its allied militias. Victims and witnesses recounted\nwidespread pillage and looting in Khartoum, Darfur, Gezira and other areas affected by the\nconflict. An interviewee from El Geneina described how the Janjaweed entered his house\nand searched the rooms. \"They took the chairs, the beds, clothes and furniture, anything they\ncould find in the house they took. [...] This other group of Janjaweed and one RSF found\nmore money, which they took, and they also took the TV screen and the small\nfridge.\"214 Civilians from Gezira similarly narrated how the RSF looted their property in Wad\nMadani, upon seizing the city in December 2023.215 Commercial shops and merchandize in\nstores were also looted.216 The Fact-Finding Mission also received submissions from several\nvictims whose houses were occupied by the RSF and/or their allied militias after they were\ndisplaced from their homes.217 Many fleeing civilians were stopped by the RSF or their allied\nmilitias and forced at gunpoint to hand over their personal items, including mobile phones\nand money.218"},{"id":"a-hrc-57-crp-6-p0148","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"148","seq":153,"section":"VII. Findings on violations of international human rights law and","text":"In Darfur, the pillage, looting and destruction of property affected entire livelihoods\nand civilian structure, including shelter, food and water, the health system, water-stations,\npublic offices and facilities, of non-Arab communities, in particular the Masalit.219 One report\nconcluded that “[t]he pillage, arson and destruction began from the onset of the fighting and\ncontinued long afterward, all but erasing Masalit neighbourhoods from the map after the bulk\nof the community fled in mid-June.”220"},{"id":"a-hrc-57-crp-6-p0149","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"149","seq":154,"section":"VII. Findings on violations of international human rights law and","text":"Many civilians, having been forced to flee their homes, and having lost all their\nproperty and savings to looting and destruction, endured untold humiliation and degradation\nof having to depend on others or relief aid for survival. Several individuals lost their jobs and\nlivelihoods and were forced into a life of extreme hardship due to lack of a source of income,\ncoupled with poverty and the high cost of living in the locations that they fled to. 221 Many\ncivilians spoke of the psychological effects of having to endure extreme hardship after losing\neverything.222"},{"id":"a-hrc-57-crp-6-p0150","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"150","seq":155,"section":"VII. Findings on violations of international human rights law and","text":"The process of documenting the losses has begun. For instance, the Fact-Finding\nMission was provided with a document prepared by a Sudan-based civil society organization,\nlisting looted and destroyed property, including houses, furniture, money, and gold, of 5663\nindividuals who fled from their home areas, mostly Khartoum. 223 The Fact-Finding Mission\nalso received approximately 400 submissions about looting, half of which related to\nKhartoum state, 32 to Gezira state, 1 to al Qadarif, 1 to Kordofan, 1 to Kassala, 1 to Darfur,\n1 to Sennar, and the others were unspecified. Based on the Fact-Finding Mission’s\ndocumentation, this appears to be only a fraction of the reality."},{"id":"a-hrc-57-crp-6-p0151","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"151","seq":156,"section":"VII. Findings on violations of international human rights law and","text":"The looting and destruction, including of cultural property, continues unabated. On 12\nSeptember 2024, the United Nations Educational, Scientific and Cultural Organization\n(UNESCO), raised the alarm over reports of looting of cultural items and damage to museums\nand heritage institutions in the Sudan, including the National Museum of the Sudan.\nUNESCO stressed that the “threat to culture appears to have reached an unprecedented level,\nwith reports of looting of museums, heritage and archaeological sites and private collections,”\nand called upon the public and the art market to refrain from acquiring or taking part in the\nimport, export or transfer of ownership of cultural property from the Sudan.224"},{"id":"a-hrc-57-crp-6-p0152","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"152","seq":157,"section":"VII. Findings on violations of international human rights law and","text":"Based on the foregoing, the Fact-Finding Mission finds that the RSF and its allied\nmilitias, at times with the involvement of civilians or Kassiba, engaged in a pattern of pillage\nand looting, attacking, removing, rendering useless or destroying objects indispensable to the\nsurvival of the civilian population in violation of international humanitarian law. Under\ninternational human rights law, it finds that these acts violate the economic, social and\ncultural rights of the civilian population, in particular their rights to physical and mental\nhealth and to food, water and housing.\nb.     Ethnic-based attacks in El Geneina"},{"id":"a-hrc-57-crp-6-p0153","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"153","seq":158,"section":"VII. Findings on violations of international human rights law and","text":"In some parts of the country, the violence had an ethnic undertone. This is particularly\nmanifest in the attacks carried out against non-Arab communities, including the Masalit, in\nWest Darfur. In El Geneina, the capital of West Darfur, the current conflict further stretched\npre-existing tribal tensions. Between April and November 2023, the conflict in El Geneina\npitted the RSF and its predominately Arab allied militias against the SAF and their allies,\nincluding the Sudanese Alliance led at the time by the Governor of West Darfur Khamis\nAbakar, and other Masalit ethnic groups. The ethnic violence that ensued reflects enduring\ntensions that have been simmering for many years and can be traced back several decades."},{"id":"a-hrc-57-crp-6-p0154","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"154","seq":159,"section":"VII. Findings on violations of international human rights law and","text":"There is a long history of ethnic tensions in Darfur as was stated earlier. 225 The 2005\nDarfur COI had found that the Government of the Sudan and the Janjaweed associated with\nit were responsible for a number of violations of international human rights and humanitarian\nlaw, some of which violations were very likely to amount to war crimes and crimes against\nhumanity.226 The majority of the victims of the attacks between 2003 and 2005 belonged to\nAfrican tribes, in particular the Fur, Masalit and Zaghawa tribes.227 Until the 3 October 2020\nJuba Peace Agreement signed between the Transitional Government of Prime Minister\nHamdok and some Darfurian militias, the Darfur conflict produced a severe humanitarian\ncrisis, with thousands killed and millions displaced."},{"id":"a-hrc-57-crp-6-p0155","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"155","seq":160,"section":"VII. Findings on violations of international human rights law and","text":"Nevertheless between 2019 and 2021, West Darfur experienced several violent clashes\nbetween the Masalit and Arab communities, fueled by longstanding ethnic tensions,\ncompetition over land and resources, and the legacy of the broader Darfur conflict that began\nin 2003. Attacks increased after the end of the UNAMID’s mandate in late 2020. Prior to the\ncurrent conflict, El Geneina was an ethnically diverse city with a population of around\n540,000 inhabitants. The population was predominately Masalit, along with a notable Arab\npopulation."},{"id":"a-hrc-57-crp-6-p0156","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"156","seq":161,"section":"VII. Findings on violations of international human rights law and","text":"Between 15 and 24 April 2023, El Geneina experienced sporadic violence, escalating\nfrom the broader conflict between the SAF and RSF that had erupted nationwide. Initially,\nclashes in El Geneina started as part of the conflict between these military forces but quickly\ndescended into ethnically charged violence. During this period, a man aligned to the Masalit\nmilitia reportedly shot and killed another person from the Arab community, which further\nheightened tensions.228 Government officials, civil society actors, and other leaders among\nthe Masalit and Arab communities in El Geneina met on 23 April 2023 in an effort to curb\nthe tensions and prevent the conflict between the SAF and RSF from expanding to El\nGeneina.229 These efforts were cut short when fighting erupted on the following day."},{"id":"a-hrc-57-crp-6-p0157","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"157","seq":162,"section":"VII. Findings on violations of international human rights law and","text":"On 24 April 2023, the RSF and its allied militias attacked a SAF convoy in the al-\nJamarek neighbourhood in El Geneina.230 The RSF and allied militias encircled the al-\nJamarek, al-Thawra, al-Tadamon and al-Madares neighbourhoods, subjecting them to intense\nmortar shelling and sniper fire, causing a large number of casualties.231 As some of the SAF\nvehicles retreated to their base in Ardamata,232 a number of SAF soldiers reportedly took\ncover in civilian neighbourhoods.233 The RSF and allied militias began a campaign of\nviolence targeting the Masalit community in El Geneina, resulting in large-scale atrocities\nincluding thousands of killings,234 torture, rape and other forms of sexual violence, pillage\nand destruction of property. During these attacks, the SAF failed to protect the civilian\npopulation."},{"id":"a-hrc-57-crp-6-p0158","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"158","seq":163,"section":"VII. Findings on violations of international human rights law and","text":"In addition to the ethnic undertone, violations targeting the Masalit community were\nalso perpetrated along intersecting gender lines. Masalit men were systematically targeted for\nkilling. The RSF and allied militias went door to door in Masalit neighbourhoods, looking\nfor men and brutally attacking and killing them, sometimes in front of their families. 235\nLawyers, doctors, human rights defenders, academics, community and religious leaders were\nalso specifically targeted.236 RSF commanders reportedly issued orders to “comb the city”\nand place checkpoints throughout.237 One interviewee explained that the RSF broke into their\nhouse in al-Tadamon and opened fire on the interviewee’s 10-year-old son and two nephews\n(16 and 17 years old), killing them on the spot. They then took the interviewee and the rest\nof the family outside the house and told them that they should look for another place to live\nbecause they are Masalit.238 Another interviewee explained how the RSF attacked their house\nin al-Jabal neighbourhood. They insulted, beat, and then shot and killed five men. They\ncompared her husband to a black donkey before killing him.239"},{"id":"a-hrc-57-crp-6-p0159","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"159","seq":164,"section":"VII. Findings on violations of international human rights law and","text":"Women were assaulted, raped and robbed of their belongings because of their gender\nand ethnicity. The attackers used derogative terms about the Masalit in the context of rape\nand other forms of sexual violence. A survivor from El Geneina told the Fact-Finding Mission\nthat her perpetrator said to her: “We will make you, the Masalit girls, give birth to Arab\nchildren” after raping her inside her house at gunpoint.240 Several women reported that they\nwere explicitly told by the RSF and its allied militias to leave for Chad and not to return or\nelse they would be harmed.241"},{"id":"a-hrc-57-crp-6-p0160","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"160","seq":165,"section":"VII. Findings on violations of international human rights law and","text":"The height of the assault on El Geneina occurred on 14 and 15 June 2023, following\nthe capture and subsequent killing of the Governor (Wali) of West Darfur, Khamis Abakar, a\nMasalit. The Governor had been in the custody of the RSF prior to his killing. During the\nnight of 14 June, tens of thousands of individuals, the majority of them Masalit civilians,\nattempted to flee from al-Jamarek and al-Madares neighborhoods and seek refuge in\nArdamata.242 At dawn on 15 June, as the miles-long convoy of people passed through the El\nGeneina neighborhoods of al-Shati’ and al-Naseem, it was ambushed by RSF and its allied\nmilitias.243 The attackers fired at the convoy from their vehicles, killing and injuring\nthousands of individuals, leaving many dead bodies on the streets of El Geneina, Kaja valley,\nand on the road to Chad, including of women and children. 244 In the days that followed, the\nRSF and its allied militias continued to pursue and attack fleeing civilians, with violence\nspreading along the escape routes to Chad.245"},{"id":"a-hrc-57-crp-6-p0161","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"161","seq":166,"section":"VII. Findings on violations of international human rights law and","text":"The RSF and its allied militias also pillaged,246 burned down247 or otherwise\ndestroyed248 and shelled Masalit neighborhoods in El Geneina.249 Interviewees described the\nRSF and allied militias using racial slurs against Masalits and other non-Arab groups,\ndescribing them as “umbay/slave” “komrod/Masalit fighter”, “nuba/black”, accompanied by\nthreats and claims that the land belonged to Arabs.250 Several Masalit detainees at the RSF\nbase in al-Jamarek and other locations endured severe beatings, other ill-treatment and\ntorture.251"},{"id":"a-hrc-57-crp-6-p0162","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"162","seq":167,"section":"VII. Findings on violations of international human rights law and","text":"In early November 2023, the RSF and its allied militias attacked Ardamata, northeast\nof El Geneina, killing numerous civilians, including women and children, and pillaging\nproperty.252 At the time, Ardamata housed thousands of IDPs, many of whom had come from\nEl Geneina in the preceding months and causing thousands to flee to Chad and elsewhere.253\nThe Fact-Finding Mission spoke to eye witnesses that saw men being gathered and\nsummarily executed in Tirsana square near the Ardamata camp.254"},{"id":"a-hrc-57-crp-6-p0163","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"163","seq":168,"section":"VII. Findings on violations of international human rights law and","text":"This widespread violence and destruction triggered hundreds of thousands of persons\nto flee.255 Injured individuals fleeing towards Chad were presumed to be fighters and targeted\nat checkpoints, with some tortured and killed. 256 Individuals were also asked to declare their\nethnicity at checkpoints manned by the RSF and its allied militias.257 Some interviewees\nreported that they lied about their tribal affiliation out of fear.258 An interviewee told the Fact-\nFinding Mission that the RSF and their allied militias stopped her and her family at a\ncheckpoint and asked them “Where are you going negros? You deserve to die. You are\nMasalit.” One of the armed men then shot and killed the interviewee’s three male cousins in\nplain sight.259"},{"id":"a-hrc-57-crp-6-p0164","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"164","seq":169,"section":"VII. Findings on violations of international human rights law and","text":"Based on the foregoing, the Fact-Finding Mission finds that the RSF and its allied\nmilitias committed coordinated and large-scale attacks on the civilian population, mainly the\nMasalit community in El Geneina, West Darfur, and other areas under their control along\nflight routes of civilians. The above-described acts of killings, torture and other forms of\ncruel, inhuman or degrading treatment or punishment, including rape and other forms of\nsexual violence, as well as looting, pillage and destruction of objects indispensable to the\nsurvival of the civilian population, formed part of large-scale attacks which targeted, in\nparticular, the Masalit community, on the basis of their ethnicity. The Fact-Finding Mission\nfinds that these acts amount to violations of international humanitarian law to life and person,\nin particular murder of all kinds, cruel treatment and torture, and outrages upon personal\ndignity, in particular humiliating and degrading treatment and rape and any form of indecent\nassault, and threats to commit the foregoing acts. They also constitute human rights\nviolations, in particular of the rights to life and non-discrimination, and the prohibition of\ntorture and other forms of cruel, inhuman or degrading treatment or punishment, including\nrape and other forms of sexual violence. The Fact-Finding Mission further finds that the RSF\nand its allied militias violated the international humanitarian law prohibitions of acts and\nthreats of violence primarily intended to spread terror among the civilian population, making\nthe civilian population the object of attacks, destroying objects indispensable to the survival\nof the civilian population, and forcible displacement.\nc.         Sexual and Gender-Based violence"},{"id":"a-hrc-57-crp-6-p0165","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"165","seq":170,"section":"VII. Findings on violations of international human rights law and","text":"Sexual violence in the Sudan has a long and tragic history, often used as a weapon of\nwar to terrorize and control communities during periods of conflict.260 It has also been used\nby Sudanese military and security forces to repress activists, members of the political\nopposition, and since 2019 also pro-democracy protesters.261 Both the SAF and the RSF have\nbeen listed in the annex to the Report of the Secretary-General on Conflict-Related Sexual\nViolence since 2017, as “parties credibly suspected of committing or being responsible for\npatterns of rape or other forms of sexual violence in a situation on the Security Council\nagenda”.262"},{"id":"a-hrc-57-crp-6-p0166","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"166","seq":171,"section":"VII. Findings on violations of international human rights law and","text":"The ongoing conflict between the SAF and the RSF has seen a resurgence of sexual\nviolence. Especially rape and gang-rape are widespread and continue to occur on a large\nscale, in particular during invasions of cities, attacks on IDP sites and against individuals\nfleeing conflict-affected areas, as well as prolonged occupation of urban residential areas by\narmed men. While women and girls are overwhelmingly targeted by these acts, further\ninvestigations into the possible use of sexual violence against men and boys in this context\nare required.\nResponsibility for acts of sexual violence"},{"id":"a-hrc-57-crp-6-p0167","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"167","seq":172,"section":"VII. Findings on violations of international human rights law and","text":"A large majority of rape cases and other forms of sexual violence documented in this\nreport have been attributed to men wearing RSF uniforms and, in the context of Darfur, armed\nmen allied to the RSF -the Janjaweed-, wearing traditional attire263 and a scarf wrapped\naround their head masking most of their facial features264, making it difficult for victims to\nidentify them."},{"id":"a-hrc-57-crp-6-p0168","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"168","seq":173,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission documented a few cases of sexual violence attributed to the\nSAF, including SAF military intelligence. It should be noted that internally displaced\ncivilians tend to flee to SAF-controlled areas, where it is more difficult for them to report on\nviolations by the SAF. The Fact-Finding Mission also received information concerning\nallegations of sexual exploitation of women and girls by the SAF in exchange for food in\nareas under their control,265 Further investigations are needed to document the patterns and\nthe extent of these acts."},{"id":"a-hrc-57-crp-6-p0169","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"169","seq":174,"section":"VII. Findings on violations of international human rights law and","text":"Victims and witnesses provided detailed explanations on how they differentiated\nbetween the RSF and SAF, including details of the uniform, and how they knew when control\nover an area shifted from one party to another. Victims and witnesses also explained how\nthey differentiated between the RSF and Janjaweed fighters, mainly based on the uniform\n(or absence thereof) as well as the vehicles and sometimes weapons used by the attackers.\nInterviewees consistently referred to the RSF moving around in pickup trucks with R.S.F\nplates,266 with Dshk (doshka) machine guns, while Janjaweed moved on motorbikes or\nsometimes on horses or camels.267"},{"id":"a-hrc-57-crp-6-p0170","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"170","seq":175,"section":"VII. Findings on violations of international human rights law and","text":"As a result of the SAF and the RSF fighting for control over strategic locations in\nurban residential areas, and women and girls having to move repeatedly from one area to\nanother in search of safety from active conflict, women and girls were exposed to the threat\nof sexual violence by both parties to the conflict. The Fact-Finding Mission spoke to a woman\nwho was raped by a member of SAF during a house search only a few days after she changed\nneighbourhood after narrowly escaping rape by the RSF. 268\nVictims"},{"id":"a-hrc-57-crp-6-p0171","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"171","seq":176,"section":"VII. Findings on violations of international human rights law and","text":"While women and girls between 17 and 35 years old constitute the majority of the\nvictims in the evidence reviewed by the Fact-Finding Mission, first-hand sources informed\nof rape of girls as young as eight years and women as old as 75 years.269 Men and boys were\nnot spared, although the number of reported cases is substantially lower. Though there\nprobably are fewer male victims, the very low number of cases documented may also be due\nto cultural norms and the lack of dedicated referral pathways that make it difficult for male\nsurvivors to come forward and seek support after an assault of a sexual nature.270 The Fact-\nFinding Mission collected victim testimonies on the use of sexual violence, including forced\nnudity, beatings on genitals and rape threats, against men and boys in detention during or\nprior to their interrogation. 271 The Fact-Finding Mission also received credible information,\nincluding witness testimonies, about rape and gang-rape of men and boys, including but not\nlimited to the context of detention, which call for further investigations.272"},{"id":"a-hrc-57-crp-6-p0172","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"172","seq":177,"section":"VII. Findings on violations of international human rights law and","text":"In many instances, male and female survivors were subjected to sexual violence\nbecause of their alleged support to the opposing party to the conflict, the perceived or real\naffiliation of their relatives with the opposing party to the conflict, or their perceived or real\nactivity of documenting human rights violations. A source told the Fact-Finding Mission that\nin Khartoum, the RSF attacked and raped women and girls in their homes while accusing\nthem of supporting the former regime (kizan).273 Other victims of rape in Khartoum or Nyala\nwere suspected of some form of support to the SAF (abolda).274 The Mission also\ndocumented several incidents of rape by RSF or their allied militias in Darfur targeting\nwomen they knew as human rights defenders and activists.275"},{"id":"a-hrc-57-crp-6-p0173","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"173","seq":178,"section":"VII. Findings on violations of international human rights law and","text":"Rape and other acts of sexual violence against women and girls were also perpetrated\nfor opportunistic reasons, in a context of impunity, highly militarized urban areas, massive\nand recurring displacements of populations, where increasingly impoverished communities\nface acute food insecurity and the absence of basic services in most parts of the country.\nNumber of victims"},{"id":"a-hrc-57-crp-6-p0174","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"174","seq":179,"section":"VII. Findings on violations of international human rights law and","text":"There are no comprehensive statistics on conflict-related sexual violence in the Sudan.\nIt is estimated that thousands of women, girls, men and boys have been subjected to conflict-\nrelated sexual violence through successive conflicts since 2003. 276 As of September 2023,\n136 cases of sexual violence had been reported to the Combating Violence Against Women\nUnit (CVAW) in the Sudan, “68 of which were recorded in Khartoum State, while the rest of\nthe cases were distributed in the states of South and West Darfur”.277 In January 2024, the\nPanel of Experts on the Sudan reported that “reliable sexual and gender-based violence local\nmonitors had reported 262 rape cases over the period from April to August [2023]” in “RSF\ncontrolled areas in north El Fasher (27), Kutum (19), Tawilah (8), El Geneina (63) and Nyala\n(145)”.278 In September 2024, the Office of the High Commissioner for Human Rights\nreported it had “documented 97 incidents of sexual violence in the context of the conflict,\ninvolving 172 victims, predominantly women and girls”. 279"},{"id":"a-hrc-57-crp-6-p0175","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"175","seq":180,"section":"VII. Findings on violations of international human rights law and","text":"Based on a review of credible open and confidential sources, the Fact-Finding Mission\nestimates that at least 400 survivors of conflict-related sexual violence, almost exclusively\nwomen and girls, were registered by hospitals and/or service providers and referred to some\nform of support in the Sudan from the start of the conflict to July 2024.280 These figures only\naccount for cases that could be verified through referral, most of the time for the provision\nof medical and psychological support. While some of the data may overlap, it is safe to\nassume that this figure only represents the tip of the iceberg with most cases going unreported\nand the total figure being significantly higher.281 As a witness told the Fact-Finding Mission,\n“We know that the moment this war ends or the ceasefire happens, we will find out more\nhorrific acts [of sexual violence] that were not reported or did not access services”.282"},{"id":"a-hrc-57-crp-6-p0176","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"176","seq":181,"section":"VII. Findings on violations of international human rights law and","text":"Sexual violence, and rape in particular, in the Sudanese society remains largely\nunreported. It is surrounded by a culture of silence due to the stigma, and exposes victims to\nsocial isolation, and in some cases, killing.283 The societal shame is compounded by domestic\nlegislation that puts an excessive burden on the victim if she wants to file a case or access\nabortion.284 With the eruption of the conflict in mid-April 2023, these social and\nadministrative barriers to reporting sexual violence were aggravated by heightened\ninsecurity, in particular for women and girls, multiple displacements, frequent\ncommunication blackouts and the collapse of the health system in several parts of the country,\nwhich further hampered the possibilities for survivors of sexual violence to report an incident\nand receive some support.285\nPatterns of sexual violence\n“[during the previous conflict] the Janjaweed used to rape women outside the cities but not\ninside the cities. It was surprising for people to see cases of rape happening inside their own\nhomes. In addition, RSF prayed in the mosques and told the men that they [the RSF] are here\nto bring reassurances and democracy and get rid of the remnants of the former Islamist\nregime. But then they would settle in the neighborhoods and rape the women”286\n-A member of civil society from South Darfur\nSexual violence in the context of attacks on civilians"},{"id":"a-hrc-57-crp-6-p0177","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"177","seq":182,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission found that sexual violence was perpetrated on a large scale\nin the context of attacks of cities in West Darfur. Interviews with victims, witnesses and other\ncredible sources confirmed that similar patterns of widespread rape and gang-rape had been\nperpetrated by the RSF during attacks on cities and sites for IDPs in South Darfur 287, Central\nDarfur288, and Greater Khartoum289, in 2023. Alarming reports depicting similar trends have\nemerged after the RSF progressive takeover of Gezira state.290 Several witnesses consider it\na tactic of warfare to terrorize families and force them out of their homes. 291"},{"id":"a-hrc-57-crp-6-p0178","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"178","seq":183,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission interviewed numerous victims and witnesses of sexual\nviolence incidents that occurred during attacks on El Geneina from mid-April to mid-June\n2023, and Ardamata, in November 2023. Victims recounted being attacked in their homes,\nbeaten, lashed and threatened with death or harm to their relatives or children, before being\nraped often by more than one perpetrator. They were also subjected to sexual violence while\nseeking shelter from attacks or fleeing."},{"id":"a-hrc-57-crp-6-p0179","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"179","seq":184,"section":"VII. Findings on violations of international human rights law and","text":"Data sets compiled by confidential sources and reviewed by the Fact-Finding Mission\nshow that incidences of rape and other forms of sexual violence increased in the weeks\nfollowing major RSF attacks in West Darfur, South Darfur, Khartoum and Gezira states. For\ninstance, one source recorded 175 cases of conflict-related sexual violence in El Geneina and\nNyala alone from mid-April to late May 2023, all attributed to RSF;292 another source verified\n63 cases of conflict-related sexual violence in Khartoum, between May 2023 and July 2024,\n40 of which occurred between mid-April and late July 2023, including 36 cases attributed to\nRSF;293 and another one reported that more than 40 percent of the cases recorded between 15\nDecember 2023 and April 2024 occurred in Gezira state.294"},{"id":"a-hrc-57-crp-6-p0180","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"180","seq":185,"section":"VII. Findings on violations of international human rights law and","text":"Based on interviews with survivors and first-line responders, vaginal single and\nmultiple-perpetrator rape has been the most documented type of sexual violence. Other acts\nof sexual violence, including anal rape or rape with body parts, notably fingers, were also\nreported to the Fact-Finding Mission and sometimes referred to by victims or witnesses as\nsexual harassment.295 A witness explained that in the Sudanese society, rape is often only\nconsidered when the penis is penetrating the vagina of the victim, and the hymen is broken,\nin case of a first intercourse, with other types of sexual penetration considered “sexual\nharassment”.296 A survivor told the Fact-Finding Mission that a post-rape medical\nexamination revealed that she had rectum injuries, which made her think that she had also\nbeen subjected to anal rape after she fell unconscious during an incident of gang rape. 297 The\nFact-Finding Mission also documented incidents of forced nudity and beatings on genitals in\nthe context of detention.298"},{"id":"a-hrc-57-crp-6-p0181","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"181","seq":186,"section":"VII. Findings on violations of international human rights law and","text":"Victims and witnesses consistently reported that perpetrators threatened them with\nweapons, including firearms, knives and whips to intimidate and coerce them.299 Victims\nwere often subjected to other forms of violence, such as punching, beatings with sticks and\nlashing, before and during the rape, to deter resistance, or punish them for resisting.300 A\nwoman who was visibly pregnant described being threatened with death, and violently\npunched and lashed with an electrical cable by the Janjaweed because she refused to undress\nand lay down to be raped. Following the ordeal, she suffered a miscarriage. 301"},{"id":"a-hrc-57-crp-6-p0182","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"182","seq":187,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission documented the widespread use of racist slurs, referring to\nspecific (non-Arab) ethnicity, darker skin colour (zurga or nuba for “black”), and associated\nwith pejorative attributes (umbay for “slave”), during incidents of sexual violence, indicative\nthat ethnicity was a basis for discrimination, often entailing more violent assault, as well as\na basis for targeting victims.302 In West Darfur, two Masalit rape survivors reported that\nJanjaweed perpetrators made explicit their intent to make them pregnant. One survivor heard\nthem saying: “this year, all girls must be pregnant by the Janjaweed.”303"},{"id":"a-hrc-57-crp-6-p0183","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"183","seq":188,"section":"VII. Findings on violations of international human rights law and","text":"Witnesses and victims have also reported the widespread use of gender-based\nderogatory language, including being called prostitutes for the pleasure of the army, or\nimplying that “liberal women” should enjoy being sexually assaulted, that the assault would\nmake the victim sexually satisfied.304"},{"id":"a-hrc-57-crp-6-p0184","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"184","seq":189,"section":"VII. Findings on violations of international human rights law and","text":"Female human rights defenders, activists, journalists and medical professionals have\nalso been targeted with sexual violence.305 While the intersecting of ethnicity and gender, and\nof gender and activism have previously been highlighted in the context of violence against\nwomen in Sudan,306 the intersecting of all three could be further investigated in relation to\npatterns of conflict-related sexual violence in the current conflict.\nRape and other acts of sexual violence during attacks on homes"},{"id":"a-hrc-57-crp-6-p0185","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"185","seq":190,"section":"VII. Findings on violations of international human rights law and","text":"Rape and attempted rape occurred in the homes of the victims, or sometimes at a\nneighbour’s house, in the context of violent attacks on specific neighborhoods involving\nkillings, abductions, looting, and torching of houses, as well as in the context of house\nsearches for weapons, ammunition, and male relatives.307"},{"id":"a-hrc-57-crp-6-p0186","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"186","seq":191,"section":"VII. Findings on violations of international human rights law and","text":"In many cases, sexual violence involved multiple perpetrators taking turns in raping\nthe victim, with co-perpetrators standing watch or immobilizing the victim, while other\nattackers were looting the house or keeping family members, including young children, at\ngunpoint.308"},{"id":"a-hrc-57-crp-6-p0187","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"187","seq":192,"section":"VII. Findings on violations of international human rights law and","text":"Sexual violence often occurred in the presence of the relatives of the victims and was\nassociated with acts of violence against them, such as lashing and beating. 309 One survivor\nfrom West Darfur was threatened that all the men sheltering in the house would be killed if\nshe did not lie down to be raped.310 In a few cases, the intervention of a relative was successful\nin averting the rape of the victims, for instance in exchange of valuables.311 However, in\nseveral other cases, family members were verbally threatened, shot at, beaten or lashed when\ntrying to intervene.312 Another woman explained that a Janjaweed violently hit her mother\non the head and on the back, as her mother tried to protect her daughter from being taken\naway to be raped.313"},{"id":"a-hrc-57-crp-6-p0188","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"188","seq":193,"section":"VII. Findings on violations of international human rights law and","text":"The majority of the incidents documented by the Fact-Finding Mission involved one\nvictim and one or several perpetrators. However, in some incidents, several women and/or\ngirls were sexually assaulted during the same house raid, compounding the humiliation and\ntrauma of the rape with the agony of not having been able to protect a loved one. A survivor\nfrom South Darfur reported that she was raped when trying to prevent the rape of her minor\ndaughter, during an RSF incursion in their home, in the presence of her remaining children. 314\nIn another incident, in Khartoum state, all three female relatives sheltering in a house were\nraped and beaten during an RSF incursion, in front of their children.315\nRape and other acts of sexual violence against women and girls fleeing attacks"},{"id":"a-hrc-57-crp-6-p0189","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"189","seq":194,"section":"VII. Findings on violations of international human rights law and","text":"In addition to being subjected to sexual violence during raids on homes, the Fact-\nFinding Mission also obtained evidence of women and girls being subjected to rape and other\nforms of sexual violence while seeking shelter from attacks or fleeing areas under attack. A\nwoman described how, in the hours following the killing of the Governor of West Darfur in\nEl Geneina, the RSF and its allied militias attacked different neighbourhoods of El Geneina\nand she was separated from her relatives as they fled in different directions. Isolated, she\njoined other civilians who sought shelter in an abandoned house, which was soon invaded by\nthe RSF and Janjaweed. She was taken aside and raped by one of them, who threatened to\nkill her with his weapon if she resisted.316"},{"id":"a-hrc-57-crp-6-p0190","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"190","seq":195,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission collected corroborating testimonies of sexual and gender-\nbased violence perpetrated by the RSF and other armed men identified as Janjaweed along\nthe road from El Geneina to Adré, Chad, particularly in the context of large displacements of\ncivilians fleeing the violence after the killing of the Governor of West Darfur. A woman who\nfled El Geneina after the killing of the Governor told the Fact-Finding Mission that groups\nof RSF members were present along the road between El Geneina to Adré. She and a female\nrelative went through multiple sexual violence incidents, including one rape attempt and\nseveral body searches involving groping of breasts, groin and vaginal penetration with\nfingers. She witnessed several women subjected to the same violence, as well as the rape of\na woman by a man she identified as an RSF member, surrounded by other RSF members, in\nplain sight by the main road.317 Another woman who was subjected to gang rape gang on the\nroad from El Geneina to Adré in June 2023, reported that she was attacked together with three\nother women, by armed men in RSF uniforms and in traditional outfits speaking colloquial\nArabic, while the women had sought shelter in an empty house. The women were separated,\nas groups of armed men each selected a woman and took her away.318\nAbductions and sexual slavery"},{"id":"a-hrc-57-crp-6-p0191","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"191","seq":196,"section":"VII. Findings on violations of international human rights law and","text":"United Nations human rights entities and civil society organizations have expressed\ntheir concern and alarm over reports of abductions of women and girls, and their detention in\nconditions that were tantamount to enslavement, in areas of Darfur controlled by the RSF,\nand highlighted the increased risk of enforced disappearance and trafficking in persons to\nwhich women, children, internally displaced persons and refugees were particularly\nexposed.319"},{"id":"a-hrc-57-crp-6-p0192","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"192","seq":197,"section":"VII. Findings on violations of international human rights law and","text":"As of mid-December 2023, the Office of the High Commissioner for Human Rights\nhad documented eight incidents of sexual violence in the context of abductions, with victims\n“held sometimes in inhuman conditions and subjected to ill-treatment.”320 As of April 2024,\n990 persons were reported missing and considered forcibly disappeared since the start of the\nconflict, according to the Sudanese Missing People Initiative, including 95 women and at\nleast 50 children.321"},{"id":"a-hrc-57-crp-6-p0193","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"193","seq":198,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission documented two incidents in West Darfur and Khartoum\nstates, in which women were abducted and held by armed men in RSF uniform for durations\nranging from four days to more than eight months, and subjected to consecutive rapes,\nincluding gang-rape. Both were abducted from the street, into a vehicle, and driven to another\nlocation in the same State. In one case, the victim was held in detention-like conditions, in a\nroom with no access nor communication to the outside, and depended on her captors for food,\nwater and access to the washrooms. She was raped several times by different RSF members\nover the course of her detention and threatened with death.322 In the other case, the victim\nwas told by her captor, an RSF member, that she was his wife and was forced to remain in\nhis house under the watch of several guards. She was threatened with death in case she\nrefused to stay and was beaten anytime she resisted sexual intercourse. She became pregnant\nas a result of the rapes but was never allowed to see a doctor in the course of the pregnancy. 323"},{"id":"a-hrc-57-crp-6-p0194","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"194","seq":199,"section":"VII. Findings on violations of international human rights law and","text":"In addition, the Fact-Finding Mission received credible testimonies about similar\nincidents, including one of a woman abducted from a road in South Darfur and held in a room\nin a house where she was raped multiple times during three days by men wearing RSF\nuniforms.324 Other sources reported that in July 2023, in a neighbourhood of Khartoum,\nseveral women and girls were abducted and subjected to sexual violence by RSF members\nbefore being released.325 Several victims of abductions reported hearing other women\nscreaming or crying in the place where they were held. 326 In at least one of the cases, the\nvictim was released following the visit of an RSF member whom she thought must have been\nan officer, as he ordered soldiers to release her after inquiring about her situation. 327"},{"id":"a-hrc-57-crp-6-p0195","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"195","seq":200,"section":"VII. Findings on violations of international human rights law and","text":"Victims and witnesses also described four separate incidents during which women\nwere abducted from the street and taken to a house or a more remote location, where they\nwere physically assaulted, beaten and raped, by RSF or Janjaweed, before being released or\nabandoned unconscious in the street.328 Witnesses also described how young women and girls\nwere abducted by the RSF on board of pick-up vehicles at a checkpoint in Al Naseem\nneighborhood while fleeing from El Geneina to Ardamata in the aftermath of the Governor’s\ndeath, in June 2023.329 Another woman described seeing the RSF and Janjaweed abducting\ngirls into their vehicles while she was fleeing from Ardamata in November 2023.330 The\nvictims were taken to an unknown destination where, witnesses believed, they would be\nexposed to sexual violence.\nTargeting of women activists"},{"id":"a-hrc-57-crp-6-p0196","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"196","seq":201,"section":"VII. Findings on violations of international human rights law and","text":"Several women appear to have been targeted with sexual violence to punish them for\ntheir professional or volunteer activities as human rights defenders, lawyers, journalists or\nmedical personnel, often being perceived as reporting on violations and/or supporting the\nenemy. While victims generally did not know the perpetrators, the latter gave clear\nindications that they knew the victims’ occupation, and in several cases, that they had been\nfollowing or looking for them specifically. 331 A woman activist gang-raped by RSF and its\nallied militias recalled the perpetrators saying: “we have been searching for you,\n[organization members] […] tonight you will see something”.332"},{"id":"a-hrc-57-crp-6-p0197","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"197","seq":202,"section":"VII. Findings on violations of international human rights law and","text":"In several cases activism and gender intersected with ethnicity, notably during the\nattacks of El Geneina and Ardamata in West Darfur, with Masalit women rights defenders,\njournalists and medical professionals being specifically targeted. 333 A Masalit survivor told\nthe Fact-Finding Mission that she was attacked because of her human rights activism: she\nwas gang-raped by several Janjaweed who also proceeded to severely beat her, while saying:\n“You deserve this. We should do even more. We should rape you with the stick”. 334 Another\nMasalit survivor, who has medical background reported that RSF members told her: “Our\ndoctor where are you going? […] Come here, criminal!” after they searched her bag and\nfound her medical attire, before they sexually assaulted her. 335\nSexual violence in detention"},{"id":"a-hrc-57-crp-6-p0198","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"198","seq":203,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission found that men and boys were exposed to sexual violence\nin detention, including the use of rape, rape threats, forced nudity and beatings on their\ngenitals as a form of ill-treatment or torture. A male victim interviewed by the Fact-Finding\nMission described how he was threatened with rape by RSF soldiers wearing khaki uniforms,\nwhile being completely naked and subjected to beatings with electric rods and lashing,\nincluding on his genitals, before interrogation. “We could rape you just like we have raped\nothers before you”.336 Another male victim who spent four months in another RSF detention\ncentre reported being threatened with rape during multiple interrogation sessions: “if you do\nnot admit we have people who will have sex with you”.337 Both victims also reported their\ninteractions with younger male detainees whom they assessed to be below the age of 18 years,\nwho either declared that they had been raped, or showed signs indicative of rape. The Fact-\nFinding Mission has also received credible allegations of gang rape of men detained by the\nRSF,338 as well as of sexual exploitation of women detained by SAF Military Intelligence.339"},{"id":"a-hrc-57-crp-6-p0199","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"199","seq":204,"section":"VII. Findings on violations of international human rights law and","text":"Based on the foregoing, the Fact-Finding Mission finds that the large-scale rape and\nother forms of sexual violence committed primarily by the RSF and its allied militias amount\nto violations of international humanitarian law of violence to life and person, and outrages\nupon personal dignity, in particular humiliating, degrading and cruel treatment and torture,\nand rape and any form of indecent assault, and threats to commit the foregoing acts. It further\nfinds that the abduction, confinement and detention of women and girls for sexual purposes,\nincluding rape and sexual exploitation, by the RSF constituted conditions whereby they\nexercised powers attaching to the right of ownership over the victims, whose liberty they also\ndeprived, amounting to prohibited acts of sexual slavery. Under international human rights\nlaw, these acts constitute violations of the rights to be free from torture and other cruel,\ninhuman degrading treatment or punishment, including rape and sexual violence, to physical\nand mental health, including reproductive rights, and to non-discrimination based on gender\ngrounds.\nOther areas requiring further investigation"},{"id":"a-hrc-57-crp-6-p0200","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"200","seq":205,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission has reviewed credible information about the increasing\nnumber of forced marriages of girls and women to RSF members, with parents surrendering\ntheir daughters in exchange for financial compensation or under threat.340 Other reports have\nhighlighted the increased risk of women and girls engaging in survival sex to access food or\nhumanitarian assistance, in a context of acute food insecurity. 341 The Fact-Finding Mission\nrecommends further investigation to verify and document these allegations and the nexus\nbetween denial of access to/obstruction to humanitarian aid, acute food insecurity/famine and\nsexual and gender-based violence, in the Sudanese context."},{"id":"a-hrc-57-crp-6-p0201","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"201","seq":206,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission shares the concerns expressed by United Nations Special\nProcedures regarding “reports of women and girls being sold at slave markets in areas\ncontrolled by RSF forces and other armed groups, including in North Darfur”. 342 At the time\nof reporting, the Fact-Finding Mission was not able to corroborate these allegations but\nrecommends further investigations, especially since the Fact-Finding Mission was able to\nverify the existence of practices of abduction for sexual exploitation purposes amounting to\nsexual slavery within RSF forces.\nConsequences of sexual violence"},{"id":"a-hrc-57-crp-6-p0202","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"202","seq":207,"section":"VII. Findings on violations of international human rights law and","text":"In their harrowing testimonies, survivors of rape shed light on the enduring and\nmultifaceted impacts of sexual violence, not only on their own physical and mental health\nbut also on the well-being of their families and communities. Survivors of sexual violence in\nthe Sudan continue to face societal stigma that hold them, and their families, responsible for\nthe violence inflicted upon them. This victim-blaming culture exacerbates the trauma and\nhinders survivors from seeking help.\nImpact on survivors’ health"},{"id":"a-hrc-57-crp-6-p0203","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"203","seq":208,"section":"VII. Findings on violations of international human rights law and","text":"Women survivors of sexual violence frequently told the Fact-Finding Mission that\nthey endure long-lasting effects from the assault, including chronic pain in the lower back\nand lower abdomen.343 Many women were beaten before or during the rape, and some had\nbroken bones, while others developed severe headaches from violent blows to their heads. A\nsurvivor reported that the assault aggravated her existing poor health condition caused by\nconflict-induced stress and a lack of access to sufficient food.344"},{"id":"a-hrc-57-crp-6-p0204","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"204","seq":209,"section":"VII. Findings on violations of international human rights law and","text":"The impact of violent rapes on survivors’ sexual and reproductive health is important\nand carries long-term family and social consequences. Survivors reported frequent\ngynecological or urinary infections and painful menstruations.345 One victim who was five\nmonths pregnant suffered a miscarriage as a result of the severe ill-treatment she was\nsubjected to, during a rape attempt.346 Another survivor, who did not have a child yet at the\ntime of the assault, was told by a doctor that the injuries she suffered would make it difficult\nfor her to conceive.347"},{"id":"a-hrc-57-crp-6-p0205","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"205","seq":210,"section":"VII. Findings on violations of international human rights law and","text":"Almost all women spoke of continuous bleeding in the aftermath of the rape, 348 and\nin several cases, required an urgent medical intervention, which was not always available.\nThe Fact-Finding Mission documented the case of a woman who appear to have died from\nbleeding following a gang-rape by alleged RSF soldiers, because she could not access\nlifesaving treatment, as her family struggled to gather the necessary financial means for it. 349\nIn another case, a survivor had to receive a blood transfusion before undergoing a long\nsurgery to repair an extensive tear, provoked by violent rape. 350 Medical sources interviewed\nby the Fact-Finding Mission confirmed that vaginal tears and bruises were the most frequent\ninjuries reported by medical personnel assisting victims of sexual violence. 351 In addition, the\npractice of female genital mutilation (FGM) remains widespread in the Sudan and can\naggravate physical damage sustained because of rape. According to the United Nations, in\n2020, more than 86% of girls and women between 15 and 49 years old in the Sudan were\naffected by FGM, including the type commonly referred to as infibulation; one of the highest\nrates in the world.352\nPregnancies and the right to abortion"},{"id":"a-hrc-57-crp-6-p0206","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"206","seq":211,"section":"VII. Findings on violations of international human rights law and","text":"The high prevalence of rape combined with a lack of access to, or unavailability of,\nsexual and reproductive health services have, according to civil society and service providers,\nled to numerous unwanted pregnancies. It is however hard to estimate how many victims are\naffected because of the stigma deterring them from disclosing their situation.353 In November\n2023, the gender-based violence (GBV) sub-cluster in the Sudan reported an increase in the\nnumber of unmarried pregnant women seeking GBV and sexual and reproductive health\nservices in IDP-hosting states, the majority of whom were pregnant as the result of rape.354\nWomen and girls found to be pregnant out of marriage face rejection from their families and\ncommunities, adding considerable socioeconomic vulnerability to the long-lasting trauma of\nthe violence.355 Research indeed indicates that “women and girls who have children born of\nsexual violence tend to suffer a higher level of social stigmatisation and face broader,\ndifferent challenges to victim-survivors without children”.356 Besides, children born from\nconflict-related sexual violence are exposed to a range of grave violations including\ninfanticide and abandonment, intersecting and multiple forms of discrimination affecting\ntheir rights and further contributing to their marginalization.357 They are also exposed to\nintergenerational transmission of trauma from their mother.358"},{"id":"a-hrc-57-crp-6-p0207","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"207","seq":212,"section":"VII. Findings on violations of international human rights law and","text":"Survivors of sexual violence in the Sudan also face many challenges to exercise their\nright to a safe termination of a pregnancy resulting from rape. Under Sudanese law, abortions\nfollowing rape are legal only within 90 days of pregnancy.359 Survivors must also obtain\npermission from the Office of the Prosecutor for a legal abortion in a public or private\nhospital. The law requires survivors to report the rape to the police, and obtain a Form 8,360\nwhich they must submit for completion by a medical practitioner to record the medical\nevidence of physical injuries resulting from the rape.361 The completed form must\nsubsequently be presented to the Office of the Prosecutor, for a decision on the request for\nabortion. This procedure, which has generally been considered as an excessive and difficult\nlegal requirement to obtaining legal abortion after rape, has been aggravated by the general\nbreakdown of rule of law institutions,362 and the destruction of medical infrastructures,\nincreasing confusion about procedures among health workers.363 A source interviewed by the\nFact-Finding Mission believed that some survivors who could not obtain legal access to\nabortion services have resorted to unsafe methods outside healthcare facilities.364\nStigmatization and trauma"},{"id":"a-hrc-57-crp-6-p0208","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"208","seq":213,"section":"VII. Findings on violations of international human rights law and","text":"Survivors have described their social isolation, often self-imposed, because of the\nshame they believe to have brought onto their families, their unsuitability for marriage, and\ntheir incompleteness as women in society.365 One survivor explained: “Our society sees girls\nwho [were raped] as shameful, [the victim] should not talk about it. They are seen [as] unfit\nfor marriage. When people gather, they talk about her.”366"},{"id":"a-hrc-57-crp-6-p0209","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"209","seq":214,"section":"VII. Findings on violations of international human rights law and","text":"Isolation and stigma amplify the challenges of coping with the aftermath of the assault.\nMany survivors do not receive the necessary psychological care, which increases their\nvulnerability to suicidal thoughts. Several women explained how they had resisted rape, often\nat great cost in terms of physical injuries, and asked the perpetrators to kill them instead. 367\nA few survivors declared that they wished they had died during the assault.368 In late\nNovember 2023, the Gender-Based Violence sub-sector in the Sudan reported on a\nconcerning trend of suicidal thoughts and attempts amongst survivors of sexual violence. 369\nFear for their life or their children’s lives, trauma and shame drove most survivors the Fact-\nFinding Mission spoke with to displacement, primarily seeking refuge in a neighboring\ncountry.370\nof training of the law enforcement officials and medical practitioners supposed to complete or use it. Additionally\nhuman rights NGOs have alerted on the risk of Form 8 being used as evidence in adultery charges brought against\nthe survivor in case of unsuccessful legal proceedings against the perpetrator of sexual violence. For details see\nRedress, Submission to the UN Special Rapporteur on Torture: Reparation sur Survivors of Conflict-Related Sexual\nViolence, 2024, para 15, https://redress.org/publication/submission-reparation-for-survivors-of-conflict-related-\nsexual-violence/"},{"id":"a-hrc-57-crp-6-p0210","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"210","seq":215,"section":"VII. Findings on violations of international human rights law and","text":"Children, or relatives, who were present during the sexual assault of a mother,\ndaughter, or sister show signs of post-traumatic stress, such as nightmares and behavioral\nchanges. One survivor described to the Fact-Finding Mission how her children had grown\nanxious and kept asking: “Why did this happen to you, mom? Don’t leave us, they are going\nto beat you, stay with us”.371\nAccess to services"},{"id":"a-hrc-57-crp-6-p0211","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"211","seq":216,"section":"VII. Findings on violations of international human rights law and","text":"The ongoing conflict has led to the occupation of health facilities, attacks on\nhealthcare workers, and significant restrictions on medical supplies.372 This has made it\nextremely difficult for survivors to receive timely and necessary treatment."},{"id":"a-hrc-57-crp-6-p0212","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"212","seq":217,"section":"VII. Findings on violations of international human rights law and","text":"One year into the conflict, UNFPA reported it had distributed 2,880 supplies for the\nclinical management of rape in the Sudan.373 Essential medical supplies for post-rape care\nhave, however, been in short supply and sometimes unavailable in Khartoum and the Darfur\nregion, due to a lack of access to the facilities where they were stored, low pre-war stock\nlevels in some states, and attacks on medical warehouses.374 On 9 May 2023, UNFPA\nreported that “[in Khartoum] the distribution of […] life-saving supplies [to cover 19,000\nchild births and 47,000 reproductive emergencies including the clinical management of rape]\nto health facilities including referral hospitals and health care providers is not possible at\nthis time due to the absence of safe access to the warehouses. Access to GBV prevention and\nresponse services in Khartoum - and across Sudan - is severely curtailed by the ongoing\nfighting, destruction and looting of health care centres and hospitals”.375 Faced with a\nshortage of supplies, doctors in Khartoum developed an alternative protocol for the clinical\nmanagement of rape, with locally available medications. This “emergency protocol”\nprotected survivors against pregnancies and some sexually transmittable diseases, yet it did\nnot include anti-viral medication against HIV and hepatitis B.376 One witness of medical\nbackground told the Fact-Finding Mission she expected that the war would lead to an increase\nin HIV infections among survivors of sexual violence.377"},{"id":"a-hrc-57-crp-6-p0213","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"213","seq":218,"section":"VII. Findings on violations of international human rights law and","text":"Some survivors reported that they did not go to the hospital because they were\nashamed,378 and when they did reach out to services, they provided minimal information on\nwhat happened to them, so as to minimize the exposure to stigma and shame.379 A recent\nreport by a human rights NGO described the persisting stigma around receiving sexual and\nreproductive health services, compounded by a shortage of trained professionals and\nconfidential services caused by the conflict.380 Indeed, as hospitals were besieged, shelled or\nlooted, health professionals evacuated to other health facilities, or fled. 381 Health\nprofessionals sometimes continued to provide care from their homes or from makeshift\nclinics created to provide emergency care for the injured and support to chronic diseases, at\na great risk of reprisals, with very limited supplies, and lacking trained personnel and specific\nsupplies for the clinical management of rape.382"},{"id":"a-hrc-57-crp-6-p0214","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"214","seq":219,"section":"VII. Findings on violations of international human rights law and","text":"As health facilities were hard to reach, service providers responded to survivors and\ntheir relatives mostly through messages and calls, unless the case required an urgent medical\nintervention.383 Repeated displacements and internet and communication outages led to\nservice providers losing contact with survivors, or survivors unable to reach out for support,\nseriously hampering possibilities of follow-up care.384"},{"id":"a-hrc-57-crp-6-p0215","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"215","seq":220,"section":"VII. Findings on violations of international human rights law and","text":"Emergency Response Rooms (ERR)385 have played a critical role in providing\nreferrals or facilitating access or evacuation of survivors of sexual violence to health care and\npsychosocial support across the country.386 The Fact-Finding Mission has gathered\nconcerning allegations of sexual violence perpetrated against ERR volunteers while they\nperformed their assistance tasks.387\nd.     Grave violations against children"},{"id":"a-hrc-57-crp-6-p0216","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"216","seq":221,"section":"VII. Findings on violations of international human rights law and","text":"Children are paying a very heavy toll in the intense fighting that has ravaged the\nSudan. According to UNICEF, the conflict has resulted in the highest number of grave child\nrights violations verified in the country in more than a decade.388 Children have been recruited\nand used in hostilities, killed, injured, abducted and forcibly displaced, detained with adults,\ntortured, subjected to sexual violence and deprived of healthcare and education. Many have\nalso witnessed their parents, siblings, friends, or neighbours being subjected to the most\nheinous crimes, have lost or been separated from their families or caretakers, or have been\nabandoned at birth after being born out of rape. Besides threatening their very survival, the\nprotracted conflict and the ensuing deterioration of the humanitarian situation are having a\ndevastating impact on their health and development. UNICEF estimates that close to 14\nmillion children are in need of humanitarian assistance, the highest number so far registered\nin the country. More than half (52 percent) of the 10.7 million IDPs are younger than 18, and\n26 percent are less than 5 years old. In the largest part of the country, schools will remain\nclosed for the second consecutive year, converting the war in the Sudan to one of the largest\nlearning crises in the world with close to 18 million children deprived of education."},{"id":"a-hrc-57-crp-6-p0217","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"217","seq":222,"section":"VII. Findings on violations of international human rights law and","text":"Exposure of children to the level of violence in the Sudan and multiple traumatic\nevents, in the absence of sufficient protective services, will leave deep psychological scars\nand pose major mental health problems that may hamper the country’s long-term prospects\nfor peace and stability. Parents told the Fact-Finding Mission that their children were\nexperiencing intense psychological distress, including chronic stress, anxiety, depression, and\nsymptoms of post-traumatic disorders. Many also expressed great concern at the lack of\neducational opportunities including in the country of refuge, and the impact it may have on\ntheir future. 389 Some children have also become the main breadwinners of their families and\nare compelled to seek a livelihood at a young age."},{"id":"a-hrc-57-crp-6-p0218","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"218","seq":223,"section":"VII. Findings on violations of international human rights law and","text":"The annual report of the Secretary-General on Children and Armed Conflict lists the\nSAF and the RSF for committing grave violations of children’s rights. The SAF is listed for\nthe killing and maiming of children, and attacks on schools or hospitals. The RSF is listed\nfor recruitment and use of children; killing and maiming; rape and other forms of sexual\nviolence against children; and attacks on schools or hospitals.390 The investigations carried\nout by the Fact-Finding Mission confirm these findings. In addition, the Fact-Finding\nMission received multiple credible reports that SAF has played a role in the training and\narming of children who have joined the popular mobilization.\nChild recruitment or use of children in hostilities by the warring parties"},{"id":"a-hrc-57-crp-6-p0219","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"219","seq":224,"section":"VII. Findings on violations of international human rights law and","text":"Both international humanitarian law and international human rights law contain\nprovisions on the recruitment into armed forces or groups and use of children in hostilities.\nWhile the prohibition to recruit and use children under international humanitarian law applies\nto children under the age of 15, the OP-CRC-AC raises the age to 18.391 The Sudan acceded\nto the OP-CRC-AC in 2005, under which it declared a minimum age of 18 years for both\nforced and voluntary recruitment into its armed forces.392 The Sudan is also party to the\nInternational Labour Convention on the Worst Forms of Child Labour (No.182) which\nprohibits the forced or compulsory recruitment of children under 18 for use in armed conflict.\nThe Sudan enacted a corresponding national law that prohibits the recruitment or\nemployment of children under 18 in its armed forces or in armed groups to participate in\nwar.393 The Sudanese Armed Forces Act of 2007 sets the minimum age of recruitment in the\narmed forces at 18 and provides for penalties in case of non-compliance.394 The Sudanese\ncriminal legislation does not, however, provide for sanctions in the case of recruitment of\nchildren and use in hostilities by armed groups.395"},{"id":"a-hrc-57-crp-6-p0220","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"220","seq":225,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission heard from human rights defenders, community leaders and\nchild rights practitioners on some of the factors that contributed to the recruitment and use of\nchildren in hostilities by the warring parties. Interlocutors cited the deprivation of education,\nprotection and defense of the community and family from both the warring parties and inter-\ncommunal violence, the desire to seek revenge for the atrocities committed against the family\nor community, the influence of social environment and tribal customs, the forced\ndisplacement and separation from family or caretakers or the search for safety, protection and\nlivelihood amongst the main factors that contributed to children being lured into joining\nmilitia, armed groups and forces in the present conflict.396 In addition, as further detailed\nbelow, both warring parties relied extensively on youth mobilization to bolster their ranks\nand demonstrated limited to no control over the age of their recruits despite credible\nallegations of forgery of birth certificates, particularly in Darfur and rural areas.397"},{"id":"a-hrc-57-crp-6-p0221","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"221","seq":226,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission received credible allegations that children were seen\npatrolling with the SAF 21st Infantry Division carrying weapons in Zalingei, as well as with\nthe SAF 16th Infantry Division in Nyala in May 2023. Of particular concern is the fact that\nthe SAF leadership has been pursuing alliances with armed groups that have been listed for\nyears in the report of the Secretary-General for the recruitment and use of children in\nhostilities, including the SLM/ Minnawi and the JEM.398 Both groups have been supporting\nSAF offensives in Northern Darfur, Khartoum and Gezira under the umbrella of the Darfur\nJoint Forces.399\nRecruitment of children through popular mobilization by the SAF","printed":"224"},{"id":"a-hrc-57-crp-6-p0222","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"222","seq":227,"section":"VII. Findings on violations of international human rights law and","text":"There are credible reports indicating that children have been joining youth groups in\nthe context of popular mobilization “Istinfar” that have been trained and armed by the SAF\nin Khartoum, River Nile, Kassala, Gedaref, Sennar or Red Sea states.400"},{"id":"a-hrc-57-crp-6-p0223","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"223","seq":228,"section":"VII. Findings on violations of international human rights law and","text":"On 5 January 2024, at the occasion of the country’s independence anniversary,\nGeneral Al-Burhan, officially invited groups of youth mobilised “Mustanfareen” to join the\narmy. In his speech, he pledged SAF support, including through the provision of weapons, to\nthe civilians seeking to defend themselves against the RSF attacks.401 One month later, SAF\nAssistant-Commander-in-Chief, declared at the occasion of the People's conference party\nheld in Kerery, Omdurman, that:\n“[...]In the army, in the national police, in the intelligence service, in the mobilized,\nin the popular resistance [...], we will train even young children to defend themselves,\ntheir people, and their land.”402"},{"id":"a-hrc-57-crp-6-p0224","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"224","seq":229,"section":"VII. Findings on violations of international human rights law and","text":"Following SAF leadership’s support call for mass mobilization to counter RSF’s\nadvances, a significant number of videos exhibiting youth and children under 18 being trained\nby SAF officers under the umbrella of popular mobilization circulated on social media. The\nevidence also demonstrated that SAF organized a shooting course for mobilized women and\nallegedly girls in Gezira.403 The Fact-Finding Mission has also received allegations indicating\nthat additional training camps have been set up in River Nile and Port-Sudan with the\nparticipation of girls under 18."},{"id":"a-hrc-57-crp-6-p0225","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"225","seq":230,"section":"VII. Findings on violations of international human rights law and","text":"At the end of May, following the death of an ex-SAF Lieutenant404 executed by the\nRSF as reported by media while he engaged in fighting under the banner of popular\nmobilization, General Al-Burhan stated that:\n“[...] three-quarters of the people are now Mustanfareen” and announced that\n“[...]we will make an army out of them.”405"},{"id":"a-hrc-57-crp-6-p0226","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"226","seq":231,"section":"VII. Findings on violations of international human rights law and","text":"Following this declaration, a new “List of mobilization and popular resistance for the\nyear 2024” was approved by General Al-Burhan on 27 May 2024. Notwithstanding the\nindicated minimum age of 18,406 the Fact-Finding Mission received information indicating\nthat children under 18 were observed manning checkpoints of popular mobilization in SAF\ncontrolled areas.407 Further investigations are needed to ascertain whether children under 18\nhave been recruited and used by the SAF under the umbrella of popular mobilization.\nRecruitment and use of children by the RSF and allied militias"},{"id":"a-hrc-57-crp-6-p0227","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"227","seq":232,"section":"VII. Findings on violations of international human rights law and","text":"The RSF and its allied militias systematically recruited and used children in hostilities.\nWitnesses reported that young boys have been seen with the RSF and its allied militias in El\nGeneina, Ardamata and other localities along the border with Chad, Zalingei, Nyala, Wad\nMadani in Gezira state and Khartoum. Reports also indicate that children have been fighting\nalongside the RSF in El Fasher.\n400   Confidential Submissions. See e.g., Updated report of Centre for information resilience (Sudan witness) on child\nrecruitment, June 2024. or SHRH-Ayin joint investigation on child soldiers available at\nhttps://sudanhrh.org/en/articles/child-soldiers-in-Sudan-may-2024.\n401   Individual submission received during the Child rights consultation. Full speech available at https://youtu.be/Q-\n4W3oroMLY?si=k6o_1lxeaYn8EuuS.\n402   Full speech available at https://youtu.be/g7A_EBNryMQ?si=b8_XGiX7Kh0PA2AV.\n403   See https://spokesperson-sd.com/ar/archives/17780 published on the website of the Official Spokesperson\nPlatform of the Government of Sudan on 27/07/2024.\n404   Mohamed Siddiq was a retired SAF Lieutenant who became famous for joining the protestors during the sits-in of\n2019. He joined the popular mobilization during the current conflict and was reportedly executed by the RSF in\nMay 2024. See https://sudantribune.com/article285834/."},{"id":"a-hrc-57-crp-6-p0228","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"228","seq":233,"section":"VII. Findings on violations of international human rights law and","text":"The RSF and its allied militias have used children as bodyguards, informers, in combat\nunits, to conduct security patrols, man checkpoints, carry out searches, monitor arrestees,\npillage, commit arson, as well as commit acts of torture in detention centres.408 A number of\ntestimonies further indicate that children associated with the RSF and its allied militias were\nused to torture and record scenes of crimes and post them on social media.409 Eyewitnesses\nhave reported that some children were dressed in RSF uniforms, with some bearing ranks."},{"id":"a-hrc-57-crp-6-p0229","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"229","seq":234,"section":"VII. Findings on violations of international human rights law and","text":"During the attacks against the civilian population in El Geneina, some children could\nclearly be identified as associated with the RSF, but for others, especially those in civilian\nclothes, it was less clear whether they were associated with the RSF or any of its allied\nmilitias including the Third-Front Tamazuj. According to the United Nations Secretary-\nGeneral, out of 209 incidents of child recruitment verified in the Sudan in 2023, close to 80\npercent are attributed to both the RSF and the Third-Front Tamazuj."},{"id":"a-hrc-57-crp-6-p0230","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"230","seq":235,"section":"VII. Findings on violations of international human rights law and","text":"The information gathered by the Fact-Finding Mission also indicates that young\nchildren have been used as part of the group of looters commonly referred to as “Kassiba and\nspoils” (‫ )مجموعات الكسيبة والغنائم‬that usually follow the RSF and its allied militias in their\nattacks to collect spoils of war of lower value.410 During the attack of El Geneina on 24 April\n2023, witnesses described seeing groups of women reciting prayers and chants encouraging\nchildren and youth to commit crimes against their enemy as they would be celebrated as\nknights.411 A witness also described how his house was looted in Gezira in the first part of\n2024 by underage boys associated with the RSF, and looted again by a group composed of\nwomen and children hailing from “Nyala or Um Dukhun in Darfur.”412"},{"id":"a-hrc-57-crp-6-p0231","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"231","seq":236,"section":"VII. Findings on violations of international human rights law and","text":"Reports indicate that the use of children by Arab militias is deeply entrenched in the\nSudanese “Faza’a” (‫ )الفزع‬tradition which consists of the spontaneous mobilization of armed\nmen to defend the community against a perceived threat, particularly prevalent in Darfur and\nKordofan.413 Witnesses indicated that tribal leaders played a significant role in recruiting\nchildren, describing the following process. Tribal military leaders or “Agid” receive\ninstructions from mid-level administrators or “Omdas” who respond to tribal leaders “Amirs”\norders to provide them with a specific number of combatants from a specific tribe. “Agid”\nwould then request each family of the clan to assign a number of their sons, including the\nones below 18.414 According to the information received by the Fact-Finding Mission,\nchildren are also easily lured into joining the RSF, drawn into the promises of receiving\nweapons and salaries as well as earning spoils of war.415\nRecruitment and use of hostilities by other armed groups"},{"id":"a-hrc-57-crp-6-p0232","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"232","seq":237,"section":"VII. Findings on violations of international human rights law and","text":"Apart from the two main warring parties, the Fact-Finding Mission additionally\nreceived credible allegations of recruitment and use of children by other parties to the\nconflict. This is notably the case with the Sudanese Alliance, formed mainly of the Masalit\ntribes. Eyewitnesses indicate having seen children, aged as young as 14, among groups of\nyouth, armed with heavy machine guns and vehicles and allegedly associated with the\nSudanese Alliance, participating in the looting of the Sudanese police weapons storage that\ntook place in April 2023 in El Geneina.416 The United Nations Secretary-General also\nreported 34 cases of recruitment and use of children under 18 by the Sudanese Alliance in its\nreport on children and armed conflict in the Sudan for the years 2022 and 2023.417\nKilling and injuring of children"},{"id":"a-hrc-57-crp-6-p0233","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"233","seq":238,"section":"VII. Findings on violations of international human rights law and","text":"The war in the Sudan has resulted in staggering numbers of children being killed,\nmaimed, or wounded under the most horrific circumstances. In nearly all cases affecting the\ncivilian population documented by the Fact-Finding Mission, children were among the\nvictims. Children have been killed and injured during airstrikes, shelling or crossfires, or\nexecuted. Numerous accounts of eyewitnesses reported the death of children during airstrikes\nthat hit residential areas in Khartoum, East Nile418, North Darfur419 or Nyala420, central\nmarkets, including in Omdurman421 or schools such as the aerial bombardment of Hadra\nelementary school, South Kordofan, on 14 March 2024 that killed and injured several\nchildren as they were queuing to enter their classrooms.422 Children have also been severely\ninjured during airstrikes with some suffering limb amputations. The extent of child casualties\nis quite significant; the sample of cases presented in this section are merely illustrations of\nthe violations against children by the warring parties."},{"id":"a-hrc-57-crp-6-p0234","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"234","seq":239,"section":"VII. Findings on violations of international human rights law and","text":"In Darfur, dead bodies with gunshots, including of children, were seen lying in the\nstreets during the attack on El Geneina by RSF and its allied militias mentioned above.\nChildren were killed by snipers while walking on the streets, inside their houses, or when the\nRSF and its allied militias shelled houses, schools, or hospitals in El Geneina, Ardamata and\nZalingei. A doctor working in a makeshift hospital during these events recalled that he\nrecorded the deaths of 350 children and 55 pregnant women hit by shelling between 24 April\nand 4 June 2023. The RSF and its allied militias also launched mortar shells on schools and\nIDP shelters in Ardamata and Zalingei resulting once again in the death of many children.423"},{"id":"a-hrc-57-crp-6-p0235","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"235","seq":240,"section":"VII. Findings on violations of international human rights law and","text":"Following the killing of the governor of West Darfur on 14 June 2023, described\nabove, many witnesses described how children, particularly boys, were killed by the RSF and\nits allied militias while attempting to flee from the city.424 Children also drowned in the\nvalley. An eyewitness also described having seen around 13 boys as young as 10, being\ngrabbed from their families by Third-Front Tamazuj and Arab militias and thrown into the\nwater. The boys could not swim and were swept away by the current.425 Another interviewee\nreported witnessing the torture and execution of a boy around 10-year-old, stopped by the\nRSF and its allied militias on the road while attempting to escape to Chad. He declared: “The\nboy was not handling the pain very well. He was screaming and crying as he was being\nwhipped. He was shot in the head by one RSF. Part of his brain blew up on my shirt.” 426\nAbduction of children by the warring parties"},{"id":"a-hrc-57-crp-6-p0236","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"236","seq":241,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission also gathered information regarding cases of abductions of\nboys and girls by the RSF in West Darfur. Witnesses reported having seen groups of underage\ngirls forced by RSF elements into their cars in El Geneina and Ardamata. 427 A girl who had\nbeen held captive for several months by the RSF explained she had been abducted with other\ngirls and boys and was not aware of the whereabouts of the other abductees.428 The Fact-\nFinding Mission is also investigating allegations concerning the reported sale of young\nchildren alongside stolen goods in markets in Khartoum.\nAttacks affecting access to healthcare for children"},{"id":"a-hrc-57-crp-6-p0237","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"237","seq":242,"section":"VII. Findings on violations of international human rights law and","text":"In the context of its investigations, the Fact-Finding Mission established that the\nshelling and occupation of hospitals, looting of medical and humanitarian supplies, threats\nand harassment of medical staff, as well as structural damage to healthcare infrastructure\nduring the conflict have had a direct impact on access to healthcare for children. An\ninterviewee recounted that his two-year-old nephew who had been admitted at Jaafar Ibnouf\nChildren’s Hospital in Khartoum, a week before the conflict broke out, died because the\nhospital had to suspend its services after the conflict broke out.429 Similarly, several children\nof Mygoma orphanage in Khartoum died of malnutrition, dehydration and disease as most of\nthe caretakers were forced to stay away from the orphans for nearly two months due to the\nheavy clashes.430"},{"id":"a-hrc-57-crp-6-p0238","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"238","seq":243,"section":"VII. Findings on violations of international human rights law and","text":"Testimonies from the Darfur region also paint a stark picture. In El Fasher, the MSF-\nsupported Babiker Nahar Children's Centre was closed down after an airstrike, allegedly\ncarried out by the SAF, landed in its vicinity, killing two children.431 The children of El Fasher\nwere left without access to pediatric treatment due to the structural damages caused to the\nhospital. In El Geneina, a medical employee informed the Fact-Finding Mission that: “When\nthe crisis erupted, the RSF shut down El Geneina public hospital because they didn’t want\ninjured people to be admitted to the hospital. Medical staff were prevented from coming to\nthe hospital and working. Medical equipment and beds were looted by the RSF. The shortage\nof medical supplies was severe, including intravenous fluids, oxygen, and antibiotics.\nChildren died from diarrhea and measles because there was no salt, serum, or measles\nvaccine available.”432 A witness also reported that after Nyala Turkish hospital was taken\nover by the RSF in March 2024, civilians were denied access, “even maternity cases”.433"},{"id":"a-hrc-57-crp-6-p0239","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"239","seq":244,"section":"VII. Findings on violations of international human rights law and","text":"Based on the foregoing and in connection with other relevant sections of this report,\nthe Fact-Finding Mission finds that RSF and affiliated militias recruited and used children in\nhostilities and committed acts of killing and maiming, abduction, and rape or other sexual\nviolence against children, attacks on schools and hospitals, and deprivation of essential\nhumanitarian assistance for children. It finds that SAF committed acts of killing and maiming\nof children, attacks on schools, and deprivation of essential humanitarian assistance for\nchildren. These acts constitute violations of international humanitarian law and international\nhuman rights law, in particular under the CRC and CRC-OP-AC, and echo the six grave\nviolations against children in times of conflict.434\ne.     Arbitrary arrests and detention"},{"id":"a-hrc-57-crp-6-p0240","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"240","seq":245,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission has documented widespread arrests and detention\nconducted by both the SAF and RSF since mid-April 2023 in areas under their control.\nCivilians were arrested mainly on suspicion of supporting the other party to the conflict.435\nAccording to some witnesses, most of those detained appear to be civilians accused of\nworking with the SAF and SAF Military Intelligence.436 Documented arrests and detentions\ntook place in various locations of Khartoum, West and Central Darfur as well as River Nile\nstate."},{"id":"a-hrc-57-crp-6-p0241","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"241","seq":246,"section":"VII. Findings on violations of international human rights law and","text":"Use of unofficial locations and “unlawful”437 or “temporary”438 detention centres by\nboth the SAF439 and RSF440 has been reported. Many were held in unofficial detention sites\nby the RSF either in Khartoum or in Darfur. The locations most frequently cited include\nuniversities - mainly the International University of Africa in Khartoum,441 schools, 442\nprivate houses,443 buildings,444 including unfinished or abandoned ones, gas stations, police\nstations,445 and areas or houses adjacent to, or near the checkpoints 446. The Fact-Finding\nMission also received allegations on the existence of unofficial detention facilities in\nKhartoum used by the SAF.447"},{"id":"a-hrc-57-crp-6-p0242","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"242","seq":247,"section":"VII. Findings on violations of international human rights law and","text":"Civilians were arrested in different locations, including at checkpoints and their\nhomes, often accompanied by acts of physical violence.448 For example, one interviewee who\nwas arrested alongside five other men and detained by the RSF in Khartoum in July 2023,\ntold the Fact-Finding Mission that he was taken to an RSF checkpoint where one of the RSF\nmembers hit him on the head while another whipped him. Following the physical assault,\nthey tied the victim’s hands and the hands of the five other individuals behind their backs,\nblindfolded them with pieces of cloth and pushed them into the RSF vehicles.449 Another\ninterviewee who was violently beaten during his arrest in Gezira in 2023 at the SAF\ncheckpoint, recalled:\n“[I] was riding in public transport when [I] got off at the checkpoint. [...].\n[The SAF] checked [my] phone and messages. [...] [The SAF] asked me what\nthese pics were. [I] explained that these are general pics in a group, but they\nbeat [me] with fists and called [me] informer for the RSF. [...] The beating\ncontinued until they took [me] to a school turned into a detention centre”450"},{"id":"a-hrc-57-crp-6-p0243","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"243","seq":248,"section":"VII. Findings on violations of international human rights law and","text":"Members of the Emergency Response Rooms451 and the resistance committees452 were\nvictims of arbitrary arrests and detentions by the SAF in Khartoum due to their professional\nactivities and their perceived association with the Freedom and Change, a political party.453\nThey appear to be a direct target of SAF Military Intelligence, as they accuse them of being\nRSF collaborators.454"},{"id":"a-hrc-57-crp-6-p0244","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"244","seq":249,"section":"VII. Findings on violations of international human rights law and","text":"Among the victims of arbitrary arrest and detention were individuals, particularly\nmen, who were trying to flee the country or various locations. Several male victims reported\nbeing arrested by the RSF as they used different routes from the main road to Adré while\nfleeing from El Geneina to avoid being killed,455 or leaving other areas.456 One witness who\nwas arrested while fleeing El Geneina in June 2023, told the Fact-Finding Mission that he\nwas on the way to the border in a group of six when they were stopped by Arab militias who\nthreatened him by placing a gun on his head. Three of them managed to escape. However, he\nwas shot in the leg and could not escape. He was captured, beaten, and returned to the rest of\nthe detained group.457"},{"id":"a-hrc-57-crp-6-p0245","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"245","seq":250,"section":"VII. Findings on violations of international human rights law and","text":"Other victims recounted being arrested by the SAF while leaving or fleeing their\nareas.458 For example, an interviewee reported having been arrested with 40 young people by\nthe SAF while fleeing Kordofan to South Sudan in September 2023.459"},{"id":"a-hrc-57-crp-6-p0246","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"246","seq":251,"section":"VII. Findings on violations of international human rights law and","text":"Arrests were conducted without a warrant or any other type of legal documentation.460\nFor example, one victim stated that, when the SAF raided his house in Southeast Khartoum\nin early 2024 to arrest him, he heard soldiers tell his family that they had received an order\nto arrest him, but the soldiers failed to provide any document or legal proof of the said\norder.461 The victim added that all actions of the soldiers were taken without legal\ndocumentation, on the sole claim that they had an order. Many individuals were arrested on\nallegations of supporting the other party to the conflict.462"},{"id":"a-hrc-57-crp-6-p0247","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"247","seq":252,"section":"VII. Findings on violations of international human rights law and","text":"Former detainees told the Fact-Finding Mission that they were held together with\nhundreds of other detainees.463 A man who was detained at a SAF detention centre in\nDecember 2023, estimated the number of detainees at around 400.464 Another former detainee\ntold the mission he was detained alongside more than 600 other persons at an RSF detention\nfacility in November 2023.465 Boys under the age of 18 were arrested and held in both SAF\nand RSF detention facilities together with male detainees in Khartoum and Darfur.466"},{"id":"a-hrc-57-crp-6-p0248","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"248","seq":253,"section":"VII. Findings on violations of international human rights law and","text":"Harsh detention conditions were reported. Victims said that they were detained in\nextremely congested facilities, in inhumane conditions without access to adequate food,\nwater and sanitation facilities.467 For example, a victim who was detained by the SAF said\nthat he was held together with more than 70 other people in a room that measured 6x4 metres\nin size with a small window and a ventilator that wasn’t functioning well. 468 The witness\nadded that they were initially 72 persons inside, but after some people were removed, 42\nwere left in the room. Everyone was standing and it was impossible to sit. They were allowed\nto use the toilet once a day. Medical facilities appear to have been totally lacking."},{"id":"a-hrc-57-crp-6-p0249","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"249","seq":254,"section":"VII. Findings on violations of international human rights law and","text":"The dire conditions of detention had a severe impact on the detainees. An interviewee\ndetained by the RSF in “a basement” in Khartoum for more than a month between July and\nAugust 2023 told the Fact-Finding Mission that such deplorable conditions led to severe\npsychological impact on some detainees, with a number losing their mental health: “Twelve\ndays into the detention, the witness began experiencing severe headaches and temporary\nlosses of vision, with episodes where everything would briefly turn black. The passage of time\nfelt very slow and never ending.”469"},{"id":"a-hrc-57-crp-6-p0250","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"250","seq":255,"section":"VII. Findings on violations of international human rights law and","text":"Deaths in detention in both SAF and RSF facilities have also been documented.470\nSources informed the Fact-Finding Mission that detainees in both SAF and RSF facilities\nwere denied adequate food, water, and hygiene materials which exacerbated the already\nhorrific conditions of detention and led to disease and death.471"},{"id":"a-hrc-57-crp-6-p0251","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"251","seq":256,"section":"VII. Findings on violations of international human rights law and","text":"With regard to SAF, a former detainee reported that nine people died at the SAF\nfacility during the time when he was detained there, around December 2023, including a\nyoung man who died after he was brought back from interrogation completely covered in\nblood. One witness said:\n“[...] [We] were not given salt and sugar to keep [us] weak. 9 people died in\ndetention while [I] was [...] There was someone called [...]. [I] saw them [sic]\nwhen he just came back from interrogation, and he was very bloodied and\nhighly disturbed. He was perhaps just 18 years old and part of a resistance\ncommittee. He did not say that he was raped, but [I] and the other detainees\nthought that may have happened to him. Eventually that person passed away\nin detention”472"},{"id":"a-hrc-57-crp-6-p0252","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"252","seq":257,"section":"VII. Findings on violations of international human rights law and","text":"With regard to RSF, the Fact-Finding Mission documented the death of individuals in\nunofficial detention centres operated by the RSF in Khartoum, due to torture and lack of\nhealth care.473 For example, a former detainee who was detained in a police station in\nOmdurman in June 2023 reported to the Fact-Finding Mission that the RSF brought four\npeople who had been arrested to the same location, tortured them and two of them died as a\nresult. The RSF then brought petrol and burnt the bodies. 474"},{"id":"a-hrc-57-crp-6-p0253","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"253","seq":258,"section":"VII. Findings on violations of international human rights law and","text":"Interviewees reported spending several weeks in detention without access to legal\nassistance or family visits.475 One man, arrested in 2024, was held in one of the SAF\nheadquarters for several weeks without being able to receive a family visit; it was not for lack\nof effort from the family to visit, but rather that they were denied the right to visit by the SAF\nagents.476 The Fact-Finding Mission also received allegations suggesting that family\nmembers of individuals sought by the SAF were detained to pressure the sought individuals\nto surrender.477"},{"id":"a-hrc-57-crp-6-p0254","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"254","seq":259,"section":"VII. Findings on violations of international human rights law and","text":"Several witnesses told the Fact-Finding Mission that relatives of the detained persons\nwere forced by the RSF to pay ransom. Former detainees told the Fact-Finding Mission that\nmembers of the RSF extorted their family members of large sums of money promising to\nrelease the individuals or to allow them to visit.478 One interviewee stated:\n“[I] saw a RSF detention centre in East Nile in a building attached to a gas\nstation “Toromba”. RSF were bringing tied up men and detaining them in this\nbuilding and would only release them after receiving ransom from their\nfamilies. [I] had 5 of [my] relatives detained at the same place and went and\nspoke to the armed guard (who spoke in the Arab dialect) at the door to release\nthem, however the guard refused to release them unless [I] pay 20 thousand\nSudanese pounds. [I] did not have the money. [I] then returned the following\nday and paid the guard 10 thousand Sudanese pounds, and they were\nreleased”479"},{"id":"a-hrc-57-crp-6-p0255","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"255","seq":260,"section":"VII. Findings on violations of international human rights law and","text":"Based on the above, the Fact-Finding Mission finds that both the RSF and SAF\narbitrarily arrested and detained civilians, including children, in violation of fundamental\nguarantees under international humanitarian law and international human rights law.\nIndividuals, including children, were not informed of the reasons for their arrest, or any\ncharges brought against them, and often held in unofficial detention locations in inhumane\nconditions, in some cases resulting in deaths, and without access to legal assistance or judicial\noversight in violation of the ICCPR and CRC.\nf.     Torture and other cruel inhuman and degrading treatment or punishment"},{"id":"a-hrc-57-crp-6-p0256","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"256","seq":261,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission found that acts amounting to torture and other forms of ill-\ntreatment were carried out by the SAF, including its Military Intelligence, and by the RSF\nand its allied militias."},{"id":"a-hrc-57-crp-6-p0257","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"257","seq":262,"section":"VII. Findings on violations of international human rights law and","text":"Civilians were often subjected to severe beatings while held inside their homes,\nparticularly during raids by the RSF and its allied militias in El Geneina. Others reported\nbeing attacked physically at checkpoints set up by the RSF on the way between El Geneina\nand Adré. One of the interviewees stated that an RSF member pulled her to the side of the\nroad that leads to Adré and whipped her because she was defending herself from being\nraped.480"},{"id":"a-hrc-57-crp-6-p0258","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"258","seq":263,"section":"VII. Findings on violations of international human rights law and","text":"In the incidents documented by the Fact-Finding Mission, the victims were subjected\nto intense physical and/or mental pain or suffering. One victim described how, in May 2023,\nthe RSF took her from a house in El Geneina, blindfolded her and transferred her to another\nlocation where they severely whipped her for what seemed like a long duration of time. They\nalso pulled out her hair with their hands. She lost consciousness.481"},{"id":"a-hrc-57-crp-6-p0259","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"259","seq":264,"section":"VII. Findings on violations of international human rights law and","text":"The most common methods which were used by the SAF included pouring cold water\non the victim; beating the victim on various parts of the body or, in some cases, on the entire\nbody with iron cables, whip, rifles and weapons; causing sometimes deep cuts and bleeding,\npulling out or damaging the victim's finger or toenails, and lashing. An interviewee who was\narrested a few times in May 2023 and detained by the SAF in Omdurman reported:\n“[I] was tak[en] to the SAF Engineering Military Base in Omdurman, [...].\nThe first time [I] stayed with them for a week. [I] was beaten with metal rods\non [my] back and feet. They broke [my] toes and left leg. They pulled out [my]\ntoenails and [I] lost all sense in [my] feet. The second time for two days, also\nheavy beating on [my] back. The third time for 4 days, also beaten. I ha[ve]\ncontinued pain on legs, back and head.”482"},{"id":"a-hrc-57-crp-6-p0260","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"260","seq":265,"section":"VII. Findings on violations of international human rights law and","text":"The most common methods of torture identified by the Fact-Finding Mission as being\nused by the RSF included lashing and beating the victim on various parts of the body or, in\nsome cases, on the entire body with iron cables, whip, rifles and weapons. An interviewee\nwho was captured by RSF allied militias in early 2024 told the Fact-Finding Mission:\n“[...] [the militias] wanted to kill [me] and get rid of [me] without leaving\nany trace by tying [me] up and hanging [me] while [I] was blindfolded and\ngagged, so that [I] could not scream, even though the area was devoid of any\nresidents. [...]. [I] was beaten and tortured there by seven men. They were\nasking [me] questions about [my] work and accusing [me] of being a\ncollaborator and military. They put a [sic] iron cable (used in a motorcycle)\naround [my] neck. They would move and drag [me] forcefully using the cable.\n[I] lost [my] breath and lost consciousness. Then [I] was severely beaten and\nkicked in [my] stomach and lost consciousness again.”483"},{"id":"a-hrc-57-crp-6-p0261","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"261","seq":266,"section":"VII. Findings on violations of international human rights law and","text":"Other reports and publications highlighted instances of torture inflicted on detainees\nby the SAF and the RSF which were filmed.484 In one incident, SAF reportedly tortured “six\nblindfolded detainees with their hands tied behind their backs by whipping and beating them\nwith sticks.”485 In another reported incident, an RSF member in uniform “placed his boot on\nthe neck of a man lying on the tarmac. A second victim, a man in a red T-shirt, is lying still\non his side on the tarmac with a pool of blood surrounding his lower back.”486"},{"id":"a-hrc-57-crp-6-p0262","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"262","seq":267,"section":"VII. Findings on violations of international human rights law and","text":"Testimonies gathered by the Fact-Finding Mission indicate that threats and torture\nwere used by the SAF in an attempt to extract confessions from the detainees on their alleged\naffiliation or collaboration with the RSF.487 An interviewee stated that when he was\ninterrogated by the SAF during his detention, the interrogator would instruct the personnel to\nconduct different types of torture if he did not answer. They asked him about “collaboration\nwith the enemy”.488 Another victim detained by the SAF described that he was beaten and\npoked with needles in different parts of his body by SAF officers while interrogating him\nabout his political views, affiliations and activities including his relationship with the Forces\nof Freedom and Change and Resistance Committees and whether he participated in the civil\nuprising.489"},{"id":"a-hrc-57-crp-6-p0263","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"263","seq":268,"section":"VII. Findings on violations of international human rights law and","text":"Witnesses stated that underage boys were also subjected to acts of torture or other\ncruel, inhuman or degrading treatment.490 Children were also deprived of food and water as\nwas the case for adult detainees. One interviewee who had been detained at Al Nakheel Police\nStation in Omdurman described that the RSF beat detainees with electric rods and whips,\nsometimes on their genitals, adding:\n“[...] The children were badly tortured, so much that any man seeing them could have\ncried. They had lots of scars on their body and one of them after a week, lost awareness\naround him.”"},{"id":"a-hrc-57-crp-6-p0264","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"264","seq":269,"section":"VII. Findings on violations of international human rights law and","text":"Evidence gathered also indicates that the RSF used teenage boys as prison wards and\nto inflict torture on other detainees, notably in Al Nakheel Police Station in Omdurman.491"},{"id":"a-hrc-57-crp-6-p0265","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"265","seq":270,"section":"VII. Findings on violations of international human rights law and","text":"Based on the foregoing, the Fact-Finding Mission finds that both the SAF and RSF\nintentionally inflicted severe physical and mental pain or suffering on its victims, including\nchildren, with the purpose of intimidating, coercing or obtaining a confession from them or\nas a form of punishment or on a discriminatory basis. These acts amount to violations of\ninternational humanitarian law of violence to life and person, in particular cruel treatment\nand torture, and outrages upon personal dignity, in particular humiliating and degrading\ntreatment. They also amount to violations of international human rights law, in particular\nunder the CAT and CRC.\ng.     Suppression of free speech, information and media"},{"id":"a-hrc-57-crp-6-p0266","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"266","seq":271,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission established that freedom of opinion and expression have\nbeen curtailed by both the SAF and RSF in numerous ways since the outbreak of hostilities\nin mid-April 2023. Incidents documented by the Fact-Finding Mission include attacks and\nreprisals on journalists and members of the press, including arbitrary detention, torture, and\nsexual violence, attacks and reprisals against human rights defenders, activists, and members\nof the Emergency Response Rooms and civil society. These incidents included surveillance,\nmonitoring, and physical violence; threats, intimidation, and warnings against publishing\ncertain information or expressing certain views; armed takeovers of media buildings and/or\ncompanies; and repeated network disruptions and shutdowns of the internet, often for lengthy\nperiods of time.\nSuppression of Information and Internet shutdown"},{"id":"a-hrc-57-crp-6-p0267","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"267","seq":272,"section":"VII. Findings on violations of international human rights law and","text":"Following the eruption of the conflict in mid-April 2023, there was an immediate\nblackout of information and communication. Key media outlets and telecommunications\nservices were suspended or shut down, first in the Khartoum area, leading to widespread\nblackouts that severely impacted the population across all of the Sudan. On 16 April 2023,\nthe RSF seized control of the state-owned Sudan TV building in Omdurman. RSF soldiers\nstormed the building, disrupting transmission and restricting broadcasters from going on air\nto prevent news updates from being broadcast to the public.492 The RSF reportedly used the\nstate broadcast building for military operations.493 The SAF immediately cut broadcast\nsignals.494 State radio was also cut after the RSF used radio networks to broadcast\npropaganda,495 and MTN Sudan blocked internet services reportedly at the request of the\ngovernment’s telecommunications regulator for several hours on 16 April 2023.496"},{"id":"a-hrc-57-crp-6-p0268","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"268","seq":273,"section":"VII. Findings on violations of international human rights law and","text":"Following the seizure by the RSF of the critical communication infrastructure,\nincluding the Sudan TV building and the Sudatel Data Centre (Sudan Telecommunications\nGroup) which houses the company’s internet and telecommunications data centres, major\nnetwork disruptions were observed. According to media reports, in February 2024, the RSF\nshut down telecommunications services provided by the two largest providers in the Sudan,\nMTN Sudan and Sudani.497 Reportedly, the RSF also forced Zain Sudan, the third largest\nprovider of telecommunications services in the Sudan, to stop its services in River Nile State\nand Port Sudan.498 These actions left civilians unable to access essential services or contact\ntheir families, causing significant psychological distress and compounding the humanitarian\ncrisis. Many Sudanese civilians rely on online payments for food and other essentials, which\nthey could no longer access due to network disruptions."},{"id":"a-hrc-57-crp-6-p0269","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"269","seq":274,"section":"VII. Findings on violations of international human rights law and","text":"The internet shutdown in the Sudan in February 2024 led to a near-total\ncommunication blackout and had significant and wide-ranging effects on the civilian\npopulation. The communications shutdown severely hindered humanitarian and emergency\nservices, left millions unable to access essential services, communicate with family, or\nreceive mobile money transfers, further jeopardized the safety and well-being of especially\nvulnerable populations, and exacerbated already poor conditions in conflict-affected areas of\nthe country. The internet shutdown hampered the work of frontline humanitarian aid\nproviders, for example persons working in the Emergency Response Rooms. The internet\nshutdown effectively paralyzed their work, rendering them unable to communicate and\ncoordinate with colleagues and unable to buy food, medicine, and other medical equipment\nfor those in need. The network shutdown also worsened the existing humanitarian crisis.499\nCensorship and restrictions on freedom of the media"},{"id":"a-hrc-57-crp-6-p0270","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"270","seq":275,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission found that the conflict has been marked by systematic\ncensorship and suppression of print and electronic media freedom by both the RSF and SAF.\nIn particular, both the RSF and the SAF have restricted the journalists and other members of\nthe press from speaking to international media. For instance, during the RSF occupation of\nSudan TV, employees reported that they were prohibited from speaking to any international\nmedia about the conflict.\"500"},{"id":"a-hrc-57-crp-6-p0271","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"271","seq":276,"section":"VII. Findings on violations of international human rights law and","text":"Due to threats, intimidation, and fear of arrests or reprisals, Sudanese media has\nreportedly self-censored, especially with respect to reporting on corruption and the security\nservices.501 The systemic targeting of both print and electronic media companies has forced\nmost to cease operations,502 leaving a majority of Sudanese journalists with unpaid dues and\nno viable source of income.503\nAttacks on journalists, media and civil society actors"},{"id":"a-hrc-57-crp-6-p0272","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"272","seq":277,"section":"VII. Findings on violations of international human rights law and","text":"Numerous reports indicate that since mid-April 2023 both the RSF and the SAF have\nthreatened, intimidated, harassed, and attacked journalists and media professionals. Women\njournalists, human rights defenders and activists were at a heightened risk, as they were\nparticularly vulnerable to gender-based violence and/or conflict-related sexual violence.504\nThe intimidation of media professionals has taken a range of forms, including reported\nconducting of raids on both the workplaces and private homes of journalists, damaging and/or\nconfiscating equipment, and mass detentions of media employees at their place of work.\nIntimidation has generally been used to suppress critical or unfavourable reporting or to\nprevent journalists from reporting on the conflict."},{"id":"a-hrc-57-crp-6-p0273","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"273","seq":278,"section":"VII. Findings on violations of international human rights law and","text":"One case documented by the Fact-Finding Mission concerned a female journalist who\nwas threatened by the RSF after being linked to media coverage of violations reportedly\ncommitted by RSF members. The repeated threats extended to her family members and\nforced her to flee.505 In another incident in May 2023, two journalists were stopped at an RSF\ncheckpoint as they tried to escape Khartoum and detained after presenting their identification,\nwhich included press cards.506 Accused of being SAF supporters, the journalists were\ninterrogated and their phones and laptops searched by the RSF. The journalists themselves\nwere threatened with death if the laptops revealed that they were aligned with the Sudanese\nmilitary. They were later released."},{"id":"a-hrc-57-crp-6-p0274","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"274","seq":279,"section":"VII. Findings on violations of international human rights law and","text":"The warring parties reportedly targeted print and electronic media entities with violent\nattacks and other forms of intimidation. In early April, SAF soldiers reportedly twice opened\nfire on the headquarters of Al-Jarida newspaper.507 In several cases, SAF soldiers reportedly\ndetained journalists at their workplaces for days at a time.508 In the first days of the conflict,\nfifteen journalists were reportedly detained at the Sudan News Agency building for 72\nhours.509 As a further example, nine journalists from Al Araby TV and four journalists\nworking for Al Arabiya and Al Hadath news channels were reportedly detained in their\noffices in Al-Neelein Towers from 15 to 23 April 2023.510"},{"id":"a-hrc-57-crp-6-p0275","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"275","seq":280,"section":"VII. Findings on violations of international human rights law and","text":"The Fact-Finding Mission has also documented multiple incidents of threats,\nintimidation, harassment, attacks and reprisals against human rights defenders, lawyers and\nactivists documenting human rights violations, and members of civil society, by both the SAF\nand RSF. For instance, a survivor informed the Fact-Finding Mission that RSF allied militias\nin El Geneina arrested and tortured her apparently due to her activities documenting human\nrights violations allegedly perpetrated by the RSF and its allies.511 Another person reported\nbeing abducted and tortured by the RSF in Omdurman in early 2024 and was accused of\nbeing a SAF collaborator and a spy due to his activism.512"},{"id":"a-hrc-57-crp-6-p0276","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"276","seq":281,"section":"VII. Findings on violations of international human rights law and","text":"Based on the foregoing, the Fact-Finding Mission finds that both RSF and SAF\nimposed broad internet shutdowns by cutting access to information and communication\nthrough internet and media services and curtailing free speech of journalists and the media\nincompatible with the right to freedom of opinion and expression under the ICCPR and\nACHPR.513\nh.     Access to Humanitarian aid\nHumanitarian needs in the Sudan"},{"id":"a-hrc-57-crp-6-p0277","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"277","seq":282,"section":"VII. Findings on violations of international human rights law and","text":"According to the United Nations Office for the Coordination of Humanitarian Affairs\n(OCHA), close to 16 million people were in need of lifesaving assistance due to prolonged\ninternal conflicts and instabilities, and economic crisis before the conflict between SAF and\nRSF broke out. 514 Sixteen months later, the conflict engulfed the vast parts of the Sudan and\naggravated the humanitarian crisis in the country. By August 2024, more than half of the\nSudanese population - 26.5 million people – was experiencing acute hunger. Among them,\nmore than 8.5 million people are facing emergency levels of hunger (IPC 4) and more than\n755,000 were in catastrophic conditions (IPC 5) in Darfur states, South and North Kordofan,\nBlue Nile, Gezira, and Khartoum.515"},{"id":"a-hrc-57-crp-6-p0278","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"278","seq":283,"section":"VII. Findings on violations of international human rights law and","text":"In July 2024, IOM estimated that 10.7 million people were internally displaced, which\nincludes an estimated 7.9 million people who fled their homes since the start of the conflict.\nChildren under the age of 18 years comprised more than half (52 per cent) of the internally\ndisplaced population in the Sudan.516"},{"id":"a-hrc-57-crp-6-p0279","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"279","seq":284,"section":"VII. Findings on violations of international human rights law and","text":"While the conflict pushed the Sudan’s health system to the verge of collapse, people\nin the Sudan are facing a lethal combination of displacement, shortage of potable water,\nhunger and disease. In July 2024, the Famine Review Committee (FRC) of the Integrated\nFood Security Phase Classification (IPC) determined that famine conditions (IPC 5) are\nprevalent in one of the IDP camps. This means “at least one in five (or 20 per cent) people\nor households have an extreme lack of food and face starvation and destitution, resulting in\nextremely critical levels of acute malnutrition and death.”517"},{"id":"a-hrc-57-crp-6-p0280","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"280","seq":285,"section":"VII. Findings on violations of international human rights law and","text":"Since the beginning of the conflict in mid-April 2023, an estimated 700,000 people\nfled to Nuba Mountain, an area bordering South Sudan and which has been under the\nadministration of the SPLM-N for decades.518 Though Nuba Mountain offered peace for\ninternally displaced persons from other parts of the Sudan, the humanitarian situation\ndeteriorated so much that the SPLM-N, which is administering the area declared famine.519\nDenial of humanitarian access"},{"id":"a-hrc-57-crp-6-p0281","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"281","seq":286,"section":"VII. Findings on violations of international human rights law and","text":"In its Mid-Year Humanitarian Situation Report, UNICEF drew attention to the\nchallenges faced by humanitarian actors in delivering assistance to vulnerable communities\nin Kordofan, Darfur, and Khartoum due to bureaucratic hurdles, active armed conflict, and\nlack of commitment from parties to the conflict to ensure safety of operations. While the need\nfor humanitarian aid in the Sudan has drastically increased since the beginning of the conflict,\nthe delivery of the humanitarian did not match the need. Access restrictions, including\nadministrative impediments, and insecurity for humanitarian aid and humanitarian workers\nhave further aggravated the humanitarian crisis."},{"id":"a-hrc-57-crp-6-p0282","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"282","seq":287,"section":"VII. Findings on violations of international human rights law and","text":"Access restrictions, including administrative impediments, and insecurity for\nhumanitarian aid and humanitarian workers have further aggravated the humanitarian crisis.\nHumanitarian organizations operating in the Sudan indicated that they are facing multiple\nchallenges. These include arbitrary denial of, or delays in processing visa applications for\nhumanitarian workers, restrictions on border-crossing options for humanitarian aid, delays in\nissuing travel permits for humanitarian workers and authorizing domestic humanitarian\nmovement.520 According to OCHA, “the planned movement of over 125 trucks to hard-to-\nreach areas have been pending approval for over 90 days” since the beginning of March\n2024 affecting delivery of humanitarian aid in South, Central, North and East Darfur, and\nKhartoum states.521"},{"id":"a-hrc-57-crp-6-p0283","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"283","seq":288,"section":"VII. Findings on violations of international human rights law and","text":"Since August 2023, the RSF has also established the Sudanese Agency for Relief and\nHumanitarian Operations (SAHRO). Though humanitarian organizations acknowledged that\nSAHRO used to be better at facilitating humanitarian aid during the first few months, it also\nintroduced administrative impediments such as registration of humanitarian organizations,\nmandatory travel permit approval for the movement of humanitarian personnel and supplies\nin areas under RSF Control.522 Representatives of humanitarian agencies have told the Fact-\nFinding Mission that the RSF recently introduced a mandatory list of vendors from whom\nhumanitarian organizations must procure goods and services if they procure them locally - a\nmove that would endanger the neutrality of humanitarian operations and organizations.523"},{"id":"a-hrc-57-crp-6-p0284","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"284","seq":289,"section":"VII. Findings on violations of international human rights law and","text":"The SAF hampered the transport of humanitarian aid through border-crossings that\nfacilitate access to communities in need of aid, especially access to locations controlled by\nthe RSF. The RSF is similarly preventing access to areas under the control of the SAF. From\nFebruary to August 2024, the SAF blocked the use of the Adré border crossing for passage\nof humanitarian assistance from Chad based on the perception that it would benefit the RSF,\nwhile the RSF blocked the delivery of medical supplies to El Fasher city on the basis that it\nwould benefit SAF forces in the city. The Sudanese authorities agreed to re-open the Adré\nborder crossing, as talks led by the United States of America continued in Geneva from 14\nAugust 2024.524"},{"id":"a-hrc-57-crp-6-p0285","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"285","seq":290,"section":"VII. Findings on violations of international human rights law and","text":"Based on the foregoing, the Fact-Finding Mission finds that both the SAF and RSF\nhave engaged in actions contrary to their obligations under international humanitarian law\nregarding unimpeded and rapid passage of humanitarian relief for civilians in need, despite\nthe repeated calls by the United Nations Security Council to allow and facilitate the full,\nrapid, safe, unhindered, and sustained passage of humanitarian relief for civilians in need.525"},{"id":"a-hrc-57-crp-6-p0286","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"286","seq":291,"section":"VIII. International Crimes and their Perpetrators","text":"The Fact-Finding Mission has examined the above findings in accordance with its\nstandard of proof under international human rights law and international humanitarian law\nthrough the lens of international criminal law, which provides for individual criminal\nresponsibility over the core international crimes of war crimes, crimes against humanity and\ngenocide. The Fact-Finding Mission underlines that there is no hierarchy among international\ncrimes and the finding of fact on one international crime does not exclude the others, as one\nset of conduct can constitute several international crimes."},{"id":"a-hrc-57-crp-6-p0287","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"287","seq":292,"section":"VIII. International Crimes and their Perpetrators","text":"In accordance with the standard of proof of the Fact-Finding Mission, determinations\nof factual findings on international crimes are based on the ‘reasonable grounds to believe’\nstandard. This means that a finding should be understood to indicate that there is verified and\ncorroborated information and/or evidence to support the suspicion or probability that a certain\nfact or pattern has occurred, leading, when measured against legal standards, to the\nconclusion that there are reasonable grounds to believe that certain crimes have occurred.\nThis is a lower standard than the beyond reasonable doubt standard used by prosecutors and\na competent court of law to establish guilt or innocence after a fair trial. Rather, a finding of\nreasonable grounds to believe establishes a threshold of proof that should lead a competent\nprosecutor to further investigate the conduct in question with a view to determining whether\nto issue an indictment.\nWar crimes"},{"id":"a-hrc-57-crp-6-p0288","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"288","seq":293,"section":"VIII. International Crimes and their Perpetrators","text":"For a finding on the commission of war crimes to be made by the Fact-Finding\nMission, it must be established that the situation in the Sudan qualifies as a non-international\narmed conflict on the basis of two cumulative criteria; that of the level of intensity and the\ndegree of organization of the armed entities involved. It must further be established that the\nconduct in question took place in the context of and was associated with the non-international\narmed conflict in the Sudan since mid-April 2023 (‘nexus requirement’). 526 War crimes\ninclude serious violations of Common Article 3 and Additional Protocol II, to which the\nSudan is a State party, as well as of rules of customary international humanitarian law\napplicable to non-international armed conflicts."},{"id":"a-hrc-57-crp-6-p0289","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"289","seq":294,"section":"VIII. International Crimes and their Perpetrators","text":"The Fact-Finding Mission has determined that the threshold for the existence of a non-\ninternational armed conflict in the Sudan has been met (See Chapter IV on Applicable Law).\nThe Fact-Finding Mission further finds that the above-described violations took place in the\ncontext of and with a nexus to the non-international armed conflict in the Sudan since mid-\nApril 2023. On this basis, it finds reasonable grounds to believe that many of the established\nviolations of international humanitarian law constitute war crimes."},{"id":"a-hrc-57-crp-6-p0290","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"290","seq":295,"section":"VIII. International Crimes and their Perpetrators","text":"The Fact-Finding Mission finds reasonable grounds to believe that the RSF and its\nallied militias committed the war crimes of violence to life and person, in particular murder\nof all kinds, mutilation, cruel treatment and torture; committing outrages upon personal\ndignity, in particular humiliating and degrading treatment; rape, sexual slavery and any form\nof indecent assault; pillage of towns or places; conscripting or enlisting children under the\nage of 15 or using them to participate actively in hostilities; intentionally directing attacks\nagainst the civilian population; and ordering the displacement of the civilian population for\nreasons related to the conflict."},{"id":"a-hrc-57-crp-6-p0291","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"291","seq":296,"section":"VIII. International Crimes and their Perpetrators","text":"It also finds reasonable grounds to believe that the SAF committed the war crimes of\nviolence to life and person, in particular murder of all kinds, mutilation, cruel treatment and\ntorture; committing outrages upon personal dignity, in particular humiliating and degrading\ntreatment.\nCrimes against humanity"},{"id":"a-hrc-57-crp-6-p0292","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"292","seq":297,"section":"VIII. International Crimes and their Perpetrators","text":"Crimes against humanity concern the commission of prohibited acts as part of a\nwidespread or systematic attack directed against any civilian population, with knowledge of\nthe attack. To establish the existence of an attack against the civilian population, the Fact-\nFinding Mission considers it must find reasonable grounds to believe that multiple acts were\ndirected against a predominantly civilian population pursuant to or in furtherance of a State\nor organizational policy.527 Such policy may comprise acts and/or omissions and be inferred\nfrom the facts.528 It must further establish reasonable grounds to believe that the attack was\nwidespread or systematic in nature. Widespread relates to the large-scale nature of the attack\nand number of victims.529 Systematic refers to its organized character and often involves a\nplan or policy.530"},{"id":"a-hrc-57-crp-6-p0293","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"293","seq":298,"section":"VIII. International Crimes and their Perpetrators","text":"The Fact-Finding Mission has established the existence of a large-scale attack by the\nRSF and its allied militias against the predominantly non-Arab civilian population, in\nparticular the ethnic Masalit, in El Geneina, West Darfur, and other areas along flight routes\nof civilians coming from El Geneina. On the basis of an examination of the facts, it finds that\nthis attack was widespread and/or systematic in nature. It further finds, on the basis of\ninferences drawn from the facts, that the attack was carried out pursuant to or in furtherance\nof an organizational policy."},{"id":"a-hrc-57-crp-6-p0294","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"294","seq":299,"section":"VIII. International Crimes and their Perpetrators","text":"On this basis, the Fact-Finding Mission finds reasonable grounds to believe that the\nRSF and its allied militias committed the crimes against humanity of murder; torture;\nenslavement; rape, sexual slavery, and acts of a sexual nature of comparable gravity;\npersecution on the basis of intersecting ethnic and gender grounds in connection with the\nforegoing acts; and forcible displacement of population.\nIdentification of persons and entities responsible"},{"id":"a-hrc-57-crp-6-p0295","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"295","seq":300,"section":"VIII. International Crimes and their Perpetrators","text":"The Fact-Finding Mission has been mandated to support accountability efforts,\nincluding to identify to the extent possible those individuals and entities responsible for the\nabove-described violations and abuses, and related crimes. To this end, its investigation\nstrategy has included the identification of alleged perpetrators. Where the standard of proof\nof reasonable grounds to believe as applied by the Fact-Finding Mission has been met, it will\ninclude those individuals and entities in a confidential list with a view to developing dossiers."},{"id":"a-hrc-57-crp-6-p0296","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"296","seq":301,"section":"IX. Accountability","text":"The Sudan carries the primary responsibility to prevent and halt violations and abuses\nof human rights and violations of international humanitarian law. In line with the United\nNations Basic Principles and Guidelines on the Right to a Remedy and Reparation for Victims\nof Gross Violations of International Human Rights Law and Serious Violations of\nInternational Humanitarian Law it must provide remedies and reparations to survivors. To\ndischarge this responsibility, it must take appropriate measures, including legislative and\nadministrative, to prevent and ensure accountability for international crimes committed on\nits territory. This requires that the domestic legal system of the Sudan is able and the\nauthorities willing to carry out investigations effectively, promptly, thoroughly and\nimpartially, and as appropriate, prosecute those responsible.531 In line with the principle of\ncomplementarity and as a basis for its jurisdiction, the International Criminal Court assessed\nthe Sudan to be unwilling or unable to investigate and prosecute international crimes\ncommitted in the Darfur conflict leading to the United Nations Security Council referral to\nthe Court in 2005.532"},{"id":"a-hrc-57-crp-6-p0297","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"297","seq":302,"section":"IX. Accountability","text":"Victims are “persons who individually or collectively suffered harm, including\nphysical or mental injury, emotional suffering, economic loss or substantial impairment of\ntheir fundamental rights, through acts or omissions that constitute gross violations of\ninternational human rights law, or serious violations of international humanitarian law”.533\nThey may include their immediate family and dependents, as well as persons who suffered\nharm through intervening to assist victims or prevent victimization.534 All survivors should\nbe treated with humanity and dignity for their human rights.535 They should be placed at the\ncentre of any accountability process and, as part of their right to remedies, be provided with\nequal and effective access to justice. This should include access to judicial and other\nappropriate remedies at the national and international levels as may be available.536 Remedies\nfurther include adequate, effective and prompt reparation for harm suffered and access to\nrelevant information concerning violations and reparation mechanisms.537\nThe Sudan’s domestic legal system"},{"id":"a-hrc-57-crp-6-p0298","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"298","seq":303,"section":"IX. Accountability","text":"Following the removal of former President Omar Al Bashir, the 2019 Transitional\nConstitutional Document (Constitutional Decree No. 38), amended in 2020 following the\nJuba Peace Agreement, set out legislative and institutional reforms to be undertaken by State\nagencies to address the country’s legacy of past violations.538 The process was, however, cut\nshort following the 2021 military takeover and the subsequent eruption of the current conflict."},{"id":"a-hrc-57-crp-6-p0299","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"299","seq":304,"section":"IX. Accountability","text":"The Sudan’s Criminal Act of 1991, as amended in 2009, provides for criminal\nresponsibility over a range of offences, including offences affecting persons and the human\nbody, or against honour, reputation, public morality or personal liberty, such as murder, rape,\nabortion, and unlawful confinement or detention. It also criminalizes offences against the\nstate, including undermining the constitutional system, waging war against the state,\nespionage, disclosure of secret matters relating to the affairs of the state, as well as sedition,\nsuch as publishing false news. The 2009 amendment added a chapter criminalizing certain\nacts as crimes against humanity, war crimes and genocide.539 The Sudan maintains the death\npenalty for crimes of extreme gravity, which include offences against the state and\ninternational crimes.540 The Armed Forces Act of 2007, amended in 2022, also contains\nprovisions on war crimes including offences against protected persons and prisoners of war,\nattacks on civilians, and displacement of the population. Criminal procedures are laid out in\nthe Criminal Procedure Act of 1991, amended in 2009, and the Evidence Act of 1994."},{"id":"a-hrc-57-crp-6-p0300","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"300","seq":305,"section":"IX. Accountability","text":"In relation to international crimes, the categories and definitions employed in the\nSudanese legislation are however narrower than the ambit recognized by international law\nthereby impeding accountability for the full range of international crimes committed at the\nnational level. For example, the definition of war crimes adds knowledge of the commission\nof war crimes - instead of the factual circumstances prevailing at the time - as a threshold for\napplication and limits the war crime of murder to the killing of one or more persons belonging\nto a protected group as opposed to any civilian or person hors de combat in the context of an\narmed conflict.541 It further does not include sexual slavery as a war crime. While crimes\nagainst humanity can be committed in times of conflict and in peace,542 some of the\nunderlying crimes listed in the 2009 amendment, such as forcible deportation or transfer and\nforced pregnancy, are limited to the context of an armed conflict. 543 In addition, the crime\nagainst humanity of extermination is not defined in the 2009 amendment, which only lists\nthe intentional killing of one or more persons. The definition of genocide to the contrary adds\nhomicide, including attempt or incitement, as a chapeau element and requires that it takes\nplace in the context of large-scale or systematic conduct directed against the protected group,\nwhich it limits to national, ethnic or religious grounds, thereby excluding racial groups."},{"id":"a-hrc-57-crp-6-p0301","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"301","seq":306,"section":"IX. Accountability","text":"The Fact-Finding Mission is further concerned over the definition of rape and other\nforms of sexual violence contained in domestic legislation, which falls short of international\nstandards rendering it inadequate to enable the prosecution of sexual and gender-based\nviolence, including sexual violence occurring during conflict. Until 2015, the Criminal Act\nof 1991, as amended in 2009, defined rape as adultery (zina) without consent, applying the\nsame burden of proof to the crime of adultery and rape (confession of the perpetrator or\ntestimony from four male witnesses), and exposing rape survivors to being prosecuted for\nadultery or fornication if they could not prove the lack of consent. A legal reform in 2015\nredefined rape in the Criminal Act of 1991, delinking it from adultery (zina). This change\naimed to provide a clearer definition of rape, focusing on the absence of consent rather than\nthe marital status of the individuals involved. Notwithstanding this reform, rape survivors\ncontinue to be exposed to prosecution for adultery or other crimes of sexual misconduct if\nthey cannot prove the lack of consent."},{"id":"a-hrc-57-crp-6-p0302","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"302","seq":307,"section":"IX. Accountability","text":"The 1991 Criminal Act, as amended in 2009, further criminalizes same-sex sexual\nactivity between men and between women with its provision on “sodomy” (applicable to men\nonly) and “indecent acts” (applicable to both men and women) that can result in severe\npenalties, including life imprisonment, which would most likely discourage any male\nsurvivor of sexual violence by a man from attempting to restore his rights, out of fear of\nfailing to prove the rape and be prosecuted with one of these provisions. In addition, the\n(Muslim) Personal Status Act of 1991, which governs familial relations such as marriage,\ndivorce, child custody and inheritance and is primarily based on Shari’a law, permits forced\nmarriages of Sudanese women and girls. It provides that the marriage of a Muslim woman or\ngirl shall be concluded by her male guardian and authorizes the marriage of children as young\nas ten, with the authorization of a judge. Marital rape is not criminalized under Sudanese\ndomestic law.\n302. In relation to sexual violence as part of international crimes, the 2009 amendment to\nthe 1991 Criminal Act of 1991 criminalizes rape and other acts of a sexual nature as\nunderlying crimes of crimes against humanity and war crimes; however, their definitions also\nfall short of the definitions under customary international law. For instance, the crime of\nforced pregnancy as a crime against humanity adds the element of “affecting the ethnic\ncomposition”. Furthermore, victims/survivors of rape and other forms of sexual violence face\nhurdles in reporting such crimes at the national level, including due to fears of stigma,\nreprisals and/or being prosecuted for adultery. Concerns have in this regard been shared with\nthe Fact-Finding Mission over the legal procedures necessary to prove rape, in particular the\nobligatory use of Form No. 8, a medical report which has become unavailable in many health\nfacilities or police stations 544"},{"id":"a-hrc-57-crp-6-p0303","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"303","seq":308,"section":"IX. Accountability","text":"Moreover, while the CAT has direct effect at the national level pursuant to Article\n42(2) of the 2019 Transitional Constitutional Document, the absence of full incorporation of\nthe definitions of acts of torture and ill-treatment into Sudanese law, raises questions\nregarding its practical implementation. The definition of torture and ill-treatment provided\nunder Article 115(2) of the Criminal Act of 1991, amended in 2009, regarding the offence of\ninfluencing the course of justice is limited to “Every person who, having public authority,\nentices or threatens, or tortures any witness, or accused, or opponent to give, or refrain from\ngiving any information in any action, shall be punished, with imprisonment, for a term, not\nexceeding three months, or with fine, or with both.” This definition also falls short the\ninternational legal obligations undertaken by the Sudan under the CAT since it does not define\nall elements of the act of torture. For example, it excludes from its definition acts committed\nat the instigation or with the consent or acquiescence of a public official or person acting in\nan official capacity, acts by which severe mental pain or suffering is inflicted, and acts of\ntorture or ill-treatment inflicted as a form of punishment for acts the victim or a third person\nhas committed or is suspected of having been committed. The penalty for acts of torture or\nill-treatment as per the above domestic definition is set at a maximum of three months of\nimprisonment, or a penalty or both, which does not reflect the seriousness of the crime nor\nact as a deterrent."},{"id":"a-hrc-57-crp-6-p0304","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"304","seq":309,"section":"IX. Accountability","text":"Furthermore, the Evidence Act of 1994, Article 10(1), allows for the admission of\nevidence obtained by unlawful means “whenever the Court is satisfied with the genuineness\nof its substance.” Against the backdrop of the existence of broad immunities and based on\nthe factual and legal findings of reasonable grounds to believe that torture and other forms of\ncruel, inhuman, degrading treatment or punishment have been committed by the RSF and\nSAF, including its military intelligence, the Fact-Finding Commission is highly concerned\nover this provision, which means that tainted evidence may be admissible in court and used\nagainst the survivor/victim, leading to his, her, or their conviction in breach of the obligations\nundertaken by the Sudan, in particular under the CAT and international fair trial standards.\nThe Fact-Finding Mission believes that this provision encourages the practice of torture with\nimpunity in the Sudan."},{"id":"a-hrc-57-crp-6-p0305","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"305","seq":310,"section":"IX. Accountability","text":"The Miscellaneous Act of 2020, amending the Criminal Act of 1991, defines an adult\nas anyone over the age of 18. However, criminal responsibility may be imposed on any child\nwho has attained puberty, with care and reform measures allowed to be imposed on any child\nover the age of 12. The Fact-Finding Mission is concerned over the possible implications this\nmay have on the position of children in the justice system, including in relation to the possible\nimposition of the death penalty for crimes committed by children under the command of the\narmed forces and/or groups, and believes that child combatants should be treated as victims\nrather than as perpetrators and the minimum age for legal liability for international crimes\nshould be aligned with the international standards as reflected Rome Statute and limited to\nadults. In this regard, the Fact-Finding Mission further notes with concern that domestic\nlegislation fails to sanction the recruitment and use of children below the age of 18 by armed\ngroups.545"},{"id":"a-hrc-57-crp-6-p0306","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"306","seq":311,"section":"IX. Accountability","text":"In relation to modes of liability, the Criminal Act of 1991, amended in 2009, lists\nseveral modes, including attempt, abetment, assistance, joint criminal acts, and criminal\nconspiracy. Its 2009 Amendment also contains language on modes of liability as part of the\ndefinition of international crimes, except for war crimes. It criminalizes the commission of,\neither alone or in association with others, as well as encouraging or supporting the\ncommission of crimes against humanity, and commission, attempt to commit, or incitement\nto commit, the crime of genocide. The Armed Forces Act of 2007, under Article 153, lists\nmodes of liability for offences against civilians that would constitute war crimes, consisting\nof commission, attempt or instigation.546 However, command and superior responsibility do\nnot seem to be recognized as distinct modes in any domestic law, thereby possibly preventing\naccountability of commanders and superiors for failing to prevent and punish, and limiting\nlegal grounds for investigation and prosecution to direct perpetrators. The Fact-Finding\nMission is concerned that this gap in legislation constitutes a breach of customary\ninternational law and is preventative of accountability for perpetrators at all levels, in\nparticular of those most responsible for international crimes."},{"id":"a-hrc-57-crp-6-p0307","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"307","seq":312,"section":"IX. Accountability","text":"Limitations are further imposed on criminal procedures held at the national level, as\nlaid out in the Criminal Procedure Act of 1991, amended in 2009. Article 3 which provides\nthat any criminal procedures against any Sudanese national accused of violations of\ninternational humanitarian law, including core international crimes, may only be initiated\nbefore the Sudanese police, General Prosecution or Judiciary. In addition, it prohibits any\ngovernment body or person from providing any assistance or support to the extradition of\nany Sudanese national for overseas prosecution. This is problematic in the context of the\nSudan considering that the Armed Forces Act of 2007, the Police Forces Act of 2008, and the\nGeneral Intelligence Law (Amendment) 2024, provide for extensive immunities to all their\nrespective members and for all acts committed in the course of, or related to their duties,\nwhich can only be lifted by those higher up in the chain of command. The Fact-Finding\nMission received reports indicating a negative record when it comes to the lifting of\nimmunities of government officials in the Sudan.547"},{"id":"a-hrc-57-crp-6-p0308","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"308","seq":313,"section":"IX. Accountability","text":"The use of statutes of limitations is incompatible in the present context of the duty of\nthe State to ensure accountability for international crimes. While the 2019 Transitional\nConstitutional Document, under Article 68, dictates for state agencies to work on\nimplementing accountability measures for crimes against humanity and war crimes on the\nbasis of the principle that there may be no impunity for such crimes, Article 38 of the Criminal\nProcedure Act of 1991, amended in 2009, maintains a statute of limitations of 10 years for\noffences punishable by death or imprisonment of a minimum of 10 years. The Fact-Finding\nMission is further concerned over the potential use of general amnesties in any peace\nnegotiation process, which would constitute a breach of the Sudan’s international legal\nobligations. It reiterates that amnesties may not be provided for international crimes\nregardless of the affiliation of the perpetrator, location of the crime or typology of the victims."},{"id":"a-hrc-57-crp-6-p0309","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"309","seq":314,"section":"IX. Accountability","text":"In addition, as a vibrant civil society is an important indicator of the functioning of\nthe rule of law in any society and essential to any domestic accountability efforts, the Fact-\nFinding Mission is concerned over legislation introduced in recent years in the Sudan that\nlimits their activities or bans them altogether. The 2020 amendment to the Cyber Crime Law\nof 2018 increased penalties for a range of cyber offences, including spreading false news to\ndamage the reputation of the state. This amendment has been heavily criticized and concerns\nraised over its effect on civil society and resulting shrinking of the online civic space.548\nFurthermore, Ministerial Decree No. 1 of 2024 dissolved all change and service committees\nin the regions and states, reportedly effectively banning all civil society groups including the\nEmergency Response Rooms and Forces for Freedom and Change. Previous decrees issued\nunder Emergency Decree No. 3/2021 dissolving the trade unions, professional organizations\nand their steering committees, remained in force.549 The Fact-Finding Mission is highly\nconcerned over these measures that are indicative of the Sudan lacking a healthy civil society\nneeded to ensure their participation as well as that of victims/survivors in any accountability\nprocess at the national level.\nImpact of the conflict on the justice system"},{"id":"a-hrc-57-crp-6-p0310","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"310","seq":315,"section":"IX. Accountability","text":"In terms of judicial and legal infrastructure, the Fact-Finding Mission received\ninformation on the destruction of government buildings and records, in particular in\nKhartoum and the Darfur States, by the RSF.550 Some pointed to a systematic attack on all\ninstitutions, including courts, and a pattern of burning of state records by the RSF, in\nparticular judicial and land records.551 Several interviewees noted the targeting of courts,\nincluding El Geneina, Nyala and Zalingei courts, including the destruction of records by way\nof burning papers.552 One interviewee raised concerns about the lack of any digital back-up\nof court records.553 The Government also noted the systematic destruction of judicial records\nby the RSF,554 and indicated that the Public Prosecution had “taken measures to retrieve data\nin lawsuits opened in war-affected areas.”555 Prisons were also attacked in several locations\nand those convicted of common crimes were reportedly released by the warring parties,\ndemonstrating the breakdown of the rule of law."},{"id":"a-hrc-57-crp-6-p0311","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"311","seq":316,"section":"IX. Accountability","text":"Lawyers were targeted by both the RSF and SAF. One victim recalled that he was\ndetained and severely tortured by the RSF and questioned about his contacts with other\nlawyers.556 He later faced interrogation by the SAF by reason of his legal profession. Another\nhuman rights lawyer indicated that he received death threats and that his legal offices were\nsubsequently attacked and destroyed.557 A further interviewee documented 10 cases of\nkillings of lawyers by the RSF, and over 35 arrested.558 Another interviewee recalled how his\nlawyer friend was detained and beaten by the RSF while being questioned about his human\nrights work.559 Yet another victim was arrested, detained, interrogated over 20 times, and\nseverely tortured, including threatened with rape, by the SAF Military Intelligence while\nbeing accused of documenting human rights violations.560"},{"id":"a-hrc-57-crp-6-p0312","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"312","seq":317,"section":"IX. Accountability","text":"Several victims spoke of harassment, arrest, detention and torture and other forms of\nill-treatment against lawyers and other individuals supporting documentation and\naccountability efforts, including journalists, human rights defenders, and Resistance\nCommittee and Emergency Response Room members, by both the RSF and SAF. They were\namong others accused of siding with the opposing side to the conflict, documenting and\nreporting on their activities, conducting human rights work and/or being affiliated to any\nlegal and/or human rights organization.561 One interviewee noted the systematic targeting of\ncivil society, especially those opposing the war: “Everyone needs to pick a party at this point.\nIf you are not with either party, they will consider you to be against them and target you.”562\nAs a result, many lawyers, human rights defenders, activists and other professionals\nsupporting accountability efforts were forced to flee the country.563"},{"id":"a-hrc-57-crp-6-p0313","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"313","seq":318,"section":"IX. Accountability","text":"In relation to sexual and gender-based violence specifically, the Fact-Finding Mission\nreceived concerning allegations that human rights defenders, journalists, and others,\nincluding Emergency Response Room volunteers, working to document and respond to\ngender-based violence, have been targeted in relation to their activities with death threats,\nsexual violence and torture by the RSF564 and intimidation, arrest and rape threats by the\nSAF.565 According to United Nations Experts, “From January to June 2024, at least nine\nwomen human rights defenders and activists were targeted by parties to the conflict”. 566 This\npattern has however not emerged with the current conflict; rather it finds its roots under the\nso-called ‘public order regime’ that disproportionally affected women human rights\ndefenders, and intensified in 2019 with women activists at the forefront of the protests\nadvocating for civilian rule and women’s rights, which were repressed by the RSF along with\nother government security forces, including the intelligence services."},{"id":"a-hrc-57-crp-6-p0314","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"314","seq":319,"section":"IX. Accountability","text":"The Fact-Finding Mission further received credible information indicating that\nlawyers who remain in the Sudan are facing difficulties in exercising their functions, due to\ncontinued harassment, monitoring, targeting, and scrutiny by security actors. They also face\nchallenges in providing adequate legal defense to the complex criminal cases brought forward\nby the authorities as part of the National Committee of Investigation on Human Rights\nViolations, War Crimes, and Violations by the Rebel Rapid Support Forces and Other Crimes,\nin SAF controlled areas since the start of the conflict. Lawyers providing legal assistance to\ncivilians in such cases may reportedly face arrest over alleged affiliation or support to the\nRSF."},{"id":"a-hrc-57-crp-6-p0315","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"315","seq":320,"section":"IX. Accountability","text":"The Fact-Finding Mission is gravely concerned over the breakdown of the rule of law\nas demonstrated by the destruction caused by the ongoing conflict to the legal infrastructure\nand justice system of the Sudan against the backdrop of pre-existing gaps in the domestic\nlegislation as outlined above. It is particularly concerned about disruption to the functioning\nof national institutions, including the police, prosecution and judiciary, as well as the\ntargeting of lawyers and other professionals involved in promoting and protecting human\nrights by both sides to the conflict, including arrest, detention, death threats, sexual violence\nand torture, and the severe impact this has and will continue to have on the functioning of the\nrule of law in the Sudan and consequently on victims and survivors of violations, including\nof rape and other forms of sexual violence. The looting and destruction of court records,\ncitizens and land registries and similar files undermine not only state institutions, but also\nindividual rights.\nAccountability mechanisms in SAF controlled areas"},{"id":"a-hrc-57-crp-6-p0316","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"316","seq":321,"section":"IX. Accountability","text":"On 21 July 2023, the Sudanese authorities established a National Committee of\nInvestigation on Human Rights Violations, War Crimes, and Violations by the Rebel Rapid\nSupport Forces and Other Crimes by Presidential Decree No. 143 of 2023 under the auspices\nof the Attorney-General.567 The National Committee is “responsible for investigating all\ncrimes and violations resulting from the insurgence of the Rapid Support Forces,”568 and\nincludes representatives from the General Intelligence Service and Military Intelligence, the\nSudanese Police Force and the Ministries of Justice and Foreign Affairs.569 It is mandated to\nreceive reports from citizens and those affected, collect evidence and proof of, and list and\ndocument all violations and crimes committed by the RSF since 15 April 2023. It may further\n“summon any individual for investigation and prosecution if they are found to be involved\nor collaborating in the crimes and violations committed by the rebel Rapid Support Forces,”\nand take all necessary legal proceedings, domestically and internationally, as well as refer\ncriminal cases to the judiciary for provision of remedies.570"},{"id":"a-hrc-57-crp-6-p0317","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"317","seq":322,"section":"IX. Accountability","text":"According to the Sudanese authorities, as of 18 June 2024, the number of registered\ncriminal cases had reached 12,470 and 346 arrest warrants had been issued against the\n“commanders and employees” of the RSF. The Sudanese authorities also indicated that 65\ncases had been tried or their trial was ongoing, including for the offences of collaboration or\nsuspected affiliation to the RSF, waging war against the state and participation in a terrorist\norganization. Of the 65 cases, 4 remained under trial, 27 were dismissed, and 32 were found\nguilty, of which 10 were sentenced to death by hanging and 4 to life imprisonment, and others\nreceived sentences of up to 20 years in prison. The Fact-Finding Mission notes, based on the\nlist included in the progress report571, that only two of these 65 cases appear to include charges\nof international crimes and that these remain under trial. The Fact-Finding Mission received\ninformation that the cases brought forward by the National Committee target Sudanese\ncivilians for their activities as lawyers, humanitarians, grassroots activists, human rights\ndefenders, or Emergency Response Rooms. This is indicative of the National Committee\nbeing involved in selective justice, primarily targeting activists perceived as RSF affiliates."},{"id":"a-hrc-57-crp-6-p0318","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"318","seq":323,"section":"IX. Accountability","text":"In this context, the SAF and police forces previously issued two mobile “Balagh”\napplications for documenting and reporting on crimes committed by the RSF, including on\nits presence and movements.572 The Fact-Finding Mission is highly concerned over the use\nof the civilian population to report on the movements of opposing parties, which it believes\nhas contributed to the instrumentalization of ordinary Sudanese citizens in the conflict and\nresulted in their targeting by both sides, including on accusations of being spies for the other\nside or otherwise supporting or being affiliated to their opponent. The Fact-Finding Mission\nrecognizes this as a key feature of the conflict since mid-April 2023 requiring immediate\nattention."},{"id":"a-hrc-57-crp-6-p0319","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"319","seq":324,"section":"IX. Accountability","text":"A second Committee was established by the authorities by Transitional Sovereignty\nCouncil Decision No. 82 of 2024, under the auspices of the Minister of Justice, focusing on\ninternational lawsuits including submission of information on RSF crimes to the International\nCriminal Court.573 A coordination and liaison office with the Court was reportedly set up as\npart of the latter’s efforts.574 In his statement to the Security Council of 5 August 2024, while\nnoting his Office finally received cooperation from the Sudan, the Prosecutor of the\nInternational Criminal Court indicated that some requests for assistance were actioned while\nothers remained pending, and asked for cooperation by the authorities to expedite them. 575"},{"id":"a-hrc-57-crp-6-p0320","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"320","seq":325,"section":"IX. Accountability","text":"To date, accountability efforts undertaken by the authorities focus on crimes\ncommitted by the RSF and its perceived affiliates. The Fact-Finding Mission has not received\nany information on investigations and prosecutions, where appropriate, of SAF members or\nother government entities for international crimes. The Fact-Finding Mission believes that\nthe developments at the domestic level are indicative of a lack of willingness to investigate\nand prosecute all those responsible on an equal basis. Victims have also informed the Fact-\nFinding Mission of their lack of trust in the domestic justice system, including fear of\nreprisals for reporting violations committed by SAF and other government entities.\nAccountability mechanisms in RSF controlled areas"},{"id":"a-hrc-57-crp-6-p0321","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"321","seq":326,"section":"IX. Accountability","text":"The RSF, including its leader Lieutenant General Mohamed Hamdan Dagalo himself,\nissued a number of statements in which it expressed its unwavering commitment to\ninternational humanitarian law and fundamental principles of human rights, and to ensure\nthat those who violate those laws be brought to justice. For instance, on 2 August 2023, the\nRSF noted “its rejection of any or assaults against civilians during the ongoing war, whether\nby RSF personnel or any other party”, adding that, without exception, all individuals found\nguilty of committing such crimes must be held accountable before the law.”576 This\nannouncement further refers to a call between RSF Second Commander, Lieutenant General\nAbdel Rahim Hamdan Dagalo and Special Representative of the United Nations Secretary-\nGeneral on Sexual Violence, Pramila Patten, during which the RSF Second Commander\nhighlighted the commitment of the RSF to abide by these principles, as well as the importance\nof cooperation between the RSF and the United Nations to safeguard civilians’ safety and\nprevent any violations or abuses.577"},{"id":"a-hrc-57-crp-6-p0322","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"322","seq":327,"section":"IX. Accountability","text":"On 24 December 2023, the RSF also posted an official video on the RSF official social\nmedia account, emphasising that any violations or misconduct against innocent civilians will\nnot be tolerated, and expressing commitment to the protection of civilians in coordination\nwith community committees in their areas of control. The statement further confirmed that a\nmilitia involved in robbing and terrorizing citizens and stealing their property had been\nidentified, and would be tracked and dealt with; and that the RSF leadership has reiterated\nstrict instructions to handle any misconduct within the forces and to subject those responsible\nto immediate court-martial.578"},{"id":"a-hrc-57-crp-6-p0323","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"323","seq":328,"section":"IX. Accountability","text":"In a response of 19 January 2024 to a joint communication by the United Nations\nSpecial Procedures concerning allegations of repeated widespread sexual violence,\nharassment and abuse by the RSF against women and girls, the RSF announced that it had\nestablished a “Commander Fudail Investigative Committee” tasked with investigating all\ncriminal activities in areas under its control.579 In response to a report by Human Rights\nWatch on widespread sexual violence committed in the capital of Khartoum by the RSF, the\nRSF further provided, among others, a copy of its code of conduct, rules of engagement, and\na decision with instructions to all competent departments and commanders of the RSF on the\nprevention of gross violations of human rights and to abide by international humanitarian law\nsigned by General Mohamed Hamdan Dagalo.580"},{"id":"a-hrc-57-crp-6-p0324","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"324","seq":329,"section":"IX. Accountability","text":"On 31 August 2024, General Mohamed Hamdan Dagalo announced on social media\nthat, on that same day, he had issued an extraordinary administrative order directed to all\nforces, including the newly formed Civilian Protection Unit, containing several obligations\nspecifically related to enhancing civilian protection and facilitating the delivery of\nhumanitarian aid. He ordered all commanders at all levels to comply with the order and\nfollow the organisational rules set out in the RSF Law, the rules of engagement, and the\nconduct rules during combat, in accordance with the law and principles of international\nhumanitarian law. He also stated: “Anyone who violates these orders will be subject to legal\naccountability.”581"},{"id":"a-hrc-57-crp-6-p0325","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"325","seq":330,"section":"IX. Accountability","text":"Whilst these announcements may sound promising, to date, effective implementation\nof any of the commitments is lacking, and human rights law and international humanitarian\nlaw continue to be violated. This is evidenced by the findings in A/HRC/57/23 and this CRP,\nas well as recent events around El Fasher, which potentially implicate the RSF in continuing\nviolations of human rights law and international humanitarian law. Whether this is due to a\nlack of control or genuine will to prevent atrocities from being committed by the RSF or its\nallied militias, needs to be further investigated. A number of sources have indicated that the\nRSF senior leadership is aware of the shortcomings in discipline but not willing to impose a\nmore stringent approach in order to prevent its alliance from fracturing.582"},{"id":"a-hrc-57-crp-6-p0326","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"326","seq":331,"section":"IX. Accountability","text":"In terms of the RSF’s claimed efforts to hold alleged RSF human rights violators to\naccount, it also remains to be seen how genuine and/or effective those efforts are. In this\nregard, the Fact-Finding Mission notes with concern the observations of the Prosecutor of\nthe International Criminal Court, in his 30 January 2024 update to the Security Council, that\nwhilst his Office had received the names of individuals that the RSF contended were part of\nan investigative committee, no information had been transferred from the RSF to his Office,\neither in relation to allegations against the RSF or in relation to any allegations regarding the\nSAF, nor any other affiliated or related armed actors.”583"},{"id":"a-hrc-57-crp-6-p0327","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"327","seq":332,"section":"IX. Accountability","text":"The Fact-Finding Mission has received some information that, from 2023, the RSF\nhas undertaken some attempts to create a rudimentary military police and justice system\nthrough an RSF Committee to Address Violations (sometimes also referred to as the\nCommittee to Address Negative Phenomena) and an RSF field court. But apart from isolated\ninstances, these institutions seem to have been rarely used to ensure discipline among\nRSF fighters in the field and curb their abuses against civilians."},{"id":"a-hrc-57-crp-6-p0328","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"328","seq":333,"section":"IX. Accountability","text":"The Fact-Finding Mission has further received reports indicating the establishment by\nthe RSF of its own administration in areas under its control, including martial courts, 584 as\nwell as an investigative body to look into reported mass killings committed in Ardamata. The\nFact-Finding Mission is looking further into this matter."},{"id":"a-hrc-57-crp-6-p0329","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"329","seq":334,"section":"X. Options for accountability and access to justice for victims","text":"For peace to sustain in the Sudan, there is a need for accountability. “The cycle of\nconflict will continue,” stated one interviewee to the Fact-Finding Mission, indicating that\nwithout accountability the victims would at some point come to take back their lands and\ntake justice in their own hands.585 Based on previous experiences, including the 2005 creation\nby the Sudanese authorities of the Special Criminal Court on Events in Darfur as a substitute\nto the International Criminal Court,586 and the lack of timely implementation of the 2020 Juba\nPeace Agreement, many interviewees, including survivors of rape and other forms of sexual\nviolence, voiced their complete lack of trust in the ability and willingness of the domestic\nsystem to deliver justice. In expressing their wish for justice and peace in the Sudan, and for\nperpetrators to be held to account, they requested the Fact-Finding Mission to amplify their\nwish for a specific accountability mechanism, such as an international criminal tribunal to be\nset up to investigate and prosecute international crimes committed by all parties to the current\nconflict comprising both the RSF and SAF and affiliated groups. While stressing that the\nSudan was currently unable and unwilling to investigate and prosecute international crimes,\nsome voiced their wish for legal reforms at the domestic level, including to align domestic\nlaws with international laws and standards and to guarantee the independence of the judiciary,\nin the longer term so that the Sudan would be able to take over the investigation and\nprosecution international crimes in the future."},{"id":"a-hrc-57-crp-6-p0330","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"330","seq":335,"section":"X. Options for accountability and access to justice for victims","text":"Many Sudanese asked the Fact-Finding Mission for protection of their rights and\nindicated that while having fled the Sudan, they still did not feel safe and that many lawyers,\nhuman rights defenders, doctors and other professionals continued to receive threats by the\nparties to the conflict. When asked if they would be willing to participate in any\naccountability process, many interviewees indicated that they would be willing to do so if\nprotection could be provided."},{"id":"a-hrc-57-crp-6-p0331","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"331","seq":336,"section":"X. Options for accountability and access to justice for victims","text":"The Fact-Finding Mission considers that only a comprehensive transitional justice\nprocess with appropriately endowed mechanisms can address the impunity and justice gaps\nin the Sudan and provide remedies and reparations for victims and survivors. In this context,\nthe 2019 African Union Transitional Justice Policy Framework587 and the Guidance Note of\nthe Secretary-General on Transitional Justice588 incorporating the four pillars of transitional\njustice: justice, truth, reparations and guarantees of non-repetition are of high relevance to\nthe situation in the Sudan today.589"},{"id":"a-hrc-57-crp-6-p0332","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"332","seq":337,"section":"X. Options for accountability and access to justice for victims","text":"With regard to the first pillar, one mechanism already in place is the continuing\njurisdiction of the International Criminal Court over crimes committed in Darfur since 1 July\n2002. The role of the Court remains crucial, particularly in light of the decades of prevailing\nimpunity. Since the Security Council referral, the International Criminal Court has issued\nseven warrants of arrest. In one case the charges were not confirmed, another case was\nterminated following the death of the suspect, and four others, including former President\nOmar Al Bashir, remain at large. The trial against one individual, Ali Muhammad Ali Abd-\nAl-Rahman who was transferred to the Court on 9 June 2020, is ongoing. For the Prosecutor\nof the Court to be able to deliver on its mandate and expectations of victims, support by all\nactors, including financial and cooperation, is required.590"},{"id":"a-hrc-57-crp-6-p0333","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"333","seq":338,"section":"X. Options for accountability and access to justice for victims","text":"Since the International Criminal Court is focusing on only a few cases involving\nthose most responsible for international crimes, other pathways to justice should also be\nexplored to ensure accountability by perpetrators at all levels across the Sudan. Different\noptions can be considered ranging from fully international to hybrid and internationalized\njudicial mechanisms. An example of the former is the United Nations International Criminal\nTribunal for Rwanda, which was set up by the Security Council pursuant to Resolution 955\n(1994). The Special Court for Sierra Leone followed a hybrid model with a mixture of\ninternational and domestic law and staffing. It was established by agreement between the\nUnited Nations and Sierra Leone and based in country and operated alongside a Truth and\nReconciliation Commission. An example of an approach straddling a hybrid and\ninternationalized set up is provided by the Special Criminal Court in the Central African\nRepublic, which was established under domestic legislation. It enjoys primacy over national\njurisdiction, is composed of national and international judges and has a special police unit\nattached to the Court. The independence of the Prosecutor was also included as a critical\nelement to this set up. A hybrid court was recommended by the African Union Panel on\nDarfur in 2005, but not implemented. An example of an internationalized mechanism is the\nExtraordinary African Chambers, set up in 2012 pursuant to an agreement between Senegal\nand the African Union with a mandate to prosecute international crimes committed in Chad\nbetween 1982 and 1990.591"},{"id":"a-hrc-57-crp-6-p0334","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"334","seq":339,"section":"X. Options for accountability and access to justice for victims","text":"Whichever modalities are deemed most suitable for such a future mechanism, for it\nto succeed in the implementation of its accountability mandate, it will need to receive\ninternational support, including political, financial and technical support, cooperation by\nrelevant stakeholders, including States, civil society, survivors/victims and witnesses, and\nhave access to survivors/victims. States are further encouraged to use the universal\njurisdiction tool to pursue individuals suspected of having committed international crimes."},{"id":"a-hrc-57-crp-6-p0335","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"335","seq":340,"section":"X. Options for accountability and access to justice for victims","text":"Second, the root causes of the violations that have been chronically hampering the\nSudan from respecting, protecting and fulfilling the human rights of its people must be\nthoroughly identified and fully addressed. This could be achieved through a genuine truth-\nseeking process to address the scale of violations committed and their impact on individuals\nand communities. Truth commissions can be established alongside the proposed judicial\nmechanism to enhance national dialogue, with the ability to refer cases to the judicial\nmechanism as appropriate. To foster a culture of accountability, it should not be endowed\nwith the power to provide immunity or amnesty to those responsible for international crimes.\nAlready in 2005, a broad consultative process, including with civil society and victim groups\nleading to the establishment of a truth and reconciliation commission, was recommended by\nthe 2005 COI Darfur. This recommendation was echoed by the African Union Panel on\nDarfur. These recommendations were not acted on."},{"id":"a-hrc-57-crp-6-p0336","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"336","seq":341,"section":"X. Options for accountability and access to justice for victims","text":"Third, reparation for serious violations of human rights and international humanitarian\nlaw, including through restitution, compensation, rehabilitation, satisfaction and guarantees\nof non-repetition as outlined in the United Nations Basic Principles and Guidelines on the\nRight to a Remedy and Reparation for Victims of Gross Violations of International Human\nRights Law and Serious Violations of International Humanitarian Law, 592 is critical to help\nvictims, survivors, families and communities overcome the devastating impact of the\nviolence. In several conflicts, reparations have proven key to addressing the plight of victims,\nsurvivors and their families. There are several models that can be considered in this regard,\nincluding by including providing reparations as an integral part of a mandate of a truth\ncommission, such as in Morocco, Peru or South Africa, or through a separate office as in Sri\nLanka. The question of reparations is highly relevant to the situation in the Sudan today and\ncontinues to be key to ensuring justice for victims. The 2005 Darfur COI Darfur made the\ncase for reparations, recommending the establishment of an International Compensation\nCommission, but this did not happen."},{"id":"a-hrc-57-crp-6-p0337","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"337","seq":342,"section":"X. Options for accountability and access to justice for victims","text":"Meanwhile, the Fact-Finding Mission has heard from Sudanese civil society, human\nrights defenders, activists, survivors, witnesses, and the legal community about the\noverwhelming and immediate need for assistance to victims and survivors of the conflict in\nthe Sudan within the country and those displaced. A dedicated entity should be established\nfor these purposes that can also work towards awarding the victims interim reparative\nmeasures."},{"id":"a-hrc-57-crp-6-p0338","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"338","seq":343,"section":"X. Options for accountability and access to justice for victims","text":"Fourth, as part of guarantees of non-repetition, legal and institutional reforms, in\nparticular of the justice and security sectors in the Sudan will need to be prioritized along\nwith accountability within any transitional justice process for the country to transition from\nrecurring cycles of violence and conflict to a stable and democratic governance in line with\nthe aspirations expressed by the Sudanese people."},{"id":"a-hrc-57-crp-6-p0339","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"339","seq":344,"section":"XI. Conclusions and Recommendations","text":"As the Sudan continues to be in turmoil and its people within and outside the country\nare experiencing immense suffering, the Fact-Finding Mission concludes that the SAF and\nRSF, and/or their allied militias, are responsible for large-scale violations of human rights\nand international humanitarian law. They include violations in the context of airstrikes and\nshelling of private property, schools, medical centers and other objects indispensable for the\nsurvival of the civilian population, looting, ethnic based attacks, sexual violence, lack of\nprotection of children’s rights, arbitrary detention, torture, suppression of freedom of\nexpression, obstruction of humanitarian assistance and attacks on civil society and human\nrights defenders. Many of these violations amount to international crimes."},{"id":"a-hrc-57-crp-6-p0340","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"340","seq":345,"section":"XI. Conclusions and Recommendations","text":"The Fact-Finding Mission considers that there are reasonable grounds to believe that\nthe SAF and its allied forces have committed the war crimes of violence to life and person,\nin particular murder of all kinds, mutilation, cruel treatment and torture; committing outrages\nupon personal dignity, in particular humiliating and degrading treatment."},{"id":"a-hrc-57-crp-6-p0341","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"341","seq":346,"section":"XI. Conclusions and Recommendations","text":"The Fact-Finding Mission considers that there are reasonable grounds to believe that\nthe RSF and its allied militias have committed the war crimes of violence to life and person,\nin particular murder of all kinds, mutilation, cruel treatment and torture; committing outrages\nupon personal dignity; rape, sexual slavery and any form of indecent assault; pillage;\nconscripting or enlisting children under the age of 15 or using them to participate actively in\nhostilities; intentionally directing attacks against the civilian population; intentionally\ndirecting attacks against persons and objects involved in humanitarian assistance and other\nspecially protected objects; and ordering the displacement of the civilian population for\nreasons related to the conflict. The Fact-Finding Mission further considers that there are\nreasonable grounds to believe that the RSF has committed the crimes against humanity of\nmurder; torture; enslavement; rape, sexual slavery, and acts of a sexual nature of comparable\ngravity; persecution on the basis of intersecting ethnic and gender grounds in connection with\nthe foregoing acts; and forcible displacement of population."},{"id":"a-hrc-57-crp-6-p0342","rec_id":"recMNz9d8dOUBoYFy","symbol":"A/HRC/57/CRP.6","n":"342","seq":347,"section":"XI. Conclusions and Recommendations","text":"Sudanese people have endured much pain. Their suffering must stop, and their human\nrights must be protected. This cannot be done without ending the fighting and silencing the\nguns. The Fact-Finding Mission is particularly concerned by the looming famine and rampant\nfood insecurity in various parts of the Sudan, including starvation. It applauds the various\nefforts to bring the parties to the negotiating table. It emphasizes the need for an inclusive\nand participatory civic dialogue leading to a democratic civilian rule. In this context, it urges\nany agreement reached, including on a permanent cessation of hostilities, to take the findings\nand recommendations below into account.\nThe Fact-Finding Mission, therefore, recommends the following:\n(a) All efforts must be invested in reaching a comprehensive and sustainable ceasefire and the\neffective delivery of the much-needed humanitarian assistance. To this end, the Fact-Finding\nMission notes the agreement on opening the border crossing with Chad in Adré as a step in the\nright direction.\n(b) The protection of civilians is paramount, and the parties must comply with their obligations\nunder international law. SAF and RSF and their respective allied forces must refrain from\ndirecting attacks against civilians or civilian objects, pillage and looting of property and\ncommitting outrageous acts against persons including torture, rape and other forms of sexual\nviolence and use and recruitment of children. Ethnically motivated attacks must end.\nCommanders must issue explicit and detailed instructions to their forces and allied militias to\nrefrain from illegal acts, also in line with their Jeddah Commitments. They must effectively\ninvestigate violations and bring the perpetrators to justice. Given the failure of the parties to\nprotect civilians so far, there is an urgent need to deploy an independent force with a specific\nmandate to protect civilians in the Sudan.\n(c) The fighting will stop once the arms flow stops. Therefore, all states and entities must comply\nwith the existing arms embargo in Darfur pursuant to Security Council Resolution 1556 (2004).\nThis embargo should also be expanded to cover the entire Sudan. The supply of weapons,\nammunition, and other logistical or financial support to any of the warring parties must end\nimmediately as there is a risk that those supplying arms may be complicit in grave violations of\nhuman rights and humanitarian law. Businesses and private actors active in the Sudan must\nrespect the UN Guiding Principles on Business and Human Rights.\n(d) Forced displacement must end and the communities that host refugees should be supported. The\nFact-Finding Mission applauds the generosity of host communities, including in Central African\nRepublic, Chad, Egypt, Ethiopia, Kenya, South Sudan, and Uganda. It calls on the international\ncommunity to increase its financial and other support for the refugees and the host communities,\nwho themselves have desperate humanitarian needs and expresses its appreciation for those who\nare already doing so.\n(e) Rape and other forms of sexual violence must end. Women, and youth should also be enabled\nto meaningfully participate in any peace negotiations or initiatives in line with Security Council\nResolution 1325 (2000) to ensure that they take into account their lived experiences and address\ntheir concerns. Recruitment and use of children must end, and children must be protected\n(f) The impunity gap in Sudan is among the key root causes of decades of continued violations.\nThe Fact-Finding Mission recommends that the Security Council extends the jurisdiction of the\nInternational Criminal Court to cover the entire territory of Sudan. It also urges Sudan to\ncooperate with the Court through the surrender to it, of all indicted persons, including former\nPresident Omar Al-Bashir.\n(g) To fully address accountability and to provide justice to victims, a path towards a\ncomprehensive approach to transitional justice must be pursued based on inclusive dialogue and\ngenuine consultations. The establishment of a separate international judicial mechanism\nworking in tandem and complementarity with the International Criminal Court, as well as a\ntruth commission. Meanwhile, there is an urgent need to establish a victim support and\nreparations office.\n(h) Finally, Sudan comprises a diverse population, endowed with ample resources. Its people\ndeserve to live in peace and prosperity. Many Sudanese stressed their wish to live in a peaceful,\ninclusive, and human-rights-oriented Sudan. They spoke of a representative and participatory\ngovernment, encompassing all communities, where the equal rights of all citizens are respected,\nirrespective of their race, ethnicity, gender, or economic status. This aspiration must be\nsupported by the international community charting the way towards equality, justice and\nsustainable peace in the Sudan."},{"id":"a-hrc-57-23-u0000","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":null,"seq":0,"section":null,"text":"United Nations                                                                                     A/HRC/57/23\nGeneral Assembly                                                            Distr.: General\n7 November 2024","unnumbered":true},{"id":"a-hrc-57-23-u0001","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":null,"seq":1,"section":null,"text":"Human Rights Council\nFifty-seventh session\n9 September–9 October 2024\nAgenda item 2\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General","unnumbered":true},{"id":"a-hrc-57-23-u0002","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":null,"seq":2,"section":null,"text":"Summary\nIn the present report, submitted pursuant to Human Rights Council resolution 54/2,\nthe independent international fact-finding mission for the Sudan outlines the findings of its\ninvestigations into violations of international human rights law and international\nhumanitarian law, and related crimes, committed in the Sudan in the context of the conflict\nthat erupted in mid-April 2023. The report also contains recommendations, including on\naccountability and access to justice for victims.","unnumbered":true},{"id":"a-hrc-57-23-p0001","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"1","seq":3,"section":"I. Introduction","text":"In its resolution 54/2, the Human Rights Council decided to establish an independent\ninternational fact-finding mission for the Sudan, composed of three experts, for an initial\nperiod of one year. It mandated the fact-finding mission to, inter alia, investigate and establish\nthe facts, circumstances and root causes of all alleged violations and abuses of human rights\nand international humanitarian law, and related crimes, in the context of the ongoing armed\nconflict that had begun on 15 April 2023 between the Sudanese Armed Forces and the Rapid\nSupport Forces, as well as other warring parties. In the same resolution, the Council requested\nthe fact-finding mission to present a comprehensive report on its findings at its fifty-seventh\nsession."},{"id":"a-hrc-57-23-p0002","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"2","seq":4,"section":"I. Introduction","text":"On 18 December 2023, the President of the Human Rights Council appointed\nMohamed Chande Othman (United Republic of Tanzania) (Chair), Joy Ngozi Ezeilo\n(Nigeria) and Mona Rishmawi (Jordan and Switzerland) to serve as the three independent\nexperts. Due to the liquidity crisis faced by the United Nations Secretariat, the secretariat of\nthe fact-finding mission was only established in May 2024, in Nairobi, and composed of\napproximately two thirds of the allocated number of staff. Prior to its establishment, a small\nstart-up team was provided by the Office of the United Nations High Commissioner for\nHuman Rights (OHCHR), for which the fact-finding mission is grateful."},{"id":"a-hrc-57-23-p0003","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"3","seq":5,"section":"I. Introduction","text":"The present report outlines the findings of the fact-finding mission since the outbreak\nof the conflict in the Sudan in mid-April 2023. The fact-finding mission is also producing a\nconference room paper containing detailed information and analysis. The draft report was\nsent to the Government of the Sudan on 23 August 2024 for corrections to any factual\ninaccuracies by 1 September 2024. No response was received."},{"id":"a-hrc-57-23-p0004","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"4","seq":6,"section":"A. Engagements and consultations","text":"Pursuant to its mandate, the fact-finding mission has engaged, both online and in\nperson during missions to Chad, Kenya, Switzerland and Uganda, with Sudanese community\nleaders, civil society organizations, victims and survivors,1 experts, organizations and entities\ninvolved in the situation in the Sudan, including United Nations agencies, and diplomatic\nmissions."},{"id":"a-hrc-57-23-p0005","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"5","seq":7,"section":"A. Engagements and consultations","text":"The experts conducted missions to Geneva in January and June 2024 and held\nconsultations with the United Nations High Commissioner for Human Rights, OHCHR staff\nand the President of the Human Rights Council."},{"id":"a-hrc-57-23-p0006","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"6","seq":8,"section":"A. Engagements and consultations","text":"Moreover, the fact-finding mission held discussions with the Expert on human rights\nin the Sudan, the Personal Envoy of the Secretary-General for the Sudan, the Special Adviser\nto the Secretary-General on the Prevention of Genocide, the Special Representative of the\nSecretary-General on Sexual Violence in Conflict, the Special Representative of the\nSecretary-General for Children and Armed Conflict, the Panel of Experts on the Sudan and\nother senior United Nations officials. The fact-finding mission also engaged with the country\nrapporteur for the Sudan of the African Commission on Human and Peoples’ Rights, the\nAfrican Union Special Envoy on the Prevention of Genocide and Other Mass Atrocities and\nrepresentatives of the International Criminal Court. It contacted the African Union, the\nLeague of Arab States, the Intergovernmental Authority on Development and the\nOrganization of Islamic Cooperation with requests for dialogue and cooperation, to\ncoordinate efforts and ensure complementarity, as required by the Human Rights Council in\nits resolution 54/2."},{"id":"a-hrc-57-23-p0007","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"7","seq":9,"section":"A. Engagements and consultations","text":"The fact-finding mission sent communications to the Sudanese authorities on four\noccasions (3 and 29 January, 7 June and 9 August 2024), requesting to visit the Sudan. Those\ncommunications remained unanswered. The fact-finding mission remains open to engaging\nwith the Sudanese authorities and to visiting the Sudan."},{"id":"a-hrc-57-23-p0008","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"8","seq":10,"section":"A. Engagements and consultations","text":"The Rapid Support Forces sent a communication to the President of the Human Rights\nCouncil, through OHCHR, on 20 December 2023, offering full cooperation with the\nfact-finding mission, and followed up on that communication in July 2024, after which there\nwas some communication at the secretariat level."},{"id":"a-hrc-57-23-p0009","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"9","seq":11,"section":"A. Engagements and consultations","text":"The fact-finding mission expresses its readiness to engage with all parties to the\nconflict, in accordance with its mandate."},{"id":"a-hrc-57-23-p0010","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"10","seq":12,"section":"A. Engagements and consultations","text":"The fact-finding mission also contacted neighbouring countries (Central African\nRepublic, Chad, Egypt, Ethiopia, Kenya, South Sudan and Uganda), requesting their\ncooperation and access to their territories to gather first-hand information from Sudanese\nvictims of the conflict. The fact-finding mission visited Kenya in May and August, Chad in\nJuly and Uganda in August 2024. The fact-finding mission is grateful to the Governments of\nChad, Kenya and Uganda for their cooperation."},{"id":"a-hrc-57-23-p0011","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"11","seq":13,"section":"B. Investigations and verification of information","text":"The fact-finding mission issued a call for submissions and received a substantial\namount of information from individuals and organizations. It examined reports from various\nsources, including United Nations entities, regional and international bodies and\nnon-governmental organizations. It held extensive consultations with Sudanese civil society\norganizations, human rights defenders, subject-matter experts and other stakeholders."},{"id":"a-hrc-57-23-p0012","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"12","seq":14,"section":"B. Investigations and verification of information","text":"The fact-finding mission obtained first-hand information through interviews with\nvictims, their families, eyewitnesses, front-line responders and other sources, including\nduring its visits to Chad, Kenya and Uganda. As at 31 July 2024, the fact-finding mission\nhad conducted interviews with 182 individuals (67 women and 115 men)."},{"id":"a-hrc-57-23-p0013","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"13","seq":15,"section":"B. Investigations and verification of information","text":"The fact-finding mission expresses its gratitude to the witnesses who shared their\naccounts and the individuals and organizations it engaged with. In discharging its mandate,\nthe fact-finding mission has adhered to the principles of independence, impartiality,\nobjectivity, transparency, integrity, the protection of sources and “do no harm”. It has applied\nthe “reasonable grounds to believe” standard of proof. It has made findings of fact and law\nonly where it was able to obtain sufficient, reliable and corroborated information, based on\nwhich a reasonable and ordinarily prudent person would have reason to believe that such an\nincident or pattern of conduct had occurred as described. The phrase “the fact-finding mission\nfinds” in the present report is reflective of this standard being met."},{"id":"a-hrc-57-23-p0014","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"14","seq":16,"section":"III. Applicable law","text":"The fact-finding mission has applied international human rights law, international\nhumanitarian law and international criminal law and has considered additional commitments\nundertaken by the parties to the conflict. It has also considered domestic laws of the Sudan,\nas relevant."},{"id":"a-hrc-57-23-p0015","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"15","seq":17,"section":"III. Applicable law","text":"The Sudan is a party to seven of the nine core international human rights treaties,\nnamely the International Covenant on Civil and Political Rights, the International Covenant\non Economic, Social and Cultural Rights, the Convention against Torture and Other Cruel,\nInhuman or Degrading Treatment or Punishment, the International Convention for the\nProtection of All Persons from Enforced Disappearance, the International Convention on the\nElimination of All Forms of Racial Discrimination and the Convention on the Rights of the\nChild and its Optional Protocol on the involvement of children in armed conflict. At the\nregional level, it is a party to the African Charter on Human and People’s Rights and the\nAfrican Charter on the Rights and Welfare of the Child. It has not acceded to the Convention\non the Elimination of All Forms of Discrimination against Women. It has signed but not\nratified the Protocol to the African Charter on Human and People’s Rights on the Rights of\nWomen in Africa."},{"id":"a-hrc-57-23-p0016","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"16","seq":18,"section":"III. Applicable law","text":"The Sudan is a State party to the four Geneva Conventions of 12 August 1949 and\ntheir two Additional Protocols of 1977. Rules of customary international law are also\napplicable and binding on all parties to the conflict."},{"id":"a-hrc-57-23-p0017","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"17","seq":19,"section":"III. Applicable law","text":"The Sudan is a party to the Convention on the Prevention and Punishment of the Crime\nof Genocide. Sudan has signed but not ratified the Rome Statute of the International Criminal\nCourt. However, the situation in Darfur since 1 July 2002 was brought within the jurisdiction\nof the Court pursuant to Security Council resolution 1593 (2005)."},{"id":"a-hrc-57-23-p0018","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"18","seq":20,"section":"III. Applicable law","text":"The Security Council imposed an arms embargo on Darfur. 2 Following the outbreak\nof hostilities, the Council, in its resolution 2724 (2024), called for an immediate cessation of\nhostilities and called upon all parties to comply with their obligations under international\nhumanitarian law and their commitments under the Jeddah Declaration of Commitment to\nProtect the Civilians of Sudan. In its resolution 2736 (2024), the Council demanded that the\nRapid Support Forces halt the siege of El Fasher and that all parties to the conflict ensure the\nprotection of civilians."},{"id":"a-hrc-57-23-p0019","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"19","seq":21,"section":"IV. Current conflict","text":"In mid-April 2023, hostilities broke out between the Sudanese Armed Forces and the\nRapid Support Forces, and their respective allied militias, in Khartoum. They quickly spread\nto other parts of the Sudan. Tensions preceded the current conflict and had been rising since\nthe removal of the former President Omer Hassan Ahmed Al-Bashir, in 2019, following\nwhich Lieutenant General Abdel-Fattah Al-Burhan took charge of the military-established\nTransitional Sovereignty Council, with Lieutenant General Mohamed Hamdan Dagalo, also\nknown as Hemedti, as his deputy. Despite the adoption of a transitional constitution, under\nwhich the country would be governed by a civilian-military coalition for a transitional period\nof 39 months, the transition to civilian rule faltered as the Sudanese Armed Forces and the\nRapid Support Forces jointly ousted the civilian leaders on 25 October 2021 and asserted\nmilitary rule."},{"id":"a-hrc-57-23-p0020","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"20","seq":22,"section":"IV. Current conflict","text":"At the time of drafting the present report, the conflict had spread to most of the states\nin the Sudan, with a devastating impact on the civilian population across the country. Multiple\ninitiatives have been pursued to end the conflict. On 16 April 2023, the Peace and Security\nCouncil of the African Union called for an immediate ceasefire, the protection of civilians\nand the provision of humanitarian support to civilians.3 On 27 May 2023, the African Union\nadopted the Roadmap for the Resolution of the Conflict in Sudan, which includes a call for a\ncomprehensive cessation of hostilities. 4 A separate political process was initiated by the\nIntergovernmental Authority on Development, resulting in the adoption of a road map on\n12 June 2023.5"},{"id":"a-hrc-57-23-p0021","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"21","seq":23,"section":"IV. Current conflict","text":"In early May 2023, Saudi Arabia and the United States of America co-facilitated talks\nin Jeddah, Saudi Arabia, between the Sudanese Armed Forces and the Rapid Support Forces.\nThe talks resulted in the signing of the Jeddah Declaration. Under this agreement, the parties\ncommitted to protecting civilians, respecting international humanitarian law and international\nhuman rights law, allowing humanitarian operations to resume, protecting humanitarian\npersonnel and assets, ensuring that their respective forces abided by international\nhumanitarian law and scheduling expanded discussions to achieve a permanent cessation of\nhostilities. Those commitments remain largely unimplemented. Another round of talks took\nplace in Manama in January 2024 and in Geneva in August 2024, leading to an agreement to\nopen the border at Adré, Chad, for humanitarian aid.6"},{"id":"a-hrc-57-23-p0022","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"22","seq":24,"section":"IV. Current conflict","text":"On 21 November 2023, the Secretary-General appointed a Personal Envoy for the\nSudan. In July 2024, the Personal Envoy held talks with representatives of the parties to the\nconflict on measures to ensure the distribution of humanitarian assistance and the protection\nof civilians across the Sudan.\nKey actors in the conflict"},{"id":"a-hrc-57-23-p0023","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"23","seq":25,"section":"IV. Current conflict","text":"The fact-finding mission considers that the situation in the Sudan amounts to a\nnon-international armed conflict to which article 3 of the Geneva Conventions and the\nProtocol Additional thereto, and relating to the Protection of Victims of Non-International\nArmed Conflict, applies. The two main parties to the armed conflict are the Sudanese Armed\nForces and the Rapid Support Forces. Both sides rely on regular armed and paramilitary\nforces, auxiliary militias, allied militias and intelligence and security agencies.\nSudanese Armed Forces Alliance"},{"id":"a-hrc-57-23-p0024","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"24","seq":26,"section":"IV. Current conflict","text":"The Sudanese Armed Forces Alliance is led and controlled by its\nCommander-in-Chief, Lieutenant General Al-Burhan. He sets the political and military\nstrategy and his most senior military officers control the Transitional Sovereignty Council,\nthe Sudanese Armed Forces, national ministries and state governments. In addition to the\nGeneral Intelligence Service, the Sudanese Armed Forces have their own military\nintelligence agency, which reports directly to Lieutenant General Al-Burhan."},{"id":"a-hrc-57-23-p0025","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"25","seq":27,"section":"IV. Current conflict","text":"During the current conflict, the Sudanese Armed Forces have relied heavily on their\nair force and have sought to strengthen their ground forces, which, prior to the conflict,\nincluded the Rapid Support Forces, through a massive mobilization drive. The leadership of\nthe Sudanese Armed Forces established a committee to coordinate the recruiting, arming and\nfinancing of new militias. In a parallel mobilization track, new recruits, known as “the\nmobilized” (mustanfareen), are enlisted into the Sudanese Armed Forces and deployed to\nreinforce depleted divisions."},{"id":"a-hrc-57-23-p0026","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"26","seq":28,"section":"IV. Current conflict","text":"Several armed groups originating in Darfur, including the Justice and Equality\nMovement, the Sudan Liberation Army-Minni Minawi, the Sudan Liberation Army Tambour\nFaction, the Sudanese Alliance, the Sudan People’s Liberation Movement/Army-North under\nMalik Agar and some groups from the eastern part of the Sudan have aligned their forces\nwith the Sudanese Armed Forces. The Justice and Equality Movement, the Sudan Liberation\nArmy-Minni Minawi and other armed groups from Darfur have formed a joint force that\nfights in coordination with the Sudanese Armed Forces against the Rapid Support Forces,\nparticularly in North Darfur State and its capital, El Fasher.\nRapid Support Forces Alliance"},{"id":"a-hrc-57-23-p0027","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"27","seq":29,"section":"IV. Current conflict","text":"The Rapid Support Forces are led by Lieutenant General Mohamed Hamdan Dagalo.\nHis older brother, Lieutenant General Abdelrahim Hamdan Dagalo, is the second in\ncommand. The Rapid Support Forces have operated as a highly mobile ground fighting force\nthat combines regular Rapid Support Forces units, their own intelligence service and newly\nrecruited Rapid Support Forces-aligned militias into an alliance under the overall control of\nLieutenant General Mohamed Hamdan Dagalo."},{"id":"a-hrc-57-23-p0028","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"28","seq":30,"section":"IV. Current conflict","text":"The roots of the Rapid Support Forces can be traced to the early 2000s, when the\nGovernment of the Sudan armed civilians to counter an insurgency in Darfur. Arab nomadic\ntribes without a traditional homeland and wishing to settle, given the encroaching\ndesertification, responded to the call and the Government organized them into militias that\nbecame known as Janjaweed. In 2005, Janjaweed militias were found to have committed, in\nconcert with the Government, serious violations of human rights and international\nhumanitarian law.7"},{"id":"a-hrc-57-23-p0029","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"29","seq":31,"section":"IV. Current conflict","text":"From 2013, facing a renewed insurgency, the Government reorganized some of the\nJanjaweed militias into what became known as the Rapid Support Forces. Lieutenant General\nMohamed Hamdan Dagalo was appointed as the commander of operations. The Rapid\n7   S/2005/60, paras. 68, 69 and 248–413.\nSupport Forces were formally recognized under the Rapid Support Forces Act of 2017.\nBefore the current conflict, the Government provided the Rapid Support Forces with\nextensive resources and support. The Rapid Support Forces increased their political influence\nand military capacity through deployments in Darfur, other parts of the Sudan and Yemen."},{"id":"a-hrc-57-23-p0030","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"30","seq":32,"section":"IV. Current conflict","text":"From the beginning of the conflict, the Rapid Support Forces senior leaders, directly\nand through intermediaries, recruited fighters from neighbouring States and the periphery of\nthe Sudan in exchange for money, weapons and other incentives, including the prospect of\nlooted goods.\nOther armed groups"},{"id":"a-hrc-57-23-p0031","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"31","seq":33,"section":"IV. Current conflict","text":"A number of other armed groups are not aligned with either the Rapid Support Forces\nor the Sudanese Armed Forces. These include the Sudan Liberation Army-Abdul Wahid and\nthe Sudan Liberation Movement-Transitional Council in Darfur and the Sudan People’s\nLiberation Movement-North Abdelaziz al-Hilu faction, which controls parts of South\nKordofan and Blue Nile States."},{"id":"a-hrc-57-23-p0032","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"32","seq":34,"section":"V. Root causes","text":"The conflict between the Sudanese Armed Forces and the Rapid Support Forces is\noften described as a dispute over power between Lieutenant General Al-Burhan and\nLieutenant General Mohamed Hamdan Dagalo. There are, however, deeper roots and\ncomplex factors that can be attributed to the lack of inclusive and democratic government,\nvast inequalities, the centralization of power and resources, the marginalization of various\ncommunities and rampant impunity in the Sudan."},{"id":"a-hrc-57-23-p0033","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"33","seq":35,"section":"V. Root causes","text":"Since its independence, the Sudan has been fragmented and stuck in a cycle of\nviolence, even during times of peace. It has experienced extensive periods of armed conflict\nand political strife. More than 46 peace agreements have been signed. One key weakness\ncommon to all past peace processes has been the focus on ending the conflict without\naddressing the root causes or enforcing accountability for mass atrocities. This has persisted,\ndespite recommendations pursuant to various initiatives, including the International\nCommission of Inquiry for Darfur and the African Union High-level Panel on Darfur. While\nthe recommendation of the International Commission of Inquiry for Darfur for the referral of\nthe situation to the International Criminal Court was implemented, the other proposed\nmeasures to end impunity were not. The recommendations of the African Union High-level\nPanel on Darfur to address the root causes and accountability were also not implemented."},{"id":"a-hrc-57-23-p0034","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"34","seq":36,"section":"V. Root causes","text":"Many of those who took up arms in prior conflicts came from the poorest\ncommunities. Their poverty was caused, in part, by neglect from the central Government,\nunderdevelopment, discrimination and ecological and demographic changes. Ongoing\nconflicts have led to massive displacement across the Sudan, exacerbating the situation."},{"id":"a-hrc-57-23-p0035","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"35","seq":37,"section":"V. Root causes","text":"Moreover, since independence, the Sudan has struggled with internal political\ninstability, leading to several military takeovers, restrictive military rule and exclusion of the\ncivilian population from participation in political processes. This situation was aggravated\nunder Mr. Al-Bashir’s 30-year rule and did not fundamentally change after his ousting in\nApril 2019. The succeeding period saw little improvement in terms of civilian participation\nin political processes, despite the December 2018 civilian uprising and planned transition to\na democratic civilian rule. The civilian movement, organized through resistance committees\nthat had evolved since the 2019 revolution, was perceived as a threat by the military, which\napplied repressive methods to suppress it.8"},{"id":"a-hrc-57-23-p0036","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"36","seq":38,"section":"V. Root causes","text":"The community leaders and civil society representatives to whom the fact-finding\nmission spoke stressed that political and ideological manipulation, recurring violence without\naccountability and the policy of divide and rule, particularly during the era of Mr. Al-Bashir’s\nrule, had intensified differences among various groups. They stressed the need for an\ninclusive dialogue to enable a deeper understanding of grievances and chart the way forward\nbased on equality and justice for all citizens of the Sudan."},{"id":"a-hrc-57-23-p0037","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"37","seq":39,"section":"VI. Violations of human rights and international humanitarian","text":"Since the outbreak of the conflict in mid-April 2023, 19,000 persons are estimated to\nhave been killed and 33,000 injured.9 A substantial number of those are civilians, who have\nbeen affected by airstrikes, heavy artillery shelling and ground attacks on homes and villages.\nThe use of explosives with wide area effects in densely populated areas, particularly in\nKhartoum and Darfur, has resulted in deaths, injuries and the extensive destruction of homes,\nhospitals, schools and other critical infrastructure, exacerbating the humanitarian crisis. As\nof August 2024, 10.7 million persons were internally displaced, which includes an estimated\n7.9 million persons who had fled their homes since the start of the conflict, and another\n2.8 million persons who had been displaced in earlier conflicts. 10 More than 2.1 million\npersons, including returnees, fled to neighbouring countries. 11"},{"id":"a-hrc-57-23-p0038","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"38","seq":40,"section":"1. Airstrikes and bombardments affecting civilians","text":"On 15 April 2023, heavy gunfire and explosions shook Khartoum, generating panic\nin the city and beyond. The exchange of fire between the Sudanese Armed Forces and the\nRapid Support Forces led to constant airstrikes and artillery shelling across the tri-city area\nof Khartoum, Omdurman and Bahri (greater Khartoum). Shelling took place across civilian\nareas and the conflict spread beyond military bases to residential neighbourhoods, causing\ncivilian deaths and injuries and large-scale destruction, including of critical bridges."},{"id":"a-hrc-57-23-p0039","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"39","seq":41,"section":"1. Airstrikes and bombardments affecting civilians","text":"Frequent shelling and airstrikes in greater Khartoum continued, affecting various\nneighbourhoods. For example, on 22 April 2023, bombs were dropped at rapid intervals in\nthe Al-Diyum neighbourhood in Khartoum, resulting in civilian deaths. Several areas of\ngreater Khartoum appear to have been flattened. The neighbourhoods of Al-Salama\nal-Qadema, Salma al-Kababesh, Al-Azhari, Al-Inkaz and Al-Nahda were subjected to\nfrequent airstrikes. Between April and June 2023, the Al-Remila neighbourhood in Khartoum\nsuffered shelling from both the Sudanese Armed Forces and the Rapid Support Forces. The\ncivilian death toll continued to rise."},{"id":"a-hrc-57-23-p0040","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"40","seq":42,"section":"1. Airstrikes and bombardments affecting civilians","text":"The conflict immediately spread to Darfur, widely affecting its towns. In May and\nJune 2023, there was intense artillery shelling of various neighbourhoods in El Geneina, West\nDarfur State. Mortars fell on civilian houses, medical clinics, internally displaced persons\nsites, and schools. The shelling reportedly came from the west and south of El Geneina, areas\nunder the control of the Rapid Support Forces."},{"id":"a-hrc-57-23-p0041","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"41","seq":43,"section":"1. Airstrikes and bombardments affecting civilians","text":"Starting in April 2023, in Nyala, South Darfur State, the Rapid Support Forces and\ntheir allied militias were engaged in intense armed confrontations with the Sudanese Armed\nForces. Both forces constantly shelled the area, affecting civilian neighbourhoods. The Taiba\nbridge in Nyala was shelled in August 2023, causing deaths and injuries among the dozens\nof civilians who had been seeking shelter near the bridge. The fighting persisted until\n26 October 2023, when the Rapid Support Forces captured the Sudanese Armed Forces base\nin Nyala."},{"id":"a-hrc-57-23-p0042","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"42","seq":44,"section":"1. Airstrikes and bombardments affecting civilians","text":"In Zalingei, Central Darfur State, armed confrontations ensued between the Sudanese\nArmed Forces and the Rapid Support Forces and their allied militias, from 15 April until\n31 October 2023, when the Rapid Support Forces captured the Sudanese Armed Forces base.\nDuring that period, both forces exchanged shelling across civilian neighbourhoods, resulting\n9  See Office for the Coordination of Humanitarian Affairs, “Sudan: humanitarian update – 1 September\n2024”.\n10 See https://dtm.iom.int/sudan (accessed on 31 August 2024).\n11 See https://data.unhcr.org/en/situations/sudansituation (accessed on 31 August 2024).\nin civilian deaths, injuries and displacement, including in the Stadium, Imtidad, Salam and\nZariba neighbourhoods on 13 and 14 May 2023."},{"id":"a-hrc-57-23-p0043","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"43","seq":45,"section":"1. Airstrikes and bombardments affecting civilians","text":"In South Kordofan State, on 14 March 2024, the Sudanese Armed Forces reportedly\nbombed Hadra elementary school, killing 11 children and two teachers, and injuring\n46 children. The Rapid Support Forces allegedly shelled a religious school known as\nAl-Khalwa al-Tijaniyah in El Fasher, killing at least 34 persons, mostly children."},{"id":"a-hrc-57-23-p0044","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"44","seq":46,"section":"1. Airstrikes and bombardments affecting civilians","text":"The fact-finding mission finds, based on the body of evidence gathered, that both the\nSudanese Armed Forces and the Rapid Support Forces failed to take sufficient measures to\nminimize the impact of airstrikes or artillery shelling on civilians. It notes that international\nhumanitarian law requires that all parties to a conflict strictly abide by the principles of\ndistinction, proportionality and precaution. Attacks are considered indiscriminate when they\nfail to distinguish between military objectives and civilians or civilian objectives, because\nthey are not or cannot be directed at a specific military objective, or their effects cannot be\nlimited. Practices inconsistent with international humanitarian law, including indiscriminate\nattacks posing risk to the lives of civilians, also violate international human rights law."},{"id":"a-hrc-57-23-p0045","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"45","seq":47,"section":"2. Pillage and destruction of civilian objects and infrastructure","text":"The fact-finding mission established that civilian infrastructure and objects, including\nobjects indispensable to the survival of the civilian population, were attacked, damaged or\ndestroyed by both the Sudanese Armed Forces and the Rapid Support Forces. Water,\ncommunication networks and electricity supply lines were destroyed in Khartoum, Darfur\nand other locations, leaving civilians in dire conditions. Large-scale destruction of residential\nhomes through airstrikes and shelling left thousands of civilians without shelter, forcing\nmany to flee and seek refuge in other locations."},{"id":"a-hrc-57-23-p0046","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"46","seq":48,"section":"2. Pillage and destruction of civilian objects and infrastructure","text":"Medical facilities in various locations affected by the conflict were also subjected to\nattacks, causing severe disruptions to the healthcare system. Several hospitals, including\nAl-Shuhada hospital in Khartoum, were looted by the Rapid Support Forces and their staff\nand patients were assaulted or even killed during the attack."},{"id":"a-hrc-57-23-p0047","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"47","seq":49,"section":"2. Pillage and destruction of civilian objects and infrastructure","text":"The fact-finding mission has documented widespread pillage, predominantly by the\nRapid Support Forces and allied militias. They were sometimes followed by civilians, bandits\nand groups of looters, including kassiba. 12 Multiple incidents of pillage and looting, in\nnumerous instances accompanied by killings and other violence against civilians, were\nreported in and around Khartoum, Al-Gazira and Darfur, particularly in and near the towns\nof El Geneina, Ardamata, Nyala, El Fasher and Zalingei. Those who were displaced from\ntheir homes in Khartoum, Darfur, Al-Gazira or other areas reported that the Rapid Support\nForces and/or their allied militias took all, or nearly all, of their belongings, including houses,\nwhich were subsequently occupied by them. In Darfur, the pillage, looting and destruction of\nproperty affected entire livelihoods and the civilian infrastructure, including shelter, food and\nwater, the health system, water stations, public offices and facilities, of non-Arab\ncommunities, in particular the Masalit."},{"id":"a-hrc-57-23-p0048","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"48","seq":50,"section":"2. Pillage and destruction of civilian objects and infrastructure","text":"Based on the foregoing, the fact-finding mission finds that the Rapid Support Forces\nand their allied militias, at times with the involvement of civilians or kassiba, engaged in a\npattern of pillage and destruction of objects indispensable to the survival of the civilian\npopulation, including through intentionally directing attacks against specially protected\nobjects, in violation of international humanitarian law. Under international human rights law,\nit finds that these acts violate the economic, social and cultural rights of the civilian\npopulation, in particular their rights to physical and mental health and to food, water and\nhousing."},{"id":"a-hrc-57-23-p0049","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"49","seq":51,"section":"B. Ethnic-based attacks in El Geneina","text":"In some parts of the country, the violence had an ethnic undertone. This was\nparticularly manifest in the attacks carried out against the non-Arab Masalit community in\nWest Darfur State."},{"id":"a-hrc-57-23-p0050","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"50","seq":52,"section":"B. Ethnic-based attacks in El Geneina","text":"In El Geneina, the capital of West Darfur, the current conflict further stretched\npre-existing tribal tensions, and was fought mainly along ethnic lines, pitting the Rapid\nSupport Forces and their allied militias against the Sudanese Armed Forces and Masalit\nethnic groups. Between April and November 2023, the Rapid Support Forces and allied\nmilitias clashed with the Sudanese Armed Forces and their allies, including the Sudanese\nAlliance led at the time by the Governor of West Darfur, Khamis Abakar, and other Masalit\ngroups, over control of El Geneina."},{"id":"a-hrc-57-23-p0051","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"51","seq":53,"section":"B. Ethnic-based attacks in El Geneina","text":"El Geneina was an ethnically diverse city with a population of around\n540,000 inhabitants. Following the outbreak of the conflict, on 24 April 2023, the Rapid\nSupport Forces and their allied militias attacked a Sudanese Armed Forces convoy in the\nAl-Jamarek neighbourhood. The Rapid Support Forces and their allied militias encircled the\nAl-Jamarek, Al-Thawra, Al-Tadamon and Al-Madares neighbourhoods, subjecting them to\nintense mortar shelling and sniper fire, causing a large number of casualties. As the Sudanese\nArmed Forces retreated to their base in Ardamata, with some of their elements taking shelter\nin some of the civilian neighbourhoods, the Rapid Support Forces and their allied militias\nbegan a campaign of violence targeting the Masalit community in El Geneina, resulting in\nlarge-scale atrocities, including thousands of killings, 13 torture, rape and other forms of\nsexual violence, pillage and destruction of property. During these attacks, the Sudanese\nArmed Forces failed to protect the civilian population."},{"id":"a-hrc-57-23-p0052","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"52","seq":54,"section":"B. Ethnic-based attacks in El Geneina","text":"Masalit men were systematically targeted. The Rapid Support Forces and their allied\nmilitias went door to door in Masalit neighbourhoods, looking for men and brutally attacking\nand killing them, sometimes in front of their families. Lawyers, doctors, human rights\ndefenders, academics and community and religious leaders were apparently specifically\ntargeted. Commanders of the Rapid Support Forces reportedly issued orders to “comb the\ncity” and place checkpoints throughout."},{"id":"a-hrc-57-23-p0053","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"53","seq":55,"section":"B. Ethnic-based attacks in El Geneina","text":"The height of the assault on El Geneina occurred on 14 and 15 June 2023, following\nthe capture and subsequent killing of the Governor of West Darfur, Khamis Abakar, a\nMasalit. During the night of 14 June, tens of thousands of individuals, the majority of them\nMasalit civilians, attempted to flee from the Al-Jamarek and Al-Madares neighbourhoods\nand seek refuge in Ardamata. At dawn on 15 June, as the miles-long convoy of people passed\nthrough the El Geneina neighbourhoods of Al-Shatii and Al-Naseem, it was ambushed by\nthe Rapid Support Forces and their allied militias. The attackers fired at the convoy from\ntheir vehicles, killing and injuring thousands of individuals, leaving many dead bodies,\nincluding of women and children, on the streets of El Geneina and on the road to the border\nwith Chad. The Rapid Support Forces and their allied militias also pillaged, burned down or\notherwise destroyed and shelled Masalit neighbourhoods in El Geneina. Interviewees\ndescribed the Rapid Support Forces and their allied militias using racial slurs against Masalits\nand other non-Arab groups, describing them as umbay (slave) komrod (Masalit fighter) and\nnuba (black), accompanied by threats and claims that the land belonged to Arabs. Several\nMasalit detainees at the Rapid Support Forces base in Al-Jamarek and other locations\nendured severe beatings and torture."},{"id":"a-hrc-57-23-p0054","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"54","seq":56,"section":"B. Ethnic-based attacks in El Geneina","text":"Women were assaulted, raped and robbed of their belongings because of their\nethnicity. The attackers used derogative terms about the Masalit in the context of rape and\nother forms of sexual violence. A survivor from El Geneina was told: “We will make you,\nthe Masalit girls, give birth to Arab children” after being raped inside her house at gunpoint.\nSeveral women reported that they had been explicitly told by the Rapid Support Forces and\ntheir allied militias to leave for Chad and not to return or they would be harmed.\n13   S/2024/65, para. 54."},{"id":"a-hrc-57-23-p0055","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"55","seq":57,"section":"B. Ethnic-based attacks in El Geneina","text":"This widespread violence and destruction caused hundreds of thousands of persons to\nflee. 14 The Rapid Support Forces and their allied militias continued to pursue and attack\nfleeing civilians along the escape routes to Chad. Individuals were asked to declare their\nethnicity at checkpoints manned by the Rapid Support Forces and their allied militias."},{"id":"a-hrc-57-23-p0056","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"56","seq":58,"section":"B. Ethnic-based attacks in El Geneina","text":"Based on the foregoing, the fact-finding mission finds that the Rapid Support Forces\nand their allied militias committed coordinated and large-scale attacks on the civilian\npopulation, mainly the Masalit community in El Geneina, and other areas under their control\nalong the routes taken by fleeing civilians. The above-described acts of killings, torture and\nother forms of cruel, inhuman or degrading treatment or punishment, including rape and other\nforms of sexual violence, as well as looting, pillage and destruction of objects indispensable\nto the survival of the civilian population, formed part of large-scale attacks that targeted, in\nparticular, the Masalit community, on the basis of their ethnicity. The fact-finding mission\nfinds that these acts amount to violations of international humanitarian law to life and person,\nin particular murder of all kinds, cruel treatment and torture, and outrages upon personal\ndignity, in particular humiliating and degrading treatment and rape and any form of indecent\nassault, and threats to commit the foregoing acts. They also constitute human rights\nviolations, in particular of the rights to life and non-discrimination, and the prohibition of\ntorture and other forms of cruel, inhuman or degrading treatment or punishment, including\nrape and other forms of sexual violence. The fact-finding mission also finds that the Rapid\nSupport Forces and their allied militias violated the international humanitarian law\nprohibitions of acts and threats of violence primarily intended to spread terror among the\ncivilian population, making the civilian population the object of attack, destroying objects\nindispensable to the survival of the civilian population, and forcible displacement."},{"id":"a-hrc-57-23-p0057","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"57","seq":59,"section":"C. Sexual and gender-based violence","text":"The fact-finding mission finds that sexual and gender-based violence, in particular\nrape and gang rape, is widespread in the context of the conflict and continues to occur on a\nlarge scale across the Sudan. While women and girls of reproductive age were\noverwhelmingly targeted by these acts, sources informed the fact-finding mission of the rape\nof girls as young as 8 years old and women as old as 75 years old. Based on testimonies,\nvaginal single and multiple-perpetrator rape has been the most documented type of sexual\nviolence. Other acts of rape and sexual violence, such as anal rape or rape with body parts,\nnotably fingers, also occurred. Men and boys were not spared, although the number of\nreported cases is substantially lower."},{"id":"a-hrc-57-23-p0058","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"58","seq":60,"section":"C. Sexual and gender-based violence","text":"Rape and other forms of sexual violence documented by the fact-finding mission were\nlargely attributed to men wearing the Rapid Support Forces uniforms and, in the context of\nDarfur, armed men allied to the Rapid Support Forces, who victims referred to as Janjaweed,\nwearing traditional attire and shawls (kadamol) around their heads, masking most of their\nfacial features."},{"id":"a-hrc-57-23-p0059","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"59","seq":61,"section":"C. Sexual and gender-based violence","text":"The fact-finding mission finds that sexual violence was perpetrated on a large scale\nby the Rapid Support Forces in the context of attacks of cities in the Darfur region and the\ngreater Khartoum area. There are numerous victims and witnesses of the rape and other forms\nof sexual violence that occurred during attacks on El Geneina from mid-April to mid-June\n2023, and Ardamata in November 2023. Victims recounted being attacked in their homes,\nbeaten, lashed and threatened with death or harm to their relatives or children, before being\nraped, often by more than one perpetrator. They were also subjected to sexual violence while\nseeking shelter from attacks or fleeing."},{"id":"a-hrc-57-23-p0060","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"60","seq":62,"section":"C. Sexual and gender-based violence","text":"Witnesses from greater Khartoum and other areas in Darfur, particularly Nyala and\nZalingei, confirmed that similar patterns of widespread rape and gang rape had been\nperpetrated by Rapid Support Forces members and their allies during attacks on cities and\nsites for internally displaced persons. In some conflict areas, perpetrators of sexual violence\nused racist slurs, in particular referring to non-Arab ethnicity, associated with pejorative\nattributes (see para. 53 above), indicating that ethnicity was a basis for discrimination, often\nentailing more violent assaults. Women human rights defenders, journalists and medical\npersonnel were also targeted with sexual violence, seemingly in reprisal for their activities."},{"id":"a-hrc-57-23-p0061","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"61","seq":63,"section":"C. Sexual and gender-based violence","text":"Women and girls were also abducted by the Rapid Support Forces for the purpose of\nsexual violence and/or sexual exploitation in Darfur and greater Khartoum. Some victims\nwere abducted and transported to remote locations where they were raped. Witnesses also\ndescribed women and girls being abducted and taken on pickup vehicles to unknown\ndestinations. Some victims described being abducted and forcibly held in and confined to a\nhouse or a room for a duration ranging from several days to several months, during which\ntime they were subjected to repeated rape and/or sexual exploitation by different Rapid\nSupport Forces members and threatened with violence or death if they tried to leave or resist\nsexual violence."},{"id":"a-hrc-57-23-p0062","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"62","seq":64,"section":"C. Sexual and gender-based violence","text":"Based on the foregoing, the fact-finding mission finds that the large-scale rape and\nother forms of sexual violence committed primarily by the Rapid Support Forces and their\nallied militias amount to violations of international humanitarian law, namely, violence to\nlife and person, and outrages upon personal dignity, in particular humiliating, degrading and\ncruel treatment and torture, and rape and any form of indecent assault, and threats to commit\nthe foregoing acts. It also finds that the abduction, confinement and detention of women and\ngirls for sexual purposes, including rape and sexual exploitation, by the Rapid Support Forces\nconstituted conditions whereby they exercised powers attaching to the right of ownership\nover the victims, whose liberty they also deprived, amounting to prohibited acts of sexual\nslavery. Under international human rights law, these acts constitute violations of the rights to\nbe free from torture and other cruel, inhuman degrading treatment or punishment, including\nrape and sexual violence, to physical and mental health, including reproductive rights, and to\nnon-discrimination based on gender."},{"id":"a-hrc-57-23-p0063","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"63","seq":65,"section":"C. Sexual and gender-based violence","text":"The fact-finding mission also documented several cases of sexual violence, including\nrape and rape threats, attributed to the Sudanese Armed Forces and their military intelligence\nagency. The fact-finding mission received information concerning allegations of sexual\nexploitation of women and girls by the Sudanese Armed Forces in exchange for food in areas\nunder their control. Further investigations are necessary to determine the extent and patterns\nof sexual violence perpetrated by the Sudanese Armed Forces in the context of the current\nconflict."},{"id":"a-hrc-57-23-p0064","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"64","seq":66,"section":"D. Grave violations against children","text":"Children are paying a very heavy toll in the conflict. They have been recruited and\nused in hostilities, killed, injured, abducted and forcibly displaced, detained with adults,\ntortured, subjected to sexual violence and deprived of healthcare and education. In his most\nrecent annual report on children and armed conflict, the Secretary-General lists the Sudanese\nArmed Forces and the Rapid Support Forces among the parties that have committed grave\nviolations against children.15 Both parties have been newly listed for the killing and maiming\nof children and for attacks on schools and hospitals, while the Rapid Support Forces have\nalso been listed for the recruitment and use of children and for the rape and other forms of\nsexual violence against children. The investigations of the fact-finding mission confirm these\nfindings. It also received multiple credible reports that the Sudanese Armed Forces have\nplayed a role in the training and arming of children who have joined the popular mobilization."},{"id":"a-hrc-57-23-p0065","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"65","seq":67,"section":"1. Child recruitment or use of children in hostilities","text":"Despite undertakings by the Government of the Sudan to maintain the minimum age\nfor voluntary service at 18 and to prohibit the forced or voluntary conscription of any person\nbelow that age, there is credible information that children younger than 18 have been\nassociated with regular Sudanese Armed Forces troops, notably in Darfur. Of particular\nconcern is that the Sudanese Armed Forces leadership has been pursuing alliances with armed\ngroups that have been listed in the report of the Secretary-General for the recruitment and use\n15   See A/78/842-S/2024/384.\nof children in hostilities, including the Sudan Liberation Army-Minni Minawi and the Justice\nand Equality Movement."},{"id":"a-hrc-57-23-p0066","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"66","seq":68,"section":"1. Child recruitment or use of children in hostilities","text":"The Rapid Support Forces and their allied militias systematically recruit and use\nchildren in hostilities. Witnesses reported that young boys have been seen with the Rapid\nSupport Forces and allied militias in El Geneina, Ardamata and other localities along the\nborder with Chad, as well as Zalingei, Nyala, Wad Madani and Khartoum. Reports also\nindicate that children have been fighting alongside the Rapid Support Forces in El Fasher."},{"id":"a-hrc-57-23-p0067","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"67","seq":69,"section":"1. Child recruitment or use of children in hostilities","text":"The Rapid Support Forces and their allied militias have used children as bodyguards\nand informers, in combat units and to conduct security patrols, monitor checkpoints, carry\nout searches, monitor arrestees, pillage, commit arson and commit acts of torture in detention\ncentres. Eyewitnesses reported that some children were dressed in Rapid Support Forces\nuniforms, with some holding ranks."},{"id":"a-hrc-57-23-p0068","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"68","seq":70,"section":"2. Killing and injuring of children","text":"The deaths, maiming and serious injuries of children as a result of airstrikes and\nshelling of residential areas, including in Khartoum and parts of Darfur, have been\ndocumented. Numerous eyewitnesses reported the deaths of children during airstrikes that\nhit civilian objects such as markets or schools and densely populated areas. For example, and\nas mentioned above, the aerial bombardment of Hadra elementary school in South Kordofan,\non 14 March 2024, reportedly by the Sudanese Armed Forces, killed 11 and injured\n46 children."},{"id":"a-hrc-57-23-p0069","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"69","seq":71,"section":"2. Killing and injuring of children","text":"In Darfur, dead bodies, including of children with gunshot wounds, were seen lying\nin the streets during the attack on El Geneina by the Rapid Support Forces and allied militias\nmentioned in paras. 49–56 above. Children were killed by snipers while walking on the\nstreets, inside their houses or when the Rapid Support Forces and allied militias shelled\nhouses, schools or hospitals in El Geneina, Ardamata and Zalingei."},{"id":"a-hrc-57-23-p0070","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"70","seq":72,"section":"2. Killing and injuring of children","text":"Based on the foregoing and in connection with other relevant sections of this report,\nthe fact-finding mission finds that the Rapid Support Forces and affiliated militias recruited\nand used children in hostilities and committed acts of killing and maiming, abduction and\nrape or other sexual violence against children, attacks on schools and hospitals and\ndeprivation of essential humanitarian assistance for children. It finds that the Sudanese\nArmed Forces committed acts of killing and maiming of children, attacks on schools and\ndeprivation of essential humanitarian assistance for children. These acts constitute violations\nof international humanitarian law and international human rights law, in particular under the\nConvention on the Rights of the Child and its Optional Protocol on the involvement of\nchildren in armed conflict, and fall under the six grave violations against children in times\nof conflict.16"},{"id":"a-hrc-57-23-p0071","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"71","seq":73,"section":"E. Arbitrary arrests and detention","text":"The fact-finding mission has documented widespread arrests and detention conducted\nby both the Sudanese Armed Forces and the Rapid Support Forces since mid-April 2023 in\nareas under their control. Civilians were arrested mainly on suspicion of supporting the other\nparty to the conflict. Documented arrests and detentions took place in various locations of\nKhartoum, West and Central Darfur and River Nile States. Use of unofficial locations by\nboth the Sudanese Armed Forces and the Rapid Support Forces has been reported: a factory,\nthe sports centre in Khartoum, schools and ordinary residential buildings were used as\ndetention centres by the Rapid Support Forces, in particular in Khartoum and Blue Nile\nStates."},{"id":"a-hrc-57-23-p0072","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"72","seq":74,"section":"E. Arbitrary arrests and detention","text":"Civilians were arrested in different locations, including checkpoints and their homes,\noften accompanied by acts of physical violence. Harsh detention conditions were reported.\nVictims said that they were detained in extremely congested facilities, in inhumane\nconditions without access to adequate food, water or sanitation facilities. Medical facilities\nappear to have been totally lacking. Arrests were conducted without a warrant or any other\ntype of legal documentation and access to legal assistance and family visits was denied."},{"id":"a-hrc-57-23-p0073","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"73","seq":75,"section":"E. Arbitrary arrests and detention","text":"Former detainees told the fact-finding mission that they had been held together with\nhundreds of other detainees. A man who was detained at a Sudanese Armed Forces detention\ncentre in December 2023 estimated the number of detainees at about 400. Another former\ndetainee indicated that he had been detained alongside more than 600 other persons at a Rapid\nSupport Forces detention facility in November 2023. Boys under the age of 18 were arrested\nand held in both Sudanese Armed Forces and Rapid Support Forces detention facilities\ntogether with adult male detainees in Khartoum and Darfur. Numerous cases of deaths in\ndetention in facilities of both forces have been documented."},{"id":"a-hrc-57-23-p0074","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"74","seq":76,"section":"E. Arbitrary arrests and detention","text":"Based on the above, the fact-finding mission finds that both the Rapid Support Forces\nand the Sudanese Armed Forces arbitrarily arrested and detained civilians, including\nchildren, in violation of fundamental guarantees under international humanitarian law and\ninternational human rights law. Individuals, including children, were not informed of the\nreasons for their arrest, or any charges brought against them, and often held in unofficial\ndetention locations in inhumane conditions and without access to legal assistance or judicial\noversight, in violation of the International Covenant on Civil and Political Rights and the\nConvention on the Rights of the Child."},{"id":"a-hrc-57-23-p0075","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"75","seq":77,"section":"F. Torture and other cruel, inhuman or degrading treatment or","text":"Acts amounting to torture and other forms of ill-treatment were carried out by the\nSudanese Armed Forces, including their military intelligence agency, and by the Rapid\nSupport Forces and their allied militias."},{"id":"a-hrc-57-23-p0076","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"76","seq":78,"section":"F. Torture and other cruel, inhuman or degrading treatment or","text":"The most common methods of torture identified by the fact-finding mission as used\nby the Sudanese Armed Forces included pouring cold water on the victim; lashing; beating\nthe victim on various parts of the body or, in some cases, on the entire body with iron cables,\nwhips, rifles or weapons; causing sometimes deep cuts and bleeding; and pulling out or\ndamaging fingernails or toenails."},{"id":"a-hrc-57-23-p0077","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"77","seq":79,"section":"F. Torture and other cruel, inhuman or degrading treatment or","text":"The most common methods of torture identified as used by the Rapid Support Forces\nincluded lashing and beating the victim on various parts of the body or, in some cases, on the\nentire body with iron cables, whips, rifles or weapons. For example, one victim said that the\nRapid Support Forces had taken her from a house in El Geneina, blindfolded her and\ntransferred her to another location, where they beat her with a whip for what seemed like a\nlong time, severely injuring her."},{"id":"a-hrc-57-23-p0078","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"78","seq":80,"section":"F. Torture and other cruel, inhuman or degrading treatment or","text":"Boys under the age of 18 were also subjected to acts of torture or ill-treatment and\nsometimes sexual violence in detention. The Rapid Support Forces also appear to have used\nteenage boys as guards in detention facilities to torture other detainees, notably in Al Nakheel\nPolice Station in Omdurman."},{"id":"a-hrc-57-23-p0079","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"79","seq":81,"section":"F. Torture and other cruel, inhuman or degrading treatment or","text":"Based on the foregoing, the fact-finding mission finds that both the Sudanese Armed\nForces and the Rapid Support Forces intentionally inflicted severe physical and mental pain\nor suffering on their victims, including children, with the purpose of intimidating, coercing\nor obtaining a confession from them or as a form of punishment or on a discriminatory basis.\nThese acts amount to violations of international humanitarian law, namely, violence to life\nand person, in particular cruel treatment and torture, and outrages upon personal dignity, in\nparticular humiliating and degrading treatment. They also amount to violations of\ninternational human rights law, in particular under the Convention against Torture and the\nConvention on the Rights of the Child."},{"id":"a-hrc-57-23-p0080","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"80","seq":82,"section":"G. Suppression of free speech, information and media","text":"Following the eruption of the conflict, key media outlets and telecommunications\nservices were suspended or shut down. The Rapid Support Forces seized critical\ncommunications infrastructure, resulting in major network disruptions. As a result, civilians\nwere unable to access essential services. The Internet shutdown by the Sudanese Armed\nForces and the Rapid Support Forces also hampered the work of front-line humanitarian aid\nproviders, including persons working in the emergency response rooms, 17 preventing them\nfrom coordinating and obtaining food, medicine and other essential items for those in need."},{"id":"a-hrc-57-23-p0081","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"81","seq":83,"section":"G. Suppression of free speech, information and media","text":"In addition, both the Rapid Support Forces and the Sudanese Armed Forces, and their\nintelligence agencies, systematically exercised censorship and suppressed media freedom by\narresting, threatening, intimidating, harassing and attacking journalists and media\nprofessionals. One female journalist was repeatedly threatened by the Rapid Support Forces\nafter being linked to media coverage of human rights violations by them. They first warned\nher brother that continuing to write would “lead to trouble”. Two members of the Rapid\nSupport Forces then made death threats against her and subsequently opened fire on her\nfamily home. The journalist, along with her mother and sister, was forced to go into hiding.\nIn another case, in June 2024, Sudanese Armed Forces military intelligence officers arrested,\nassaulted and threatened a freelance journalist in El Fasher. He said he was held in a small\ncell and kicked and beaten until he lost consciousness."},{"id":"a-hrc-57-23-p0082","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"82","seq":84,"section":"G. Suppression of free speech, information and media","text":"The fact-finding mission has also documented multiple incidents of threats,\nintimidation, harassment, attacks and reprisals against individuals involved in documenting\nhuman rights violations, including human rights defenders, lawyers, emergency response\nroom and resistance committee members, and other members of civil society, by both the\nSudanese Armed Forces and the Rapid Support Forces."},{"id":"a-hrc-57-23-p0083","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"83","seq":85,"section":"G. Suppression of free speech, information and media","text":"Based on the foregoing, the fact-finding mission finds that both the Rapid Support\nForces and the Sudanese Armed Forces imposed broad Internet shutdowns by cutting access\nto information and communications through Internet and media services and curtailing the\nfree speech of journalists and the media, which are incompatible with the right to freedom of\nopinion and expression under the International Covenant on Civil and Political Rights and\nthe African Charter on Human and People’s Rights."},{"id":"a-hrc-57-23-p0084","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"84","seq":86,"section":"H. Humanitarian situation","text":"According to the Office for the Coordination of Humanitarian Affairs, close to\n16 million persons in the Sudan were in need of lifesaving assistance due to prolonged\ninternal conflicts and instabilities, and economic crises before the conflict broke out.18 By\nAugust 2024, more than half of the Sudanese population – 25.6 million – was experiencing\nacute hunger. Among them, more than 8.5 million persons were facing emergency levels of\nhunger and more than 755,000 were in catastrophic conditions in Darfur, South and North\nKordofan, Blue Nile, Al-Gazira and Khartoum States.19"},{"id":"a-hrc-57-23-p0085","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"85","seq":87,"section":"H. Humanitarian situation","text":"The conflict has brought the country’s health system to the verge of collapse, and\npeople are facing a lethal combination of displacement, shortage of potable water, hunger\nand disease. In July 2024, the Famine Review Committee of the Integrated Food Security\nPhase Classification determined that famine conditions (meaning that at least one in five\npeople or households have an extreme lack of food and face starvation and destitution,\nresulting in extremely critical levels of acute malnutrition and death) were prevalent in one\nof the camps for internally displaced persons. 20"},{"id":"a-hrc-57-23-p0086","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"86","seq":88,"section":"H. Humanitarian situation","text":"Access restrictions, including administrative impediments, and insecurity for\nhumanitarian aid and humanitarian workers have further aggravated the humanitarian crisis.\nHumanitarian organizations operating in the Sudan indicated that they were facing multiple\nchallenges, including arbitrary denial of or delays in processing visa applications for\nhumanitarian workers, restrictions on border crossing options for humanitarian aid and delays\nin the issuance of travel permits for humanitarian workers and in the authorization of\ndomestic humanitarian movement. 21 Since the beginning of March 2024, the planned\nmovement of over 125 trucks to hard-to-reach areas had been pending approval for over\n90 days, affecting delivery of humanitarian aid in South, Central, North and East Darfur and\nKhartoum States.22"},{"id":"a-hrc-57-23-p0087","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"87","seq":89,"section":"H. Humanitarian situation","text":"The Sudanese Armed Forces, including through their intelligence services, have\nhampered the transport of humanitarian aid through border crossings to communities in need\nof aid, especially access to locations controlled by the Rapid Support Forces, which are also\npreventing access to areas under the control of the Sudanese Armed Forces. From February\nto August 2024, the Sudanese Armed Forces blocked the passage of humanitarian assistance\nfrom Chad through the Adré border crossing, based on perceived benefit to the Rapid Support\nForces, while the Rapid Support Forces blocked the delivery of medical supplies to El Fasher\non the basis that it would benefit the Sudanese Armed Forces. The Sudanese authorities\nreopened the Adré border crossing from 15 August 2024, as talks led by the United States\ncontinued in Geneva.23"},{"id":"a-hrc-57-23-p0088","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"88","seq":90,"section":"H. Humanitarian situation","text":"While it welcomes the reopening of the Adré border crossing, the fact-finding mission\nfinds that, despite the call by the Security Council, in its resolutions 2724 (2024) and\n2736 (2024), to the parties to the conflict to allow and facilitate the rapid, safe, unhindered\nand sustained passage of humanitarian relief for civilians in need, both the Sudanese Armed\nForces and the Rapid Support Forces have engaged in actions contrary to their obligations\nunder international humanitarian law regarding such passage of humanitarian relief."},{"id":"a-hrc-57-23-p0089","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"89","seq":91,"section":"VII. International crimes and their perpetrators","text":"The fact-finding mission has examined the above findings in accordance with its\nstandard of proof under international human rights law and international humanitarian law\nthrough the lens of international criminal law, which provides for individual criminal\nresponsibility for the core international crimes."},{"id":"a-hrc-57-23-p0090","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"90","seq":92,"section":"A. War crimes","text":"The fact-finding mission finds that the above-described violations took place in the\ncontext of the non-international armed conflict in the Sudan since mid-April 2023. On this\nbasis, it finds reasonable grounds to believe that many of the established violations of\ninternational humanitarian law constitute war crimes."},{"id":"a-hrc-57-23-p0091","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"91","seq":93,"section":"A. War crimes","text":"The fact-finding mission finds reasonable grounds to believe that the Rapid Support\nForces and affiliated militias committed the war crimes of violence to life and person, in\nparticular murder of all kinds, mutilation, cruel treatment and torture; committing outrages\nupon personal dignity, in particular humiliating and degrading treatment; rape, sexual slavery\nand any form of indecent assault; pillage of towns or places; conscripting or enlisting children\nunder the age of 15 or using them to participate actively in hostilities; intentionally directing\nattacks against the civilian population; and ordering the displacement of the civilian\npopulation for reasons related to the conflict."},{"id":"a-hrc-57-23-p0092","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"92","seq":94,"section":"A. War crimes","text":"It also finds reasonable grounds to believe that the Sudanese Armed Forces committed\nthe war crimes of violence to life and person, in particular murder of all kinds, mutilation,\ncruel treatment and torture; and committing outrages upon personal dignity, in particular\nhumiliating and degrading treatment.\n21 See https://reliefweb.int/report/sudan/sudan-humanitarian-access-snapshot-july-2024.\n22 Office for the Coordination of Humanitarian Affairs, “Sudan: humanitarian update – 24 June 2024”.\n23 See https://reliefweb.int/report/sudan/sudan-adre-border-crossing-situation-update-flash-update-no-\n01-27-august-2024-enar."},{"id":"a-hrc-57-23-p0093","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"93","seq":95,"section":"B. Crimes against humanity","text":"Crimes against humanity concern the commission of prohibited acts as part of a\nwidespread or systematic attack directed against any civilian population, with knowledge of\nthe attack. An attack against the civilian population involves multiple acts directed against a\npredominantly civilian population pursuant to or in furtherance of a State or organizational\nplan or policy, which may be inferred from the acts.24"},{"id":"a-hrc-57-23-p0094","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"94","seq":96,"section":"B. Crimes against humanity","text":"The fact-finding mission has established the existence of a large-scale attack by the\nRapid Support Forces and their allied militias against the predominantly non-Arab civilian\npopulation, in particular the ethnic Masalit, in El Geneina and other areas along the routes\ntaken by civilians fleeing El Geneina. On the basis of an examination of the facts, it finds that\nthis attack was widespread and/or systematic in nature. It further finds, on the basis of\ninferences drawn from the facts, that the attack was carried out pursuant to or in furtherance\nof an organizational policy."},{"id":"a-hrc-57-23-p0095","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"95","seq":97,"section":"B. Crimes against humanity","text":"The fact-finding mission finds reasonable grounds to believe that the Rapid Support\nForces and their allied militias committed the crimes against humanity of murder, torture,\nenslavement, rape, sexual slavery and acts of a sexual nature of comparable gravity,\npersecution on the basis of intersecting ethnic and gender grounds in connection with the\nforegoing acts, and the forcible displacement of population."},{"id":"a-hrc-57-23-p0096","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"96","seq":98,"section":"VIII. Accountability","text":"The Sudan carries the primary responsibility to prevent and halt violations and abuses\nof human rights and violations of international humanitarian law. In line with the Basic\nPrinciples and Guidelines on the Right to a Remedy and Reparation for Victims of Gross\nViolations of International Human Rights Law and Serious Violations of International\nHumanitarian Law, it must provide remedies and reparation to victims."},{"id":"a-hrc-57-23-p0097","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"97","seq":99,"section":"A. Domestic legal system","text":"Following the removal of the former President Mr. Al-Bashir, the 2019 Transitional\nConstitutional Document (Constitutional Decree No. 38), amended in 2020 by the Juba\nAgreement for Peace in the Sudan, set out legislative and institutional reforms to be\nundertaken by State agencies to address the country’s legacy of past violations. The process\nwas, however, cut short following the 2021 military takeover and the subsequent eruption of\nthe current conflict."},{"id":"a-hrc-57-23-p0098","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"98","seq":100,"section":"A. Domestic legal system","text":"The Criminal Act of 1991, as amended in 2009, allows for the prosecution of certain\nacts as war crimes, crimes against humanity and genocide at the domestic level. The Armed\nForces Act of 2007, amended in 2022, also contains provisions on war crimes. However, the\ncategories and definitions employed in Sudanese legislation are narrower than those\nrecognized by international law, thereby impeding accountability for the full range of\ninternational crimes committed at the national level."},{"id":"a-hrc-57-23-p0099","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"99","seq":101,"section":"A. Domestic legal system","text":"In terms of judicial and legal infrastructure, the fact-finding mission received\ninformation on the destruction of government buildings and records, in particular in\nKhartoum and the Darfur states, by the Rapid Support Forces. Several interviewees noted the\ntargeting of courts, including in El Geneina, Nyala and Zalingei, and the destruction of\nrecords. Prisons were also attacked in several locations and detainees were reportedly\nreleased by the warring parties, demonstrating the breakdown of the rule of law."},{"id":"a-hrc-57-23-p0100","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"100","seq":102,"section":"B. Accountability mechanisms in areas controlled by the Sudanese Armed","text":"On 21 July 2023, the Sudanese authorities established the National Committee of\nInvestigation on Human Rights Violations, War Crimes and Violations by the Rebel Rapid\nSupport Forces and Other Crimes. According to the authorities, as at 18 June 2024, the\nnumber of registered criminal cases had reached 12,470 and 346 arrest warrants had been\nissued against the commanders and employees of the Rapid Support Forces.25 The authorities\nalso indicated that 65 cases had been tried. The fact-finding mission notes, based on the list\nincluded in the progress report circulated by the authorities at the fifty-sixth session of the\nHuman Rights Council, that only 2 of the 65 cases appear to include charges of international\ncrimes. The others concern offences against the State and sedition. The fact-finding mission\nreceived information that these cases target Sudanese civilians for their activities as lawyers,\nhumanitarians, grass-roots activists, human rights defenders or emergency response room\ncoordinators. This is indicative of the National Committee being involved in selective justice,\nprimarily targeting activists perceived as affiliates of the Rapid Support Forces."},{"id":"a-hrc-57-23-p0101","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"101","seq":103,"section":"B. Accountability mechanisms in areas controlled by the Sudanese Armed","text":"A second committee was established by the authorities, focusing on international\nlawsuits, including the submission of information on crimes committed by the Rapid Support\nForces to the International Criminal Court. 26 In his statement to the Security Council on\n5 August 2024, the Prosecutor of the Court noted that his Office had finally received\ncooperation from the Sudan and that his team could enter Port Sudan and had managed to\ncollect evidence.27"},{"id":"a-hrc-57-23-p0102","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"102","seq":104,"section":"B. Accountability mechanisms in areas controlled by the Sudanese Armed","text":"To date, accountability efforts undertaken by the authorities have been focused on\ncrimes committed by the Rapid Support Forces and their perceived affiliates. The fact-finding\nmission has not received any information on investigations and prosecutions, where\nappropriate, of members of the Sudanese Armed Forces or other government entities for\ninternational crimes. The fact-finding mission believes that the developments at the domestic\nlevel are indicative of a lack of willingness to investigate and prosecute all those responsible\non an equal basis. Victims have also informed the fact-finding mission of their lack of trust\nin the domestic justice system, including fear of reprisals for reporting violations committed\nby the Sudanese Armed Forces and other government entities."},{"id":"a-hrc-57-23-p0103","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"103","seq":105,"section":"C. Accountability mechanisms in areas controlled by the Rapid Support","text":"The Rapid Support Forces announced the establishment of the “Commander Fudail\ninvestigative committee” to investigate all criminal activities in areas under their control, and\na fact-finding committee to look into reported mass killings in Ardamata. 28 The Prosecutor\nof the International Criminal Court noted that, while his office had received the names of\nindividuals that the Rapid Support Forces contended were part of an investigative committee,\nno information had been transferred from the Rapid Support Forces to his office in relation\nto either allegations against the Rapid Support Forces or allegations regarding the Sudanese\nArmed Forces.29"},{"id":"a-hrc-57-23-p0104","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"104","seq":106,"section":"C. Accountability mechanisms in areas controlled by the Rapid Support","text":"The fact-finding mission has received allegations indicating the establishment by the\nRapid Support Forces of their own administration in areas under their control, including a\nfield court under the head of administration to address criminal activities. The fact-finding\nmission has not been able to obtain further information on these mechanisms, including any\nof their activities, which seem to have had no discernible impact on violations by the Rapid\nSupport Forces and their allied militias. The fact-finding mission is concerned that these\n25 Attorney General of the Sudan, statement to the Human Rights Council at its fifty-sixth session,\nGeneva, 18 June 2024.\n26 See A/HRC/55/G/2.\n27 See S/PV.9697.\n28 A/HRC/55/29, para. 96.\n29 See S/PV.9538.\ncourts have been set up outside of the framework of the law and therefore lack any legal basis\nand the necessary fair trial guarantees."},{"id":"a-hrc-57-23-p0105","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"105","seq":107,"section":"IX. Options for accountability and access to justice for victims","text":"For permanent peace to be maintained in the Sudan, there is a need for accountability.\nThe fact-finding mission considers that only a comprehensive transitional justice process\nwith appropriately endowed mechanisms can address the impunity and justice gaps in the\nSudan and provide remedies and reparation for victims. In this context, the 2023 updated\nGuidance Note of the Secretary-General on Transitional Justice and the 2019 African Union\nTransitional Justice Policy Framework are highly relevant to the current situation. These\npolicy documents incorporate the four pillars of transitional justice: justice, truth, reparation\nand guarantees of non-repetition."},{"id":"a-hrc-57-23-p0106","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"106","seq":108,"section":"IX. Options for accountability and access to justice for victims","text":"With regard to the first pillar, justice, one mechanism already in place is the continuing\njurisdiction of the International Criminal Court over crimes committed in Darfur since 1 July\n2002. The role of the Court remains crucial, particularly in the light of the decades of\nprevailing impunity. Since the Security Council referral, the Court has issued seven arrest\nwarrants. The trial against one individual, Ali Muhammad Ali Abd-Al-Rahman, who was\ntransferred to the Court on 9 June 2020, is ongoing. In one case the charges were not\nconfirmed and another case was terminated following the death of the suspect. Four suspects,\nincluding the former President Mr. Al-Bashir, remain at large. The Prosecutor of the\nInternational Criminal Court indicated on 5 August 2024 that the Sudan had responded to\nsome requests for assistance, while others remained pending.30 With the spread of the conflict\nto most of the Sudan, the Court’s jurisdiction should now be expanded to cover the entire\ncountry."},{"id":"a-hrc-57-23-p0107","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"107","seq":109,"section":"IX. Options for accountability and access to justice for victims","text":"Moreover, and since the International Criminal Court focuses on a few cases involving\nthose most responsible for international crimes, other pathways to justice should also be\nexplored to ensure accountability by perpetrators at all levels. Different options could be\nconsidered, from fully international to hybrid and internationalized judicial mechanisms.\nStates are encouraged to use universal jurisdiction to pursue individuals suspected of having\ncommitted international crimes."},{"id":"a-hrc-57-23-p0108","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"108","seq":110,"section":"IX. Options for accountability and access to justice for victims","text":"The root causes of the violations that have been chronically hampering the Sudan from\nrespecting, protecting and fulfilling the human rights of its people must be thoroughly\nidentified and fully addressed. This could be achieved through a genuine truth-seeking\nprocess to address the scale of violations committed and their impact on individuals and\ncommunities. Truth commissions can be established alongside the proposed judicial\nmechanism to enhance national dialogue, with the ability to refer cases to the judicial\nmechanism as appropriate. To foster a culture of accountability, such a commission should\nnot be endowed with the power to provide immunity or amnesty to those responsible for\ninternational crimes."},{"id":"a-hrc-57-23-p0109","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"109","seq":111,"section":"IX. Options for accountability and access to justice for victims","text":"Reparation for serious violations of human rights and international humanitarian law,\nincluding through restitution, compensation, rehabilitation, satisfaction and guarantees of\nnon-repetition, as outlined in the Basic Principles and Guidelines on the Right to a Remedy\nand Reparation for Victims of Gross Violations of International Human Rights Law and\nSerious Violations of International Humanitarian Law, is critical to help victims, survivors,\nfamilies and communities overcome the devastating impact of the violence. The fact-finding\nmission has heard from Sudanese civil society, human rights defenders, activists, survivors,\nwitnesses and the legal community about the overwhelming and immediate need for\nassistance to victims and survivors of the conflict in the Sudan within the country and those\ndisplaced. A dedicated entity should be established for those purposes.\n30   See S/PV.9697."},{"id":"a-hrc-57-23-p0110","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"110","seq":112,"section":"X. Conclusions and recommendations","text":"The Sudan is in turmoil and its people within and outside the country are\nexperiencing immense suffering. The fact-finding mission concludes that the Sudanese\nArmed Forces and the Rapid Support Forces, and their allied militias, are responsible\nfor large-scale violations of human rights and international humanitarian law. Many of\nthese violations amount to international crimes."},{"id":"a-hrc-57-23-p0111","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"111","seq":113,"section":"X. Conclusions and recommendations","text":"The fact-finding mission finds that there are reasonable grounds to believe that\nthe Sudanese Armed Forces and their allied militias have committed the war crimes of\nviolence to life and person, in particular murder of all kinds, mutilation, cruel treatment\nand torture and committing outrages upon personal dignity, in particular, humiliating\nand degrading treatment."},{"id":"a-hrc-57-23-p0112","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"112","seq":114,"section":"X. Conclusions and recommendations","text":"The fact-finding mission finds that there are reasonable grounds to believe that\nthe Rapid Support Forces and their allied militias have committed the war crimes of\nviolence to life and person, in particular murder of all kinds, mutilation, cruel treatment\nand torture, committing outrages upon personal dignity, rape, sexual slavery and any\nform of indecent assault, pillage, conscripting or enlisting children under the age of 15\nor using them to participate actively in hostilities, intentionally directing attacks against\nthe civilian population, intentionally directing attacks against persons and objects\ninvolved in humanitarian assistance and other specially protected objects and ordering\nthe displacement of the civilian population for reasons related to the conflict. The\nfact-finding mission also finds that there are reasonable grounds to believe that the\nRapid Support Forces has committed the crimes against humanity of murder, torture,\nenslavement, rape, sexual slavery and acts of a sexual nature of comparable gravity,\npersecution on the basis of intersecting ethnic and gender grounds in connection with\nthe foregoing acts and forcible displacement of population. The fact-finding mission,\ntherefore, makes the recommendations set out below."},{"id":"a-hrc-57-23-p0113","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"113","seq":115,"section":"X. Conclusions and recommendations","text":"Sudanese people have endured much pain. Their suffering must stop, and their\nhuman rights must be protected. This cannot be done without ending the fighting. All\nefforts must be invested in reaching a sustainable ceasefire that would also enable the\neffective delivery of much-needed humanitarian assistance. Concerned by the rampant\nfood insecurity in various parts of the Sudan and starvation, the fact-finding mission\nnotes the agreement on opening the Adré border crossing with Chad as a step in the\nright direction. It applauds the various efforts to bring the parties to the negotiating\ntable and urges any agreement reached, including a permanent cessation of hostilities,\nto take the findings and recommendations of this report into account."},{"id":"a-hrc-57-23-p0114","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"114","seq":116,"section":"X. Conclusions and recommendations","text":"Given the failure of the parties to protect civilians so far, the fact-finding mission\nrecommends the deployment of an independent and impartial force with a mandate to\nprotect civilians in Sudan. The protection of civilians is paramount, and the parties\nmust comply with their obligations under international law. The Sudanese Armed\nForces and the Rapid Support Forces and their respective allied militias must refrain\nfrom directing attacks against civilians or civilian objects, pillage and looting of\nproperty and committing outrages upon personal dignity, torture, rape and other forms\nof sexual violence, and recruitment and use of children. Ethnically motivated attacks\nmust end. Commanders must issue explicit and detailed instructions to their forces and\nallied militias to refrain from unlawful acts, also in line with their commitments under\nthe Jeddah Declaration. They must effectively investigate all violations and bring the\nperpetrators to justice."},{"id":"a-hrc-57-23-p0115","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"115","seq":117,"section":"X. Conclusions and recommendations","text":"The fact-finding mission considers that fighting will stop once the arms flow\nstops. Therefore, all States and entities must comply with the existing arms embargo in\nDarfur pursuant to Security Council resolution 1556 (2004) and subsequent resolutions.\nThis embargo should be expanded to cover the entire country. The supply of weapons,\nammunition and other logistical or financial support to any of the warring parties must\nend immediately as there is a risk that those supplying arms may be complicit in grave\nviolations of human rights and humanitarian law. Businesses and private actors active\nin the Sudan must respect the Guiding Principles on Business and Human Rights."},{"id":"a-hrc-57-23-p0116","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"116","seq":118,"section":"X. Conclusions and recommendations","text":"Forcible displacement must end and the communities that host refugees should\nbe supported. The fact-finding mission applauds the generosity of host communities,\nincluding in the Central African Republic, Chad, Egypt, Ethiopia, Kenya, South Sudan\nand Uganda. It calls upon the international community to increase its financial and\nother support for Sudanese refugees and their host communities, who themselves face\ndesperate humanitarian situations."},{"id":"a-hrc-57-23-p0117","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"117","seq":119,"section":"X. Conclusions and recommendations","text":"Rape and other forms of sexual violence must end. Women and youth should be\nenabled to meaningfully participate in any peace negotiations or initiatives, in line with\nSecurity Council resolution 1325 (2000), to ensure that they take into account their lived\nexperiences and address their concerns. Recruitment and use of children must end, and\nchildren must be protected."},{"id":"a-hrc-57-23-p0118","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"118","seq":120,"section":"X. Conclusions and recommendations","text":"The impunity gap in the Sudan is among the key root causes of decades of\ncontinued violations. The fact-finding mission recommends that the Security Council\nexpand the jurisdiction of the International Criminal Court to cover the entire territory\nof the Sudan. It urges the Sudan to cooperate with the Court through the surrender to\nit of all indicted persons, including the former President Mr. Al-Bashir."},{"id":"a-hrc-57-23-p0119","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"119","seq":121,"section":"X. Conclusions and recommendations","text":"To fully address accountability and to provide justice to victims, a path towards\na comprehensive approach to transitional justice must be pursued based on inclusive\ndialogue and genuine consultations. The establishment of a separate international\njudicial mechanism working in tandem and complementarity with the International\nCriminal Court, as well as a truth commission and a victim support and reparation\noffice, should urgently be considered."},{"id":"a-hrc-57-23-p0120","rec_id":"recLRvyVbuv1l48E2","symbol":"A/HRC/57/23","n":"120","seq":122,"section":"X. Conclusions and recommendations","text":"The Sudan has a diverse population, endowed with ample resources. Its people\ndeserve to live in peace and prosperity. Many Sudanese with whom the fact-finding\nmission spoke with stressed their wish to live in a peaceful, inclusive and human\nrights-oriented Sudan. They spoke of a representative and participatory government,\nencompassing all communities, where the equal rights of all citizens are respected,\nirrespective of their race, ethnicity, gender or economic status. This aspiration must be\nsupported by the international community charting the way towards equality, justice\nand sustainable peace."},{"id":"a-hrc-60-22-u0000","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":null,"seq":0,"section":null,"text":"Human Rights Council\nSixtieth session\n8 September–3 October 2025\nAgenda item 2\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General","unnumbered":true},{"id":"a-hrc-60-22-u0001","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":null,"seq":1,"section":null,"text":"Summary\nThis report documents attacks on civilians and objects essential for their survival in\nSudan. It concludes that both parties to the conflict violated international human rights and\nhumanitarian law, with most violations amounting to war crimes. The Rapid Support Forces’\nconduct may also constitute crimes against humanity, including persecution and\nextermination. The report calls for accountability and sets out a roadmap for justice.","unnumbered":true},{"id":"a-hrc-60-22-p0001","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"1","seq":2,"section":"I. Mandate","text":"The Independent International Fact-Finding Mission for the Sudan submits this report\npursuant to Human Rights Council resolutions 54/2 and 57/2. It focuses on the impact of the\nconflict on the civilian population and critical infrastructure and describes atrocities\ndocumented during the reporting period. It should be read in conjunction with its previous\nreports. It will be followed by a Conference Room Paper.1"},{"id":"a-hrc-60-22-p0002","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"2","seq":3,"section":"I. Mandate","text":"The Mission is composed of three independent experts: Mohamed Chande Othman\n(Tanzania) - chairperson, Joy Ngozi Ezeilo (Nigeria) and Mona Rishmawi (Palestine, Jordan\nand Switzerland). It is supported by a secretariat whose capacity is approximately 40 per cent\ndue to the United Nations liquidity crisis."},{"id":"a-hrc-60-22-p0003","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"3","seq":4,"section":"A. Methodology","text":"The standard of proof applied by the Mission is that of “reasonable grounds to believe”.\nThe phrase “the Mission finds” is used when this standard is met."},{"id":"a-hrc-60-22-p0004","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"4","seq":5,"section":"A. Methodology","text":"All information gathered by the Mission is subjected to rigorous verification and\ncorroboration, and open-source materials undergo authentication processes. Requests for\ncooperation by judicial and other entities are processed in line with applicable policies and\nprocedures, and subject to victim or witness informed consent."},{"id":"a-hrc-60-22-p0005","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"5","seq":6,"section":"A. Methodology","text":"The Mission travelled to Ethiopia (10 to 14 December 2024), Uganda (1 to 18\nDecember 2024), Chad (1 to 18 April 2025) and Kenya (20-22 February; 26-31 May 2025)."},{"id":"a-hrc-60-22-p0006","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"6","seq":7,"section":"A. Methodology","text":"The Mission conducted a total of 257 interviews (120 men; 137 women) between\nOctober 2024 and July 2025. Of these 199 were conducted in person and 58 remotely. It held\nover 50 meetings and consultations with victims and survivors, affected communities, civil\nsociety, other stakeholders and experts."},{"id":"a-hrc-60-22-p0007","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"7","seq":8,"section":"A. Methodology","text":"The Mission verified 43 videos and geolocated 8 attacks. It reviewed information\nreceived from 147 individuals and 32 civil society organizations following the issuance of a\ncall for submissions. It also reviewed reports from public sources, including United Nations,\nregional and international bodies and non-governmental organizations."},{"id":"a-hrc-60-22-p0008","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"8","seq":9,"section":"A. Methodology","text":"In February 2025, the Mission observed the ongoing trial before the District Court of\nStockholm, Sweden, against two former executives of the company Lundin Oil, accused of\ncomplicity in serious human rights violations and war crimes in Sudan."},{"id":"a-hrc-60-22-p0009","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"9","seq":10,"section":"A. Methodology","text":"From 28 to 30 May 2025, it organised a consultation on accountability in Nairobi,\nKenya, with the support of the Kenya Section of the International Commission of Jurists."},{"id":"a-hrc-60-22-p0010","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"10","seq":11,"section":"B. Cooperation","text":"The Mission sent five notes verbales to the Permanent Mission of the Republic of\nSudan in Geneva. On 27 November 2024 with reference to earlier correspondence, it renewed\nits request to visit Sudan and to meet with officials. On 19 February 2025, it reiterated this\nrequest. On 2 July, it wrote to the civilian Prime Minister, requesting a meeting and a visit to\nSudan. On 28 July, it shared questions on allegations of violations of human rights and\ninternational humanitarian law, also requesting a meeting. On 22 August, it shared a draft of\nthis report for comments. All communications remained unanswered."},{"id":"a-hrc-60-22-p0011","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"11","seq":12,"section":"B. Cooperation","text":"The Mission wrote to the Rapid Support Forces on 14 July 2025 requesting a meeting.\nOn 29 July it reiterated its request and shared questions on allegations of violations of human\nrights and international humanitarian law. No response was received."},{"id":"a-hrc-60-22-p0012","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"12","seq":13,"section":"B. Cooperation","text":"The Mission also sent notes verbales to neighbouring States requesting access to the\nSudanese communities. It is grateful to Chad, Ethiopia, Kenya, and Uganda which provided\nvisas."},{"id":"a-hrc-60-22-p0013","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"13","seq":14,"section":"B. Cooperation","text":"In December 2024, the Mission met with African Union officials in Ethiopia,\nincluding members of its Peace and Security Council. It met with the diplomatic corps,\nIntergovernmental Authority on Development, and United Nations."},{"id":"a-hrc-60-22-p0014","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"14","seq":15,"section":"B. Cooperation","text":"The Mission deepened its collaboration with the African Union Special Envoy on the\nPrevention of Genocide and Other Mass Atrocities and the Joint Fact-Finding Mission on\nSudan of the African Commission on Human and Peoples' Rights and the African Union."},{"id":"a-hrc-60-22-p0015","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"15","seq":16,"section":"B. Cooperation","text":"The Mission engaged with representatives of the European Union, the European\nParliament and diplomats in Brussels, Belgium, and participated in events related to its\nmandate in Germany, Kenya, Switzerland, and the United Kingdom."},{"id":"a-hrc-60-22-p0016","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"16","seq":17,"section":"B. Cooperation","text":"The Mission established cooperation with judicial and other entities, including the\nInternational Criminal Court."},{"id":"a-hrc-60-22-p0017","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"17","seq":18,"section":"III. Legal developments","text":"The legal framework applicable to Sudan was outlined in Mission reports. The\nMission classified the conflict starting in mid-April 2023 as a non-international armed\nconflict with the Sudanese Armed Forces and the Rapid Support Forces as its main parties.\nTogether with their allies, they are bound by international human rights law, article 3\ncommon to the 1949 Geneva Conventions and by Additional Protocol II of 1977, to which\nSudan is a party, and customary international law. The parties signed the Jeddah Declaration,\nwhich, despite repeated calls for its full implementation, remains unimplemented."},{"id":"a-hrc-60-22-p0018","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"18","seq":19,"section":"III. Legal developments","text":"International humanitarian law imposes obligations on third States. Article 1 common\nto the Geneva Conventions requires all High Contracting Parties to respect and ensure respect\nfor international humanitarian law. States must not only ensure respect by their own armed\nforces, but also by other groups or persons acting on their behalf and the population as a\nwhole. All States must refrain from providing aid or assistance to the commission of\nviolations, and work actively to ensure compliance with international humanitarian law."},{"id":"a-hrc-60-22-p0019","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"19","seq":20,"section":"III. Legal developments","text":"Resolutions adopted by the United Nations Security Council are binding. The arms\nembargo and sanctions regime related to Darfur under Security Council resolution 1556\n(2004) and subsequent resolutions were extended for one year by resolution 2750 (2024).\nTargeted sanctions were imposed on several Sudanese individuals and companies affiliated\nto the Sudanese Armed Forces and the Rapid Support Forces, including by the Security\nCouncil 1591 Sanctions Committee, Canada, European Union, United Kingdom and the\nUnited States."},{"id":"a-hrc-60-22-p0020","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"20","seq":21,"section":"III. Legal developments","text":"Sudan instituted proceedings at the International Court of Justice under the\nConvention on the Prevention and Punishment of the Crime of Genocide against the United\nArab Emirates. It requested the Court to issue provisional measures ordering the United Arab\nEmirates to, inter alia, refrain from any conduct amounting to complicity in genocide by the\nRapid Support Forces. The Court upheld the United Arab Emirates’ reservation to the\nConvention, concluding that it lacked jurisdiction to adjudicate the case."},{"id":"a-hrc-60-22-p0021","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"21","seq":22,"section":"III. Legal developments","text":"In January and July 2025, the Office of the Prosecutor of the International Criminal\nCourt reiterated it had reasonable grounds to believe that international crimes continue to be\ncommitted in Darfur. It announced that steps were being taken to request arrest warrants. In\nDecember 2024, closing arguments were delivered in the trial of Mr. Ali Muhammad Ali\nAbd-Al-Rahman. All other suspects remain at large, including former President Omar Al\nBashir."},{"id":"a-hrc-60-22-p0022","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"22","seq":23,"section":"III. Legal developments","text":"Accountability efforts are ongoing within several domestic jurisdictions. In the United\nKingdom, a war crimes dossier concerning the Rapid Support Forces and international\ncomplicity was submitted to the relevant authorities. In the United States, legal proceedings\nwere initiated against BNP Paribas, accused of violating sanctions and assisting Sudan's\nGovernment in committing international crimes between 1997 and 2011. In Sweden, the\nlandmark trial against two former Lundin Oil executives for complicity in war crimes\nbetween 1999 and 2003 is ongoing, highlighting control over resources as a root cause of\nSudan's recurring conflicts."},{"id":"a-hrc-60-22-p0023","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"23","seq":24,"section":"IV. Main findings","text":"As the conflict in Sudan intensifies, parties not only failed to protect civilians and\ncritical infrastructure, but rendered civilians primary targets. The Mission documented\nwidespread violence against individuals and communities, including killings, mass\ndisplacement, detention, enforced disappearance, and sexual violence. Civilian infrastructure\nsuffered extensive damage, with medical centres, schools, markets, food production systems,\nelectricity stations, and displacement camps under attack."},{"id":"a-hrc-60-22-p0024","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"24","seq":25,"section":"A. Violations against life and personal integrity","text":"The Mission finds that both warring parties and allies targeted civilians. Civilians and\nindividuals taking no active part in hostilities were killed and injured through shelling and\nattacks on displacement camps, checkpoints, roads, and convoys, as well as retaliatory\nassaults based on perceived allegiances. They also faced torture, arbitrary detention and\nsexual violence."},{"id":"a-hrc-60-22-p0025","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"25","seq":26,"section":"1. Attacks on civilians","text":"From the beginning of the siege by the Rapid Support Forces of El Fasher in May\n2024, El Fasher and surrounding areas were repeatedly shelled by both warring parties. Over\n470,000 persons have been displaced from El Fasher city and its surroundings, including\nfrom Shagra, Zamzam and Abu Shouk displacement camps."},{"id":"a-hrc-60-22-p0026","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"26","seq":27,"section":"1. Attacks on civilians","text":"The Abu Shouk displacement camp, north of El Fasher, has become a target of\nshelling by the Rapid Support Forces since mid-July 2024 and intensified in 2025. Between\n20 January and 31 March, multiple artillery strikes killed over 80 persons, injured others, and\ncaused severe damage to property, triggering displacement. On 10 April 2025, the Rapid\nSupport Forces intensified its shelling on Abu Shouk when shelling occurred almost daily,\nkilling dozens of civilians and causing massive damage. Overall, more than 300 people have\nreportedly been killed in Abu Shouk. Most civilians in the camp were from non-Arab\ncommunities."},{"id":"a-hrc-60-22-p0027","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"27","seq":28,"section":"1. Attacks on civilians","text":"Since May 2024, the Zamzam displacement camp, south of El Fasher, was also\nregularly shelled by the Rapid Support Forces. The Rapid Support Forces associate certain\ncommunities, particularly the Zaghawa, with the joint forces allied to the Sudanese Armed\nForces which are present in the area. One witness noted: \"They burned everything. They\nclaimed they only wanted to fight soldiers, but they punished the whole community. It felt\nlike they wanted to remove us because of who we are.\" Shelling intensified by late 2024 and\nparticularly on 11 and 12 February 2025, when the Rapid Support Forces stormed the camp.\nAt least 30 persons were killed and 21 injured. Property was looted."},{"id":"a-hrc-60-22-p0028","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"28","seq":29,"section":"1. Attacks on civilians","text":"From 11 to 13 April 2025, the Rapid Support Forces and allies launched a large-scale\nground offensive on the camp. A large military convoy entered the camp, firing randomly,\nkilling and injuring many. Members or perceived associates of the Sudanese Armed Forces\nand the Joint Forces were summarily executed. Estimates of the number of persons killed\nrange from 300 to 1500, with over 157 wounded. the majority women and children. By the\ntime the Rapid Support Forces took control, parts of the camp were burned, and all facilities\nwere destroyed. Over 400,000 inhabitants, about 81 per cent of the camp's population, were\nagain displaced, with many fleeing towards Tawilah or back to El Fasher."},{"id":"a-hrc-60-22-p0029","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"29","seq":30,"section":"1. Attacks on civilians","text":"The Rapid Support Forces also attacked civilian convoys. In mid-January 2025, the\nRapid Support Forces attacked a convoy of 42 to 60 vehicles close to the Chadian border.\nThey were largely from non-Arab communities fleeing from Tawilah to Tine in Chad. The\nconvoy had been assured safe passage through areas under control of the Rapid Support\nForces and was escorted by neutral forces. At a checkpoint at the entrance of Kabkabiya, it\nwas ordered to stop. Members of the Rapid Support Forces and affiliates surrounded the\nvehicles and opened fire on the convoy. The sudden attack caused panic. Civilians attempted\nto escape, but at least 30 were killed. Others were captured, detained and subjected to physical\nassaults until their families paid ransom."},{"id":"a-hrc-60-22-p0030","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"30","seq":31,"section":"1. Attacks on civilians","text":"On the road or at checkpoints as they were fleeing, many civilians, including children,\nwere killed, beaten, robbed, and subjected to racial slurs by the Rapid Support Forces. The\nmain victim groups of these attacks were the non-Arab communities Zaghawa, Fur, Masalit\nand Tunjur.\nFindings"},{"id":"a-hrc-60-22-p0031","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"31","seq":32,"section":"1. Attacks on civilians","text":"The Mission finds that the Rapid Support Forces and allies continued coordinated,\nlarge-scale attacks on civilians as part of a deliberate policy targeting non-Arab communities.\nThese operations, some involving large scale killings and forced displacement, constitute\nserious violations of international humanitarian law, intersecting with the prohibition of\nadverse distinction based on race or ethnicity, including violence to life and person,\nintentionally directing attacks against civilians, terrorizing populations and forcing civilian\ndisplacement. They also violate international human rights law, particularly the rights to life\nand non-discrimination."},{"id":"a-hrc-60-22-p0032","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"32","seq":33,"section":"1. Attacks on civilians","text":"The Mission finds that acts carried out by the Rapid Support Forces, occurring in the\ncontext of and directly linked to the non-international armed conflict, amount to war crimes,\nincluding violence to life and person, in particular murder, intentionally directing attacks\nagainst civilians, and forcing displacement of civilians. Given its widespread and systematic\ncharacter and the existence of an underlying policy, the Mission finds that the Rapid Support\nForces also committed crimes against humanity, notably murder, torture, forced\ndisplacement, persecution on ethnic grounds, and other inhumane acts."},{"id":"a-hrc-60-22-p0033","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"33","seq":34,"section":"2. Reprisals","text":"The Mission finds that civilians were targeted by both parties and their respective\nallies, because of their real or perceived affiliation with the opposite side.\nRapid Support Forces and allies"},{"id":"a-hrc-60-22-p0034","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"34","seq":35,"section":"2. Reprisals","text":"In early October 2024, after the Joint Forces allied to the Sudanese Armed Forces\nattacked and captured a base of the Rapid Support Forces in Bir Maza, North Darfur, The\nRapid Support Forces and allies attacked Kutum locality, targeting several villages between\nKutum town and Anka, perceived as sympathetic to the Sudanese Armed Forces. Towns and\nvillages, including Breidik, Bir Maza, and Anka, were looted and burned. By late November\n2024, an estimated 4,630 households had been displaced from Kutum locality. Over 50\nindividuals were killed, primarily from Zaghawa and Tunjur communities."},{"id":"a-hrc-60-22-p0035","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"35","seq":36,"section":"2. Reprisals","text":"Following the defection of Commander Abu Aqla Keikel and his Sudan Shield Forces\nfrom the Rapid Support Forces to the Sudanese Armed Forces on 20 October 2024, the Rapid\nSupport Forces launched attacks in Keikel’s stronghold in East Gezira. Over 30 towns and\nvillages including Tamboul, Rufaa, al Sireha and al-Hilaliya, were targeted. Witnesses\nreported extra-judicial killings, beatings, widespread looting and rape. The Rapid Support\nForces entered Tamboul in vehicles and on motorbikes, shooting at residents with heavy\nmachine guns, entering houses, beating and insulting residents for the perceived celebration\nof Keikel’s defection. By November 2024, the Rapid Support Forces reportedly killed\nhundreds including 80 in al Sireha alone. Over 130,000 people fled their homes.\nSudanese Armed Forces and allies"},{"id":"a-hrc-60-22-p0036","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"36","seq":37,"section":"2. Reprisals","text":"After the Sudanese Armed Forces and their allies recaptured Gezira in January 2025,\nreprisals targeted particularly the Kanabi community, that it accused of siding with the Rapid\nSupport Forces. From 9 to 12 January 2025, the Sudan Shield Forces attacked several Kanabi\nvillages, including Tayba and Dar al-Salam al-Hideba. They arrived in armed vehicles,\nshooting and killing unarmed civilians, burning homes, and looting property and livestock.\nIn Tayba alone, at least 26 individuals, including a child, were killed. Perpetrators used racial\nslurs against victims such as “abeed” (slaves) and “gharaba” (foreigners). In Dar al-Salam\nal-Hideba, at least 16 individuals were killed and many houses looted and burned. Some\nremain missing. Most residents were forced to flee and were prevented from returning to their\nvillage."},{"id":"a-hrc-60-22-p0037","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"37","seq":38,"section":"2. Reprisals","text":"During the retaking of Wad Madani, between 12 and 25 January 2025, videos verified\nby the Mission show individuals in army fatigues beating a civilian on crutches. Another man\nwas beaten, thrown from a bridge and then shot. Other videos show individuals beaten while\naccused of supporting the Rapid Support Forces. Some perpetrators appeared in Baraa bin\nMalik Brigade uniforms. One perpetrator can be heard saying \"this is in revenge for all our\nmartyrs\"."},{"id":"a-hrc-60-22-p0038","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"38","seq":39,"section":"2. Reprisals","text":"Verified videos also document violent reprisals by the Sudanese Armed Forces and\ntheir allies while advancing towards and recapturing Khartoum, Omdurman and Bahri. They\nshow men in uniforms of the Sudanese Armed Forces or allied forces beating and killing\nindividuals in civilian clothes, accused of being members of the Rapid Support Forces. One\nvideo, dated 8 January 2025, shows individuals in army uniforms in Umbada, south\nOmdurman, beating a man in civilian clothes while saying \"This guy is Rapid Support Forces\nand Kafir-infidel\" before shooting and killing him. Another video, dated 19 February 2025,\nshows several detained men blindfolded and tied together while soldiers beat them with sticks\nwhile chanting slurs for supporting the Rapid Support Forces. On 25 March 2025, also in\nUmbada, six individuals in army uniforms are seen dragging an injured young man in civilian\nclothes and then shooting him. A man in civilian clothes decapitated the body with a knife\nand held the victim's head, while others chanted \"Allahu Akbar\". On 27 March 2025, two\nindividuals in army uniforms publicly executed an individual in civilian clothes for suspected\ncollaboration with the Rapid Support Forces on Siteen street, Al Jereif West, Khartoum."},{"id":"a-hrc-60-22-p0039","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"39","seq":40,"section":"2. Reprisals","text":"The Mission received credible reports that it continues to investigate, of similar\ntargeting by the Sudanese Armed Forces and allies of the Arab Rizeigat community in Sennar\nbased on their perceived allegiance with the Rapid Support Forces.\nFindings"},{"id":"a-hrc-60-22-p0040","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"40","seq":41,"section":"2. Reprisals","text":"The Mission finds that the parties, and their allies, carried out large-scale attacks\nagainst civilians in North Darfur, Gezira and/or Khartoum. Civilians were deliberately\ntargeted based on their ethnicity and/or perceived affiliation with the opposing side. The\nMission documented killings, some at a large scale, executions, and injuring of civilians.\nThese acts constitute serious international humanitarian law violations intersecting with the\nprohibition of adverse distinction based on race or ethnicity, including violence to life and\nperson, outrages upon personal dignity, intentionally directing attacks against civilians, and\nmeasures designed to terrorize populations."},{"id":"a-hrc-60-22-p0041","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"41","seq":42,"section":"2. Reprisals","text":"The Mission recorded collective punishment, reprisals, and conflict-related\ndisplacement. The Sudanese Armed Forces, in some cases with civilian involvement, were\nresponsible for desecration of the dead and exposing victims to public curiosity. Executions\nof civilians or persons hors de combat without judicial guarantees violate international\nhumanitarian law. The Mission finds that these practices also violate international human\nrights law, including the rights to life, liberty, security of person, freedom from torture, non-\ndiscrimination, and guarantees of fair trial and due process."},{"id":"a-hrc-60-22-p0042","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"42","seq":43,"section":"2. Reprisals","text":"Accordingly, the Mission finds that both parties committed war crimes, including\nviolence to life and person, intentionally directing attacks against civilians, or persons hors\nde combat, collective punishment or reprisals against civilians, and forced displacement of\ncivilians."},{"id":"a-hrc-60-22-p0043","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"43","seq":44,"section":"2. Reprisals","text":"It also finds that the Sudanese Armed Forces perpetrated the war crimes of carrying\nout executions without previous judgement or judicial guarantees and outrages on personal\ndignity by desecration of the dead. The Rapid Support Forces also committed crimes against\nhumanity, in particular murder, persecution on ethnic grounds, forced displacement, and\nother inhumane acts."},{"id":"a-hrc-60-22-p0044","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"44","seq":45,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"The Mission finds that both parties detained individuals arbitrarily without charge or\nlegal process, and subjected them to torture, inhumane and degrading treatment, and\ninhumane conditions.\nRapid Support Forces"},{"id":"a-hrc-60-22-p0045","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"45","seq":46,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"The Rapid Support Forces detained civilians in Darfur, Khartoum and other parts of\nSudan under its control in military bases, police stations, prisons, and civilian infrastructure\nthat were converted into detention facilities."},{"id":"a-hrc-60-22-p0046","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"46","seq":47,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Most detainees were arrested at their homes or checkpoints. They were held\nincommunicado without access to legal representation or communication with, or visits by\ntheir families. None were charged nor appeared before a court."},{"id":"a-hrc-60-22-p0047","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"47","seq":48,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Guards of the Rapid Support Forces subjected them to severe beatings with whips.\nOne interviewee stated he was beaten, whipped, and drenched with cold water for several\nhours until he lost consciousness. The beating continued for three days."},{"id":"a-hrc-60-22-p0048","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"48","seq":49,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Detainees were held in crowded facilities without access to adequate food and\nsanitation or medical care, including in Soba prison in Khartoum and central prison in\nZalingei. Those detained in Soba Prison described it as a ”slaughterhouse” stating that\nbetween June and October 2024, at least 50 detainees died due to torture, malnutrition and\nlack of medical care. Some were forced to work in construction or prepare meals for the\nguards."},{"id":"a-hrc-60-22-p0049","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"49","seq":50,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Families of some detainees had to pay ransom to secure their release. One witness,\nheld near Nyala between February and August 2024, stated a guard told him he could 'buy\nhis freedom'. He managed to relate a message to his wife who paid around 500,000 Sudanese\npounds (833 USD) for his release. He was threatened with consequences if he disclosed being\nheld by the Rapid Support Forces."},{"id":"a-hrc-60-22-p0050","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"50","seq":51,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Guards of the Rapid Support Forces executed detainees, including seven detainees in\na military base of the Rapid Support Forces in North Darfur in May 2024. Verified videos\ndepict armed men wearing Rapid Support Forces uniforms beating a large group of\napproximately 15 to 25 male detainees with sticks and whips and then shooting them in Salha,\nOmdurman, on or around 27 April 2025.\nSudanese Armed Forces"},{"id":"a-hrc-60-22-p0051","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"51","seq":52,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Arrests carried by the Sudanese Armed Forces were mainly based on suspicion of\ncollaboration with the Rapid Support Forces. In areas retaken by the Sudanese Armed Forces\nor at army checkpoints, many who lived under control of the Rapid Support Forces were\nstopped, beaten and detained for alleged association with the Rapid Support Forces. Former\ndetainees reported their incommunicado detention and the lack of due process and judicial\noversight. Only one of them appeared before a judge, which led to his release following more\nthan two months of detention."},{"id":"a-hrc-60-22-p0052","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"52","seq":53,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Individuals recounted horrific details while in detention facilities of the Sudanese\nArmed Forces. In military intelligence facilities in Sinja, Sennar, in May 2024 detainees\nwere beaten with water pipes while tied. In the White Nile military base, daily beatings with\nsticks, whips, punches, and kicks also took place."},{"id":"a-hrc-60-22-p0053","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"53","seq":54,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"In Serkab prison in Karari, Omdurman, a victim was hit with a hammer upon arrival.\nHe was interrogated about his connections with the Rapid Support Forces while being forced\nto sit naked on a metal chair, with weights attached to his genitals, while two masked men\nadministered electric shocks. Another victim, arrested in El Fasher in April 2025, was beaten\nby six soldiers for denying collaboration with the Rapid Support Forces. He was later held in\nsolitary confinement for 20 days before being released."},{"id":"a-hrc-60-22-p0054","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"54","seq":55,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Witnesses also reported the lack of adequate food, sanitation and medical care in army\ndetention facilities. For instance, in Serkab prison, some prisoners slept standing due to the\novercrowded cells.\nFindings"},{"id":"a-hrc-60-22-p0055","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"55","seq":56,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"The Mission finds that both parties arbitrarily arrested and detained civilians,\nsubjecting them to inhumane conditions and severe physical and mental suffering for\npurposes of intimidation, coercion, punishment, or discrimination. The Rapid Support Forces\ncarried out executions and caused deaths in detention. These acts constitute serious\ninternational humanitarian law violations, including violence to life and person and outrages\nupon dignity, as well as violations of international human rights law, notably the prohibitions\nof torture and other cruel, inhuman or degrading treatment or punishment, and the rights to\nlife, liberty, security, health, and adequate food."},{"id":"a-hrc-60-22-p0056","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"56","seq":57,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"The Mission finds that the Rapid Support Forces forced detainees into labour, or\ndemanded ransom for their release, amounting to hostage-taking and forced labour practices\nin violation of both international humanitarian law and international human rights law."},{"id":"a-hrc-60-22-p0057","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"57","seq":58,"section":"3. Arbitrary detention, torture and inhumane treatment","text":"Accordingly, the Mission finds that both parties perpetrated war crimes, including\nviolence to life and person, in particular murder, mutilation, cruel treatment and torture, and\noutrages upon personal dignity. The Rapid Support Forces also perpetrated the war crimes of\nmurder and hostage-taking. Given its widespread and systematic character, the acts of the\nRapid Support Forces may also amount to crimes against humanity, including imprisonment\nor severe deprivation of liberty, requiring further investigation."},{"id":"a-hrc-60-22-p0058","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"58","seq":59,"section":"4. Sexual and gender-based violence","text":"The Mission received an overwhelming volume of information and evidence on\nsexual violence, including rape, gang rape, forced nudity, abduction, sexual slavery and\nforced marriage. Members of the Rapid Support Forces were identified as the primary\nperpetrators, but members of the Sudanese Armed Forces were also implicated. While\npredominantly directed at women and girls, some victims were men and boys.\nRapid Support Forces"},{"id":"a-hrc-60-22-p0059","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"59","seq":60,"section":"4. Sexual and gender-based violence","text":"The Rapid Support Forces used sexual violence as a deliberate tactic to humiliate and\nsubjugate women, girls, and entire communities. Such violence is rooted in racism, prejudice\nand extreme cruelty, and violence has become a defining feature of the conflict. It is enabled\nby widespread impunity."},{"id":"a-hrc-60-22-p0060","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"60","seq":61,"section":"4. Sexual and gender-based violence","text":"Sexual violence occurred throughout Sudan’s conflict zones including Bahri, El\nFasher, Gezira, Khartoum, Kordofan, Kornoi, Nyala, Omdurman and Zamzam. It took place\nin streets, public squares, homes, abandoned buildings, and forested areas. In some incidents,\nmultiple perpetrators in Rapid Support Forces uniforms raped women and girls. In June 2025,\none survivor fleeing from El Fasher was stopped at a checkpoint of the Rapid Support Forces\nbetween Shagra and Tawilah. She was taken to an abandoned building, along with several\nother women and girls aged 15 to17, where they were all raped. Some raped women were\nvisibly pregnant while others became pregnant as a result."},{"id":"a-hrc-60-22-p0061","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"61","seq":62,"section":"4. Sexual and gender-based violence","text":"Forced nudity was also documented, particularly in Khartoum and Gezira. Girls were\nreportedly stripped at checkpoints manned by the Rapid Support Forces under the pretext of\nbeing searched. A male victim reported being forced to remain naked for three consecutive\ndays while detained by the Rapid Support Forces in Khartoum."},{"id":"a-hrc-60-22-p0062","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"62","seq":63,"section":"4. Sexual and gender-based violence","text":"The Rapid Support Forces systematically carried out abductions in areas under their\ncontrol for sexual exploitation purposes. This violence was especially prevalent between May\n2023 and February 2025 in North and South Darfur and Khartoum. In El Fasher, in April\n2024, two sisters and three girls were abducted from their house, blindfolded and taken to a\nRapid Support Forces camp where they were repeatedly raped over three days. Witnesses\nreported women and girls being forced into Rapid Support Forces vehicles. Many are\nreported missing. There are allegations, requiring further investigation, of the Rapid Support\nForces trafficking and selling women and girls. One interviewee saw 28 young women with\ntheir hands tied being brought by the Rapid Support Forces to the Al-Daman hotel in Nyala\nin May 2023, allegedly to be sold."},{"id":"a-hrc-60-22-p0063","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"63","seq":64,"section":"4. Sexual and gender-based violence","text":"Forced marriage is another form of gender-based violence. It has been documented\nparticularly in Khartoum and Gezira between May 2023 and December 2024. Members of\nthe Rapid Support Forces appear to have coerced families, often during home raids, into\n“marrying” off girls as young as 12. The coercion included killing or injuring family\nmembers, or threats of such violence."},{"id":"a-hrc-60-22-p0064","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"64","seq":65,"section":"4. Sexual and gender-based violence","text":"Sexual violence often has an ethnic dimension. The Rapid Support Forces mostly\ntargeted women and girls belonging to non-Arab communities in North Darfur, including the\nZaghawa and Fur, often associating them with the Joint Forces allied to the Sudanese Armed\nForces. Racial slurs were used to dehumanize victims. In some cases, perpetrators apparently\nstated that rape was intended to “improve” the victims’ race. Information was also received\nabout children born out of rape and that many such children have been abandoned or remain\nundocumented. More investigation is needed in this area."},{"id":"a-hrc-60-22-p0065","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"65","seq":66,"section":"4. Sexual and gender-based violence","text":"The persistence and recurrence of violent sexual acts across multiple regions and\ntime frames indicate a systemic pattern. Access to medical and psychological services for\nsurvivors of sexual violence remains limited mainly due to the collapse of the healthcare\nsystem within Sudan and decreased support in displacement. Many women and girls only\nsought help after fleeing to neighbouring countries.\nSudanese Armed Forces"},{"id":"a-hrc-60-22-p0066","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"66","seq":67,"section":"4. Sexual and gender-based violence","text":"The Mission received evidence that members of the Sudanese Armed Forces\ncommitted sexual violence in White Nile, Blue Nile, Khartoum and Northern State.\nDocumented incidents include rape, sexual harassment, and sexualized torture of women and\nmen, particularly during detention or while fleeing. An example is the case of a man detained\nfor months by the Sudanese Armed Forces in Khartoum in 2024 and subjected to sexualized\ntorture, including electrocution to his genitals, mentioned earlier."},{"id":"a-hrc-60-22-p0067","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"67","seq":68,"section":"4. Sexual and gender-based violence","text":"The Mission continues to investigate rape and other forms of sexual violence by the\nSudanese Armed Forces. These violations appear to be underreported for fear of retaliation\nand perceived sympathy towards the Sudanese Armed Forces in some areas.\nFindings"},{"id":"a-hrc-60-22-p0068","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"68","seq":69,"section":"4. Sexual and gender-based violence","text":"The Mission finds that the Rapid Support Forces continued large-scale rape and other\nforms of sexual and gender-based violence against women and girls, often targeting victims\nbased on their combined gender and ethnic identity. These acts, including forced nudity of\nmen in detention, constitute serious violations of international humanitarian law, intersecting\nwith the prohibition of adverse distinction, including violence to life and person (in particular\ncruel treatment and torture), outrages upon personal dignity, in particular rape and indecent\nassault, and adverse distinction, as well as collective punishment on intersecting gender and\nethnic grounds."},{"id":"a-hrc-60-22-p0069","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"69","seq":70,"section":"4. Sexual and gender-based violence","text":"Under international human rights law, this conduct violates the rights of victims,\nincluding children and family members who witnessed the violence, to be free from torture\nand other cruel, inhuman or degrading treatment to physical and mental health, including\nreproductive rights, and to non-discrimination. The Mission confirmed a pattern of\ndeprivation of liberty, including forced marriage of women and children for sexual purposes,\nwhere perpetrators appear to exercise ownership over the victims, amounting to sexual\nslavery."},{"id":"a-hrc-60-22-p0070","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"70","seq":71,"section":"4. Sexual and gender-based violence","text":"Accordingly, the Mission finds that the Rapid Support Forces committed war crimes,\nincluding violence to life and person, outrages upon personal dignity, rape and sexual slavery.\nThe Mission finds that this conduct formed part of a widespread and systematic attack against\ncivilians and constitutes crimes against humanity, including torture, enslavement, rape,\nsexual slavery and comparable sexual violence, persecution on intersecting ethnic and gender\ngrounds, and other inhumane acts."},{"id":"a-hrc-60-22-p0071","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"71","seq":72,"section":"B. Attacks on Civilian Infrastructure","text":"The Mission has documented a consistent pattern of attacks on civilian infrastructure\nand objects indispensable to the survival of the civilian population. Hospitals, markets, water\nsources and electricity systems were damaged. These attacks have had a devastating impact\non civilians, denying them access to healthcare, food, clean water and shelter. Food insecurity\nincreased due to the inability of farmers to reach their fields, and because seeds were not\ndistributed due to the conflict."},{"id":"a-hrc-60-22-p0072","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"72","seq":73,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Rapid Support Forces and their allies systematically targeted civilians and civilian\nobjects, including dwellings, markets, shops and food sources, as well as critical\ninfrastructure, including water and electricity systems, across Sudan. Ground operations were\naccompanied by widespread looting, including of personal items, livestock, warehouses,\ngenerators, solar panels, and water pumps."},{"id":"a-hrc-60-22-p0073","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"73","seq":74,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Rapid Support Forces repeatedly shelled civilian neighbourhoods in areas under\nthe control of the Sudanese Armed Forces in the southern and western parts of El Fasher city,\nmostly inhabited by non-Arab communities, destroying homes and infrastructure, and killing\nmany civilians in houses, hospitals, markets and streets. In particular, the al-Wahda and al-\nThawra neighbourhoods were targeted and destroyed. Shelling intensified towards late 2024\nuntil today, damaging residential areas and houses. The Rapid Support Forces also launched\nground attacks on several El Fasher neighbourhoods, as well as nearby villages and towns,\nincluding Borush on 25 January 2025, and Shagra on 27 February, killing civilians, and\ndestroying and looting property. Shagra was burned down."},{"id":"a-hrc-60-22-p0074","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"74","seq":75,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Rapid Support Forces also struck markets. On 23 September 2024, shelling by\nthe Rapid Support Forces struck Sabreen Market in Karari, Omdurman, killing at least 15\ncivilians. A second attack on 1 February 2025 on the same market killed 54 to 60 civilians\nand wounded about 158. In North Darfur, particularly in and around El Fasher, repeated\nshelling of local markets, including the Al Mawashi livestock market on 3–4 July 2024 and\n26 September 2024, jointly killing over 40 civilians damaged the livestock market and\nlivelihoods. In the Abu Shouk displacement camp, the Rapid Support Forces repeatedly\nshelled the market, including in August, November and December 2024, in January, on 5\nMarch, 18 May and 4 June 2025, killing and injuring civilians, and damaging food stalls and\nsupplies."},{"id":"a-hrc-60-22-p0075","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"75","seq":76,"section":"1. Attacks on food systems and other critical infrastructure","text":"In North Darfur, ground attacks launched by the Rapid Support Forces were\ndocumented in 2024 and 2025, including on Zamzam, Abu Zeriga, Um Hejalij, Tabit, and\nDar al-Salaam. In October and November 2024, attacks by the Rapid Support Forces on\nKutum, Breidik, Bir Maza and Anka led to markets and surrounding homes set ablaze,\nwidespread looting, and villages burned. On 11–12 February 2025, during assaults on\nZamzam displacement camp, the Rapid Support Forces and allies burned large parts of the\nmarket and looted food, livestock, and vehicles. Individuals bringing food into the camp were\nalso targeted: some were killed, while others were robbed of their goods. These recurring\noperations destroyed essential trading infrastructure and hampered access to vital goods."},{"id":"a-hrc-60-22-p0076","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"76","seq":77,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Rapid Support Forces attacked Sudan’s electricity infrastructure. Early April\n2025, drone strikes launched by the Rapid Support Forces hit the Merowe Dam power station,\ndisrupting supply across northern Sudan. On 14 May, drone strikes destroyed several power\nstations in Omdurman, causing widespread blackouts. El Fasher’s grid has been a frequent\ntarget, with repeated strikes causing prolonged interruptions to electricity and internet\nservices."},{"id":"a-hrc-60-22-p0077","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"77","seq":78,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Rapid Support Forces targeted water infrastructure, particularly around El Fasher.\nLate May 2024, it briefly seized the Golo water reservoir, El Fasher’s primary water source,\nand shut down pumps. In February 2025, the Rapid Support Forces damaged water facilities\nand supply lines in Shagra, exacerbating El Fasher's water shortages. Attacks by the Rapid\nSupport Forces on Abu Shouk and Zamzam displacement camps further disrupted access to\nsafe water; by mid-2025, many local water towers and pumps were destroyed or non-\nfunctional."},{"id":"a-hrc-60-22-p0078","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"78","seq":79,"section":"1. Attacks on food systems and other critical infrastructure","text":"Farmland and crops were also violently grazed, destroyed or burned by the Rapid\nSupport Forces and allies. Between 31 March and 15 April 2024, Berka and eight other\nvillages and surrounding agricultural land, west of El Fasher, were subjected to arson and\ndestruction. Crops were also forcibly grazed in Mahajirya, East Darfur in late 2024.\nSudanese Armed Forces"},{"id":"a-hrc-60-22-p0079","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"79","seq":80,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Sudanese Armed Forces destroyed civilian property and infrastructure,\nparticularly through shelling and airstrikes on areas held by the Rapid Support Forces."},{"id":"a-hrc-60-22-p0080","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"80","seq":81,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Sudanese Armed Forces frequently conducted attacks on civilian\nneighbourhoods, particularly in East El Fasher, killing and injuring civilians, and damaging\ntheir houses and property. As civilians began to flee, the Rapid Support Forces occupied\nhouses and schools, resulting in the Sudanese Armed Forces shelling entire residential areas,\ncausing extensive casualties and widespread damage to civilian property and infrastructure.\nOne witness described how, in October 2024, his house was hit by an airstrike, killing his\nsiblings."},{"id":"a-hrc-60-22-p0081","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"81","seq":82,"section":"1. Attacks on food systems and other critical infrastructure","text":"Markets across North Darfur have suffered deadly airstrikes of the Sudanese Armed\nForces. On 4 October 2024, airstrikes launched by the Sudanese Armed Forces on El Koma\nmarket near El Fasher reportedly killed at least 45 civilians, including 13 children, and injured\nhundreds. The entire market was engulfed in flames and destroyed. Multiple surrounding\nstructures, including health facilities and water sources, were also damaged. El Koma market\nwas struck again on 1 June 2025, killing dozens of civilians."},{"id":"a-hrc-60-22-p0082","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"82","seq":83,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Sudanese Armed Forces also struck the market and wells in nearby Mellit\nmultiple times after the Rapid Support Forces took control of it, including on 26 April 2024,\nwhen the water wells were hit, thereby killing hundreds of camels, and 2 September, when\nthe Al-Aish market was hit, killing 14 persons, severely disrupting trade activities and food\naccess. On 9 December 2024, a strike on the Kabkabiya market killed over 100 civilians.\nVerified videos show the market destroyed with damaged buildings, burned shops, smoke,\nand wounded civilians being pulled from under the rubble by other civilians."},{"id":"a-hrc-60-22-p0083","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"83","seq":84,"section":"1. Attacks on food systems and other critical infrastructure","text":"On 24 March 2025, the Sudanese Armed Forces bombed the Tora market, north of El\nFasher, during peak hours, setting fire to the market, livestock, cattle and people, killing and\ninjuring hundreds of civilians, largely women and children, and many animals, and\ndestroying numerous livestock. the Sudanese Armed Forces reportedly using imprecise barrel\nbombs. The consequences were catastrophic, as Tora was among the last accessible food\nsources in the area."},{"id":"a-hrc-60-22-p0084","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"84","seq":85,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Sudanese Armed Forces also hit markets in other parts of Sudan, including the\nFur Market in Al-Hasahisa, Gezira, on 7 October 2024, killing over 100 civilians.\nFindings"},{"id":"a-hrc-60-22-p0085","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"85","seq":86,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Mission finds that the Rapid Support Forces and their allies engaged in large-\nscale looting, pillage, and destruction of objects essential to civilian survival, including the\nburning of camps and towns. These acts deprived civilians of food, water, and housing,\nviolating international humanitarian law and economic, social, and cultural rights."},{"id":"a-hrc-60-22-p0086","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"86","seq":87,"section":"1. Attacks on food systems and other critical infrastructure","text":"It finds that both parties failed to take sufficient measures to minimize the impact of\nairstrikes and artillery on civilians and civilian infrastructure, including markets.\nIndiscriminate attacks risking civilian lives violate international humanitarian law and human\nrights law as well as international criminal law."},{"id":"a-hrc-60-22-p0087","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"87","seq":88,"section":"1. Attacks on food systems and other critical infrastructure","text":"The Mission finds that the Rapid Support Forces and their allies perpetrated war\ncrimes, including pillage and intentionally directing attacks against civilians. Combined with\nthe denial of humanitarian relief supplies, they also committed the war crime of intentionally\nusing starvation as a method of warfare by depriving the civilian population of objects\nindispensable to their survival. These acts may also constitute crimes against humanity,\nincluding persecution on ethnic and political grounds, forced displacement, and other\ninhumane acts and contributing to extermination."},{"id":"a-hrc-60-22-p0088","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"88","seq":89,"section":"2. Attacks on medical facilities","text":"The Mission finds that attacks on, or in the vicinity of medical infrastructure by both\nparties caused the near-total collapse of the healthcare system across Sudan."},{"id":"a-hrc-60-22-p0089","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"89","seq":90,"section":"2. Attacks on medical facilities","text":"The World Health Organisation (WHO) and other organisations documented several\nhundred attacks on health care infrastructure since the beginning of the conflict. The Office\nfor the Coordination of Humanitarian Affairs, reported that as of 30 June 2025, less than 25\nper cent of the health facilities remained operational in the worst-affected areas. Over half of\nthe reported attacks occurred during the siege of El Fasher. By March 2025, the Office for\nthe Coordination of Humanitarian Affairs reported that over 200 health facilities in El Fasher\nwere no longer operational. The destruction of these essential services has left civilians\nwithout access to urgent care. More than 20 million people are in need of health care, amid\nescalating medical needs due to injury, malnutrition, and disease.\nRapid Support Forces"},{"id":"a-hrc-60-22-p0090","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"90","seq":91,"section":"2. Attacks on medical facilities","text":"The Rapid Support Forces carried out large-scale and systematic attacks on medical\nfacilities across Sudan, including Gezira, Khartoum and North Darfur, attacking hospitals,\nlooting medical supplies, and killing medical care professionals, leading to widespread\nclosures, death, and the collapse of healthcare provision."},{"id":"a-hrc-60-22-p0091","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"91","seq":92,"section":"2. Attacks on medical facilities","text":"Around El Fasher, in particular, attacks on health infrastructure escalated from May\n2024. Al Janoubi Hospital in southern El Fasher, which was one of the last two surgical-\ncapacity facilities, was repeatedly attacked from 25 May until 8 June, killing several\nindividuals."},{"id":"a-hrc-60-22-p0092","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"92","seq":93,"section":"2. Attacks on medical facilities","text":"On 8 June 2024, fighters of the Rapid Support Forces entered the hospital, opening\nfire on staff and patients, looting medical supplies and taking an ambulance. Family members\nattempting to evacuate patients were shot at. This attack led to the closure of the hospital."},{"id":"a-hrc-60-22-p0093","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"93","seq":94,"section":"2. Attacks on medical facilities","text":"Al-Saudi Maternal Teaching Hospital, in western El Fasher, was also repeatedly\nshelled. From March 2024 onwards, artillery shelling damaged the facility and injured\ncivilians. On 19 May, the maternity ward was struck; on 21 June, the shelling killed a\npharmacist and four others; on 27 June, an attack damaged the pharmacy and water tanks.\nAdditional attacks on 29 July killed three and injured 25. On 11 August, another attack killed\none person, injured five and damaged the surgical ward. Between October and December\n2024, continued strikes caused severe structural damage to the hospital and more casualties.\nOn 24 January 2025, a drone strike launched by the Rapid Support Forces killed over 70\npeople and destroyed its emergency and surgical wards, rendering the hospital non-\noperational."},{"id":"a-hrc-60-22-p0094","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"94","seq":95,"section":"2. Attacks on medical facilities","text":"Smaller clinics in and around El Fasher were forced to close due to destruction,\ninsecurity, or looting. Patients often required transfer amidst dangerous conditions as the\nRapid Support Forces increased control of roads."},{"id":"a-hrc-60-22-p0095","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"95","seq":96,"section":"2. Attacks on medical facilities","text":"In northern El Fasher, the Police Hospital was shelled in August 2024, injuring\ncivilians and destroying the facility, which was subsequently abandoned. In Baradik, the local\nclinic was burned down by the Rapid Support Forces in November 2024."},{"id":"a-hrc-60-22-p0096","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"96","seq":97,"section":"2. Attacks on medical facilities","text":"Medical infrastructure in displacement camps was similarly decimated. In Abu Shouk,\nall medical facilities, including a private clinic, an emergency volunteer unit, and a\nmalnutrition treatment centre, were destroyed in April and June 2024."},{"id":"a-hrc-60-22-p0097","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"97","seq":98,"section":"2. Attacks on medical facilities","text":"In February 2025, the Rapid Support Forces shelled and raided multiple hospitals in\nKhartoum, including the Al-Nau Hospital in Omdurman killing at least six civilians. In late\nNovember 2024, the Rapid Support Forces attacked Al-Hilaliya in Gezira, looting health\nfacilities, and threatening to kill health workers."},{"id":"a-hrc-60-22-p0098","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"98","seq":99,"section":"2. Attacks on medical facilities","text":"Medical personnel were directly targeted. Since the start of the conflict, at least 159\nhealth workers were reportedly attacked, while others were arrested. Most of these cases were\nattributed to the Rapid Support Forces. For example, one doctor was killed in his home in al\nThawra in El Fasher, and another was abducted to treat wounded fighters. In Kutum, the\nRapid Support Forces occupied the hospital and threatened staff, demanding preferential\ntreatment for their wounded fighters. On 24 December 2024 and 10 January 2025, during\npatient transfers to El Fasher, Médecins sans frontières (MSF) ambulance staff were shot at,\nforcing MSF to suspend operations. On 11 April 2025, fighters of the Rapid Support Forces\nshot and killed 11 International Relief clinic staff and injured several more in Zamzam.\nSudanese Armed Forces"},{"id":"a-hrc-60-22-p0099","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"99","seq":100,"section":"2. Attacks on medical facilities","text":"The Sudanese Armed Forces also launched attacks on hospitals or in their vicinity,\nincluding in Khartoum and North Darfur, with serious consequences. For example, on 11\nMay 2024, an airstrike landed roughly 50 meters from the Babiker Nahar Paediatric Hospital\nin El Fasher killing two children and a caregiver and injuring others. MSF had to suspend\noperations in what was one of the few children’s hospitals in the country. The facility was\neventually closed."},{"id":"a-hrc-60-22-p0100","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"100","seq":101,"section":"2. Attacks on medical facilities","text":"On 28 May 2024, airstrikes launched by the Sudanese Armed Forces caused fire to\nKutum Hospital in North Darfur, destroying the maternity ward and major infrastructure.\nSeveral patients and staff were killed or injured, and the hospital was rendered inoperable."},{"id":"a-hrc-60-22-p0101","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"101","seq":102,"section":"2. Attacks on medical facilities","text":"On 21 June 2025, the Sudanese Armed Forces bombed the Mujlad Referral Hospital\nin West Kordofan, killing at least 41 and wounding dozens more. The hospital remains only\npartially operational.\nFindings"},{"id":"a-hrc-60-22-p0102","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"102","seq":103,"section":"2. Attacks on medical facilities","text":"The Mission finds that the parties violated the protections afforded to medical\nfacilities and personnel. It finds that the Rapid Support Forces made medical units, transports,\nand the wounded and sick the object of attack and compelled medical staff to perform tasks\nof prioritise patients on non-medical grounds. These acts constitute prohibited acts under\ninternational humanitarian law and human rights law, including the rights to life and to\nphysical and mental health."},{"id":"a-hrc-60-22-p0103","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"103","seq":104,"section":"2. Attacks on medical facilities","text":"The Mission finds that the Sudanese Armed Forces failed to take sufficient measures\nto minimize the impact of airstrikes and artillery on civilians and civilian infrastructure,\nincluding hospitals and medical facilities. Indiscriminate attacks risking civilian lives violate\ninternational humanitarian law and human rights law as well as international criminal law."},{"id":"a-hrc-60-22-p0104","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"104","seq":105,"section":"2. Attacks on medical facilities","text":"The Mission further finds that the Rapid Support Forces perpetrated war crimes,\nincluding violence to life and person and intentionally directing attacks against hospitals and\nlocations where the wounded and sick are collected. Taken together with other findings, these\nacts may also constitute the war crime of intentionally directing attacks against civilians,\nforcing civilian displacement, the use of starvation as a method of warfare, as well as crimes\nagainst humanity, including persecution on ethnic grounds, forced displacement and\ncontributing to extermination."},{"id":"a-hrc-60-22-p0105","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"105","seq":106,"section":"3. Attacks on humanitarian workers and facilities","text":"Humanitarian workers and facilities were targeted or caught in the crossfire. Between\nApril 2023 and April 2025, more than 84 Sudanese humanitarian workers were reportedly\nkilled."},{"id":"a-hrc-60-22-p0106","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"106","seq":107,"section":"3. Attacks on humanitarian workers and facilities","text":"On 15 April 2023, several World Food Programme (WFP) staff members were killed\nfollowing clashes between the Rapid Support Forces and the Sudanese Armed Forces in\nKabkabiya. The Rapid Support Forces also looted WFP vehicles and cash intended for aid.\nOn 19 December 2024, three WFP workers were killed as a result of an aerial bombardment\nthat hit the WFP Field Office Compound in Yabus, Blue Nile State."},{"id":"a-hrc-60-22-p0107","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"107","seq":108,"section":"3. Attacks on humanitarian workers and facilities","text":"In May 2024, armed groups attacked a convoy of three vehicles marked with\nInternational Committee of the Red Cross (ICRC) emblem in Layba, East Jebel Marra, South\nDarfur, resulting in the killing of two ICRC drivers and injuring three other staff."},{"id":"a-hrc-60-22-p0108","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"108","seq":109,"section":"3. Attacks on humanitarian workers and facilities","text":"The Office for the Coordination of Humanitarian Affairs reported that a team of an\ninternational non-governmental organisation was abducted by armed men in June 2025 while\nvisiting Nertiti, in Central Darfur. The were released after a few days."},{"id":"a-hrc-60-22-p0109","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"109","seq":110,"section":"3. Attacks on humanitarian workers and facilities","text":"An alarming incident that the Mission continues to investigate concerns a drone attack\non a joint WFP and the UNICEF humanitarian convoy in the night of 2 June 2025. The\nconvoy was carrying food supplies for El Fasher, at El Koma in North Darfur. The attack\nkilled five humanitarian workers, injured several others and damaged life-saving\nhumanitarian supplies. According to WFP, the parties were aware of the whereabouts and\nroute of the convoy. The trucks were marked with WFP and UNICEF banners. The convoy\nhad been stopped in El Koma by the Rapid Support Forces, which controlled the area, and\nwas waiting for permission to proceed to El Fasher."},{"id":"a-hrc-60-22-p0110","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"110","seq":111,"section":"3. Attacks on humanitarian workers and facilities","text":"United Nations entities and international non-governmental organisations continue to\nface administrative challenges, which frustrate their operations, including delays in issuing\nvisas and travel authorizations. The Office for the Coordination of Humanitarian Affairs\nreported that in May 2025 only 110 visas were approved out of the of 355 pending visa\nrequests, while the backlog is increasing.\nFindings"},{"id":"a-hrc-60-22-p0111","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"111","seq":112,"section":"3. Attacks on humanitarian workers and facilities","text":"The Mission finds that attacks on humanitarian facilities, convoys, and workers, along\nwith imposed bureaucratic restrictions, significantly impeded humanitarian operations,\nresulting in the denial of humanitarian access, particularly as part of prohibited siege tactics\nof El Fasher and surrounding areas. Despite Security Council resolutions 2724 (2024) and\n2736 (2024) obliging parties to allow rapid, safe, and unhindered passage of humanitarian\nrelief, both parties continued actions contrary to their international humanitarian law\nobligations."},{"id":"a-hrc-60-22-p0112","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"112","seq":113,"section":"3. Attacks on humanitarian workers and facilities","text":"The Mission finds that these violations, together with intentionally directing attacks\non civilians and the destruction of objects indispensable to their survival, have contributed to\nfamine and starvation in and around El Fasher. It finds that the Rapid Support Forces, through\nthe siege of El Fasher and its surroundings, committed the war crime of intentionally using\nstarvation as a method of warfare by depriving civilians of objects indispensable to their\nsurvival, including wilfully impeding relief supplies. The combined effect of deprivation of\naccess to food and medicine and attack on and obstruction of humanitarian assistance by the\nRapid Support Forces may also amount to the crime against humanity of extermination."},{"id":"a-hrc-60-22-p0113","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"113","seq":114,"section":"4. Attacks on places of worship and culture","text":"The Mission received credible allegations of attacks on places of worship by both\nwarring parties and is planning additional investigations on this topic."},{"id":"a-hrc-60-22-p0114","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"114","seq":115,"section":"4. Attacks on places of worship and culture","text":"The Sudanese Armed Forces reportedly bombed the Sheikh El Jeili Mosque in Wad\nMadani in October 2024, and the Sheikh Elsidiq Mosque in Khartoum North in December\n2024. Later that same month, an airstrike launched by the Sudanese Armed Forces damaged\nthe Al Ezba Baptist Church, its nursery and residential buildings in Khartoum North."},{"id":"a-hrc-60-22-p0115","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"115","seq":116,"section":"4. Attacks on places of worship and culture","text":"In June 2025, the Rapid Support Forces reportedly shelled three Christian churches in\nEl Fasher. The Rapid Support Forces reportedly also looted churches and pressured\nChristians from the Nubian community to convert to Islam."},{"id":"a-hrc-60-22-p0116","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"116","seq":117,"section":"C. The socioeconomic toll","text":"The conflict has triggered one of Sudan’s worst humanitarian crises, marked by\nrelentless violence, destruction of infrastructure, collapse of food systems, and deliberate\nobstruction of aid, leaving civilians in acute peril."},{"id":"a-hrc-60-22-p0117","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"117","seq":118,"section":"C. The socioeconomic toll","text":"According to the Office of the United Nations High Commissioner for Refugees\n(UNHCR), the conflict caused the world’s fastest-growing displacement crisis. As of early\nJuly 2025, nearly 12.1 million persons have been forcibly displaced, of whom 7.6 million are\nwithin Sudan and 4.2 million in other countries."},{"id":"a-hrc-60-22-p0118","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"118","seq":119,"section":"C. The socioeconomic toll","text":"Disruptions to food supply chains and agricultural production, as well as delays and\nadministrative challenges in delivering aid have resulted in widespread hunger and\nmalnutrition, with some areas facing famine conditions. According to the WFP, Sudan is on\nthe brink of becoming the world’s most severe hunger emergency in recent history.\nApproximately 24.6 million, half of Sudan’s population, are experiencing acute food\ninsecurity. In the Zamzam and Abu Shouk camps the situation is particularly dire. The Rapid\nSupport Forces cut all critical food and water supplies in the camps. Witnesses described that\nin Zamzam, access to food and water deteriorated sharply by March 2025 and that basic items\nlike oil, lentils, sugar and water were scarce and unaffordable, leading to malnourishment,\ndehydration and death, in particular of children. Furthermore, witness recounted seeing\ncivilians dying in the streets from hunger while moving from one shelter to another."},{"id":"a-hrc-60-22-p0119","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"119","seq":120,"section":"C. The socioeconomic toll","text":"The Mission documented the devastating impact of the siege of the Rapid Support\nForces on El Fasher. The Rapid Support Forces severely restricted supply entry and targeted\nkey infrastructure, resulting in widespread food and water shortages. Lack of food and water\nis a leading cause of death. One witness reported that hunger was so severe she lost 20\nkilograms, and her daughter was hospitalized for malnutrition, where a two-year-old child\ndied from starvation."},{"id":"a-hrc-60-22-p0120","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"120","seq":121,"section":"C. The socioeconomic toll","text":"The conflict also left families and communities without economic means. The\ndestruction of infrastructure including roads, factories, and agricultural land has compounded\nthe challenges facing Sudan’s labour force. Businesses have shut down, supply chains are\nbroken, and millions have lost access to essential goods and services."},{"id":"a-hrc-60-22-p0121","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"121","seq":122,"section":"C. The socioeconomic toll","text":"Poverty levels have thus worsened significantly, with the proportion of the population\nliving on less than US$2.15 per day nearly doubling—from 33 per cent in 2022 to 71 per cent\nin 2024."},{"id":"a-hrc-60-22-p0122","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"122","seq":123,"section":"C. The socioeconomic toll","text":"The conflict also had a devastating impact on children. According to UNICEF, more\nthan six million children (27 per cent under the age of five) are internally displaced or seeking\nrefuge and protection in neighbouring countries. Over 770,000 children are expected to suffer\nfrom severe acute malnutrition in 2025, and over one in three children are already suffering\nfrom acute malnutrition, according to WFP."},{"id":"a-hrc-60-22-p0123","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"123","seq":124,"section":"V. Accountability","text":"The Mission reported on accountability measures in detail in its previous reports and\nwill expand it further in the Conference Room Paper."},{"id":"a-hrc-60-22-p0124","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"124","seq":125,"section":"VI. Domestic developments","text":"By June 2025, 120,594 cases were reportedly registered with the National Committee\nfor the Investigation of Crimes and Violations of National and International Humanitarian\nLaw, established by the Sudanese authorities, of which 3,997 were referred to regular courts\nwith 1,093 verdicts issued. While announcing further investigations and emergency courts to\ndeal with the Rapid Support Forces and its perceived collaborators, various officials\ncontinued to stress that the small number of cases against the Sudanese Armed Forces,\nconstituting 257 out of the total registered, reflected the isolated nature of violations by the\nSudanese Armed Forces, and that they did not constitute international crimes. Information\nand evidence of violations were denied without initiating credible investigations. Broad\nimmunities from prosecution provided to State forces were upheld and blanket amnesties\nwere offered to members of the Rapid Support Forces willing to report to the Sudanese\nArmed Forces, without excluding international crimes as required by international law."},{"id":"a-hrc-60-22-p0125","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"125","seq":126,"section":"VI. Domestic developments","text":"While promising to end impunity, the Rapid Support Forces deny responsibility for\nreported violations without indication of any credible investigations having been instituted.\nIt continued to set up investigative mechanisms and courts in areas under its control in the\nDarfur States. Little is known, however, about the legal basis, the composition or the current\nfunctioning of these courts."},{"id":"a-hrc-60-22-p0126","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"126","seq":127,"section":"VI. Domestic developments","text":"The Mission finds that Sudan remains unwilling and unable genuinely to conduct\nthorough, prompt and impartial investigations and prosecutions for international crimes\ncommitted in the current conflict. It reiterates its previous finding of selective justice, lack of\ntrust by victims and survivors in the domestic legal institutions given the historical pattern of\nuse of domestic laws and mechanisms to evade accountability, and the need for thorough\nlegal institutional reforms in the context of a democratic civilian rule."},{"id":"a-hrc-60-22-p0127","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"127","seq":128,"section":"B. Options for victim-centred accountability measures","text":"To effectively break the cycle of impunity, a range of options for delivering justice\nand ensuring accountability should be considered. Towards this end, the Mission organized\na three-day consultation in Nairobi. which offered a safe space for developing\nrecommendations on accountability measures, that the Mission will examine."},{"id":"a-hrc-60-22-p0128","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"128","seq":129,"section":"B. Options for victim-centred accountability measures","text":"Discussions considered lessons from past accountability and transitional justice\nexperiences in Sudan, sequencing between justice and peace, and options for future measures.\nIt was agreed that preparations for justice and accountability must begin immediately. The\noverarching principle of an all-inclusive Sudanese dialogue with a gender sensitive approach\nshould guide the design and implementation of any process."},{"id":"a-hrc-60-22-p0129","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"129","seq":130,"section":"B. Options for victim-centred accountability measures","text":"Different justice models were explored, including the modalities of expanding the\njurisdiction of the International Criminal Court to all of Sudan and the establishment of an\nindependent judicial mechanism working in tandem with the Court. It was noted that the 2020\nJuba Peace Agreement for Darfur includes an approach for transitional justice, including the\nidea of a hybrid special court. The use of universal jurisdiction was also stressed."},{"id":"a-hrc-60-22-p0130","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"130","seq":131,"section":"B. Options for victim-centred accountability measures","text":"It was stressed that professional documentation of violations and related crimes should\ncontinue as a tool for justice, including registers for specific violations, missing persons, and\ndamages, as well as training and capacity building. The Mission’s mandate of evidence\ncollection and preservation remains crucial."},{"id":"a-hrc-60-22-p0131","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"131","seq":132,"section":"B. Options for victim-centred accountability measures","text":"The consultation stressed the transformative role of reparations and distributive\njustice. Interim reparatory measures should be provided to victims, survivors and\ncommunities as priority."},{"id":"a-hrc-60-22-p0132","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"132","seq":133,"section":"VI. Conclusions and recommendations","text":"The Mission finds that both parties to the conflict violated international law,\namounting to international crimes. The Rapid Support Forces carried out large-scale\nand systematic attacks on civilians, constituting violations of international\nhumanitarian law and human rights, including large-scale killings, sexual and gender-\nbased violence, looting, and destruction of essential survival objects. These acts\nconstitute war crimes, including violence to life and person, outrages on personal\ndignity, intentionally directing attacks on civilians, hostage-taking, forced\ndisplacement, pillage and the use of starvation as a method of warfare. They also\nconstitute crimes against humanity, including murder, torture, rape, sexual slavery and\nsexual violence of comparable gravity, and persecution based on intersecting gender,\npolitical and ethnic grounds. The deprivation of food, medicine and humanitarian\nassistance may also amount to extermination."},{"id":"a-hrc-60-22-p0133","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"133","seq":134,"section":"VI. Conclusions and recommendations","text":"The Mission finds that the Sudanese Armed Forces committed violations of\ninternational humanitarian law and human rights, including direct attacks on civilians,\nindiscriminate airstrikes and artillery affecting populated areas and civilian\ninfrastructure, and failed to protect hospitals, medical personnel, and humanitarian\noperations. These acts amount to war crimes, including violence to life and person,\noutrages on personal dignity, carrying out executions without previous judgement or\njudicial guarantee, and attacks on specially protected objects."},{"id":"a-hrc-60-22-p0134","rec_id":"recB6EAjiAHMbgWF7","symbol":"A/HRC/60/22","n":"134","seq":135,"section":"VI. Conclusions and recommendations","text":"In light of continuing war of atrocities in Sudan and the need for accountability,\nthe Mission recommends the following roadmap:\nConflict Parties – Stop Violence and Protect Civilians\n(a)    Stop the fighting immediately and commit to a lasting peace, abide by\ninternational law obligations, Human Rights Council and Security Council resolutions\nand the Jeddah Declaration;\n(b)   Protect civilians, including by ending shelling of civilians and\ninfrastructure, reprisals, hate speech and ethnic targeting;\n(c)     Lift sieges, particularly on El Fasher and in Kordofan, and ensure\nunhindered humanitarian access; establish secure corridors for aid delivery and allow\nsafe civilian evacuation;\n(d)    Protect displaced communities by halting attacks on camps, preventing\nkillings, ensuring safe shelter, and safe routes for civilians out of active conflict zones;\n(e)     Safeguard cultural heritage by preventing looting and destruction of\nhistorical, religious, public and community sites;\n(f)    Stop sexual violence, sexual slavery, and forced marriage and end child\nuse in conflict;\n(g)   End impunity and ensure accountability, including by cooperating with\nthe Mission and the International Criminal Court, and surrendering all wanted\npersons.\nOther States and International Community – Support the People of Sudan Without\nFuelling Conflict\n(a)    Respect, enforce and expand the Security Council arms embargo and halt\nall material support to the parties, including via private actors and transit routes;\n(b)     Back durable peace efforts and stop interference that fuels instability and\ndeepens the illicit war economy;\n(c)    Support humanitarian needs, including by restoring medical assistance,\nresponding to disease outbreaks, and providing large-scale food support;\n(d)   Promote compliance with international humanitarian and human rights\nlaw through diplomatic, legal, and economic influence and enable independent and\nimpartial investigations by cooperating with the Mission and the International\nCriminal Court;\n(e)    Explore avenues for bringing the perpetrators to justice by expanding the\nInternational Criminal Court jurisdiction and supporting the establishment of an\nindependent and impartial judicial mechanism for Sudan;\n(f)   Suspend cooperation with those suspected of international crimes and\nbring them to justice in national courts through the exercise of universal jurisdiction;\nissue targeted sanctions against individuals and entities suspected of international\ncrimes;\n(g)    Fund victim support structures and interim reparatory measures.\nMediators – Drive Inclusive, Sustainable Peace\n(a)   Increase engagement to bring the parties to the table and secure a\nsustainable ceasefire;\n(b)   Address humanitarian priorities, including famine prevention, health\nsystem recovery and safe humanitarian access;\n(c)    Facilitate inclusive civilian participation in negotiations; ensure women’s\nrepresentation in line with Security Council Resolution 1325;\n(d)    Align with the Sudanese people’s aspirations for justice, stability and\nprosperity in the design of any peace process and embed justice in peace processes\nthrough a comprehensive approach to transitional justice and no amnesty for\ninternational crimes.\nCivil Society and Local Communities – Sustain Evidence and Build the Future\n(a)    Document violations and preserve evidence for accountability processes;\n(b)     Maintain community resilience and solidarity by supporting victims and\nsurvivors;\n(c)     Continue the commendable efforts toward building an inclusive,\ndemocratic, and human rights–oriented Sudan that works for all its people."},{"id":"a-hrc-60-crp-7-u0000","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":null,"seq":0,"section":null,"text":"This conference room paper presents the findings of the independent\ninternational fact-finding mission for the Sudan on accountability for international\ncrimes committed since mid-April 2023 in the conflict between the Sudanese Armed\nForces and Rapid Support Forces, and their respective allies. It assesses the Sudan’s\ndomestic capacity to deliver justice and explains the options for accountability for\ninternational crimes grounded in four pillars: the right to truth, right to justice, right\nto reparations and legal and institutional reforms. The paper emphasizes that all\naccountability efforts must be victim-centred, gender-sensitive, inclusive, and\nrooted in dialogue across Sudanese society. It urges all stakeholders, including\ninternational and regional organizations, third States and Sudanese civil society and\nlegal experts, to work together to end the cycle of impunity and ensure justice for all\nvictims and survivors.","unnumbered":true},{"id":"a-hrc-60-crp-7-p0001","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"1","seq":1,"section":"I. Introduction","text":"This conference room paper builds on Section V. Accountability of the report of\nthe independent international fact-finding mission for the Sudan to the Human Rights\nCouncil, (A/HRC/60/22) entitled “Sudan: a war of atrocities”. As Section V focuses\non accountability, this paper expands on that analysis and should be read in\nconjunction with the said report."},{"id":"a-hrc-60-crp-7-p0002","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"2","seq":2,"section":"I. Introduction","text":"In its previous reports and conference room paper, the mission highlighted the\nmyriads of serious violations of human rights and international humanitarian law that\nhave been committed by both sides since mid-April 2023 across the Sudan. It found\nreasonable grounds to believe that they amount to atrocity crimes and called for the\nimmediate implementation of accountability measures to halt the cycles of impunity\nand address the root causes of the many conflicts that have raged in the Sudan over\nthe years, including the current conflict.1"},{"id":"a-hrc-60-crp-7-p0003","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"3","seq":3,"section":"I. Introduction","text":"In particular, in its report Sudan: A War of Atrocities, the Mission found that both\nparties to the conflict violated international law, amounting to international crimes.\nThe Rapid Support Forces carried out large-scale and systematic attacks on civilians,\nconstituting violations of international humanitarian law and human rights, including\nlarge-scale killings, sexual and gender-based violence, looting, and destruction of\nessential survival objects. The Mission emphasized that these acts constitute war\ncrimes, including violence to life and person, outrages on personal dignity,\nintentionally directing attacks on civilians, hostage-taking, forced displacement,\npillage and the use of starvation as a method of warfare. They also constitute crimes\nagainst humanity, including murder, torture, rape, sexual slavery and sexual violence\nof comparable gravity, and persecution based on intersecting gender, political and\nethnic grounds. The deprivation of food, medicine and humanitarian assistance may\nalso amount to extermination."},{"id":"a-hrc-60-crp-7-p0004","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"4","seq":4,"section":"I. Introduction","text":"The Mission also found that the Sudanese Armed Forces committed violations of\ninternational humanitarian law and human rights, including directing attacks on\ncivilians, indiscriminate airstrikes and artillery affecting populated areas and civilian\ninfrastructure, and failed to protect hospitals, medical personnel, and humanitarian\noperations. The Mission stressed that these acts amount to war crimes, including\nviolence to life and person, outrages on personal dignity, carrying out executions\nwithout previous judgment or judicial guarantees, and attacks on specially protected\nobjects."},{"id":"a-hrc-60-crp-7-p0005","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"5","seq":5,"section":"I. Introduction","text":"Calls for immediate implementation of accountability measures to halt the cycles\nof impunity and address root causes have been consistently made in the context of the\nmany conflicts that have raged the Sudan over the years, including the current conflict.\nAgainst this background, the Mission seeks to elaborate on two aspects that were\ntouched on in the above-mentioned report: first, the ability of the Sudan’s domestic\nlegal system to ensure genuine accountability for international crimes; and, second,\nthe available accountability options to deliver justice for the people of the Sudan."},{"id":"a-hrc-60-crp-7-p0006","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"6","seq":6,"section":"I. Introduction","text":"The Mission reiterates its call to the parties to the conflict to respect and ensure\nrespect for international humanitarian law and human rights. They must combat\nimpunity and ensure justice and accountability for all violations and abuses, and\nrelated international crimes as well as provide remedies and reparations to victims and\nsurvivors. 2 Their actions must be in conformity with international law and\ninvestigations carried out promptly, thoroughly, independently and impartially and\nthose responsible prosecuted, tried and duly punished.3 Where domestic mechanisms\nare unable or unwilling to conduct effective investigations or prosecutions,\ninternational mechanisms alongside third States may – and should – exercise\nconcurrent jurisdiction to uphold victims’ human rights.4"},{"id":"a-hrc-60-crp-7-p0007","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"7","seq":7,"section":"A. Domestic investigations and prosecutions, and denial of","text":"Following the onset of the conflict, the Sudanese authorities set up investigative\nmechanisms and urged civilians to report crimes by the Rapid Support Forces and its\ncollaborators.5 By June 2025, the authorities reported that 120,594 individual cases\nhad been registered with the National Committee for the Investigation of Crimes and\nViolations of National and International Humanitarian Law.6 Of those, 3,997 had\nbeen referred to regular courts and 1,093 verdicts had been issued.7 By September\n2025, the total number according to the authorities rose to 131,706 registered cases,\nof which 4,985 had been referred to courts and 1,988 verdicts reached.8 647 cases had\nbeen dropped during the investigation phase.9 The National Committee also made\nrequests to six States for the extradition of 17 suspects in undisclosed cases.10"},{"id":"a-hrc-60-crp-7-p0008","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"8","seq":8,"section":"A. Domestic investigations and prosecutions, and denial of","text":"It is unknown how many of these cases registered by the National Committee\nconcern international crimes. As will be discussed further below, most cases appear\nto concern offences against the state under domestic law, including waging war\nagainst the state, rather than human rights and international humanitarian law\nviolations and related international crimes. In light of the ongoing retaliation against\nindividuals and communities for their actual or perceived association with the Rapid\nSupport Forces, the Mission is concerned that some of the individuals may be\narbitrarily detained for acts that do not constitute crimes under international law."},{"id":"a-hrc-60-crp-7-p0009","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"9","seq":9,"section":"A. Domestic investigations and prosecutions, and denial of","text":"Various Sudanese officials praised the work of the National Committee, referring\nto the Rapid Support Forces and their alleged collaborators in public statements as\n“remnants,” “filth” and “cancer”, calling for “cleansing”, “elimination” and\n“purification operations”, and stating the “hour of retribution would come”.11"},{"id":"a-hrc-60-crp-7-p0010","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"10","seq":10,"section":"A. Domestic investigations and prosecutions, and denial of","text":"In July 2025, Dr. Kamil Idris, two months after his appointment as the civilian\nPrime Minister, called on “all citizens, including lawyers and legal professionals, to\njoin forces and contribute to monitoring the militia's large-scale violations,” stressing\n“the need for justice to take its course, particularly in cases related to the war and the\n3\nE/CN.4/2005/102/ADD.1, Principle 19.\n4\nE/CN.4/2005/102/ADD.1, Principle 20.\n5\nSee also A/HRC/57/CRP.6, para. 296 onwards.\nviolations and crimes committed against citizens by the rebel Rapid Support Forces\n(RSF) militia.” 12"},{"id":"a-hrc-60-crp-7-p0011","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"11","seq":11,"section":"A. Domestic investigations and prosecutions, and denial of","text":"The authorities continued to stress publicly that the small number of cases\nregistered by the National Committee against the Sudanese Armed Forces,\nconstituting 257 of the total cases registered as of June and 366 as of September 2025,\nreflected the isolated nature of such violations and that they did not constitute\ninternational crimes.13 The Minister of Justice in particular stressed he would not\naccept “any report, statement, or letter that equates the National Institution of the\nArmed Forces, which is responsible for protecting the land and dignity of Sudanese\ncitizens, with the terrorist rebel militia with regard to human rights, considering such\nequality, in this regard, to be unfair and in violation of international conventions and\ntreaties that stipulate the country's sovereignty.”14 It was reported that, during a visit\nto Khartoum in August 2025 to assess the situation of judicial institutions, the\nMinister of Justice further praised the Sudanese Armed Forces for the sacrifices made\nin the “battle of dignity”, and confirmed he would continue to fight alongside them\n“until the last militia and mercenary in our country is eliminated”.15 This statement\nreflected language employed by other officials including General Al-Burhan\nconfirming the Sudanese Armed Forces were resolved to “decisively vanquish and\neliminate the rebel terrorist militia.”16"},{"id":"a-hrc-60-crp-7-p0012","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"12","seq":12,"section":"A. Domestic investigations and prosecutions, and denial of","text":"Information and evidence of violations and related crimes committed by the\nSudanese Armed Forces and allies were largely denied in public statements without\nthe initiation of credible investigations. For example, the authorities denied the use\nof arbitrary arrest and detention by the Sudanese Armed Forces, highlighting that the\nRapid Support Forces were rather responsible for detaining individuals in degrading\nconditions. 17 In relation to torture and ill-treatment, the authorities referred to an\nongoing criminal case that was registered against some members of the Sudanese\nArmed Forces in connection with allegations of acts of cruel, degrading or inhuman\ntreatment. 18 It reiterated, however, that none of the criminal cases filed against\nindividuals affiliated to the Sudanese Armed Forces concerned international crimes.19"},{"id":"a-hrc-60-crp-7-p0013","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"13","seq":13,"section":"A. Domestic investigations and prosecutions, and denial of","text":"Moreover, in June 2024, the Sudanese Armed Forces publicly denied\nresponsibility for violations and related crimes reported to have been committed by\nits own forces after a video appeared on social media depicting individuals believed\nto be affiliated with the Sudanese Armed Forces executing prisoners. The video\nshows a row of men lying face down on the floor with their hands tied behind their\nbacks while shots can be heard being fired in the background before their executions.\nThe armed men surrounding the detainees can be heard chanting “Allahu Akbar,\nthose are the mercenaries” and “we are only enforcing justice”.20 Instead, without an\nindication of any credible investigation having been completed, they blamed the\nRapid Support Forces and labelled them as fabricated.21"},{"id":"a-hrc-60-crp-7-p0014","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"14","seq":14,"section":"A. Domestic investigations and prosecutions, and denial of","text":"Broad immunities from prosecution provided to State forces were also upheld and\nblanket amnesties were offered to members of the Rapid Support Forces willing to\nreport to the Sudanese Armed Forces in violation of international law, as they do not\nexclude persons implicated in international crimes.22 On 20 June 2024, the General\nCommand of the Sudanese Armed Forces, following the defecting of Rapid Support\nForces Commander Abu Aqla Kaykal and a number of his Sudan Shield Forces to\nthe Sudanese Armed Forces, renewed “the amnesty of the head of the sovereignty\ncouncil and commander in chief of the armed forces to any rebel that sides with the\nnation and reports to the nearest army base in all parts of Sudan.” 23 While\ninternational humanitarian law requires the authorities in power to endeavour to grant\nat the end of hostilities the broadest possible amnesty to persons who have\nparticipated in the armed conflict, such amnesty should not be offered to those\nsuspected of having committed international crimes, which effectively shields them\nfrom investigation and prosecution.24"},{"id":"a-hrc-60-crp-7-p0015","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"15","seq":15,"section":"A. Domestic investigations and prosecutions, and denial of","text":"Further investigations and the set-up of emergency courts to deal with the Rapid\nSupport Forces and their supporters were announced. On 15 January 2025, the\nSudanese authorities set up an investigative committee into events in Tayba, Gezira.25\nThe Mission found that the attack on Tayba from 9 to 12 January 2025 claimed the\nlives of at least 26 individuals. 26 The investigation by the authorities reportedly\nresulted in the arrest of 5,000 individuals, and in the trial of some, accused of\ncollaborating with the Rapid Support Forces. 27 In Northern State, the authorities\nopened emergency courts in Dongola, Ad-Dabba, Halfa, and Merowe with a mandate\nto deal with criminal cases.28 In Port Sudan, they proceeded with an in-absentia trial\nbefore the Special Terrorism Court against the Rapid Support Forces leadership in\nrelation to the killing of Former Governor of West Darfur, Khamis Abkar, in El\nGeneina in June 2023.29 Official charges against 16 defendants, including General\nHemedti, were issued in absentia in August 2025, and included war crimes, crimes\nagainst humanity and genocide.30"},{"id":"a-hrc-60-crp-7-p0016","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"16","seq":16,"section":"A. Domestic investigations and prosecutions, and denial of","text":"The authorities also announced, on 11 July 2025, the formation of a national\ncommittee to investigate allegations of the use of chemical weapons. 31 On 27\nSeptember, in the context of the 60th session of the Human Rights Council, the Sudan\nRepresentative stated the committee had made progress, including conducting field\nsurveys and taking soil samples. The Sudan Representative also alleged that the civil\nsociety groups who referred to chemical weapons in their statements to the Council\nwere Rapid Support Forces supporters and threatened to take retaliatory action\nagainst them in the United Nations Economic and Social Council Committee on Non-\nGovernmental Organizations.32"},{"id":"a-hrc-60-crp-7-u0017","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":null,"seq":17,"section":"B. Unfair trials and death sentences violating international law","text":"22\nOHCHR, Rule-of-law tools for post-conflict states: Amnesties, 1 January 2009,\nhttps://www.ohchr.org/en/publications/policy-and-methodological-publications/rule-law-tools-post-conflict-states-\namnesties.\n23 https://suna-sd.net/posts/armed-forces-issues-press-release-on-kaykal-giving-up.\n24 Additional Protocol II, Article 6(5); Jean-Marie Henckaerts & Louise Doswald-Beck, Customary International","unnumbered":true},{"id":"a-hrc-60-crp-7-u0018","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":null,"seq":18,"section":"B. Unfair trials and death sentences violating international law","text":"Humanitarian Law, Volume II: Practice, International Committee of the Red Cross (ICRC), 2005, Rule 159.\n25 https://suna-sd.net/posts/tsc-president-issues-a-decision-forming-a-committee-to-investigate-the-events-that-took-place-","unnumbered":true},{"id":"a-hrc-60-crp-7-u0019","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":null,"seq":19,"section":"B. Unfair trials and death sentences violating international law","text":"in-taiba-camp-in-gezira-state.\n26 A/HRC/60/22, para. 36.\n27 https://suna-sd.net/posts/tsc-member-dr-salma-al-gezira-state-overcame-difficulties-and-completed-life-normalization.\n28 https://suna-sd.net/posts/head-of-northern-state-judiciary-issues-decisions-forming-emergency-courts-in-localities.\n29 https://suna-sd.net/posts/terrorism-court-for-the-killing-of-former-west-darfur-state-governor-continues-its-sessions-on-","unnumbered":true},{"id":"a-hrc-60-crp-7-u0020","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":null,"seq":20,"section":"B. Unfair trials and death sentences violating international law","text":"wali-khamis-abkar.\n31 https://suna-sd.net/posts/sudan-affirms-commitment-to-chemical-weapons-convention.\n32 60th Council session, 28th meeting, 25 September 2025; see also https://www.suna-sd.net/posts/sudans-delegate-in-","unnumbered":true},{"id":"a-hrc-60-crp-7-p0017","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"17","seq":21,"section":"B. Unfair trials and death sentences violating international law","text":"The Mission has continued to collect information and evidence, including court\nrecords, videos of trials, and direct testimonies, of cases brought against individuals\nsuspected of being affiliated with the Rapid Support Forces. Most cases against\ncivilians appear to be based on their alleged collaboration with the Rapid Support\nForces under articles 50 and 51 of the Criminal Act of 1991, which concern offences\nagainst the State. In particular, article 51(3), which prohibits ‘any type of support’ to\nwaging war against the State, has been subject to overly broad and non-uniform\ninterpretation. 33 This violates international human rights law which requires that\narrest and detention is based on substantive grounds that are not only prescribed by\nlaw but also sufficiently precise to avoid arbitrary interpretation or application.34 It\nalso has a chilling effect on the exercise of fundamental rights in Sudan, including\nonline and offline freedom of opinion and expression. Some of these cases have\nresulted in the imposition of death sentences for crimes that are not considered most\nserious under international law and hence further violate international human rights\nlaw, with more cases pending.35"},{"id":"a-hrc-60-crp-7-p0018","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"18","seq":22,"section":"B. Unfair trials and death sentences violating international law","text":"For example, in Port Sudan a man was arrested for having pictures linked to the\nRapid Support Forces on his phone. Following interrogation by the National\nCommittee he was charged under articles 26, 50 and 51 of the Criminal Act of 1991\nand in conjunction with article 27 of the Cybercrime Law of 2018. According to the\ncourt, under article 51a inciting war against the state applied to anyone who provided\nsupport in any way. It indicated that it was agreed that any support to the rebel Rapid\nSupport Militia amounted to the crime of provoking war against the State.\nAccordingly, the only questions that needed answering were if the defendant was a\nsupporter of the Rapid Support Forces and if the Rapid Support Forces provoked war\nagainst the state. The court answered these questions in the affirmative believing that\nthe defendant was waiting for the right opportunity to assist the Rapid Support Forces\nand sentenced him to 10 years in prison.36"},{"id":"a-hrc-60-crp-7-p0019","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"19","seq":23,"section":"B. Unfair trials and death sentences violating international law","text":"Punishments appeared to also be disproportionate to the crimes concerned. In\nRiver Nile State, for example, a man was sentenced to death by hanging for violating\narticles 50 and 51a of the Criminal Act of 1991 for having been mobilized by the RSF\nin Khartoum State and looting household items. The case revolved around a forced\nconfession obtained by the intelligence services from the defendant under torture.\nThe court dismissed these allegations and allowed the tainted statement into\nevidence.37 In another case, also from River Nile State, a woman was sentenced to\ndeath by hanging by a court for violating article 51 of the Criminal Act of 1991 for\nhaving provided support to the Rapid Support Forces because she worked at a\nmedical clinic that was headed by an individual who was affiliated to the Rapid\nSupport Forces.38 Moreover, in Northern state, two men who had just been acquitted\nby a court of charges concerning cooperation with the Rapid Support Forces, were\nre-arrested while barely released from prison without being informed of the reasons\nfor their new arrest or receiving information on the new charges brought against\nthem.39"},{"id":"a-hrc-60-crp-7-p0020","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"20","seq":24,"section":"B. Unfair trials and death sentences violating international law","text":"The Sudanese authorities specifically targeted political opponents, lawyers,\nhuman rights defenders and journalists, with women facing compounded risks.40 In\n33 See also A/HRC/58/29, paras. 91-92.\n34 CCPR/C/GC/35, para. 22, the Committee further noted in para. 12 that “An arrest or detention may be authorized by\ndomestic law and nonetheless be arbitrary. The notion of “arbitrariness” is not to be equated with “against the law”, but\nmust be interpreted more broadly to include elements of inappropriateness, injustice, lack of predictability and due\nprocess of law, as well as elements of reasonableness, necessity and proportionality”.\n35 See e.g. https://ishr.ch/latest-updates/sudan-over-25-women-facing-charges-that-could-lead-to-execution/.\n36 FFMS-D-003464.\n37 FFMS-D-003410.\n38 FFMS-D-003456.\n39 FFMS-D-004291; FFMS-D-004218.\n40 E.g. FFMS-D-004286; FFMS-D-004205; FFMS-D-003409; FFMS-D-004212; FFMS-D-004211; FFMS-D-004208;\nFFMS-D-002875; FFMS-D-003512; FFMS-D-002912; FFMS-D-002742; FFMS-D-002856.\none reported case, a journalist was arrested by the Sudanese Armed Forces in early\nDecember 2024 and accused him of collaborating with the Rapid Support Forces.\nShortly after his release, one month later, he died in hospital as a result of injuries\nsustained due to torture and ill-treatment in detention.41"},{"id":"a-hrc-60-crp-7-p0021","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"21","seq":25,"section":"B. Unfair trials and death sentences violating international law","text":"In another emblematic case, a human rights defender and the legal representative\nof the former Democratic Civil Forces (Taqaddum) Coordination Committee, which\nwas led by former Prime Minister Abdallah Hamdok and seen by the Sudanese\nauthorities as aligned with the Rapid Support Forces, was arrested on 4 September\n2024 and again on 7 September after inquiring about the charges filed against 17\nleaders of the Taqaddum Coordination Committee. Charges were filed against him\nunder article 53 of the Criminal Code of 1991 related to espionage and collaboration\nwith a foreign state or its agents, which may carry the death penalty. A court hearing\nwas reportedly held in April 2025. His case was widely reported on,42 and previously\nbrought to the attention of the Sudanese authorities by the United Nations Special\nProcedures.43 He was reported released on 20 October 2025.44"},{"id":"a-hrc-60-crp-7-p0022","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"22","seq":26,"section":"B. Unfair trials and death sentences violating international law","text":"The criminal charges filed by the National Committee against 17 leaders of the\nformer Taqaddum Coordination Committee, in early April 2024, include offences\nthat carry the death penalty such as inciting war against the state and undermining the\nconstitutional order under articles 50 and 51 of the Criminal Act of 1991, as well as\ninternational crimes under Chapter 18 of the 2009 amendment to the Criminal Act of\n1991. 45 In January 2025, the Public Prosecutor General for Economic Crimes\npublished a list of 24 individuals believed to be fugitives under article 20, 21, 177(2)\nand 180 of the Criminal Act of 1991 and article 13 and 14 of the Empowerment\nRemoval Law. 46 This list included politicians, journalists and activists, including\nformer leaders of the Taqaddum Coordination Committee. Targeted individuals who\nsought refuge outside of Sudan informed the Mission of harassment that extended\nbeyond its borders, including complications in passport renewals preventing them\nfrom travelling."},{"id":"a-hrc-60-crp-7-p0023","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"23","seq":27,"section":"C. Constitutional amendment (2025)","text":"The Mission continued to receive information regarding the absence of checks\nand balances within the system.47 A clear example of this trend is the February 2025\nconstitutional amendment adopted by the Sudanese authorities, which, among others,\naltered the composition of the Sovereignty Council. This body controls the State\napparatus and is headed by General Al-Burhan as Commander-in-Chief of the Armed\nForces. The amendment extended the transitional period by 39 months, therefore\ndelaying the timeline for transition to civilian rule. It also increased the representation\nof the armed forces in the Council and expanded powers over key appointments and\nforeign policy."},{"id":"a-hrc-60-crp-7-p0024","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"24","seq":28,"section":"C. Constitutional amendment (2025)","text":"The Sovereignty Council was further given the power, together with the Council\nof Ministers, to issue laws and legislation pending the establishment of a Legislative\nCouncil and to appoint and dismiss key justice actors, including the Chief Justice and\nPresident and members of the Constitutional Court, until the formation of the High\nJudicial Council. In August 2025, General Al-Burhan issued a constitutional decree\nappointing the Chief Justice of the Constitutional Court.48 The Constitutional Court\nhas since resumed its functions,49 and can again consider final appeals related to the\nprotection of human rights and fundamental freedoms, including death sentences.\nOnce this appeals process has been exhausted, General Al-Burhan has the final power\nto approve the implementation of death sentences. While the Minister of Justice\nstated that the Constitutional Court “would reduce the number of death row inmates\nwhose sentences have become final by adjudicating their applications before it”,50\nSudanese legal experts expressed fears that this development would instead lead to\nthe implementation of death sentences.51"},{"id":"a-hrc-60-crp-7-p0025","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"25","seq":29,"section":"C. Constitutional amendment (2025)","text":"The constitutional amendment (2025) also abolished the 3 June 2019 massacre\ninvestigative committee. This investigative committee had been established pursuant\nto article 8(16) of the 2019 Transitional Constitutional Document “(…) to conduct a\ntransparent, detailed investigation of violations committed on 3 June 2019, and events\nand incidents where violations of the rights and dignity of civilian and military\ncitizens were committed. (…)”. The investigative committee was reportedly able to\ngather a significant amount of evidence, including over 3,000 testimonies, related to\nthe killing of over 100 protesters and injuring of hundreds more in front of the military\nheadquarters in Khartoum, as well as dozens of reported rapes.52"},{"id":"a-hrc-60-crp-7-p0026","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"26","seq":30,"section":"C. Constitutional amendment (2025)","text":"Although the work of the investigative committee was generally welcomed,\nconcerns were expressed over the lack of gender parity in its membership and its\nability to function fully independently and resist political pressure.53 This became\nevident in 2022, when the investigative committee had to suspend its activities after\nsecurity forces raided its offices and the authorities denied access to Sudan to foreign\nteams to support its forensic investigations.54 As a result, it was not able to conclude\ninvestigations or deliver its findings prior to its abolition, and hence the truth and\naccountability for the killings and other violations were escaped for the time being.55\nThe Mission finds that this development is emblematic of a wider pattern of\nestablishing investigative bodies and when they start to be effective, abolish them to\nevade accountability.56"},{"id":"a-hrc-60-crp-7-p0027","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"27","seq":31,"section":"D. Cooperation with international mechanisms","text":"The Sudanese authorities continued to call for complementarity and provision of\ntechnical support, not interference in its domestic affairs.57 It noted that the National\n48 https://www.suna-sd.net/posts/tsc-president-issues-constitutional-decree-appointing-wahbi-mohamed-mokhtar-as-chief-\njustice-of-the-constitutional-court.\nCommittee was cooperating with the International Criminal Court and had provided\nit with information on its mandate and progress of work on violations and crimes\ncommitted by the Rapid Support Forces with focus on West Darfur, including\nthrough a visit in December 2024 to the Court in The Hague.58"},{"id":"a-hrc-60-crp-7-p0028","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"28","seq":32,"section":"D. Cooperation with international mechanisms","text":"The Office of the Prosecutor in turn reported cautious optimism in cooperation\nwith Sudan with a visit carried out to Port Sudan in April 2025. It, however, noted\nthe need for further consolidation and expansion of the cooperation.59 The Prosecutor\nreferred in particular to the continued lack of execution of warrants of arrest issued\nby the Court against former President Omar Hassan Ahmad Al Bashir, former\nMinister of State for the Interior Ahmad Muhammad Harun and former Minister of\nDefence Abdel Raheem Muhammad Hussein.60 These suspects all face charges of\nmultiple counts of war crimes and crimes against humanity, and in the case of former\nPresident Al Bashir also genocide, committed in Darfur in the mid- to late 2000’s\nwith arrest warrants outstanding for over two decades.61"},{"id":"a-hrc-60-crp-7-p0029","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"29","seq":33,"section":"A. Establishment of a parallel authority","text":"The Rapid Support Forces have reportedly continued to set up its own civilian\nadministrations in areas under its effective control, including West and South\nKordofan, Blue Nile, Khartoum and the Darfur States.62 On 15 April 2025, it further\nannounced the establishment of a parallel “Government of Peace and Unity” also\ncalled founding coalition for Sudan or Ta’sis alliance to be headed by General\nMohamed Hamdan Dagalo (“Hemedti”).63 The announcement was accompanied by\nthe publication of its own constitution founded in “freedom, equality and justice”. As\npart of its principles, the Rapid Support Forces committed to justice and\naccountability, and promised to adhere to international human rights conventions,\nend impunity by prosecuting all those responsible for human rights violations and\ncrimes against the nation, and hand over individuals wanted by the International\nCriminal Court.64"},{"id":"a-hrc-60-crp-7-p0030","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"30","seq":34,"section":"A. Establishment of a parallel authority","text":"Members of the United Nations Security Council rejected the announcement of\nthe establishment of a parallel governing authority by the Rapid Support Forces,\nexpressing grave concerns about inter alia fragmentation of the country and\nworsening an already dire humanitarian situation.65 The African Union also strongly\ncondemned and rejected the announcement of the so-called “parallel government”. It\ncalled on all African Union Member States and the international community to reject\nthe fragmentation of Sudan and not recognize the “parallel government”, indicating\nit would have serious consequences on peace efforts.66\nB. Attacks on the justice system and denial of responsibility"},{"id":"a-hrc-60-crp-7-p0031","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"31","seq":35,"section":"A. Establishment of a parallel authority","text":"The Rapid Support Forces publicly denied responsibility for reported violations\nand related crimes. Without indication of any credible investigations having been\ninstituted, they labeled them as individual acts, not systematic and fabricated.67 For\nexample, in June 2025, the Rapid Support Forces stated that the contents of a video\ncirculating online depicting scenes of alleged violations by the Rapid Support Forces\nwithin the Zamzam camp, North Darfur, as “orchestrated” by the Sudanese Armed\nForces and Joint Forces to falsely incriminate the Rapid Support Forces. “The scenes\nwere filmed under the full supervision of a production team equipped with cameras,\ndirectors, and assistants, some of whom can be seen in the background, instructing\nmen and women to perform scripted roles,” aimed at “manipulating Sudanese\nemotions,” according to the Rapid Support Forces.68"},{"id":"a-hrc-60-crp-7-p0032","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"32","seq":36,"section":"A. Establishment of a parallel authority","text":"In September 2025, another video circulated on social media showing a woman\nhanging by her arms from a tree somewhere in the Darfur region.69 She appeared to\nhave been subjected to acts of torture resulting in her death. The face of the alleged\nperpetrator is briefly shown in the video, who the Rapid Support Forces confirmed\nwore the “distinctive military uniform or our Forces”.70 The Rapid Support Forces,\nhowever, again denied responsibility and without any indication of any investigation\nhaving been carried out labeled it as a fabrication and “deceptive theatrics”.71"},{"id":"a-hrc-60-crp-7-p0033","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"33","seq":37,"section":"A. Establishment of a parallel authority","text":"The Mission reported on the destruction of the justice system by the Rapid\nSupport Forces in its 2024 report. 72 This included the destruction of government\nbuildings and records, in particular in Khartoum and Darfur States, as well as the\ntargeting of courts, including in El Geneina, Nyala and Zalingei courts, and judicial\nrecords. Further attacks were carried out on justice actors, in particular lawyers, often\nwith an ethnic undertone."},{"id":"a-hrc-60-crp-7-p0034","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"34","seq":38,"section":"A. Establishment of a parallel authority","text":"The Mission found a pattern of targeting of, in particular, Masalit lawyers, human\nrights defenders, community leaders and politicians, including through arbitrary\narrest and detention, torture and ill-treatment, and killings. For example, as part of\ntheir attack on El Geneina, West Darfur, in 2023, lawyers belonging to the Masalit\ntribe and those previously involved in criminal cases filed against Rapid Support\nForces members, including in the first Krinding camp massacre, were targeted and a\nnumber killed. The Krinding case concerned the killing or wounding of around 180\nMasalit persons by the Rapid Support Forces in 2019.73 The Mission also recorded\nmore recent cases of lawyers detained and tortured by the Rapid Support Forces for\nreasons related to their work in other areas of the country, including Khartoum State.74\nC. Establishing administrations, investigative bodies and courts"},{"id":"a-hrc-60-crp-7-p0035","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"35","seq":39,"section":"A. Establishment of a parallel authority","text":"The Rapid Support Forces set up investigative mechanisms and courts in areas\nunder its effective control. 75 They previously announced the establishment of\ninvestigative bodies, including into the killing of the former Governor of West Darfur\nand the mass killing at Ardamata in 2023, a “Commander Fudail Investigative\nCommittee, and a “Committee to Adress Violations” (sometimes also referred to as\nthe Committee to Address Negative Phenomena).76 It reportedly also set up further\ninvestigative bodies in Al Jazeera and Khartoum States.77 More recently, the Rapid\nSupport Forces announced that while these investigative bodies had initially been\ncreated by General Hemedti, a new commission had been established by the Ta’sis\ncoalition to continue the work of the previously established investigative bodies.78\nThis commission did not only look at alleged violations by the Rapid Support Forces\nbut also those committed by civilians.79"},{"id":"a-hrc-60-crp-7-p0036","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"36","seq":40,"section":"A. Establishment of a parallel authority","text":"Witnesses the Mission spoke to further confirmed the existence of courts set up\nby the Rapid Support Forces in areas under its control such as in Zalingei, El Geneina,\nand around El Fasher, but stated they did not carry out any investigations despite\ncomplaints filed.80 No further information had been made available on the legal basis,\ncomposition or functioning of these courts or the newly established Ta’sis\ncommission at the time of writing, despite the Mission’s request for such information.\nThe Mission finds that none of these mechanisms or investigative bodies have carried\nout credible investigations to date.\nD. Cooperation with international mechanisms"},{"id":"a-hrc-60-crp-7-p0037","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"37","seq":41,"section":"A. Establishment of a parallel authority","text":"The Office of the Prosecutor of the International Criminal Court noted efforts\nmade to engage with the Rapid Support Forces, including a meeting held in January\n2025 with its representatives. While the Prosecutor expected swift and meaningful\naction earlier in the year,81 his 41st report to the United Nations Security Council\nnoted that “The upcoming period and in particular the substance of information or\nassistance received from the RSF will serve to demonstrate any genuine readiness\nand willingness to fully cooperate with the Office”.82"},{"id":"a-hrc-60-crp-7-p0038","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"38","seq":42,"section":"IV. Options for victim-centred accountability measures","text":"The Mission reaffirms that peace without justice is merely an illusion, and that\naccountability is not a privilege but a fundamental right, as well as a cornerstone of\nsustainable peace in Sudan. Its absence has long been among the principal drivers of\nconflict. The Mission stresses the pressing need to deliver justice and urges that\npreparations for justice and accountability begin without delay. These must form an\nintegral part of any future peace agreement, which, historically, have too often\noverlooked them, and serve as a catalyst for genuine transformation and social\nhealing."},{"id":"a-hrc-60-crp-7-p0039","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"39","seq":43,"section":"IV. Options for victim-centred accountability measures","text":"Many Sudanese individuals expressed to the Mission their lack of confidence in\ndomestic processes to render justice for international crimes in a fair and impartial\nmanner. Autocratic rule, military coups and the inability to settle political differences\npeacefully, as well as the various measures employed to evade international\naccountability efforts, have contributed to the Sudanese civilians lacking trust in\ndomestic institutions."},{"id":"a-hrc-60-crp-7-p0040","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"40","seq":44,"section":"IV. Options for victim-centred accountability measures","text":"To effectively break the cycle of impunity in Sudan, a range of options for\ndelivering justice and ensuring accountability should be considered. Towards this\nend, the mission engaged with a diverse range of Sudanese, regional and international\nstakeholders, including through interviews, meetings and missions, ensuring balance\nin among others in age, gender, profession and region of origin. It also organized a\nconsultation in Nairobi, Kenya, from 28 to 30 May 2025, with the support of the\nKenya Section of the International Commission of Jurists. The three-day meeting\nincluded 145 Sudanese and other participants with near equal gender representation,\noffering a safe space for developing its initial recommendations on accountability\nmeasures. These included a call for an expansion of the jurisdiction of the\nInternational Criminal Court to cover the entire territory of Sudan, as well as the\nestablishment of a complementary judicial mechanism, truth commission, and victim\nsupport and reparation office."},{"id":"a-hrc-60-crp-7-p0041","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"41","seq":45,"section":"IV. Options for victim-centred accountability measures","text":"During the consultation, lessons learnt from past accountability and transitional\njustice experiences in Sudan and the region and options for future measures for justice\nand accountability in Sudan were explored. The discussion touched on the sequencing\nbetween justice and peace and options for future measures, and agreed that\npreparations for justice and accountability must begin without delay. As an\noverarching principle, all-inclusive Sudanese dialogue with a gender-sensitive\napproach should guide the design and implementation any of accountability process\nin line with its legal, cultural and social contexts. This should be ensured through\ncontinued inclusive consultations and coordination and cooperation between the\nvarious bodies. A victim-centered approach should equally be prioritized, which must\ninclude the equal representation of women in all areas and at all levels as well as\nconsider the situation of children affected by the conflict. Accountability mechanisms\nmust also ensure that survivors of sexual and gender-based violence are provided\nwith safe, confidential, and trauma-informed avenues to enable their participation in\njustice processes and related reparations."},{"id":"a-hrc-60-crp-7-p0042","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"42","seq":46,"section":"A. Right to truth","text":"Victims and survivors, their families, affected communities and society as a\nwhole have the right to know the truth about violations of international human rights\nlaw and international humanitarian law that have been committed in Sudan. 83 They\nmust be supported in their efforts to seek and obtain information on the commission\nof the alleged violations and related crimes, the causes thereof, the fate and\nwhereabouts of loved ones, and the role of the authorities in their commission, if\nany.84 The right to truth and to the right to justice, including individual accountability\nof perpetrators of international crimes, are mutually reinforcing and part and parcel\nof transitional justice and a path towards sustainable peace."},{"id":"a-hrc-60-crp-7-p0043","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"43","seq":47,"section":"A. Right to truth","text":"Professional documentation of violations and related crimes should therefore\ncontinue as a tool for establishing the truth in support of the victims and survivors of\nrepeated cycles of conflict and related violations, and to enable independent and\nimpartial justice processes to take place in the future. This could include the creation\nof repositories and registers for damages particularly related to the widespread\npillage, looting and destruction of private properties, and specific harms suffered,\nsuch as deaths, missing persons, rape and other forms of sexual and gender-based\nviolence. The Mission’s mandate of evidence collection and preservation remains\ncrucial in this regard and it is committed to continue its efforts and cooperate with all\nother relevant stakeholders."},{"id":"a-hrc-60-crp-7-p0044","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"44","seq":48,"section":"A. Right to truth","text":"To facilitate the participation of Sudanese civil society organizations in the\ndocumentation and truth-seeking process, immediate technical training and capacity-\nbuilding is needed. Many Sudanese individuals from different backgrounds have\nsince the onset of the conflict supported monitoring and documentation of violations\nand related international crimes in Sudan without proper training or financial support.\n83 A/RES/60/147, Principle 24.\n84 United Nations, Guidance note of the Secretary-General, Transitional Justice A Strategic Tool for People, Prevention\nand Peace, 2023, page 14; African Union, Transitional Justice Policy, 2019.\nB. Right to justice"},{"id":"a-hrc-60-crp-7-p0045","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"45","seq":49,"section":"A. Right to truth","text":"The right to justice, including to remedies and reparations, centres on victims’\nand survivors’ access justice and fair and impartial proceedings.85 They should inter\nalia be provided with the necessary information on available remedies, rendered\nassistance as may be needed to access justice, and receive protection from\nintimidation and retaliation.86 To this end, alongside truth-seeking processes, further\nconsideration should be given to the Mission’s recommendations on the expansion of\nthe jurisdiction of the International Criminal Court to cover the entire territory of\nSudan and the establishment of an independent and impartial judicial mechanism for\nSudan to work in tandem with the Court adhering to its complementarity principles\nas stipulated by the Rome Statute.87"},{"id":"a-hrc-60-crp-7-p0046","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"46","seq":50,"section":"A. Right to truth","text":"Firstly, there is a credible argument to be made that many aspects of the current\nconflict in Sudan stem from and are a continuation of the Darfur conflict. The mandate\nof the Office of the Prosecutor should include critical events in other parts of Sudan\nwhere there is a sufficiently strong connection to Darfur, including based on the same\nalleged perpetrators and/or victim groups. The execution of already issued arrest\nwarrants is imperative. The Mission reiterates its call on all States to fully cooperate\nwith the Court and for Sudan to extradite all suspects in the Darfur case, including\nformer President Omar Hassan Ahmad Al Bashir and former Minister of State for the\nInterior Ahmad Muhammad Harun, so that the victims and survivors of atrocities in\nSudan may finally see justice done."},{"id":"a-hrc-60-crp-7-p0047","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"47","seq":51,"section":"A. Right to truth","text":"In a recent development, while referring to the non-execution of other arrest\nwarrants in the Darfur situation, on 6 October 2025, Trial Chamber I of the\nInternational Criminal Court issued its judgment in the case of former Janjaweed\nleader Ali Muhammad Ali Abd-Al-Rahman (nickname Ali Kushayb), who\nsurrendered himself to the Court in 2020. It found Mr. Abd-Al-Rahman guilty on 27\ncounts of war crimes and crimes against humanity, including for the first time\npersecution on ethnic, gender and political grounds, in relation to attacks carried out\nagainst members of the Fur ethnicity on the villages of Mukjar, Deleig, Kodoom and\nBindisi, in Darfur, between August 2003 and April 2004.88"},{"id":"a-hrc-60-crp-7-p0048","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"48","seq":52,"section":"A. Right to truth","text":"The Chamber confirmed, among others, that it was established beyond reasonable\ndoubt that a plan had been designed at the highest level of state with an ethnic\ndimension to target and attack the non-Arab Fur, Masalit and Zaghawa tribes, and that\norders given failed to distinguish between fighters and civilians, without a doubt\nresulting in the commission of crimes. The Presiding Judge stated that the case had\ngiven a voice to victims for the first time – 1591 victims were able to participate in\nthe trial proceedings,89 - and made a connection to the further misery suffered by the\ncitizens of Sudan due to the current conflict. 90 The Mission hopes this landmark\njudgement can act as a catalyst to further victim-centered accountability efforts."},{"id":"a-hrc-60-crp-7-p0049","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"49","seq":53,"section":"A. Right to truth","text":"Secondly, Sudan itself can take the step of making a declaration under Article\n12(3) of the Rome Statute to accept the exercise of jurisdiction by the International\nCriminal Court as the State on whose territory international crimes have been\n85 A/RES/60/147, Principle 12.\n86 Ibid.\n87 International Criminal Court, Office of the Prosecutor, Policy on Complementarity and Cooperation, April 2024.\n88\nhttps://www.icc-cpi.int/news/ali-muhammad-ali-abd-al-rahman-declared-guilty-war-crimes-and-crimes-against-\nhumanity.\ncommitted. Other States who were not at the time a party to the Rome Statute, namely\nArmenia,91 Palestine,92 and Ukraine,93 have made such declarations."},{"id":"a-hrc-60-crp-7-p0050","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"50","seq":54,"section":"A. Right to truth","text":"Thirdly, action should be taken by the international community without delay\ntowards the establishment a complementary mechanism to ensure all perpetrators of\ninternational crimes are held to account. Lessons learned from past accountability\ninitiatives in Sudan and the region should play a central role in its design, which\nshould be based on an all-inclusive Sudanese dialogue, include a gender-sensitive lens\nand take account of Sudan’s legal, cultural and social contexts. For example, the 2020\nJuba Agreement for Peace in the Sudan included an approach for transitional justice\nand envisaged the set-up of a hybrid special court for Darfur. This hybrid special court\nwas never implemented and its design, including as regards the independence of\njudges and prosecutors and time limits imposed on its operations, faced serious\ncriticism. However, with the necessary amendments and a mandate covering the\nwhole of Sudan, a hybrid design could be included in a future peace agreement."},{"id":"a-hrc-60-crp-7-p0051","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"51","seq":55,"section":"A. Right to truth","text":"As highlighted in the Mission’s previous report, there are indeed different options\nto be considered for the design of any independent and impartial judicial institution\nfor Sudan – given the spectrum of options from fully international, to hybrid or an\ninternationalized design - based on experiences in among others in Rwanda, Sierra\nLeone, Central African Republic and Senegal (Chad).94 For example, the institution\ncould be composed of both national and international judges, employ a mix of\nSudanese and international staffing, and rely on an independent special police force\nand prosecutors office attached to it, allowing at the same time for Sudanese trust and\ncapacity building.95 The Mission believes that what is crucial in the selection of a\ndesign for the complementary independent and impartial judicial institution for\nSudan, is that the institution is able to decide on cases before it in an independent and\nimpartial manner, meaning “on the basis of the facts and in accordance with the law,\nwithout any restrictions, improper influences, inducements, pressures, threats or\ninterferences, direct or indirect, from any quarter or for any reason.”96 Its features\nmust reflect its impartiality, including in its ability to function without political\ninterference and ensure victim participation and witness protection."},{"id":"a-hrc-60-crp-7-p0052","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"52","seq":56,"section":"A. Right to truth","text":"Fourthly, access to justice should also be guaranteed by third States through the\nuse the universal jurisdiction as a tool to pursue individuals suspected of having\ncommitted international crimes in Sudan. Universal jurisdiction permits States to\ninvestigate and prosecute international crimes extraterritorially given their heinous\ncharacter and in the interest of the international community as a whole. There are\nalready a myriad of examples of the application of universal jurisdiction in relation\nto international crimes committed in other country contexts, including in relation to\nthe Gambia and Syria.97 The Mission calls on all third States to include the situation\nin Sudan in their efforts to uphold international law through the application of\nuniversal jurisdiction and support victims and survivors of international crimes in\nSudan in their desperate search for accountability."},{"id":"a-hrc-60-crp-7-p0053","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"53","seq":57,"section":"A. Right to truth","text":"An important example of the role of domestic courts in other countries is the\nLundin trial. In February 2025, the Mission observed hearings in Stockholm\nregarding the criminal trial before the District Court of Stockholm against two former\nexecutives of Lundin Oil, Alexandre Schneiter and Ian Lundin, charged with\ncomplicity in war crimes committed between 1999 and 2003. The case,\n91 https://www.icc-cpi.int/sites/default/files/2023-11/Letter_MFA.pdf.\n92 https://www.icc-cpi.int/palestine.\n93 https://www.icc-cpi.int/situations/ukraine.\n94 A/HRC/57/CRP.6, para. 333.\n95 A/HRC/57/CRP.6, para. 333.\n96 A/CONF.121/22/Rev.1, Principle 2.\n97 See e.g. Federal Criminal Court, Bellinzona, Switzerland, 15 May 2024, https://www.bstger.ch/uploads/2025-01-\n20_Press_release.pdf; The Hague Court of Appeals, The Netherlands, decision, 27 August 2025,\nunprecedented in holding corporate leaders accountable for business-related\nviolations of international law, is of direct relevance to the Mission’s mandate on\njustice, accountability, and addressing the root causes of violations. The charges stem\nfrom one of the most extensive investigations ever conducted by Swedish authorities,\nlaunched in 2010 following civil society reports documenting serious crimes in what\nis now South Sudan’s oil-producing areas. The indictment alleges that the company’s\noperations contributed to violations of international humanitarian law in connection\nwith efforts to secure oil concessions. The proceedings, which began in September\n2023 and are expected to continue until February 2026, involve extensive\ndocumentary evidence and participation by victims seeking compensation amounting\nto SEK 110 million. The hearings observed were sober and reflective of the gravity\nand complexity of the case.\nC. Right to reparations"},{"id":"a-hrc-60-crp-7-p0054","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"54","seq":58,"section":"A. Right to truth","text":"Under the 2005 Basic Principles and Guidelines on the Right to a Remedy and\nReparation for Victims of Gross Violations of International Human Rights Law and\nSerious Violations of International Humanitarian Law, reparations may take multiple\ncomplementary forms, reflecting the nature and gravity of the violation. These\ninclude restitution, aimed at restoring the victim to the original situation before the\nviolation occurred; compensation, for economically assessable damage;\nrehabilitation, encompassing medical, psychological, legal, and social services;\nsatisfaction, which includes measures such as public acknowledgment, truth-seeking,\nand apologies; and guarantees of non-repetition, through institutional and legal\nreforms to prevent recurrence. Together, these forms embody a holistic approach to\njustice and the restoration of dignity. 98"},{"id":"a-hrc-60-crp-7-p0055","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"55","seq":59,"section":"A. Right to truth","text":"Victims and survivors of atrocities committed in the ongoing conflict in Sudan\nare living in dire situations, often having been displaced multiple times inside Sudan\nand across borders to neighbouring countries. They cannot wait and interim\nreparations must be provided to them as a matter of priority. Especially women and\nchildren are in urgent need of assistance and safe spaces in displacement camps and\nurban centers where they can seek refuge and receive protection, including from\nsexual and gender-based violence and other threats. Sudanese victims and survivors\nfurther repeatedly stressed to the Mission the need for education for their children,\nmedical treatment, psycho-social assistance, and access to basic necessities such as\nfood and shelter. Survivors of sexual and gender-based violence, including rape and\ngang rape, in particular need urgent access to medical and psychological services.\nVictims and survivors also wished for economic opportunities to support their\nfamilies and displaced Sudanese communities in their hardship."},{"id":"a-hrc-60-crp-7-p0056","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"56","seq":60,"section":"A. Right to truth","text":"A victim-centered approach to any accountability process for international crimes\ncommitted in Sudan must take their situation into account. It requires that all victims\nand survivors of these atrocities, as well as affected communities, are supported in an\nequal manner to enable their full participation. Without this any accountability\nprocess will instead risk creating further communal tensions and exacerbate conflict\nand be rendered meaningless. As one person told the Mission, justice can only be\npursued and those responsible held to account, once victims and survivors have\naccess to shelter, medical care, education, and other basic necessities.99 This was\nechoed by all other relevant actors during the accountability consultation held earlier\nthis year."},{"id":"a-hrc-60-crp-7-p0057","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"57","seq":61,"section":"A. Right to truth","text":"Reparations and distributive justice are therefore essential elements of\naccountability that is transformative in character. There is no “one size fits all” and\ninterim measures must be tailored to the specific situation and needs of victims and\nsurvivors and affected communities, and the types of harms and violations of human\nrights and international humanitarian law suffered and their specific gendered\nimpacts. The Mission believes that a dedicated entity should be established to\ncoordinate this complex task and award victims’ interim reparative measures. It\ntherefore reiterates its recommendation for the set-up of a victim support and\nreparations office and additionally encourages States to create a dedicated trust fund\nto facilitate timely reparations delivery."},{"id":"a-hrc-60-crp-7-p0058","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"58","seq":62,"section":"A. Right to truth","text":"Following the recent guilty verdict in the Abd-Al-Rahman case (nickname Ali\nKushayb), the International Criminal Court will consider next the victims’\napplication for reparations. The Court previously confirmed they may be awarded to\nindividual victims and survivors to make repairs for the harms they have suffered\nand/or to benefit a group or category of persons who have suffered a shared harm.100\nAn example can be taken from the Ongwen case that concerned victims of crimes\ncommitted in Northern Uganda and where the Court handed down the largest\nreparations order to date. The Court in this case ordered both individual and collective\ncommunity-based measures and programmes due to the sheer number of around\n50,000 victims. It acknowledged the wishes of victims to receive individual\nreparations and prioritized these over collective ones, awarding all eligible victims\n750 EUR.101\nD. Legal and institutional reform"},{"id":"a-hrc-60-crp-7-p0059","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"59","seq":63,"section":"A. Right to truth","text":"Finally, as part of guarantees of non-recurrence, legal and institutional reforms,\nin particular of the justice and security sectors in Sudan will need to be prioritized\nalongside accountability as part of any transitional justice process for the country to\naddress root causes of recurring violence and conflict and transition to a stable and\ndemocratic society in line with the aspirations expressed by the Sudanese people.102\nThe Mission stresses that domestic legal and institutional reforms can only be\ncredibly undertaken following such transition to a fully democratic rule and based on\ninclusive consultations. However, the mapping of a justice and security sector reform\nagenda, which was commenced during the 2019 transitional period but prematurely\nhalted, should be undertaken pending this transition. This comprehensive mapping of\nwhat needs to be changed requires urgent updating and completion by Sudanese legal\nexperts."},{"id":"a-hrc-60-crp-7-p0060","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"60","seq":64,"section":"A. Right to truth","text":"Sudanese legal experts referred to the current situation in Sudan as a crisis of\nimplementation of laws and ability and willingness to deliver justice.103 Initiatives\nundertaken during the transitional period to fully incorporate international laws into\nSudanese domestic legislation were not only cut short, the progress that was made\nwas largely reversed by the Sudanese authorities since the onset of the conflict. An\nemblematic example of this is the reversal regarding extensive immunities provided\nto State actors, including under the 2024 amendment of the General Intelligence\nServices law. 104 As detailed previously, the Criminal Act of 1991 and its 2009\namendment, Criminal Procedure Act of 1991, and Evidence Act of 1994, among\nothers, require significant legal review and amendment to align them with\ninternational human rights law.105"},{"id":"a-hrc-60-crp-7-p0061","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"61","seq":65,"section":"A. Right to truth","text":"For example, a longstanding issue is that defendants carry the burden of proof to\nshow that their confession was obtained under torture for it to be considered\ninadmissible in court. This reversed burden of proof is contrary to the Convention\nagainst Torture and Other Cruel, Inhuman or Degrading Treatment or Punishment, to\n100 International Criminal Court, Prosecutor v. Ntaganda, Reparations Order, ICC-01/04-02/06, 8 March 2021.\n101 International Criminal Court, Prosecutor v. Ongwen, Reparations Order, ICC-02/04-01/15 28 February 2024; See also\nhttps://www.globalsurvivorsfund.org/latest/articles/icc-largest-ever-reparation-order-ongwen/.\nwhich Sudan is a party.106 In addition to the issue of mixed definitions of the core\ninternational crimes included in the 2009 amendment of the Criminal Act of 1991,107\nanother problem identified is that of command responsibility and its absence from\nSudanese domestic legislation that effectively prevents the leadership of parties to\nthe conflict as well as mid-level commanders and superiors from being held\naccountable for the international crimes committed. 108 Furthermore, as regards\ninternational cooperation to ensure accountability for international crimes committed\nin Sudan, an amendment to the Criminal Procedure Act of 1991 was introduced in\n2009 to prevent the extradition of any Sudanese national for overseas prosecution.109\nDomestic law further does not foresee in any right to remedies and reparations.110"},{"id":"a-hrc-60-crp-7-p0062","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"62","seq":66,"section":"A. Right to truth","text":"Legal and institutional reforms should further guarantee the full independence of\njudges and lawyers as well as of state institutions, such as the office of the prosecutor,\nfrom any form of political or other type of interference. Sudanese legal experts also\nstressed the need for legal education on human rights and international criminal law\ncombined with English language skills to ensure domestic capacity to deal with\nviolations of human rights and international crimes and cooperate internationally.\nLong-term trust-building measures, including legal digitization to ensure\ntransparency, will simultaneously be required to restore the faith of the Sudanese\npeople in its institutions, and for credible justice to be able to be delivered in the\nfuture at the domestic level to all victims and survivors of atrocities that have taken\nplace in the current conflict."},{"id":"a-hrc-60-crp-7-p0063","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"63","seq":67,"section":"V. Conclusions and recommendations","text":"The Mission concludes that accountability for international crimes\ncommitted during the ongoing conflict in Sudan, as well as in previous cycles of\nviolence, remains elusive. It finds that Sudan, including all parties to the conflict,\nremain unwilling or unable to conduct genuine, thorough, prompt, and\nimpartial investigations and prosecutions, as evidenced by recent developments\nand documented cases. The Mission reiterates its earlier findings of selective\njustice and the continued lack of trust among victims and survivors in domestic\ninstitutions, given the longstanding pattern of using domestic laws and\nmechanisms to evade accountability. It further emphasizes the urgent need for\ncomprehensive legal and institutional reforms within the framework of a\ndemocratic civilian rule."},{"id":"a-hrc-60-crp-7-p0064","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"64","seq":68,"section":"V. Conclusions and recommendations","text":"The breakdown of the rule of law in Sudan amid the ongoing conflict,\ncompounded by serious gaps in domestic legislation, has been further\naggravated by the February 2025 constitutional amendment adopted by the\nSudanese authorities, which delays the transition to civilian rule. The Mission is\ndeeply concerned by the continued targeting of political leaders, lawyers, human\nrights defenders, journalists, and civilians. It is also alarmed by the further\nfragmentation of authority and its negative impact on accountability following\nthe Rapid Support Forces’ announcement of a parallel authority, including the\nestablishment of courts and investigative bodies without any legal basis,\nframework, or capacity to guarantee fair trial rights and protection for victims\nand survivors."},{"id":"a-hrc-60-crp-7-p0065","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"65","seq":69,"section":"V. Conclusions and recommendations","text":"Calls for accountability can no longer be ignored. Immediate, concrete steps\nmust be taken to deliver justice and support to all Sudanese victims and\nsurvivors of atrocities. Accountability measures must be victim-centered,\ngender-sensitive, and inclusive, and grounded in broad-based consultations with\nall segments of Sudanese society. To this end, the Mission identifies four essential\npillars in its roadmap for justice: the right to truth, right to justice, right to\nreparations, and legal and institutional reforms. It urges all stakeholders —\nincluding international and regional organizations, third States, and Sudanese\ncivil society and legal experts — to work collectively to break the cycle of\nimpunity and advance accountability."},{"id":"a-hrc-60-crp-7-p0066","rec_id":"recBDiuLvlb1i3NNY","symbol":"A/HRC/60/CRP.7","n":"66","seq":70,"section":"V. Conclusions and recommendations","text":"There are viable paths to justice and accountability for the atrocities\ncommitted in Sudan. These are anchored in the roadmap presented by the\nMission in its September 2025 report to the United Nations Human Rights\nCouncil (A/HRC/60/22) and include the following:\na.       For the parties to the conflict: immediately cease hostilities, protect\ncivilians, and commit to a lasting peace; comply with obligations under\ninternational law; end impunity, including by cooperating fully with the\nMission and the International Criminal Court, including the surrender of all\npersons subject to arrest warrants.\nb.        For other States: pursue avenues to bring perpetrators to justice,\nincluding by expanding the jurisdiction of the International Criminal Court\nand supporting the establishment of an independent and impartial judicial\ninstitution for Sudan; suspend cooperation with individuals suspected of\ninternational crimes; exercise universal jurisdiction to prosecute them in\nnational courts; impose targeted sanctions against those responsible; and\nfund victim support and interim reparatory mechanisms.\nc.       For mediators: align peace efforts with the Sudanese people’s\naspirations for justice, stability, and prosperity; ensure that justice and\naccountability are central to any peace process; and reject amnesties for\ninternational crimes.\nd.       For civil society: continue to document violations, preserve evidence\nfor future accountability processes, and advocate for impartial justice and\ngenuine accountability in Sudan."},{"id":"a-hrc-61-77-u0000","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/61/77\nGeneral Assembly                                                          Distr.: General\n10 March 2026","unnumbered":true},{"id":"a-hrc-61-77-u0001","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":null,"seq":1,"section":null,"text":"Human Rights Council\nSixty-first session\n23 February–2 April 2026\nAgenda item 2\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General","unnumbered":true},{"id":"a-hrc-61-77-u0002","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":null,"seq":2,"section":null,"text":"Summary\nThe independent international fact-finding mission for the Sudan assesses that the\nmass killings and related atrocities committed by the Rapid Support Forces in and around El\nFasher, during its takeover of the city on or around 26 and 27 October 2025, are indicators\nof a genocidal path. These crimes followed an 18-month siege during which the Rapid\nSupport Forces deliberately imposed conditions of life calculated to bring about the physical\ndestruction of non-Arab communities, in particular the Zaghawa and the Fur.\nThe mission documented an escalating pattern that demonstrates coordination and\nidentity-based targeting linked to ethnicity, gender and perceived political affiliation,\nresulting in mass killings, serious bodily and mental harm, widespread rape and other forms\nof sexual violence, arbitrary detention, torture and cruel treatment, and enforced\ndisappearances, accompanied by dehumanizing and exterminatory rhetoric. This cumulative\nfactual matrix reveals the intent of the Rapid Support Forces to destroy the Zaghawa and Fur\ncommunities in whole or in part. The conduct in El Fasher is an aggravation of earlier patterns\nof mirror attacks against other non-Arab communities elsewhere in the Sudan, but on a far\nmore lethal scale. Accountability of perpetrators, including those who facilitate, aid or abet\nthese crimes, remains imperative. As the conflict expands to other regions, urgent protection\nfor civilians is needed more than ever.","unnumbered":true},{"id":"a-hrc-61-77-p0001","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"1","seq":3,"section":"I. Mandate, methodology and cooperation","text":"At its thirty-eighth special session, held on 14 November 2025, the Human Rights\nCouncil adopted its resolution S-38/1, requesting the mission to conduct an urgent inquiry\ninto the recent violations and abuses of international human rights law and violations of\ninternational humanitarian law allegedly committed in and around El Fasher and to identify,\nwhere possible, all those for whom there are reasonable grounds to believe that they are\nresponsible. The Council also requested the mission to give due regard to ensuring the\ncomplementarity of its efforts with those of other actors."},{"id":"a-hrc-61-77-p0002","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"2","seq":4,"section":"I. Mandate, methodology and cooperation","text":"In fulfilling this request, the mission applied its previously outlined methodology and\nguiding principles. 1 While recognizing the standard of proof of “reasonable grounds to\nbelieve”, common to the United Nations investigative bodies, the mission paid particular\nattention to the question of whether clear and fully convincing evidence, as articulated by\njudicial bodies, exists to invoke the crime of genocide.2 It also considered whether genocidal\nintent was the sole reasonable explanation for the conduct documented."},{"id":"a-hrc-61-77-p0003","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"3","seq":5,"section":"I. Mandate, methodology and cooperation","text":"The mission identified persons of interest in relation to the commission of violations\nand related international crimes in and around El Fasher. It is developing confidential dossiers,\ntaking account of all possible modes of liability, including command responsibility, which it\nmay share with judicial and other entities, as appropriate, in pursuit of individual criminal\naccountability and access to justice for victims.3"},{"id":"a-hrc-61-77-p0004","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"4","seq":6,"section":"I. Mandate, methodology and cooperation","text":"The mission has interviewed 320 witnesses and victims from El Fasher and\nsurrounding areas, including on the impact of the prolonged attacks and siege on the civilian\npopulation. Following the request by the Human Rights Council for an urgent inquiry, the\nmission conducted consultations with survivors (on 28 November 2025), as well as targeted\ninvestigative missions to Chad (from 6 to 17 January 2026) and South Sudan (from 10 to\n21 January 2026) where it interviewed additional survivors from the El Fasher area. A total\nof 131 interviews have been conducted so far in 2026 alone (107 in-person and 24 remote),\nwith 54 women and 77 men. The mission is deeply grateful to all survivors for their courage\nin sharing their experiences, to the Governments of Chad and South Sudan for facilitating the\nmissions and to host communities for their generosity."},{"id":"a-hrc-61-77-p0005","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"5","seq":7,"section":"I. Mandate, methodology and cooperation","text":"The mission also collected non-testimonial evidence and information, including\naround 40 public reports and related materials. It authenticated, verified and corroborated\n25 videos and held more than 37 meetings with civil society, human rights defenders, and\nexperts, including global health experts."},{"id":"a-hrc-61-77-p0006","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"6","seq":8,"section":"I. Mandate, methodology and cooperation","text":"The mission engaged with a range of international and regional entities, including the\nSpecial Adviser to the Secretary-General on the Prevention of Genocide, the African Union\nSpecial Envoy on the Prevention of Genocide and Mass Atrocities, the Special\nRepresentative of the Secretary-General on Sexual Violence in Conflict, the African Union\nJoint Fact-Finding Mission on the Human Rights Situation in the Sudan, the African Union\nMission in South Sudan, and the International Criminal Court."},{"id":"a-hrc-61-77-p0007","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"7","seq":9,"section":"I. Mandate, methodology and cooperation","text":"Despite its best efforts, the mission did not receive cooperation from the Sudan. On\n24 November 2025, it sent a note verbale to the Government of the Sudan, requesting a visit,\nparticularly to El Fasher, and to engage with Sudanese officials and with victims and\nsurvivors. The mission also pursued engagement through additional channels. On 13\nFebruary 2026, the mission shared the final draft report on El Fasher with the Government\nof the Sudan. No response was received."},{"id":"a-hrc-61-77-p0008","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"8","seq":10,"section":"I. Mandate, methodology and cooperation","text":"On 12 December 2025, the mission sent a letter to the Rapid Support Forces\nrequesting a meeting with their leadership and sharing a list of questions relating to their\ntakeover of El Fasher. No response was received, notwithstanding public assertions by the\nRapid Support Forces that they would cooperate with the mission. 4"},{"id":"a-hrc-61-77-p0009","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"9","seq":11,"section":"II. Legal framework and parties to the conflict","text":"In its previous reports, the mission determined that the ongoing conflict in the Sudan\nmeets the threshold for a non-international armed conflict to which article 3 common to the\nGeneva Conventions of 12 August 1949 applies.5 This provision, which applies to all parties\nto the conflict, sets out minimum protections that must be guaranteed – prohibiting violence\nand cruel treatment against, and murder of, civilians, the wounded and the sick, and persons\nhors de combat, and requiring humane treatment and care without adverse distinction. The\nProtocol Additional to the Geneva Conventions of 12 August 1949, and relating to the\nProtection of Victims of Non-International Armed Conflicts (Protocol II) strengthens these\nprotections and is applicable to the Sudan as a State Party."},{"id":"a-hrc-61-77-p0010","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"10","seq":12,"section":"II. Legal framework and parties to the conflict","text":"International human rights law applies concurrently with international humanitarian\nlaw, including the Convention on the Prevention and Punishment of the Crime of Genocide,\nof 1948, to which the Sudan is a State Party. International criminal law also applies, and the\nsituation in Darfur since 1 July 2002 is subject to the jurisdiction of the International Criminal\nCourt pursuant to Security Council resolution 1593 (2005)."},{"id":"a-hrc-61-77-p0011","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"11","seq":13,"section":"II. Legal framework and parties to the conflict","text":"The parties to the conflict remain the Sudanese Armed Forces and the Rapid Support\nForces, and their respective allies. Obligations under international law extend not only to the\nparties, but also to third States and entities which must respect and ensure respect for\ninternational humanitarian law and refrain from aiding or abetting violations committed by\nthe parties.6"},{"id":"a-hrc-61-77-p0012","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"12","seq":14,"section":"II. Legal framework and parties to the conflict","text":"Until its takeover on or around 26 and 27 October 2025, El Fasher represented the last\nremaining stronghold of the Sudanese Armed Forces in Darfur, following the capture by the\nRapid Support Forces of four of Darfur’s five state capitals between April and November\n2023. The city’s defence relied on the Army’s Sixth Infantry Division, supported by the Joint\nForces and locally mobilized civilian units formed to protect families and communities."},{"id":"a-hrc-61-77-p0013","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"13","seq":15,"section":"II. Legal framework and parties to the conflict","text":"The Joint Forces comprised armed movements that were signatories to the Juba Peace\nAgreement. The Joint Forces are closely associated with leadership figures from the Zaghawa\ncommunity, including factions linked to the Sudan Liberation Army–Minni Minawi and the\nJustice and Equality Movement–Jibril Ibrahim."},{"id":"a-hrc-61-77-p0014","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"14","seq":16,"section":"II. Legal framework and parties to the conflict","text":"The Rapid Support Forces’ military campaign was reinforced by local Arab militias\nand allied groups, and by mercenaries reportedly deployed through foreign security firms or\nnetworks and equipped with advanced weaponry and communications systems. Witnesses\ndescribed the Rapid Support Forces’ use of heavy artillery and drones and their electronic\nwarfare capabilities. The Rapid Support Forces appear to have benefited from logistical\nmilitary support, in violation of the arms embargo under Security Council resolution 1593\n(2005). The mission is engaging with several States regarding credible information that it has\nreceived about their own involvement or that of their nationals or entities in the ongoing\nconflict in the Sudan. It will report on this matter in the future.\n4 See https://t.me/RSFSudan/8396.\n5 See A/HRC/60/22; A/HRC/57/23; and the conference room paper containing the findings of the\ninvestigations conducted by the independent international fact-finding mission for the Sudan into\nviolations of international human rights law and international humanitarian law, and related crimes,\ncommitted in the Sudan in the context of the conflict that erupted in mid-April 2023.\n6 A/HRC/60/22, para. 17."},{"id":"a-hrc-61-77-p0015","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"15","seq":17,"section":"II. Legal framework and parties to the conflict","text":"Although all parties recruited children, 7 multiple interviewees emphasized that the\nRapid Support Forces deployed a substantial number of children, using them as fighters and\nfor intelligence-gathering within El Fasher."},{"id":"a-hrc-61-77-p0016","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"16","seq":18,"section":"III. Siege and takeover of El Fasher","text":"The siege and eventual takeover of El Fasher unfolded against a backdrop of repeated\nwarnings, clearly identified atrocity risk indicators, and escalating conduct consistent with\nmass atrocity crimes under international law."},{"id":"a-hrc-61-77-p0017","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"17","seq":19,"section":"III. Siege and takeover of El Fasher","text":"From mid‑2024, the risk of mass atrocity crimes was repeatedly and explicitly\nidentified. On 13 June 2024, the Security Council demanded that the Rapid Support Forces\nhalt their siege of El Fasher and that all parties protect civilians. 8 The African Union Peace\nand Security Council recalled Security Council resolution 2736 (2024) and warned of\ndangerous ethnic and communal repercussions. 9 These concerns were reiterated in\nsubsequent international warnings, including the Security Council statement of 30 October\n2025.10"},{"id":"a-hrc-61-77-p0018","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"18","seq":20,"section":"III. Siege and takeover of El Fasher","text":"Despite these warnings, no effective measures were taken by any party to protect the\ncivilian population. Over approximately 18 months of siege, the Rapid Support Forces\nsteadily squeezed the life out of El Fasher and surrounding displacement camps, cutting off\nfood, water, medical supplies and humanitarian assistance, while subjecting the city to\nrecurring shelling and ground assaults. Civilians were increasingly trapped, as escape routes\nwere restricted or closed, and were forced to endure conditions of life progressively\nincompatible with human survival."},{"id":"a-hrc-61-77-p0019","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"19","seq":21,"section":"A. Modus operandi","text":"Across Darfur, the Rapid Support Forces exhibited a pervasive, consistent and\nidentifiable operational pattern characterized by ethnically discriminatory targeting,\nencirclement and siege tactics, and systematic violence against civilians. In West Darfur,\nincluding El Geneina and surrounding areas, the mission previously found that the Rapid\nSupport Forces and allied Arab militias had repeatedly attacked predominantly non-Arab\ncommunities, particularly the Masalit, through persistent waves of indiscriminate killing,\nsexual violence, torture, looting, and destruction of homes and infrastructure. These attacks\nwere frequently accompanied by discriminatory and humiliating slurs. Civilians and persons\nhors de combat were deliberately isolated, escape routes blocked, and fleeing populations\nattacked. Community leaders, displacement camps and medical facilities were targeted, while\nentire neighbourhoods were razed."},{"id":"a-hrc-61-77-p0020","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"20","seq":22,"section":"A. Modus operandi","text":"The Rapid Support Forces intensified these tactics in and around El Fasher, revealing\nthe intent to eliminate the city’s residents. Survivors describe explicit threats to “clean” the\ncity. The patterns employed included a siege that comprised multidirectional encirclement\nand repeated encroachments with attacks on civilians and civilian infrastructure using drones\nand heavy weapons in populated areas. The facilities attacked included displacement camps,\nmedical facilities, places of worship, and food systems such as communal kitchens and\nmarkets. Humanitarian relief was persistently denied. When the Rapid Support Forces\nentered a besieged area, mass killings, beatings, looting, sexual violence and destruction of\nproperty followed – all accompanied by ethnically discriminatory rhetoric and conduct."},{"id":"a-hrc-61-77-p0021","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"21","seq":23,"section":"B. The people of El Fasher and repeated displacement","text":"Prior to the takeover, the population of El Fasher predominantly consisted of\nnon-Arab communities, mainly the Zaghawa. The displacement camps around the city hosted\ndisplaced persons predominantly from the Fur community, as well as Berti, Masalit and Tama,\nparticularly persons who had endured multiple waves of displacement from across the five\nDarfur states, starting from the conflict of 2003 and 2004.11"},{"id":"a-hrc-61-77-p0022","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"22","seq":24,"section":"B. The people of El Fasher and repeated displacement","text":"Several witnesses described repeated cycles of flight and return. They recounted\nfleeing neighbourhoods within El Fasher following attacks by the Rapid Support Forces,\nultimately seeking refuge in the Zamzam displacement camp, and after the fall of the camp,\nreturning temporarily to neighbourhoods inside the city, before being forced to flee again\nfollowing the takeover. Each displacement compounded existing vulnerabilities, particularly\nfor women, children and elderly persons.12"},{"id":"a-hrc-61-77-p0023","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"23","seq":25,"section":"B. The people of El Fasher and repeated displacement","text":"Survivors consistently reported that the Rapid Support Forces had openly stated their\nintention to target non-Arab communities. Witnesses had heard the Rapid Support Forces\nsaying: “Is there anyone Zaghawa among you? If we find Zaghawa, we will kill them all”.\n“We want to eliminate anything black from Darfur.” “What are you doing in this town? We\nwill carry out extermination against you, an extermination like what we did to Masalit.”\nOthers reported statements asserting that Darfur (meaning “the house of the Fur”) now\nbelonged to the Arabs, and that its name would be changed to “house of Arabs”."},{"id":"a-hrc-61-77-p0024","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"24","seq":26,"section":"IV. Conditions of life imposed through the siege","text":"In the words of one interviewee: “Life became unbearable. We were eating only\nombaz – the food for livestock. When there was no more, we ate the skin of the animal. We\nsoaked it in water and ate.”"},{"id":"a-hrc-61-77-p0025","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"25","seq":27,"section":"A. Starvation and the collapse of medical services","text":"In its previous report, the mission described the starvation tactics and the attacks on\nmedical facilities in and around El Fasher.13 It had received fresh accounts from survivors\ndescribing the severe and progressively worsening food shortages during the siege. Markets\nwere repeatedly attacked, looted or forced to close, supply routes into the city were\nsystematically cut, and trucks carrying food were denied entry or attacked.14 Persons trying\nto move in and out of El Fasher to obtain food risked being shot or detained. Prices of basic\ngoods rose beyond the reach of most residents, and food became entirely unavailable for\nextended periods."},{"id":"a-hrc-61-77-p0026","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"26","seq":28,"section":"A. Starvation and the collapse of medical services","text":"Those in El Fasher increasingly relied on community kitchens (takiyas), which\nprovided limited shared meals, but even those were attacked. Survivors described how they\nresorted to extreme measures, including eating animal fodder (ombaz), tree leaves or residual\npeanut oil. Even those items became prohibitively expensive. People were dying from severe\nmalnutrition and starvation, particularly children and older persons."},{"id":"a-hrc-61-77-p0027","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"27","seq":29,"section":"A. Starvation and the collapse of medical services","text":"Water also became increasingly scarce. Survivors described the damage to or\ndestruction of water infrastructure, electricity networks and health facilities. Water systems\nwere destroyed, leading to reliance on unsafe water sources, and increasing the spread of\ndisease. The continuous shelling further prevented access to any remaining water sources."},{"id":"a-hrc-61-77-p0028","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"28","seq":30,"section":"A. Starvation and the collapse of medical services","text":"Medical supplies were critically limited, and health facilities were repeatedly attacked,\nleading many to cease functioning. At the time of the takeover, only the Saudi Hospital\nremained operational, but its capacity was severely compromised by shortages of medicine\n11 See https://news.un.org/en/story/2024/05/1149281; and A/HRC/60/22, para. 31.\n12 See https://www.unhcr.org/sites/default/files/2025-11/Flash Update %231 - Darfur and Kordofan\nSituation.pdf.\n13 A/HRC/60/22, paras. 88–104.\n14 Ibid., paras. 71–115.\nand equipment, intermittent electricity, and diminishing staff levels. Patients suffering from\ntreatable illnesses, such as malaria, or moderate injuries, 15 died because of inadequate care."},{"id":"a-hrc-61-77-p0029","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"29","seq":31,"section":"A. Starvation and the collapse of medical services","text":"Attacks on humanitarian facilities, convoys and health workers, as well as\nbureaucratic restrictions imposed, have already been documented, in the mission’s previous\nreport; these have significantly impeded humanitarian operations and resulted in denial of\nhumanitarian access. The mission invoked the war crime of starvation, which may also\namount to the crime against humanity of extermination, owing to the combined effects of\ndeprivation of access to food and medicine, including through repeated shelling and\nindiscriminate attacks on critical civilian infrastructure, and attacks on and obstruction of\nhumanitarian assistance.16"},{"id":"a-hrc-61-77-p0030","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"30","seq":32,"section":"B. Restriction of movement and prevention of civilian escape","text":"By mid-2024, the Rapid Support Forces had established positions along key southern\nand eastern corridors, effectively tightening the siege, with devastating results. Evidence\ncollected confirmed that, months before the takeover, the Rapid Support Forces had\nconstructed earthen berms with trenches encircling El Fasher. Survivors described these\nberms as being approximately 2 metres wide and more than 2.5 metres deep. The Yale School\nof Public Health’s Humanitarian Research Lab identified more than 31 km of earthen walls\nsurrounding the city since May 2025, enabling the Rapid Support Forces to control and\nprevent movements.17"},{"id":"a-hrc-61-77-p0031","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"31","seq":33,"section":"B. Restriction of movement and prevention of civilian escape","text":"Survivors consistently reported that, as the siege tightened, residents were largely\nunable to flee. Multiple checkpoints manned by the Rapid Support Forces exposed residents,\nparticularly men, to significant risks of being captured, robbed, detained and/or killed. One\ninterviewee described assisting in the clandestine evacuation of women, children and elderly\npeople in the months preceding the city’s takeover, while men stayed away from the exit\npoints for fear of being shot. These restrictions effectively trapped civilians inside El Fasher,\nwithout adequate water and food, medical care, or protection."},{"id":"a-hrc-61-77-p0032","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"32","seq":34,"section":"C. Last six months of the siege","text":"Due to the constant shelling of El Fasher, many inhabitants left and went to the\nZamzam or Abu Shouk displacement camps, where there was relative calm in the initial\nstages of the siege, due to the presence of Joint Forces and Sudanese Armed Forces bases\nclose by. However, towards the end of 2024, these camps also became targets of repeated\nshelling and ground attacks, leading to civilian casualties, destroyed shelters and markets,\nand repeated forced displacement within already overcrowded sites."},{"id":"a-hrc-61-77-p0033","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"33","seq":35,"section":"C. Last six months of the siege","text":"The mission previously reported on the major attack on Zamzam Camp, where\npredominantly those displaced from the Fur community lived, that was launched by the Rapid\nSupport Forces from 11 to 14 April 2025, killing over 1,000 inhabitants. 18 The Rapid Support\nForces used their usual modus operandi. The inhabitants were chased out from the third day\nof the attack, with some fleeing back to El Fasher."},{"id":"a-hrc-61-77-p0034","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"34","seq":36,"section":"C. Last six months of the siege","text":"In the months preceding the takeover of El Fasher, the areas under the protection of\nthe Sudanese Armed Forces and the Joint Forces were limited to the centre of El Fasher,\nwestern neighbourhoods including Daraja Oula, the Abu Shouk (“Naivasha”) displacement\ncamp, and the surrounding Abu Shouk neighbourhood in the north, predominantly populated\nby the Fur, the Zaghawa and other non-Arab communities. These areas were subjected to\nintense shelling. The Rapid Support Forces repeatedly entered these areas to loot and to\nassault, detain and/or kill inhabitants, particularly men, before withdrawing again. The fate\nand whereabouts of those taken remain unknown. Given the intensity of the attacks on Abu\nShouk Camp, most inhabitants fled in the weeks preceding the takeover of El Fasher to the\nAbu Shouk or Daraja Oula neighbourhoods."},{"id":"a-hrc-61-77-p0035","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"35","seq":37,"section":"C. Last six months of the siege","text":"Women were specifically targeted on the basis of their gender intersecting with their\nethnicity. A survivor said that a few weeks before the takeover, she had been abducted and\ndetained in a container. She had been flogged and raped by members of the Rapid Support\nForces, who had accused her of being “a woman of the Joint Forces”."},{"id":"a-hrc-61-77-p0036","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"36","seq":38,"section":"C. Last six months of the siege","text":"On 19 September 2025, a Rapid Support Forces drone struck Al-Safiya Mosque in\nDaraja Oula during dawn prayers, killing around 70 individuals, including 11 children, and\ninjuring many others. Survivors said that many of their family members had been killed in\nthe attack. On 8 October 2025, another Rapid Support Forces attack targeted a mosque in the\nAbu Shouk neighbourhood, killing and injuring residents. 19"},{"id":"a-hrc-61-77-p0037","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"37","seq":39,"section":"C. Last six months of the siege","text":"Further attacks on the Abu Shouk neighbourhood occurred on 10 and 11 October 2025,\nwhen Rapid Support Forces artillery and drones struck the Dar al-Arqam Centre, an\neducational institute that had been converted into a site sheltering internally displaced persons\nand hosting a communal kitchen, as well as houses adjacent to the Centre. 20 Survivors\ndescribed the Centre being hit by multiple munitions, and seeing around 30 to 50 bodies in\nthe aftermath of the attack, including many women and at least 17 children. 21"},{"id":"a-hrc-61-77-p0038","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"38","seq":40,"section":"C. Last six months of the siege","text":"By the time the Rapid Support Forces entered the city, its residents were physically\nweakened, malnourished, traumatized, and in part unable to flee, leaving them defenceless\nagainst the extreme level of violence that ensued."},{"id":"a-hrc-61-77-p0039","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"39","seq":41,"section":"V. Three days of horror – the taking of El Fasher","text":"In the preceding days, survivors described a rapid collapse of security and of\nhumanitarian conditions, and as the Rapid Support Forces’ strikes intensified, the counterfire\nby the Sudanese Armed Forces and the Joint Forces diminished."},{"id":"a-hrc-61-77-p0040","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"40","seq":42,"section":"V. Three days of horror – the taking of El Fasher","text":"On 24 October 2025, the Sudanese Armed Forces received orders to withdraw from\nEl Fasher and hand over responsibility for the protection of civilians to the Joint Forces. On\n25 October 2025, the Sudanese Armed Forces vacated the Sixth Infantry Division\nheadquarters and began to withdraw from the city to the west. Some soldiers warned civilians\nthat they were withdrawing and told them to flee. Other soldiers were cut off, continued to\nresist, fled, or were killed while attempting to surrender, or once they were hors de combat."},{"id":"a-hrc-61-77-p0041","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"41","seq":43,"section":"V. Three days of horror – the taking of El Fasher","text":"In the early hours of 26 October 2025, while shelling continued, the Rapid Support\nForces entered the city and consolidated their control from multiple directions, deploying\nlarge numbers of vehicles."},{"id":"a-hrc-61-77-p0042","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"42","seq":44,"section":"V. Three days of horror – the taking of El Fasher","text":"Some Joint Forces elements broke out from the city as the defence collapsed, while\nothers went into hiding or were killed. The use of sophisticated jamming equipment by the\nRapid Support Forces blocked communication between the defenders, contributing to a\nbreakdown of command and control and the ultimate collapse of the final defence put up by\narmed civilians."},{"id":"a-hrc-61-77-p0043","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"43","seq":45,"section":"V. Three days of horror – the taking of El Fasher","text":"During the night of 25 to 26 October 2025, residents increasingly attempted to flee,\nparticularly along routes toward Tawilah and other areas outside the berms, but the Rapid\nSupport Forces were positioned to intercept escape attempts. Multiple accounts describe\nthose attempting to leave being shot at, intercepted by vehicles, forced back or trapped at exit\npoints.\n19 See https://x.com/UNOCHA_Sudan/status/1976235317108805841 and\nhttps://www.ajnet.me/politics/2025/10/9/‫مسجد‬-‫قصف‬-‫السريع‬-‫الدعم‬-‫تكرار‬-‫تفاصيل‬.\n20 See https://www.ajnet.me/news/2025/10/11/30-‫قتيال‬.\n21 See https://www.unicef.org/press-releases/least-17-children-reportedly-killed-attack-displacement-\ncentre-north-darfurs-al."},{"id":"a-hrc-61-77-p0044","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"44","seq":46,"section":"1. Killings throughout the city","text":"Survivors consistently spoke of widespread killings, including indiscriminate\nshootings and point-blank executions of civilians in homes, streets, open areas or while\nattempting to flee the city, particularly in the neighbourhoods that had previously been\nprotected by the Sudanese Armed Forces or the Joint Forces, including the Daraja Oula and\nAbu Shouk neighbourhoods, the Grand Market area and the airport. They described\nindividuals being gunned down in the streets, trenches and public buildings where they were\nhiding, while bodies of men, women and children filled the roads. One survivor, fleeing\ntogether with 23 others, recounted walking past many corpses when they were attacked by\nRapid Support Forces in several vehicles, leaving only seven survivors. He was injured in\nthe shoulder, whipped, beaten and detained."},{"id":"a-hrc-61-77-p0045","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"45","seq":47,"section":"1. Killings throughout the city","text":"Another survivor described how she and 20 family members had been ambushed by\nthe Rapid Support Forces in several vehicles at the Zeriba (the livestock market, to the\nnortheast of El Fasher) during which seven persons had been taken and killed. One of the\nperpetrators apparently stated: “I am from the Mahri Arabs, and the Joint Forces killed our\npeople, and today we will kill you all.” When she responded they were civilians, she was\nwhipped on the head."},{"id":"a-hrc-61-77-p0046","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"46","seq":48,"section":"1. Killings throughout the city","text":"One survivor described hiding near the airport fence, about 150 metres from a\nmassacre site, as many vehicles belonging to the Rapid Support Forces approached those\ntrying to flee. The perpetrators asked whether those fleeing were “Falangiyat, soldiers or\ncivilians”. Irrespective of the response, the men were killed. The survivor also witnessed a\nwoman, holding a child, being killed, and a young woman being taken away. Other survivors\nsaw corpses in civilian clothes near the airport, either shot or run over. Several survivors\nreported lying down among corpses, pretending to be dead, on the roads out of El Fasher\nwhen vehicles of the Rapid Support Forces approached."},{"id":"a-hrc-61-77-p0047","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"47","seq":49,"section":"2. Mass executions at exit points","text":"From 26 October 2025, the Rapid Support Forces rounded up those trying to leave the\ncity at three main exit points: on the northern axis towards Mellit, on the El Fasher–Garni\nroad (north-west of El Fasher)22 and on the El Fasher–Tawilah road (south-west of El Fasher).\nThese three exits led to areas not under the control of the Rapid Support Forces. 23"},{"id":"a-hrc-61-77-p0048","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"48","seq":50,"section":"2. Mass executions at exit points","text":"At these exit points, survivors described the Rapid Support Forces separating men\nfrom women and children, while beating, detaining or executing them, and accusing them of\nsupporting the Sudanese Armed Forces and/or the Joint Forces. Verified videos show the\nRapid Support Forces holding large groups of men in civilian clothes, labelling them\n“Falangiyat”, chanting “Allahu akbar” and beating them with sticks."},{"id":"a-hrc-61-77-p0049","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"49","seq":51,"section":"2. Mass executions at exit points","text":"Several survivors described a recurring pattern whereby the Rapid Support Forces\nintercepted those fleeing collectively, held them, and executed the men in groups. According\nto one, the Rapid Support Forces gathered ten to twenty men together in groups, often tied\ntheir hands, and later killed them."},{"id":"a-hrc-61-77-p0050","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"50","seq":52,"section":"2. Mass executions at exit points","text":"Although men were disproportionately targeted for execution, women and children\nwere not spared. Most of the corpses were left unburied along the exit routes."},{"id":"a-hrc-61-77-p0051","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"51","seq":53,"section":"3. Mass executions at the berms","text":"The earthen berms and trenches constructed by the Rapid Support Forces around El\nFasher became locations where the Rapid Support Forces separated, detained and killed\ncivilians. There, the Rapid Support Forces opened fire indiscriminately on those attempting\nto flee, killing those who could not get out of the berms or move away quickly. The wounded\nwere executed at close range. 24 Witnesses saw burned military and civilian vehicles, and\nhundreds of corpses in and around the berms, including men in civilian clothing with bound\nhands, as well as women, elderly persons and children."},{"id":"a-hrc-61-77-p0052","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"52","seq":54,"section":"3. Mass executions at the berms","text":"One survivor witnessed a Rapid Support Forces commander ordering the execution\nof men after questioning whether they were soldiers or civilians. He saw eight men being\nshot dead and saw what he estimated as hundreds of bodies in or around the berms. Other\nsurvivors described being separated from male family members, who were then executed, or\nwitnessing women and girls being killed. Men who were not killed were blindfolded, bound\nand transported to unknown locations, while the perpetrators chanted “slaves, slaves, slaves”."},{"id":"a-hrc-61-77-p0053","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"53","seq":55,"section":"3. Mass executions at the berms","text":"The Rapid Support Forces also recorded and circulated videos of themselves\nexecuting people at the berms, chanting ethnic or religious slogans. Survivors’ testimonies\ncorroborated multiple videos showing members of the Rapid Support Forces accusing people\nof being “Falangai/Falangayat” or “Abolda”, which are derogatory slurs linked to the victims’\nperceived ethnic identity and political affiliation."},{"id":"a-hrc-61-77-p0054","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"54","seq":56,"section":"3. Mass executions at the berms","text":"Three separate verified videos of 27 October 2025 show a notorious Rapid Support\nForces commander known as “Abu Lulu” executing detained individuals in civilian clothes,\nseated or lying in trenches. The detainees were forced to chant slogans such as “Hemedti is\non top” or “My master is Abu Lulu” while Abu Lulu said to one of the injured detainees,\n“I swear to God if you were Burhan himself, I would rape you”. Survivors identified “Abu\nLulu”, known as the “Butcher of El Fasher” for his ruthlessness, as having personally carried\nout executions of defenceless persons in multiple locations, including at the berms."},{"id":"a-hrc-61-77-p0055","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"55","seq":57,"section":"4. Killings at El Fasher University","text":"Thousands of persons, largely civilians, sought refuge at El Fasher University,\nattempting to escape the shelling and killings in the streets. The Rapid Support Forces\ntargeted the university through shelling and drone strikes, killing and injuring civilians\nsheltering there. During the morning of 26 October 2025, before their withdrawal from El\nFasher University, the Sudanese Armed Forces informed the civilians that they were no\nlonger able to protect them and advised them to leave. What ensued made El Fasher\nUniversity one of the bloodiest execution sites in the city."},{"id":"a-hrc-61-77-p0056","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"56","seq":58,"section":"4. Killings at El Fasher University","text":"At around 5 p.m., people started to flee the university collectively. However, the Rapid\nSupport Forces had surrounded the campus and opened fire on those attempting to leave,\nreferring to them as “Falangiyat”. Many were killed, while others were trapped inside the\nuniversity buildings."},{"id":"a-hrc-61-77-p0057","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"57","seq":59,"section":"4. Killings at El Fasher University","text":"Survivors described the Rapid Support Forces commander, who identified himself as\n“Abu Lulu”, as particularly ruthless. He became known as the “Butcher of El Fasher”. On\n27 October 2025, a family of 13 was forced at gunpoint to walk to El Fasher University,\npassing numerous corpses along the way. Upon arrival, “Abu Lulu” identified himself,\nshouting, “I will kill you like fat autumn locusts.” Shooting at people at random and killing\nseveral, at one stage he stopped, saying, “I was planning to kill 2,000 people today, but I lost\ncount, so I will start all over again”. He resumed the shooting."},{"id":"a-hrc-61-77-p0058","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"58","seq":60,"section":"4. Killings at El Fasher University","text":"Two survivors witnessed “Abu Lulu” asking a pregnant woman how far she was into\nher pregnancy. When she responded “seven months”, he fired seven bullets into her abdomen,\nkilling her. Multiple witnesses described him moving through the university buildings,\nordering people out of rooms and shooting them. At some stage, other members of the Rapid\nSupport Forces stopped him. By then, hundreds of men, women and children had already\nbeen killed."},{"id":"a-hrc-61-77-p0059","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"59","seq":61,"section":"4. Killings at El Fasher University","text":"Another survivor, hiding with others in a university room, described Rapid Support\nForces storming the campus while shouting: “Soldiers, come out, wives of soldiers, come out.\nSoldiers, do not hide among the women.” Those who identified themselves as soldiers were\nkilled immediately. Civilians, including women and children, were also killed. One witness\ndescribed how 15 people had been killed in front of her. Some had been executed, while\n24   See https://www.facebook.com/reel/1409599147834443 and https://sudanwarmonitor.com/p/rsf-\nethnic-based-killings-in-fasher.\nothers had been hit by random bullets. Another witness, who entered the university building\nlater, found 150 to 200 bodies there."},{"id":"a-hrc-61-77-p0060","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"60","seq":62,"section":"4. Killings at El Fasher University","text":"One survivor, found alive while the Rapid Support Forces were inspecting bodies and\nlooting in the university area, was asked about his tribe. After identifying himself as Zaghawa,\nhe was tied to a vehicle and was dragged until he was unconscious. Later, two other\nperpetrators said: “We will exterminate you, [as] we did to Masalit.” They whipped him, tied\na rope fastened to a camel around his neck, and dragged him back to the university."},{"id":"a-hrc-61-77-p0061","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"61","seq":63,"section":"4. Killings at El Fasher University","text":"People hiding near the university reported seeing numerous corpses lying on the\nground, including in surrounding trenches. Some of the injured lay among the dead for hours,\nwithout assistance. One interviewee witnessed a Rapid Support Forces commander opening\nfire on dozens of people hiding at the Faculty of Education."},{"id":"a-hrc-61-77-p0062","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"62","seq":64,"section":"4. Killings at El Fasher University","text":"Videos verified by the mission confirm large numbers of bodies inside the main\nuniversity building. Footage includes that of a fighter executing a wounded person lying\namong other injured and deceased persons inside the Faculty of Medical Laboratory Sciences."},{"id":"a-hrc-61-77-p0063","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"63","seq":65,"section":"5. Killings at the Saudi Hospital","text":"Hospitals, medical personnel and the sick and wounded were not spared. The World\nHealth Organization reported that on 26 October 2025, the Saudi Hospital was hit by heavy\nshelling, killing one nurse and injuring three health workers. 25 A survivor described seeing\nmembers of the Rapid Support Forces entering the building with large rifles threatening\npatients and firing in the air while asking those present if they were “Falangayat”. She\nmanaged to escape, but continued to hear gunshots for approximately one hour."},{"id":"a-hrc-61-77-p0064","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"64","seq":66,"section":"5. Killings at the Saudi Hospital","text":"In the days following, the Rapid Support Forces stormed the hospital. One survivor\nsaid he heard them saying, “We want to destroy you all.” They proceeded to search the wards\nand to kill those they found, including patients, people accompanying them, and medical\npersonnel. Doctors took off their white attire so as not to be targeted. Six health workers –\nfour doctors, a nurse and a pharmacist – were abducted.26 A civilian and an hors de combat\nsoldier were killed in front of their wives, who survived, as were many other men present in\nthe same ward. Children as young as 8 were also killed. Overall, it is estimated that more\nthan 460 patients and others present were killed. According to satellite imagery analysed by\nthe Yale Humanitarian Research Lab, the corpses were later burned.27"},{"id":"a-hrc-61-77-p0065","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"65","seq":67,"section":"5. Killings at the Saudi Hospital","text":"The Rapid Support Forces filmed themselves in front of the Saudi Hospital together\nwith affiliated armed fighters, looting civilian vehicles and celebrating their control over the\narea."},{"id":"a-hrc-61-77-p0066","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"66","seq":68,"section":"5. Killings at the Saudi Hospital","text":"In the early morning of 26 October 2025, at least nine people, including one young\nwoman and two girls, were brought to the University Health Centre with bullet wounds.\nWhen the Rapid Support Forces subsequently stormed the Centre with machine guns,\nshouting “Where is the army?”, over 30 sick and wounded persons and those accompanying\nthem were killed."},{"id":"a-hrc-61-77-p0067","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"67","seq":69,"section":"6. Continued killings and executions on the road","text":"One witness told the mission: “There were bodies everywhere. Some bodies were torn\nto pieces.”"},{"id":"a-hrc-61-77-p0068","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"68","seq":70,"section":"6. Continued killings and executions on the road","text":"Survivors reported that flight did not bring safety. Civilians endured successive cycles\nof life-threatening dangers: shelling and killings inside El Fasher, shootings and executions\nat the berms around El Fasher and at exit points, and renewed attacks along escape routes."},{"id":"a-hrc-61-77-p0069","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"69","seq":71,"section":"6. Continued killings and executions on the road","text":"Survivors fled in small groups, often at night or in the early morning, to reduce\ndetection. Families were frequently separated to increase their chances of survival, with men\nmoving separately from women and children, while the elderly, or sick relatives, were\nsometimes left behind. Multiple men disguised themselves as women to escape discovery,\nalthough some were found and killed. Many survivors reported not seeing separated family\nmembers again or later learning that they had been killed."},{"id":"a-hrc-61-77-p0070","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"70","seq":72,"section":"6. Continued killings and executions on the road","text":"The Rapid Support Forces pursued fleeing civilians along escape routes towards Jabal\nWana, Tawilah, Garni, and rural areas around El Fasher, where they had established\nambushes and checkpoints. Survivors described the perpetrators chasing people in open\nfields, firing at them with automatic rifles and mounted submachine guns, and running over\nfleeing persons with vehicles, causing mass casualties. Survivors estimated that hundreds of\npersons had been killed in this manner. Verified video material supports this claim."},{"id":"a-hrc-61-77-p0071","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"71","seq":73,"section":"6. Continued killings and executions on the road","text":"One survivor stated that of 63 civilians fleeing together one night, only seven reached\nTawilah alive, with the remainder killed by Rapid Support Forces gunfire during the journey.\nOthers described members of the Rapid Support Forces filming themselves as they opened\nfire on groups. One such incident took place at Golo, where the Rapid Support Forces shot\nindiscriminately at hundreds of people attempting to flee."},{"id":"a-hrc-61-77-p0072","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"72","seq":74,"section":"6. Continued killings and executions on the road","text":"In Jabal Wana, survivors recounted the Rapid Support Forces saying, “If we had killed\nyou in 2003, you would not have come to fight us in 2023. You are Falangiyat, you are the\nJoint Forces”, killing children as young as 2 years old. One survivor reported seeing a young\nboy being flogged while hanging from a tree, after his four brothers and his parents had been\nkilled, and stated that he had later succumbed to his wounds."},{"id":"a-hrc-61-77-p0073","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"73","seq":75,"section":"6. Continued killings and executions on the road","text":"Even if some of the men chased and killed were Sudanese Armed Forces or Joint\nForces members, the mission’s information indicates that they were hors de combat and\ntherefore protected."},{"id":"a-hrc-61-77-p0074","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"74","seq":76,"section":"1. Rape and other forms of sexual violence","text":"One interviewee told the mission: “They raped me in front of the bodies of my mother,\nmy father and my slaughtered brother.”"},{"id":"a-hrc-61-77-p0075","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"75","seq":77,"section":"1. Rape and other forms of sexual violence","text":"At the centre of the takeover and its aftermath were widespread, systematic and\ncoordinated acts of sexual violence primarily targeted at women and girls from non-Arab\ncommunities, particularly the Zaghawa. Women and girls ranging from 7 to 70 years old,\nincluding pregnant women, were subjected to rape and other forms of sexual and\ngender-based violence. This included acts of killings, whipping, beating, humiliation, forced\nnudity and sexual harassment, while their belongings were looted. Survivors consistently\nreported that numerous women had been raped during the same incidents, which indicates\nthat the cases documented by the mission represent only a fraction of a far wider pattern.\n(a)    Mass and gang rape"},{"id":"a-hrc-61-77-p0076","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"76","seq":78,"section":"1. Rape and other forms of sexual violence","text":"The mission has collected a substantial body of corroborated information\ndemonstrating that widespread rape, mass rape and gang rape, abduction and other forms of\nsexual violence began immediately following the takeover of El Fasher. Women and girls\nfrom non-Arab communities, particularly the Zaghawa, and those perceived as Sudanese\nArmed Forces or Joint Forces supporters, were the primary victims."},{"id":"a-hrc-61-77-p0077","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"77","seq":79,"section":"1. Rape and other forms of sexual violence","text":"Many survivors reported being raped in front of their relatives, including children,\nintensifying the humiliation and psychological harm of all victims involved. Multiple\nperpetrators assaulted victims in succession during the same incident, with assaults being\ncarried out in private homes, public buildings, hospitals and open spaces, including escape\nroutes."},{"id":"a-hrc-61-77-p0078","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"78","seq":80,"section":"1. Rape and other forms of sexual violence","text":"Sexual violence was frequently accompanied by extreme physical brutality, including\nbeating and whipping. Survivors described having their clothes forcibly torn off, leaving\nthem completely naked, while their hands were tied to prevent resistance. Rapes occurred\nboth vaginally and anally, sometimes with the insertion of sharp objects, and were often\naccompanied by ethnic slurs and threats."},{"id":"a-hrc-61-77-p0079","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"79","seq":81,"section":"1. Rape and other forms of sexual violence","text":"Multiple survivors also reported that male relatives had been killed while trying to\nprotect them. In one case, a 12-year-old girl was raped by three Rapid Support Forces fighters\nin front of her mother, shortly after her father had been killed while trying to protect her. The\ngirl later died from her injuries before reaching hospital in Tawilah. One woman reported\nbeing raped by two fighters, alongside at least 10 other women, after witnessing men and\nchildren being killed."},{"id":"a-hrc-61-77-p0080","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"80","seq":82,"section":"1. Rape and other forms of sexual violence","text":"Sexual violence continued during the flight, particularly along the main exit routes\nout of El Fasher, towards Tawilah, Garni, Jabal Wana and Mellit, as well as in Garni, Golo\nand Shagra. One survivor stated that after fleeing Daraja Oula and reaching Jabal Wana on\n27 October 2025, the Rapid Support Forces killed many children, mutilated a woman by\ncutting off her breast with a knife, and raped several others, including herself. The mission\nheard numerous accounts of women, especially from the Zaghawa community, being\ngang-raped in forests along escape routes.\n(b)     Abduction and sexual violence"},{"id":"a-hrc-61-77-p0081","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"81","seq":83,"section":"1. Rape and other forms of sexual violence","text":"Survivors reported the systematic abduction of women and girls by the Rapid Support\nForces. Several described seeing victims, frequently below 18 years of age, being physically\nrestrained and transported to unknown locations. More investigations are needed regarding\nthese abductions, which may reflect a pattern of exploitation and amount to enforced\ndisappearances."},{"id":"a-hrc-61-77-p0082","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"82","seq":84,"section":"1. Rape and other forms of sexual violence","text":"One survivor described being abducted in late October 2025 on her way to Tawilah,\nafter identifying herself as Zaghawa. The Rapid Support Forces took her to a remote area,\ntied her to a tree, left her naked and repeatedly raped her over six days. She eventually\nmanaged to escape. Her prolonged deprivation of liberty, combined with repeated sexual\nviolence, constitutes sexual slavery.\n(c)     Rape in the presence of corpses"},{"id":"a-hrc-61-77-p0083","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"83","seq":85,"section":"1. Rape and other forms of sexual violence","text":"Rape was often committed in locations where mass killings had taken place, including\nat the Saudi Hospital and at El Fasher University. Witnesses recounted the Rapid Support\nForces violently and publicly gang-raping at least 19 women in rooms filled with corpses,\nincluding the remains of their own husbands. The women were called “Falangiya”. One\nsurvivor described seeing a woman being raped in Jabal Wana in front of the body of her\n2-year-old son, who had just been killed.\n(d)     Normalization of acts of sexual violence"},{"id":"a-hrc-61-77-p0084","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"84","seq":86,"section":"1. Rape and other forms of sexual violence","text":"The Rapid Support Forces conducted invasive body searches of fleeing women and\ngirls they intercepted, including forcing women to lift their clothes or have their bodies\ntouched under the pretext of searching for money, gold or mobile phones."},{"id":"a-hrc-61-77-p0085","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"85","seq":87,"section":"1. Rape and other forms of sexual violence","text":"Survivors consistently reported that sexual violence, including rape, was perpetrated\nopenly and publicly by the Rapid Support Forces while others were forced to watch and were\nprevented from leaving. In addition, survivors widely reported that perpetrators appeared\ncalm, deliberate, and fully aware of their actions."},{"id":"a-hrc-61-77-p0086","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"86","seq":88,"section":"1. Rape and other forms of sexual violence","text":"The Rapid Support Forces sometimes filmed rape and other acts of violence against\nwomen and girls. One verified video shows Rapid Support Forces fighters mocking and\npoking the corpse of a woman, calling her “the slave of El Fasher”. In another video, a female\nmember of the Rapid Support Forces publicly encouraged her male comrades to rape.\n(e)     Gender and ethnic dimension"},{"id":"a-hrc-61-77-p0087","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"87","seq":89,"section":"1. Rape and other forms of sexual violence","text":"The violence demonstrated a dual ethnic and gender dimension. By killing or\nremoving men and systematically assaulting women and girls, the Rapid Support Forces\nattacked the very fabric of the group, undermining its survival. Evidence shows that women\nand girls were not victims of opportunistic violence but were directly targeted as part of a\nbroader campaign of terror and collective punishment against their community."},{"id":"a-hrc-61-77-p0088","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"88","seq":90,"section":"1. Rape and other forms of sexual violence","text":"The sexual violence was closely linked to ethnic targeting, particularly against\nZaghawa. Survivors reported the Rapid Support Forces stating: “We have to empty El Fasher\nof the Falangiyat.” “These are slaves. Kill them, destroy them, rape them.” “We are your only\nmen, no other men.” “We are allergic to Zaghawa.” “You must give birth to our children.”\nWomen who identified themselves as Arab or who, in the eyes of perpetrators, appeared Arab,\nwere spared. One Zaghawa survivor said that she managed to avoid rape by pretending to be\nArab, and speaking their dialect, and because she was light-skinned."},{"id":"a-hrc-61-77-p0089","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"89","seq":91,"section":"1. Rape and other forms of sexual violence","text":"Survivors reported that members of the Rapid Support Forces used terms such as\n“marry”, “bride” and “our ladies” to assert ownership and intimidate women and girls before\nraping them. The perpetrators told one woman, while raping her in front of her children:\n“Now El Fasher is under our control. You will come back to us and you will be our ladies”,\nechoing a pattern of ownership language."},{"id":"a-hrc-61-77-p0090","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"90","seq":92,"section":"2. Detention, torture, humiliation, extortion, ransom and disappearances","text":"The mission documented a widespread and systematic pattern of detention and\nenforced disappearance of civilians and persons hors de combat by the Rapid Support Forces.\nThese occurred particularly at berms and checkpoints and along escape routes. Survivors\ndescribed members of the Rapid Support Forces intercepting those fleeing, accusing them of\naffiliation with the Sudanese Armed Forces or the Joint Forces and using ethnic slurs. The\nperpetrators would rob their victims of their belongings and detain them in vehicles, shipping\ncontainers, makeshift checkpoints or detention sites, often pending payments of ransom.\nWhile many are detained in Nyala and Garni, the fate and whereabouts of many others remain\nunknown."},{"id":"a-hrc-61-77-p0091","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"91","seq":93,"section":"2. Detention, torture, humiliation, extortion, ransom and disappearances","text":"Individuals were often asked to declare their tribal affiliation. Survivors described\nmen and boys being separated from women, girls and elderly persons. Men and boys were at\nheightened risk of execution, torture, arbitrary detention and/or enforced disappearance.\nBound and with their eyes covered, they were taken away in trucks belonging to the Rapid\nSupport Forces. Verified video footage shows detainees being transported on or around\n26 and 27 October 2025 by the Rapid Support Forces."},{"id":"a-hrc-61-77-p0092","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"92","seq":94,"section":"2. Detention, torture, humiliation, extortion, ransom and disappearances","text":"Women were not spared. In one documented incident, the Rapid Support Forces\ndetained four women, tying them to a cart and dragging it behind a vehicle for about one\nkilometre, resulting in their deaths."},{"id":"a-hrc-61-77-p0093","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"93","seq":95,"section":"2. Detention, torture, humiliation, extortion, ransom and disappearances","text":"Torture and other forms of cruel, inhuman and degrading treatment were widespread.\nThe Rapid Support Forces subjected detainees and civilians to severe humiliation and\nphysical abuse. One detainee held in a police cell described guards throwing food on the floor,\nurinating on detainees, and referring to them as “dogs”. He further reported being burned\nwith hot irons and subjected to severe mutilation. Severe beatings with sticks, whips, metal\ntools and pliers were common, as was deprivation of adequate food and water, or medical\nassistance."},{"id":"a-hrc-61-77-p0094","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"94","seq":96,"section":"2. Detention, torture, humiliation, extortion, ransom and disappearances","text":"Survivors described being held outside, or in overcrowded, filthy cells with\ninadequate sanitation and few windows. Many were subjected to forced labour, including\ncarrying ammunition, transporting weapons or digging graves. Some survivors described\ndetainees dying in custody because of wounds, starvation and lack of medical treatment."},{"id":"a-hrc-61-77-p0095","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"95","seq":97,"section":"2. Detention, torture, humiliation, extortion, ransom and disappearances","text":"From at least 26 October 2025, the Rapid Support Forces converted the former\nchildren’s hospital in El Fasher into a detention centre and execution site. Survivors reported\nbeing held at the hospital for prolonged periods. They were subjected to systematic beatings\nand ethnic-based slurs, and were forced to drink contaminated water, resulting in widespread\nillness and deaths in custody. Survivors reported hearing a mass shooting on 27 October 2025.\nThey were later forced to bury dozens of bodies. Satellite imagery analysed by the Yale\nHumanitarian Research Lab between 1 and 3 November 2025 revealed objects consistent\nwith human bodies and newly disturbed earth east of the facility, assessed as consistent with\nmass body disposal following killings likely to have occurred between 27 October and\n1 November 2025.28"},{"id":"a-hrc-61-77-p0096","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"96","seq":98,"section":"2. Detention, torture, humiliation, extortion, ransom and disappearances","text":"Extortion and ransom demands formed an integral component of the Rapid Support\nForces’ practices. Either directly or through their allies, they contacted the detainees’ families\n28   See https://files-profile.medicine.yale.edu/documents/8163d430-7a33-458e-be60-f0022a6c31d2.\nby phone, on social media or through intermediaries, demanding payment which sometimes\nreached 25 million Sudanese pounds in exchange for the detainee’s release. Survivors\nreported a sliding scale for ransom, based on ethnicity, with ransom for Zaghawa being the\nmost extortionate, followed by Fur and Masalit."},{"id":"a-hrc-61-77-p0097","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"97","seq":99,"section":"2. Detention, torture, humiliation, extortion, ransom and disappearances","text":"Witnesses also described being driven around in Rapid Support Forces vehicles while\ntheir captors contacted their relatives for ransom. In most cases, the detainees were released\nwhen the ransom was paid. The mission has documented cases where the ransom was paid\nbut the release was not effected. Those who did not pay were either killed or remained in\ndetention."},{"id":"a-hrc-61-77-p0098","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"98","seq":100,"section":"1. Deliberate starvation and destruction","text":"The conditions imposed in and around El Fasher from the time of the siege, as detailed\nbefore, amounted to a systematic destruction of the means of survival of its non-Arab\ncommunities, particularly the Zaghawa and the Fur. Through prolonged siege tactics, the\nRapid Support Forces deliberately deprived the population of food, water, medical care,\nadequate housing and basic services, dismantling the material foundations of their survival."},{"id":"a-hrc-61-77-p0099","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"99","seq":101,"section":"1. Deliberate starvation and destruction","text":"Throughout the siege, sustained shelling rendered schools inoperable, destroyed\nmarkets and shelters and forced civilians to remain in hiding for extended periods. The\ncollapse of commercial supply routes, combined with the denial of humanitarian assistance,\neliminated access to food, while repeated shelling of civilian areas and attacks on markets\nand community kitchens further exacerbated starvation. These conditions were neither\nincidental nor unavoidable consequences of hostilities; rather, they were the foreseeable and\nintended result of the Rapid Support Forces’ conduct."},{"id":"a-hrc-61-77-p0100","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"100","seq":102,"section":"1. Deliberate starvation and destruction","text":"Following the takeover, these conditions worsened dramatically: civilians could no\nlonger remain in their homes or move through the city without facing a real and immediate\nrisk of death. The seizure and effective closure of the last functioning hospital, combined\nwith the killing, abduction or flight of medical personnel, eliminated access to medical care\naltogether. Injured persons and those suffering illness were left to die untreated."},{"id":"a-hrc-61-77-p0101","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"101","seq":103,"section":"1. Deliberate starvation and destruction","text":"Inhabitants were compelled to flee the city on foot, often for days and nights, while\nwounded, severely malnourished and without access to food, water, shelter or medication.\nAlong escape routes, the Rapid Support Forces systematically robbed them of their remaining\npossessions, including clothes and shoes, further aggravating starvation and contributing to\nphysical collapse. Multiple deaths also occurred during flight due to hunger, exhaustion, and\nuntreated injuries."},{"id":"a-hrc-61-77-p0102","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"102","seq":104,"section":"1. Deliberate starvation and destruction","text":"The cumulative effect of deliberate starvation, denial of medical care, restriction of\nmovement, and violence targeted at life and physical integrity rendered survival increasingly\nimpossible. Taken together, these deliberate acts imposed conditions of life incompatible\nwith the continued existence of the targeted communities, particularly the Zaghawa and the\nFur, and were calculated to bring about their physical destruction, in whole or in part."},{"id":"a-hrc-61-77-p0103","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"103","seq":105,"section":"2. Impact on survivors","text":"It has been estimated that around 100,000 out of the estimated population of 260,000\nhas fled El Fasher since late October 2025.29 Those who were able to visit El Fasher in the\naftermath of the takeover spoke of seeing very few civilians inside the city, describing it as a\n“ghost town”.30"},{"id":"a-hrc-61-77-p0104","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"104","seq":106,"section":"2. Impact on survivors","text":"Survivors systematically emphasized the need to know the fate of their family\nmembers. Internet connections and communications in El Fasher were cut during the\ntakeover, leaving Starlink, which is controlled and monitored by the Rapid Support Forces,\nas the only way to reach the outside world. Those currently in El Fasher thus have little ability\nto freely connect with their families and friends. Most people lost members of their families\n– mothers, fathers, sons and daughters – and knowing the fate of the missing and the\ndisappeared was a recurrent demand."},{"id":"a-hrc-61-77-p0105","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"105","seq":107,"section":"2. Impact on survivors","text":"Those who left El Fasher are also suffering anxiety, loss, trauma and grief, due to their\nlived experience.31 Survivors of sexual violence reported severe and long-lasting physical\nand psychological consequences, including miscarriages, prolonged bleeding, genital and\nanal injuries, infections and urinary retention; it has even led to death. Trauma, often\naccompanied by social stigma, is common. Some became pregnant because of rape. One\nsurvivor who aborted after learning she was pregnant said: “My husband and I tried to have\nchildren and had never had a child, but to become pregnant after rape, I could not accept it.”"},{"id":"a-hrc-61-77-p0106","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"106","seq":108,"section":"2. Impact on survivors","text":"Access to medical care is extremely limited. Survivors frequently travelled for several\ndays under dangerous conditions before reaching treatment in Tawilah or Kutum, where\nmedical services were severely overstrained. At least two survivors died in Tawilah due to\nuntreated injuries. During its visit to Tine in Chad, the mission observed that many refugees\nwere women and children, often separated from male relatives. Some women had given birth\nwhile fleeing, demonstrating the intergenerational impact of the violence."},{"id":"a-hrc-61-77-p0107","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"107","seq":109,"section":"2. Impact on survivors","text":"Many children arrived at safe areas on their own or with one parent or family member\nor with strangers who picked them up along the way. It was estimated that about 400 children\narrived in Tawilah without their parents in the first month following the takeover."},{"id":"a-hrc-61-77-p0108","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"108","seq":110,"section":"D. Acts by the leadership of the Rapid Support Forces","text":"On the day of the takeover of El Fasher, the Rapid Support Forces leaders publicly\nclaimed and celebrated the operation. Deputy commander Lieutenant General Abdel Rahim\nDagalo and spokesperson Lieutenant Colonel Al-Fatih Al-Qurashi described it as a “major\nand historic military victory”, praising their forces for “liberating” the city from the “terrorist\nIslamic army”.32 He threatened opponents with the same fate as “the terrorists”,33 framing the\nassault as part of a broader campaign extending to Port Sudan and beyond."},{"id":"a-hrc-61-77-p0109","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"109","seq":111,"section":"D. Acts by the leadership of the Rapid Support Forces","text":"On 29 October 2025, the Rapid Support Forces leader, Lieutenant General Mohamed\nHamdan Dagalo (Hemedti) likewise praised the “liberation” and praised the fighters as “lions\nand heroes”. Although he acknowledged that “some violations occurred”, including looting,\nand described El Fasher as a “catastrophe”, he justified the assault, however, as necessary.\nHe issued instructions not to harm civilians or kill prisoners and promised investigations. 34\nThe mission’s request to the Rapid Response Forces to clarify the steps it has taken in this\nregard remains unanswered."},{"id":"a-hrc-61-77-p0110","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"110","seq":112,"section":"D. Acts by the leadership of the Rapid Support Forces","text":"Furthermore, these statements came after widespread killings, detentions and looting\nhad already occurred in public view. Although one commander, “Abu Lulu”, was arrested\nafter viral footage of brutality surfaced, no information has been provided regarding any\njudicial proceedings, nor have reports been dispelled that he was subsequently released."},{"id":"a-hrc-61-77-p0111","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"111","seq":113,"section":"D. Acts by the leadership of the Rapid Support Forces","text":"Survivors identified Rapid Support Forces commanders issuing orders to kill, detain\nand loot, with allied Arab militias operating under the same command structure. Survivors\ndescribed the perpetrators as wearing similar uniforms and a turban. The scale, coordination\nand public endorsement of the operation by the senior leadership of the Rapid Support Forces\npoint to a planned and organized operation executed through an established hierarchy and\nstructure, rather than isolated acts.\n31 See https://media.un.org/unifeed/en/asset/d352/d3525404.\n32 See https://t.me/RSFSudan/8089 and https://t.me/RSFSudan/8083.\n33 See https://t.me/RSFSudan/8089.\n34 See https://web.facebook.com/groups/262062521587117/posts/1566868\n297773193/?_rdc=1&_rdr#."},{"id":"a-hrc-61-77-p0112","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"112","seq":114,"section":"VI. Legal analysis and findings","text":"The mission finds that serious violations of international humanitarian law and\ninternational human rights law, amounting to international crimes, were committed by the\nRapid Support Forces in and around El Fasher during the siege and following the takeover\nof the city. While individual acts constitute war crimes and crimes against humanity, their\nconsolidation, scale, systematic nature and cumulative effects may indicate a path to genocide,\nwhen the necessary intent to destroy, in whole or in part, a national, ethnical, racial or\nreligious group (dolus specialis) is found."},{"id":"a-hrc-61-77-p0113","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"113","seq":115,"section":"VI. Legal analysis and findings","text":"In the case of The Prosecutor v. Omar Hassan Ahmad Al Bashir, the International\nCriminal Court held that the Fur, the Masalit and the Zaghawa constituted such distinct\ncharacteristics and hence were protected ethnic groups within the meaning of article 6 of the\nRome Statute concerning the crime of genocide. The Court found these groups to be stable\nand identifiable, and perceived as such by both perpetrators and victims\n(“self-identification”), which it considered the decisive criterion for determining the\nexistence of a protected group for the purposes of genocide. 35"},{"id":"a-hrc-61-77-p0114","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"114","seq":116,"section":"VI. Legal analysis and findings","text":"The mission finds that the widespread and systematic pattern of conduct of the Rapid\nSupport Forces, in particular large-scale killings committed through different means and\nmethods, mass-scale rape, gang rape and other forms of torture and cruel treatment, and\ndeliberate starvation conditions including destruction of means of survival and denial of\nmedical and humanitarian aid, imposed through the extended siege, was committed pursuant\nto a plan or policy and with knowledge and intent. This is established through numerous\nconsistent survivor testimonies, utterances and statements made by Rapid Support Forces\ncommanders and fighters while committing atrocities, verified videos and satellite imagery,\nand warnings issued by the Security Council and others that were ignored. It thus\ndemonstrates that at least three of the material crimes of genocide are overwhelmingly\npresent, namely:\n(a)    Killing members of the group;\n(b)    Causing serious bodily or mental harm to members of the group;\n(c)     Deliberately inflicting on the group conditions of life calculated to bring about\nits physical destruction in whole or in part."},{"id":"a-hrc-61-77-p0115","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"115","seq":117,"section":"VI. Legal analysis and findings","text":"The existence of dolus specialis or specific intent to destroy the protected group in\nwhole or in part is a key element of the crime of genocide. Such intent can not only be\nascertained through direct statements by perpetrators; it may also be inferred from the body\nof evidence as a whole. In this regard, based on relevant jurisprudence, consideration is to be\nhad for, among other things, the general context; the scale of atrocities; the systematic\ntargeting of victims, regardless of their status as civilians or persons hors de combat, on\naccount of their membership of the protected group; repetition of destructive or\ndiscriminatory acts; the existence of a plan or policy; and displays of intent made during\npublic speeches or in meetings.36"},{"id":"a-hrc-61-77-p0116","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"116","seq":118,"section":"VI. Legal analysis and findings","text":"In the mission’s assessment, based on a careful consideration of all other possible\nexplanations regarding intent, the only reasonable inference that can be drawn from the\npattern of conduct of the Rapid Support Forces in and around El Fasher, including the scale\nand sequence of events, the patterns of targeting, the language used by commanders and\ndirect perpetrators stating their intention to kill, eliminate and destroy all Zaghawa and the\nFur, and the cumulative impact of their acts on the victims individually and the protected\ngroup collectively, is that they acted with genocidal intent. That intent is inferred from the\nfull body of evidence collected by the mission, which the Rapid Support Forces sometimes\nsought to destroy to avoid accountability."},{"id":"a-hrc-61-77-p0117","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"117","seq":119,"section":"VI. Legal analysis and findings","text":"Other international crimes are also established by the mission, including crimes\nagainst humanity, notably extermination and persecution on ethnic, gender and political\ngrounds, as well as war crimes including murder, torture, rape and other forms of sexual\nviolence, outrages upon personal dignity, starvation, and directing attacks against civilians,\nthe wounded and sick, and persons hors de combat, as well as against protected objects. These\ncrimes have reached this level of atrocities because of impunity."},{"id":"a-hrc-61-77-p0118","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"118","seq":120,"section":"VII. Conclusions and recommendations","text":"Since the International Criminal Court issued its 2009 arrest warrant against the\nthen President, Omar al-Bashir, for genocide in Darfur, that question has remained\nbefore it. Our findings indicate that events in and around El Fasher in 2025 point to\nrenewed acts of genocide by the Rapid Support Forces."},{"id":"a-hrc-61-77-p0119","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"119","seq":121,"section":"VII. Conclusions and recommendations","text":"The mission concludes that the violence committed by the Rapid Support Forces\nin and around El Fasher forms part of a coherent, widespread and escalating course of\nconduct directed, in particular, against the Zaghawa and the Fur, in the context of a\nprolonged siege followed by a takeover marked by brutal atrocities."},{"id":"a-hrc-61-77-p0120","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"120","seq":122,"section":"VII. Conclusions and recommendations","text":"The evidence establishes a widespread and systematic pattern by the Rapid\nSupport Forces of killings, ethnically targeted rape and other forms of sexual and\ngender-based violence, arbitrary detention, torture and cruel treatment, enforced\ndisappearances, extortion and forced displacement, combined with the deliberate\nimposition of conditions of life incompatible with survival, including starvation and the\ndestruction of medical care. These acts were committed with knowledge, organization\nand repetition, and were accompanied by dehumanizing and exterminatory language."},{"id":"a-hrc-61-77-p0121","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"121","seq":123,"section":"VII. Conclusions and recommendations","text":"Taken together, the scale, severity and cumulative impact of the acts by the\nRapid Support Forces, assessed in the light of patterns of targeting, conduct, and\ninferred intent, present indications pointing to genocide in and around El Fasher."},{"id":"a-hrc-61-77-p0122","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"122","seq":124,"section":"VII. Conclusions and recommendations","text":"The mission further concludes that crimes against humanity, notably\nextermination and persecution on ethnic, gender and political grounds, as well as war\ncrimes, including murder, torture, rape and other forms of sexual violence, outrages\nupon personal dignity, starvation, and attacks against civilians, the wounded and the\nsick, and persons hors de combat, as well as against protected objects, were committed.\nThey underscore the gravity and multilayered criminality of the conduct documented."},{"id":"a-hrc-61-77-p0123","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"123","seq":125,"section":"VII. Conclusions and recommendations","text":"The atrocities committed in and around El Fasher are aggravations of earlier\npatterns of violence in Darfur, including those previously documented by the mission\nin Zamzam Camp and elsewhere, demonstrating continuity and escalation. In the\nabsence of effective prevention and accountability, the mission considers that the risk\nof further genocidal violence remains acute."},{"id":"a-hrc-61-77-p0124","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"124","seq":126,"section":"VII. Conclusions and recommendations","text":"Earlier warnings about the risk of atrocities in El Fasher did not yield concrete\nresults in protecting civilians. As the conflict now moves further, in particular to\nKordofan, marked by the same modus operandi, the international community must act\ndecisively to prevent further atrocities, hold the perpetrators of international crimes to\naccount, and bring an end to this senseless violence."},{"id":"a-hrc-61-77-p0125","rec_id":"recHPTNMHsLNQ2vIp","symbol":"A/HRC/61/77","n":"125","seq":127,"section":"VII. Conclusions and recommendations","text":"Considering its findings, and given that the conduct documented in and around\nEl Fasher presents indications pointing to genocide, as well as war crimes and crimes\nagainst humanity, the mission once again calls upon the international community to act\nwithout delay:\n(a)    To protect civilians and prevent further atrocities, including by fully\nenforcing and expanding the arms embargo, preventing the transfer of weapons,\nequipment and financial and logistical support to parties credibly implicated in serious\nviolations, and using all available diplomatic, political and preventive tools to halt\nfurther mass violence;\n(b)    To secure unrestricted humanitarian access into El Fasher and the\nguarantee of free movement of the remaining civilian population there;\n(c)    To ensure accountability and deter further crimes, including through\ntargeted sanctions against those who aid or abet the commission of international crimes,\nby fully cooperating with the International Criminal Court and expanding its\njurisdiction, and considering the establishment of a judicial mechanism working in\ntandem with the Court to advance accountability for perpetrators at all levels and\nensure justice for victims;\n(d)   To support survivors, including through interim reparatory measures and\nsustained access to medical, psychosocial and legal assistance;\n(e)    To encourage the documentation of violations and the preservation of\nevidence for accountability processes, including ensuring access for investigative bodies,\nincluding the independent international fact-finding mission for the Sudan, into El\nFasher to document and preserve evidence and ascertain the fate of missing and\ndetained persons;\n(f)    To ensure protection for lawyers, human rights defenders, humanitarian\nworkers, medical workers, journalists and civil society actors, who remain at grave risk;\n(g)    To end the suffering of the Sudanese people and align with their\naspirations for justice, stability and prosperity in the design of any peace process and\nto embed justice in peace processes through a comprehensive approach to transitional\njustice."},{"id":"a-hrc-62-crp-4-p0001","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"1","seq":0,"section":"I. Introduction","text":"On 19 February 2026, the independent international Fact-Finding Mission for\nthe Sudan issued its findings on the situation in El Fasher, pursuant to a request\ncontained in the Human Rights Council's resolution S-38/1 of 14 November 2025.\nThe mission concluded that the mass killings and related atrocities committed by the\nRapid Support Forces in and around El Fasher, during its takeover of the city in late\nOctober 2025, are indicators of a genocidal path. The report, \"Hallmarks of Genocide\nin El-Fasher\", was presented to the United Nations Human Rights Council on 26\nFebruary 2026 at its 61st session."},{"id":"a-hrc-62-crp-4-p0002","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"2","seq":1,"section":"I. Introduction","text":"Due to the word limit, the mission was unable to provide detailed references to\nthe sources it had relied upon in the report. This conference room paper provides\nthose references. It also provides information obtained during additional\ninvestigations that the mission has conducted since the presentation of the report to\nthe Human Rights Council, particularly relating to mass killings, brutal sexual\nviolence of immense gravity including mass gang rape, and systematic abduction of\nwomen and girl by the Rapid Support Forces and the extreme consequences of these\npractices, as well as the plight of thousands of individuals who were detained,\ntortured, held for ransom or effectively disappeared. It also develops the legal basis\nfor the conclusions that were drawn in the report. The continued investigations by the\nmission reaffirm the findings, conclusions and recommendations contained in the\n\"Hallmarks of Genocide in El-Fasher\" report. This supplementary paper should be\nread in conjunction with it."},{"id":"a-hrc-62-crp-4-p0003","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"3","seq":2,"section":"I. Introduction","text":"In both the report and this paper, the mission applied its previously outlined\nmethodology and guiding principles.1 While recognizing the standard of proof of\n\"reasonable grounds to believe\", common to the United Nations investigative bodies,\nthe mission paid particular attention to the question of whether there exists clear and\nfully convincing evidence, as articulated by judicial bodies, that could support the\ninvocation of the crime of genocide.2 It also considered whether genocidal intent was\nthe sole reasonable inference for the conduct it documented."},{"id":"a-hrc-62-crp-4-p0004","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"4","seq":3,"section":"I. Introduction","text":"The evidence thus far collected by the mission on the situation regarding El-\nFasher includes interviews with 333 survivors. In addition to its investigative\nmissions to Chad (from 6 to 17 January 2026) and South Sudan (from 10 to 21\nJanuary 2026), the mission conducted an online consultation with survivors who had\nfled from El Fasher. The conversations with survivors revealed the deep wounds left\nby the atrocities that were committed in and around El Fasher as well as the quest for\nsustainable peace, dignity and justice that the people of Sudan have long demanded\nand deserve. The mission is deeply grateful to all the survivors for their courage in\nsharing their experiences. The mission also expresses appreciation to the\nGovernments of Chad and South Sudan for facilitating these missions, and to host\ncommunities of the Sudanese refugees for their generosity."},{"id":"a-hrc-62-crp-4-p0005","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"5","seq":4,"section":"I. Introduction","text":"To date, the mission has reviewed more than 50 public reports and related\nmaterials pertaining to the situation in El Fasher. It authenticated, verified and\n1 See A/HRC/60/22; A/HRC/57/23; and the conference room paper containing the\nfindings of the investigations conducted by the independent international fact-finding\nmission for the Sudan into violations of international human rights law and\ninternational humanitarian law, and related crimes, committed in the Sudan in the\ncontext of the conflict that erupted in mid-April 2023, available from\nhttps://www.ohchr.org/sites/default/files/documents/hrbodies/hrcouncil/sessions-\nregular/session57/a-hrc-57-crp-6-en.docx.\n2 Rome Statute of the International Criminal Court, art. 17 (1) (d) (Rome Statute of the\nInternational Criminal Court); ICJ, Bosnia and Herzegovina v. Serbia and\nMontenegro, Application of the Convention on the Prevention and Punishment of the\nCrime of Genocide, Judgment, 26 February 2007.\ncorroborated 25 videos and held more than 45 meetings with civil society, human\nrights defenders, and experts, including global health experts, all in relation to El\nFasher."},{"id":"a-hrc-62-crp-4-p0006","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"6","seq":5,"section":"I. Introduction","text":"In addition to the international and regional entities mentioned in paragraph 6\nof its report, the mission consulted the newly appointed United Nations Secretary\nGeneral's Special Envoy for Sudan and continued its cooperation with the\nInternational Criminal Court."},{"id":"a-hrc-62-crp-4-p0007","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"7","seq":6,"section":"I. Introduction","text":"Despite the mission's best efforts, Sudan continued its lack of cooperation with\nthe mission. Although some officials have attempted to cooperate, fear of government\nreprisal has prevented this cooperation from materializing. The mission regrets this\nand calls on Sudan to reconsider its approach. In accordance with standard practice,\non 3 July 2026, the mission shared the final draft of this conference room paper with\nthe Government of the Sudan. No response was received."},{"id":"a-hrc-62-crp-4-p0008","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"8","seq":7,"section":"I. Introduction","text":"The mission contacted the Rapid Support Forces for information and requested\nmeetings with its leadership. It was followed up through various means, including\nletters in April, May and June 2026. The mission received a letter on 7 June 2026\nresponding to some of its questions. At the time of publishing the conference report\npaper, no meeting had occurred.\nII. Sources used in the report and additional information3"},{"id":"a-hrc-62-crp-4-p0009","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"9","seq":8,"section":"A. Parties to the Conflict and their allies","text":"As was stated in the report, the Sudanese Armed Forces remain led by the\nCommander-in-Chief, Lieutenant General Abdel Fattah Al-Burhan, who exercises\noverall political and military authority over the operations of the Sudanese Armed\nForces.4 In the battle for El Fasher, the Sudanese Armed Forces primarily relied on\nthe Sixth Infantry Division, and progressively consolidated alliances with Darfurian\narmed movements operating collectively as the Darfur Joint Protection Force (`Joint\nForces'). The Joint Forces, formed in April 2023 following the outbreak of the\nconflict,5 comprise armed movements that were signatories to the Juba Peace\nAgreement. They initially adopted a position of neutrality and non-alignment to the\nwarring parties."},{"id":"a-hrc-62-crp-4-p0010","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"10","seq":9,"section":"A. Parties to the Conflict and their allies","text":"Some armed groups progressively aligned with the Sudanese Armed Forces. By\nearly 2024, the Joint Forces was formed and included the Sudan Liberation\nMovement/Army led by Minni Minawi, the Justice and Equality Movement, the\nGathering of Sudan Liberation Forces, and factions of the Sudan Liberation\nMovement/Army-Transitional Council. They cited widespread attacks and violations\ncommitted by the Rapid Support Forces and their allies against civilians across\nDarfur. Several of these movements were closely associated with the Zaghawa\nleadership and recruitment networks.6"},{"id":"a-hrc-62-crp-4-p0011","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"11","seq":10,"section":"A. Parties to the Conflict and their allies","text":"Other Darfurian armed movements and factions, including elements of the\nSudan Liberation Movement/Army led by Abdul Wahid Mohamed Nour, remained\nformally outside the Joint Forces and largely maintained a neutral position."},{"id":"a-hrc-62-crp-4-p0012","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"12","seq":11,"section":"A. Parties to the Conflict and their allies","text":"At the same time, internal divisions emerged within certain Darfurian armed\nmovements. Factions associated with Al-Hadi Idris within the Sudan Liberation\nMovement/Army�Transitional Council, and with Al-Tahir Hajar within the Gathering\nof Sudan Liberation Forces, distanced themselves from elements aligned with the\nSudanese Armed Forces. These factions initially maintained a neutral position and\nwithdrew from El Fasher, before later aligning with the Rapid Support Forces. After\nthese splits, the Joint Forces remaining in El Fasher fully supported the Sudanese\nArmed Forces."},{"id":"a-hrc-62-crp-4-p0013","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"13","seq":12,"section":"A. Parties to the Conflict and their allies","text":"The Sudanese Armed Forces were also supported by locally mobilised civilian\nunits in and around El Fasher and Popular Resistance Forces established to defend\ncommunities and strategic positions. In May 2024, the Sudanese Armed Forces\nformally established a National Committee to integrate the Popular Resistance Forces\nthrough recruitment, arming and financing. The Popular Resistance Forces actively\ndefended El Fasher, alongside the Sudanese Armed Forces and the Joint Forces, until\nthe eventual collapse of the city's defence.7\nRapid Support Forces"},{"id":"a-hrc-62-crp-4-p0014","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"14","seq":13,"section":"A. Parties to the Conflict and their allies","text":"As described in previous reports, the Rapid Support Forces, a highly mobile\nforce combining regular units, intelligence, and allied militias, were part of Sudan's\nsecurity apparatus at the outbreak of hostilities in 2023, with origins as an irregular\nmilitia.8 It is led by Lt. General Mohamed Hamdan Dagalo, with his brother,\nAbdelrahim Dagalo, as his second in command."},{"id":"a-hrc-62-crp-4-p0015","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"15","seq":14,"section":"A. Parties to the Conflict and their allies","text":"The Rapid Support Forces' military campaign has been reinforced by local Arab\nmilitias and tribal networks, which provided manpower, logistics and local\nintelligence.9 Witnesses also reported the presence of a large number of foreign\nfighters among the ranks of the Rapid Support Forces.10"},{"id":"a-hrc-62-crp-4-p0016","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"16","seq":15,"section":"A. Parties to the Conflict and their allies","text":"Survivors consistently identified the perpetrators during the take-over of El\nFasher as members of the Rapid Support Forces and their allies. They also described\ndistinctive kaki/akhbashi/sandy coloured attire, noting they were all armed with\nfirearms, but also carried knives and whips.11 The Rapid Support Forces use a\ncombination of small arms, light and heavy weapons, armoured vehicles, artillery\nincluding rocket artillery, mortars, anti-tank guided missiles, surveillance drones,\nloitering munitions/suicide drones, drones capable of air dropping munitions as well\nas large armed fixed-wing drones.12 The Rapid Support Forces also utilised electronic\nwarfare equipment, including jamming systems and Starlink-based command\nterminals.13"},{"id":"a-hrc-62-crp-4-p0017","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"17","seq":16,"section":"A. Parties to the Conflict and their allies","text":"Several survivors stated that the Rapid Support Forces and their allies recruited\nsubstantial numbers of children, using them as fighters, guards and for intelligence-\ngathering within the city of El Fasher and surrounding areas.14 Witnesses described\n7 FFMS-D-004994; FFMS-D-005012; FFMS-D-005016; FFMS-D-005022.\n8 A/HRC/57/23, paras. 27-30; A/HRC/57/CRP.6, para. 91-95.\n9 FFMS-D-005130; FFMS-D-005034; FFMS-D-002167; FFMS-D-002142.\n10 FFMS-D-005128; FFMS-D-005023; FFMS-D-005509; FFMS-D-005089.\n11 See e.g. FFMS-D-005127; FFMS-D-004983; FFMS-D-004995; FFMS-D-005023;\nFFMS-D-005524.\n12 FFMS-D-005133; FFMS-D-005526.\n13 FFMS-D-004967; FFMS-D-004982; FFMS-D-005118; FFMS-D-005131; FFMS-D-\n005509.\n14 FFMS-D-004566; FFMS-D-004969; FFMS-D-005050.\nseeing armed boys between 12 and 16 years of age with the Rapid Support Forces\nafter El Fasher had been taken.15"},{"id":"a-hrc-62-crp-4-p0018","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"18","seq":17,"section":"B. Conflict Dynamics","text":"As the report indicates, by late November 2023, the Rapid Support Forces\ncontrolled four of Darfur's five states, leaving only parts of North Darfur, including\nEl Fasher, under control of the Sudanese Armed Forces and their allies."},{"id":"a-hrc-62-crp-4-p0019","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"19","seq":18,"section":"B. Conflict Dynamics","text":"Until late 2023, El Fasher experienced a period of relative calm under a locally\nnegotiated ceasefire arrangement reached in May 2023.16 The Rapid Support Forces\ncontrolled the northern and eastern sectors of the city and strategic supply routes\nconnecting El Fasher to Nyala, Zalingei and Shangil Tobaya, while the Sudan Armed\nForces retained control over the city centre, western and southern districts, including\nthe 6th Infantry Division Headquarters and areas surrounding Zamzam and Abu\nShouk displacement camps. Sporadic shelling persisted, but there were no significant\nclashes.17"},{"id":"a-hrc-62-crp-4-p0020","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"20","seq":19,"section":"B. Conflict Dynamics","text":"The ceasefire progressively collapsed in early 2024. The Rapid Support Forces\nincreasingly portrayed the city as a hostile stronghold of non-Arab armed groups\naligned with the Sudanese Armed Forces. The growing participation of Zaghawa\nfighters and commanders within the Joint Forces and Popular Resistance Forces\nfurther contributed to the perceived ethnicization of the conflict and heightened risks\nof retaliatory attacks against civilians perceived as being affiliated to opposing\nparties.18"},{"id":"a-hrc-62-crp-4-p0021","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"21","seq":20,"section":"B. Conflict Dynamics","text":"The Sudanese Armed Forces regained control over Khartoum in March 2025.\nAs noted in the report, with the retreat to their strongholds, mainly in Darfur, the\nRapid Support Forces and their allies began attacking towns and villages surrounding\nEl Fasher from 6 April 2024. In May 2024, they imposed a siege on the city, until\nthey took it over in October 2025.19"},{"id":"a-hrc-62-crp-4-p0022","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"22","seq":21,"section":"B. Conflict Dynamics","text":"The battle for the control of El Fasher was intense, characterised by widespread\nand indiscriminate shelling, aerial bombardments, drone attacks and repeated ground\nassaults affecting densely populated residential areas from both sides.20 Although the\nSudanese Armed Forces and Joint Forces and their allies continued to hold central El\nFasher, the Rapid Support Forces progressively advanced through peripheral areas\nand temporarily entered some neighbourhoods and strategic sites, including areas\nsurrounding the Saudi Hospital, before being repelled by counterattacks launched by\nthe Sudanese Armed Forces, the Joint Forces and their allies.21"},{"id":"a-hrc-62-crp-4-p0023","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"23","seq":22,"section":"B. Conflict Dynamics","text":"As the constant shelling and ground attacks in some neighbourhoods in El\nFasher intensified, many inhabitants fled towards the Zamzam and Abu Shouk\ndisplacement camps for safety, seeking the protection of the Joint Forces and the\nSudanese Armed Forces present in their vicinity.22 Towards the end of 2024, however,\nthese camps became targets of repeated shelling and ground attacks, resulting in\ncivilian casualties, destruction of shelters and markets, and repeated forced\ndisplacement within already overcrowded sites.23 Survivors described a pattern of\nencirclement of the camps, coordinated artillery and ground assaults from multiple\ndirections, strengthened by drone attacks, followed by widespread killings, rape and\nforced displacement, with large numbers of inhabitants fleeing towards Tawila or El\nFasher, while being abused and robbed of their last items.24 The fighting intensified\nin July and August 2025, and the Rapid Support Forces entered the city, but they were\nrepelled by the Sudanese Armed Forces and their allies.25"},{"id":"a-hrc-62-crp-4-p0024","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"24","seq":23,"section":"B. Conflict Dynamics","text":"In September 2025, the Rapid Support Forces entered the city centre once again,\npushing towards key military positions, including the El Fasher central market (Hajar\nKado), the 6th Infantry Division Headquarters, and surrounding areas. Although the\nRapid Support Forces failed to take over these military positions at that time, the\ncity's defences were progressively weakened.26 The defences ultimately collapsed in\nlate October 2025 following the final large-scale offensive by the Rapid Support\nForces.27"},{"id":"a-hrc-62-crp-4-p0025","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"25","seq":24,"section":"C. The people of El Fasher and repeated displacement","text":"Evidence of what was included in the report, regarding the indications by several\nsurvivors of repeated cycles of flight and return in and around El Fasher is cited\nbelow.28"},{"id":"a-hrc-62-crp-4-p0026","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"26","seq":25,"section":"D. Starvation and the collapse of the food supply systems and","text":"Evidence of what was included in the report, regarding markets being repeatedly\nattacked, looted or forced to close, supply routes into the city being systematically\ncut, and trucks carrying food being denied entry or attacked, are referenced below.29"},{"id":"a-hrc-62-crp-4-p0027","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"27","seq":26,"section":"D. Starvation and the collapse of the food supply systems and","text":"Since the publication of the report, the Mission has continued to receive\ninformation regarding the severe and deteriorating food shortages caused by the\nRapid Support Forces' siege and the cumulative impact on the civilian population,\n23 FFMS-D-005128; FFMS-D-005500.\n24 A/HRC/60/22, para. 28; FFMS-D-005132; FFMS-D-005130; FFMS-D-005129;\nFFMS-D-005128; FFMS-D-005127; FFMS-D-005126; FFMS-D-005123; FFMS-D-\n005295; FFMS-D-005151; FFMS-D-005302; FFMS-D-005290.\n25 FFMS-D-004995; FFMS-D-005026; FFMS-D-005027; FFMS-D-004566.\n26 FFMS-D-005027; FFMS-D-005026; FFMS-D-005032; FFMS-D-005038; FFMS-D-\n005033; FFMS-D-005035; FFMS-D-005036; FFMS-D-005039; FFMS-D-005044;\nFFMS-D-005045; FFMS-D-005046.\n27 FFMS-D-004563; FFMS-D-005008; FFMS-D-004995.\n28 FFMS-D-004566; FFMS-D-004973; FFMS-D-004980; FFMS-D-005013; FFMS-\nD-005016; FFMS-D-005023; FFMS-D-005085; FFMS-D-005120; FFMS-D-\n005121; FFMS-D-005123; FFMS-D-005126; FFMS-D-005127; FFMS-D-005128;\nFFMS-D-005129; FFMS-D-005130; FFMS-D-005131; FFMS-D-005132; FFMS-\nD-005133. The mission previously reported on the major attack on Zamzam Camp,\nwhere predominantly those displaced from the Fur community lived, that was\nlaunched by the Rapid Support Forces from 11 to 14 April 2025, killing over 1,000\ninhabitants. The inhabitants were chased out from the third day of the attack, with\nsome fleeing back to El Fasher. (A/HRC/60/22, para. 28; also see\nhttps://www.ohchr.org/sites/default/files/documents/countries/sudan/ohchr-sudan-\nrapid-support-forces-zamzam-idp-camp-north-darfur-3-days-safe-refuge-offensive-\napril-terror-1-en.pdf, para. 34).\n29 FFMS-D-005128; FFMS-D-005123; FFMS-D-005524; FFMS-D-005497.\nparticularly children, older persons and persons with disabilities.30 Beyond physical\ndeprivation, survivors described the siege as having a profound mental health and\npsychosocial impact.31 Pregnant women were disproportionally affected by stress\ncaused by shelling, which reportedly triggered premature labor and pre- and perinatal\ncomplications.32"},{"id":"a-hrc-62-crp-4-p0028","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"28","seq":27,"section":"D. Starvation and the collapse of the food supply systems and","text":"Evidence of what was included in the report regarding limited medical supplies\nand the resulting collapse of medical services in El Fasher is included in the\nfootnote.33 Additional information received by the mission indicates that in Saudi\nHospital, the only hospital operational at the time of the takeover, medical staff\nresorted to cleaning wounds with water and salt as access to medical supplies\ndiminished.34 Medical specialists described the shortages of supplies for treating rape\nsurvivors as further undermining the ability to provide timely and adequate care."},{"id":"a-hrc-62-crp-4-p0029","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"29","seq":28,"section":"E. Restriction of movement and prevention of civilian escape","text":"Evidence supporting what was included in the report regarding the construction\nof berms and blocking civilians from fleeing, is referenced in the footnote.35 These\nstructures contributed to cutting of food supplies, inter alia leading to the creation of\nfamine conditions in the city. During the final assault between 26 and 28 October\n2025, the structures also facilitated channelling both combatants and civilians into\nchoke points and became mass killing sites."},{"id":"a-hrc-62-crp-4-p0030","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"30","seq":29,"section":"E. Restriction of movement and prevention of civilian escape","text":"Movement restrictions exacerbated the already weakened healthcare system,\nparticularly affecting women in need of urgent maternal and reproductive care. In\nseveral cases, women who became pregnant as a result of rape resorted to unsafe\nabortion practices due to the lack of timely medical care, leading to severe\ncomplications, including hemorrhage and death.36"},{"id":"a-hrc-62-crp-4-p0031","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"31","seq":30,"section":"F. Last months of the siege","text":"Evidence supporting what was included in the report regarding the shelling of\nthe displacement camps, and the targeting of women on the basis of their gender\nintersecting with their ethnicity, is cited in the footnote.37"},{"id":"a-hrc-62-crp-4-p0032","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"32","seq":31,"section":"G. Three days of untold horror � the taking of El Fasher","text":"Evidence supporting what was included in the report regarding the rapid\ncollapse of security and humanitarian conditions in El Fasher in the days preceding\nthe takeover, is footnoted.38"},{"id":"a-hrc-62-crp-4-p0033","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"33","seq":32,"section":"1. Killings throughout the city","text":"Evidence supporting what was included in the report regarding killings\nthroughout the city is referenced in the footnote.39 As was stated in the report,\nsurvivors consistently spoke of widespread killings, including indiscriminate\nshootings and point-blank executions of civilians in homes, in trenches and public\nbuildings where they were hiding, in market areas, near the airport fence, in open\nareas or while attempting to flee the city."},{"id":"a-hrc-62-crp-4-p0034","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"34","seq":33,"section":"2. Mass executions at exit points","text":"Evidence supporting what was included in the report regarding killings at exit\npoints is footnoted.40 As was stated in the report, from 26 October 2025, the Rapid\nSupport Forces rounded up those trying to leave the city at three main exit points: on\nthe northern axis towards Mellit, on the El Fasher�Garni road (north-west of El\nFasher) and on the El Fasher�Tawila road (south-west of El Fasher). At these exit\npoints, survivors described members of the Rapid Support Forces separating men\nfrom women and children. The men were beaten, detained, abducted, or executed,\nbased on accusations of them supporting the Sudanese Armed Forces and/or the Joint\nForces."},{"id":"a-hrc-62-crp-4-p0035","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"35","seq":34,"section":"3. Mass executions at the berms","text":"Evidence supporting what was included in the report regarding killings at the\nberms is footnoted.41 As was stated in the report, the earthen berms and trenches\nhttps://www.unicef.org/sudan/press-releases/least-11-children-reportedly-killed-\nattack-mosque-sudans-north-darfur-state; https://www.unicef.org/press-\nreleases/least-17-children-reportedly-killed-attack-displacement-centre-north-\ndarfurs-al.\n38 FFMS-D-005509; FFMS-D-005090; FFMS-D-005046; FFMS-D-005045; FFMS-D-\n005031; FFMS-D-005030; FFMS-D-005012; FFMS-D-005010; FFMS-D-005004;\nFFMS-D-004994; FFMS-D-004989; FFMS-D-004972; FFMS-D-004969; FFMS-D-\n004967; FFMS-D-004566; FFMS-D-004565; FFMS-D-004564; FFMS-D-004563.\n39 FFMS-D-005483; FFMS-D-005036; FFMS-D-005034; FFMS-D-005030; FFMS-D-\n005023; FFMS-D-005021; FFMS-D-005018; FFMS-D-005014; FFMS-D-005013;\nFFMS-D-005008; FFMS-D-004999; FFMS-D-004990; FFMS-D-004989; FFMS-D-\n004988; FFMS-D-004983; FFMS-D-004981; FFMS-D-004979; FFMS-D-004974.\n40 FFMS-D-005036; FFMS-D-005021; FFMS-D-005018; FFMS-D-005014; FFMS-D-\n005013; FFMS-D-005007; FFMS-D-005005; FFMS-D-005000; FFMS-D-004999;\nFFMS-D-004997; FFMS-D-004995; FFMS-D-004989; FFMS-D-004971; FFMS-D-\n004566; FFMS-D-004564; FFMS-D-004348; FFMS_0368 (26 Oct 2025);\nFFMS_0365 (26 Oct 2025); FFMS_0366 (26 Oct 2025); FFMS-D-005526.\n41 FFMS-D-005481; FFMS-D-005047; FFMS-D-005036; FFMS-D-005035; FFMS-D-\n005030; FFMS-D-005027; FFMS-D-005021; FFMS-D-005020; FFMS-D-005019;\nFFMS-D-005016; FFMS-D-005015; FFMS-D-005013; FFMS-D-005012; FFMS-D-\n005009; FFMS-D-005008; FFMS-D-005007; FFMS-D-005006; FFMS-D-005005;\nFFMS-D-005004; FFMS-D-005002; FFMS-D-005000; FFMS-D-004998; FFMS-D-\n004996; FFMS-D-004993; FFMS-D-004989; FFMS-D-004982; FFMS-D-004976;\nFFMS-D-004566; FFMS-D-004565; FFMS-D-004348; FFMS-D-004335; FFMS-D-\nconstructed by the Rapid Support Forces around El Fasher were also locations where\nmembers of the Rapid Support Forces separated, detained and killed civilians."},{"id":"a-hrc-62-crp-4-p0036","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"36","seq":35,"section":"4. Killings at El Fasher University","text":"Evidence supporting what was included in the report regarding what happened\nat the university, where the Rapid Support Forces targeted the El Fasher University\nwith shelling and drone strikes, killing and injuring civilians sheltering there and its\nenvirons, is footnoted.42"},{"id":"a-hrc-62-crp-4-p0037","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"37","seq":36,"section":"5. Killing at the Saudi Hospital","text":"Evidence supporting what was included in the report regarding the killings at\nthe El Saudi Hospital, where multiple survivors described witnessing mass killings at\nthe hospital or encountering large number of corpses immediately afterwards, is\nfootnoted.43"},{"id":"a-hrc-62-crp-4-p0038","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"38","seq":37,"section":"6. Continued killings and executions on the road","text":"Evidence supporting what was included in the report regarding the continued\nkillings and executions on the road, is footnoted.44 As was stated in the report,\nsurvivors reported extreme danger while attempting to flee, often leading to\ndispersion of persons fleeing in groups, and members of the Rapid Support Forces\nopening fire on the groups. Since the publication of the report, the mission has\ncontinued to receive information regarding the killings on the roads. Verified video\nmaterial as well as survivor testimonies describe encountering numerous bodies of\nmen, women, and children along the roads to Garni and Tawila.45"},{"id":"a-hrc-62-crp-4-p0039","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"39","seq":38,"section":"1. Rape and other forms of sexual violence","text":"Evidence of what was included in the report regarding the widespread,\nsystematic and coordinated acts of rape and other forms of sexual violence primarily\n004315; FFMS-D-004313; FFMS-D-004311; FFMS-D-004309; FFMS_0371 (27\nOct 2025); FFMS_0372 (28 Oct 2025).\ntargeted at women and girls from non-Arab communities, particularly the Zaghawa,\nis cited in this section.46"},{"id":"a-hrc-62-crp-4-p0040","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"40","seq":39,"section":"1. Rape and other forms of sexual violence","text":"The mission has continued to receive information regarding the identification of\nperpetrators of the rapes and other forms of sexual violence. Like other survivors,\nwomen who survived sexual violence identified the perpetrators as members of the\nRapid Support Forces, describing their distinctive kaki/akhbashi/sandy coloured\nattire. Survivors further reported the presence of foreign fighters among the Rapid\nSupport Forces who also perpetrated acts of sexual violence.47\na) Mass and gang rape"},{"id":"a-hrc-62-crp-4-p0041","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"41","seq":40,"section":"1. Rape and other forms of sexual violence","text":"The mission has continued to receive information regarding mass and gang\nrapes. The Rapid Support Forces members carried out these assaults amid broader\nattacks involving killings, looting, forced displacement, and abductions, often\nseparating men from women.48"},{"id":"a-hrc-62-crp-4-p0042","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"42","seq":41,"section":"1. Rape and other forms of sexual violence","text":"At the El Saudi Hospital, survivors described members of the Rapid Support\nForces raping numerous women after storming wards, killing wounded and sick\npeople and civilians who had sought refuge inside.49 Another survivor reported that,\non 26 October 2025, Rapid Support Forces fighters entered a takiya where civilians\nhad sought refuge, attacked the people, killing numerous men, as well as women and\nchildren.50 As the survivor attempted to flee with her husband, Rapid Support Forces\nfighters raped her. When the husband tried to intervene to prevent the assault, one of\nthe fighters slit the husband's throat with a knife, killing him on the spot.51"},{"id":"a-hrc-62-crp-4-p0043","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"43","seq":42,"section":"1. Rape and other forms of sexual violence","text":"Several witnesses described women and girls between 12 and 17 years being\nraped by two or more members of the Rapid Support Forces. In Shagra, during the\ntake-over, an eyewitness reported members of the Rapid Support Forces raping large\nnumbers of women and girls, some as young as 13 years, after halting groups\nattempting to escape.52 In this same incident, between 15 and 20 women and girls\nwere raped, including adolescents and at least one elderly woman in her seventies,\nwho later died from injuries sustained during the assault."},{"id":"a-hrc-62-crp-4-p0044","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"44","seq":43,"section":"1. Rape and other forms of sexual violence","text":"The mission has further found that the vast majority of the mass and gang rapes\ntook place between El Fasher city and the routes of Tawila, Garni, Jabal Wana, and\nMellit, as well as in Garni, Golo and Shagra areas.53\n46 FFMS-D-005490; FFMS-D-005122; FFMS-D-005120; FFMS-D-005085; FFMS-D-\n005036; FFMS-D-005036; FFMS-D-005024; FFMS-D-005023; FFMS-D-005020;\nFFMS-D-005019; FFMS-D-005005; FFMS-D-004991; FFMS-D-004990; FFMS-D-\n004989; FFMS-D-004988; FFMS-D-004987; FFMS-D-004986; FFMS-D-004984;\nFFMS-D-004983; FFMS-D-004982; FFMS-D-004978; FFMS-D-004977; FFMS-D-\n004976; FFMS-D-004975; FFMS-D-004974; FFMS-D-004973; FFMS-D-004972;\nFFMS-D-004971; FFMS-D-004969; FFMS-D-004966; FFMS-D-004922; FFMS-D-\n004566; FFMS-D-004565; FFMS-D-004564; FFMS-D-00969.\n47 FFMS-D-004983, FFMS-D-005023.\n48 FFMS-D-005509; FFMS-D-005490; FFMS-D-005483; FFMS-D-005122; FFMS-D-\n005120; FFMS-D-005024; FFMS-D-005023; FFMS-D-004992; FFMS-D-004991;\nFFMS-D-004989; FFMS-D-004988; FFMS-D-004987; FFMS-D-004986; FFMS-D-\n004983; FFMS-D-004982; FFMS-D-004981; FFMS-D-004979; FFMS-D-004976;\nFFMS-D-004975; FFMS-D-004974; FFMS-D-004973; FFMS-D-004971; FFMS-D-\n004970; FFMS-D-004566.\n49 FFMS-D-004976; FFMS-D-004973; FFMS-D-005024.\n50 FFMS-D-005122.\n51 FFMS-D-005122. See also FFMS-D-005500, reporting that the survivor's husband\nwas killed in an attempt to protect his wife.\n52 FFMS-D-004983, FFMS-D-005497.\n53 FFMS-D-004970; FFMS-D-004975; FFMS-D-004976; FFMS-D-005024; FFMS-\nD-004983; FFMS-D-004986.\nb) Abduction and sexual violence"},{"id":"a-hrc-62-crp-4-p0045","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"45","seq":44,"section":"1. Rape and other forms of sexual violence","text":"Since the publication of the report, the mission has continued to receive\ninformation regarding the systematic abduction of women and girls and sexual\nviolence by the Rapid Support Forces. One witness saw members of the Rapid\nSupport Forces tie the hands of three girls she knew behind their back, force them\ninto a vehicle and drive them away.54 In other incidents, survivors described women\nand girls being beaten, restrained with their hands tied behind their back, and taken\naway in a Landcruiser, while men were separated and taken in a different direction.55\nSeveral survivors reported that abducted women and girls were transported to remote\nlocations, including forested areas outside El Fasher, where they were raped.56"},{"id":"a-hrc-62-crp-4-p0046","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"46","seq":45,"section":"1. Rape and other forms of sexual violence","text":"In one documented case, members of the Rapid Support Forces detained four\nwomen before subsequently tying them to a cart and dragging it behind a vehicle for\nabout one kilometre, resulting in their death.57"},{"id":"a-hrc-62-crp-4-p0047","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"47","seq":46,"section":"1. Rape and other forms of sexual violence","text":"The mission's findings demonstrate that women and girls were deliberately\ntargeted for rape and gang rape, with forced nudity used to humiliate, terrorize, and\nsubjugate the civilian population. Similar patterns documented previously in El\nGeneina58 and Zamzam59 reveal continuity and reinforce the assessment that sexual\nviolence has been used as a weapon of war in Darfur. Reflecting on this recurring\npattern in El Fasher, the International Criminal Court's Deputy Prosecutor told the\nUnited Nations Security Council on 19 January 2025 that \"the pattern of atrocities in\nEl Geneina in 2023 have been replicated in El Fasher in 2025\",60 underscoring that\nsexual violence continues to be used as a tool of war in Darfur.\nc) Rape in the presence of corpses"},{"id":"a-hrc-62-crp-4-p0048","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"48","seq":47,"section":"1. Rape and other forms of sexual violence","text":"Since the publication of the report, the mission has continued to receive\ninformation regarding the perpetration of rape in the presence of corpses. Survivors\ndescribed being raped in rooms where bodies of recently killed civilians, including\ntheir own family members, were still lying on the ground or recently killed.61"},{"id":"a-hrc-62-crp-4-p0049","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"49","seq":48,"section":"1. Rape and other forms of sexual violence","text":"The same pattern took place along the roads used by civilians fleeing the city.\nOne survivor recounted the rape of a woman in front of the body of her two-year-old\nson in Jabal Wana, who was killed along with other children. Members of the Rapid\nSupport Forces explicitly stated that these children should have died in 2003, stating\nthat, had they been killed then, they would not have had to fight them when grown\nup in 2023.62 Another survivor was raped next to the bodies of her parents, who had\nbeen shot dead moments earlier, and her brother, who had been slain in her presence.\nShe said: \"They raped me in front of the bodies of my mother, my father and my\nslaughtered brother\".63 Rape perpetrated in the presence of the dead, particularly\nwhen the deceased were relatives, served to inflict terror, severe mental suffering,\nasserting power and domination through the combined use of sexual violence and\nkilling."},{"id":"a-hrc-62-crp-4-p0050","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"50","seq":49,"section":"1. Rape and other forms of sexual violence","text":"The breadth of locations, the consistency of methods, and the repetition across\ntime indicate that these acts, perpetrated by the Rapid Support Forces and their allies,\nwere neither isolated nor opportunistic. Rather, they formed part of a deliberate\npattern of sexual violence systematically deployed during the operations of the Rapid\nSupport Forces.\nd) Normalization of acts of sexual violence"},{"id":"a-hrc-62-crp-4-p0051","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"51","seq":50,"section":"1. Rape and other forms of sexual violence","text":"Since the publication of the report, the mission has continued to receive\ninformation regarding the normalization of acts of sexual violence."},{"id":"a-hrc-62-crp-4-p0052","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"52","seq":51,"section":"1. Rape and other forms of sexual violence","text":"Sexual violence in Sudan has long been enabled by a climate of impunity, with\nthe events in El Fasher reflecting a clear escalation. Acts of rape were carried out\nopenly, repeatedly and in full view of others, with perpetrators demonstrating no fear\nof consequences. One survivor recalled perpetrators laughing during the assaults,\ncompounding the degrading and terrorizing nature of the violence.64"},{"id":"a-hrc-62-crp-4-p0053","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"53","seq":52,"section":"1. Rape and other forms of sexual violence","text":"The absence of accountability appears to have normalized rape within the Rapid\nSupport Forces modus operandi, where sexual violence functioned as a tolerated,\npermitted, systematic, and integrated practice of war, rather than as an isolated or\nincidental by-product of the conflict.\ne) The gender dimension"},{"id":"a-hrc-62-crp-4-p0054","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"54","seq":53,"section":"1. Rape and other forms of sexual violence","text":"Since the publication of the report, the mission has continued to receive\ninformation regarding the gender dimension of the attacks."},{"id":"a-hrc-62-crp-4-p0055","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"55","seq":54,"section":"1. Rape and other forms of sexual violence","text":"While men and young men were subjected to mass killings - often rounded up,\nseparated, and executed - women and girls were not spared. Survivors consistently\nreported that women and girls were not only harmed incidentally by stray bullets\nduring flight; rather, they were also shot dead deliberately, including at close range\nand in the course of attacks by the Rapid Support Forces on civilian groups, in\nparticular either while defending their relatives from being abducted or assaulted, or\nbecause they resisted rape.65 In one such case, a mother was reportedly killed after\nattempting to stop members of the Rapid Support Forces from taking her daughters\nfrom her on the road to Tawila, while fleeing from El Fasher.66 In another case, a\nsurvivor reported that, after being abducted and held in a house along with other\nwomen and girls, Rapid Support Forces members attempted to rape two young\nwomen.67 When the women resisted, the perpetrators killed them immediately.68"},{"id":"a-hrc-62-crp-4-p0056","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"56","seq":55,"section":"1. Rape and other forms of sexual violence","text":"This demonstrates that the violence used by the Rapid Support Forces was not\nlimited to targeting men as perceived combatants or supporters; it extended to the\ndirect killing of women and girls as part of a broader campaign of terror and collective\npunishment. By killing or removing men and systematically violating women and\ngirls, the actions of the Rapid Support Forces also attacked the very structure of\nfamilies and communities, undermining social continuity.\n64 FFMS-D-0370.\n65 FFMS-D-004990; FFMS-D-004989; FFMS-D-004992; FFMS-D-004969; FFMS-D-\n004977; FFMS-D-004982; FFMS-D-005014.\n66 FFMS-D-005120.\n67 FFMS-D-005122.\n68 FFMS-D-005122.\nf) The ethnic dimension"},{"id":"a-hrc-62-crp-4-p0057","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"57","seq":56,"section":"1. Rape and other forms of sexual violence","text":"Since the publication of the report, the mission has continued to receive\ninformation regarding the ethnic dimension of the sexual violence by the Rapid\nSupport Forces."},{"id":"a-hrc-62-crp-4-p0058","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"58","seq":57,"section":"1. Rape and other forms of sexual violence","text":"Survivors reported hearing statements made by members of the Rapid Support\nForces after the takeover of the city, including: \"We have to empty El Fasher of the\nFalangiyat; \"These are Falangiyat, these are slaves. Kill them, destroy them, rape\nthem; \"The Rapid Support Forces are above everything\"; \"Any Zaghawa we will\ncapture, will not survive the night\"; \"Is there anyone Zaghawa among you? If we find\nZaghawa, we will kill them all\".69 Such expressions were accompanied by acts of\nkilling, beatings, sexual violence and forced displacement."},{"id":"a-hrc-62-crp-4-p0059","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"59","seq":58,"section":"1. Rape and other forms of sexual violence","text":"Survivors consistently reported that women and girls perceived as non-Arab,\nparticularly those who were or believed to be Zaghawa, were specifically targeted.\nOne survivor reported that when she stated her Zaghawa tribe, the Rapid Support\nForces fighters beat her harder and told her: \"We are allergic to the Zaghawa.\" They\nthen raped her after tying her hands, and while raping her said: \"Zaghawiya hein? We\nare your only men, no other men,\" implying the erasure of the Zaghawa men and the\nownership over the Zaghawa women.70"},{"id":"a-hrc-62-crp-4-p0060","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"60","seq":59,"section":"1. Rape and other forms of sexual violence","text":"Other survivors stated that, immediately before raping women, fighters of the\nRapid Support Forces used the word \"marry\" or \"bride\" or \"our ladies\", referring to\nrape, as a form of ownership, intimidation and humiliation.71 One survivor told the\nmission that, on 26 October 2025, about an hour after leaving El Fasher, on the road\nto Tawila, she and others fleeing were intercepted by fighters of the Rapid Support\nForces.72 These fighters separated the men from the women, and took the men away.\nThen the fighters picked some of the women to be raped, while forcing the other\nwomen to sit and watch the rapes. The fighters of the Rapid Support Forces told the\nobserving women: \"Sit here until we `marry' your sister.\"73"},{"id":"a-hrc-62-crp-4-p0061","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"61","seq":60,"section":"1. Rape and other forms of sexual violence","text":"Meanwhile, women who identified themselves as Arab or Arab-aligned were\noften spared.74 One woman avoided rape after claiming she belonged to the Fallati\ntribe, prompting a Rapid Support Forces member to say: \"You are my cousin\".75\nAnother woman described how a member of the Rapid Support Forces pulled his\ntrousers down to rape her but stopped after she asserted she was from the Masri\nneighbourhood, prompting him to pull up his trousers and tell her: \"Get up, my\ncousin\" and let her leave.76"},{"id":"a-hrc-62-crp-4-p0062","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"62","seq":61,"section":"1. Rape and other forms of sexual violence","text":"Such discriminatory treatment, consistently reported across several interviews,\nindicates that ethnicity was a primary criterion guiding the conduct of the Rapid\nSupport Forces and that sexual violence was intentionally directed against non-Arab\ncommunities as part of a broader campaign of ethnically motivated violence. This\nwidespread conduct of the Rapid Support Forces also points to a broader campaign\nof persecution and collective punishment. The repetition of these methods across\nlocations and days, consistency of language used, and alignment with patterns\ndocumented elsewhere in Darfur since 2023, indicate an organized and tolerated\npolicy. The events in El Fasher represent both a continuation and an intensification\nof these methods.\ng) Consequences of sexual violence"},{"id":"a-hrc-62-crp-4-p0063","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"63","seq":62,"section":"1. Rape and other forms of sexual violence","text":"Since the publication of the report, the mission has continued to receive\ninformation regarding the consequences of the rapes and other forms of sexual\nviolence."},{"id":"a-hrc-62-crp-4-p0064","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"64","seq":63,"section":"1. Rape and other forms of sexual violence","text":"Survivors reported severe physical and psychological consequences, including\nmiscarriages, prolonged bleeding, extensive genital and anal injuries, infections,\nurinary retention, unwanted pregnancies, and intense trauma and social stigma. One\ninterviewee who aborted after learning she was pregnant as a result of rape said: \"My\nhusband and I tried to have children and had never had a child, but to become\npregnant after rape, no, I cannot accept it\".77"},{"id":"a-hrc-62-crp-4-p0065","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"65","seq":64,"section":"1. Rape and other forms of sexual violence","text":"Multiple victims of sexual violence died as a result of rape.78 Accounts received\nby the mission indicate that, on some occasions, members of the Rapid Support\nForces perpetrated rape by inserting a sharp object into the anus of the victims,\nleading to the death of at least one victim.79"},{"id":"a-hrc-62-crp-4-p0066","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"66","seq":65,"section":"1. Rape and other forms of sexual violence","text":"Survivors could not access timely or sufficient medical assistance due to\nongoing hostilities and destruction of health facilities, insecurity along escape routes,\nand deliberate obstruction by armed actors. Survivors frequently reported that they\nwere only able to reach medical care after arriving in Tawila or Kutum, often after\ndays of travel in extremely vulnerable conditions. Even upon arrival, care was\nlimited, and at least two women documented by the mission died in Tawila from\ninjuries sustained during rape combined with a prolonged lack of treatment.80"},{"id":"a-hrc-62-crp-4-p0067","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"67","seq":66,"section":"1. Rape and other forms of sexual violence","text":"During its visit to Tine (Chad), members of the mission observed that a\nsignificant number of refugees were women and children. Women described giving\nbirth on the road while fleeing. Many of them were also in precarious conditions after\nbecoming heads of households after losing or being separated from male relatives.81\nDisplacement, insecurity, and the absence of basic services have compounded their\nvulnerability, underscoring the gendered impact of the conflict."},{"id":"a-hrc-62-crp-4-p0068","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"68","seq":67,"section":"2. Detention, torture, humiliation, extortion, ransom and","text":"Evidence of what was included in the report, regarding the widespread and\nsystematic pattern of detention and enforced disappearance of civilians and persons\nhors de combat,82 and, acts of torture and other forms of cruel, inhuman and\ndegrading treatment,83 committed by the Rapid Support Forces, is included in the\nfootnotes."},{"id":"a-hrc-62-crp-4-p0069","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"69","seq":68,"section":"2. Detention, torture, humiliation, extortion, ransom and","text":"Since the publication of the report, the mission has continued to receive\ninformation regarding different detention sites used by the Rapid Support Forces. A\nsignificant number of detained persons who were arrested in different locations while\nfleeing from El Fasher, were later brought back to El Fasher and detained there in\ndifferent buildings, including schools, the El Saudi Hospital and former government\n77 FFMS-D-004982.\n78 FFMS-D-004983; FFMS-D-004969; FFMS-D-004988; FFMS-D-005490.\n79 FFMS-D-005082; FFMS-D-004991.\n80 FFMS-D-004988; FFMS-D-004983.\n81 See, inter alia, FFMS-D-005490.\n82 FFMS-D-005151; FFMS-D-004989; FFMS-D-005131; FFMS-D-005118; FFMS-D-\n005016; FFMS-D-004350; FFMS-D-005025; FFMS-D-005013; FFMS-D-005509.\n83 FFMS-D-005509; FFMS-D-005483; FFMS-D-005151; FFMS-D-005131; FFMS-D-\n005083; FFMS-D-005021; FFMS-D-005016; FFMS-D-005013; FFMS-D-004995;\nFFMS-D-004979; FFMS-D-004566; FFMS-D-005475.\nbuildings.84 Credible sources indicate that towards the end of 2025, thousands of\npersons apprehended in El Fasher were transferred to Nyala. In Nyala, they were\nreportedly held in the main prison, `Daqris', which was already severely overcrowded\nwith thousands of persons previously captured by the Rapid Support Forces in other\nparts of Sudan and transferred to the same facility.85"},{"id":"a-hrc-62-crp-4-p0070","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"70","seq":69,"section":"2. Detention, torture, humiliation, extortion, ransom and","text":"Thousands of detainees reportedly remain in Nyala. Severe overcrowding,\ninadequate medical care, widespread physical violence, and detention conditions\nincompatible with human dignity, are widely reported to the mission. There is a high\nrisk of disappearances given the lack of legal processes and denial of family and\nlawyers' visits.86 Family members are neither provided with information regarding\nthe fate or whereabouts of their relatives nor granted access to them. The risk of\nenforced disappearance is further heightened by the complete absence of any legal\nprocess, let alone due process. Detainees are reportedly held without any legal basis,\nwith no access to lawyers or judicial review. At the same time, humanitarian actors\nand human rights monitors have been systematically denied access to detention\nfacilities by both parties to the conflict. Some humanitarian workers were themselves\ndetained.87 The lack of independent oversight prevents verification of conditions,\nexacerbates concerns regarding the missing persons and facilitates ongoing\nviolations. It also compounds the suffering of families seeking information about\nmissing relatives."},{"id":"a-hrc-62-crp-4-p0071","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"71","seq":70,"section":"2. Detention, torture, humiliation, extortion, ransom and","text":"The mission has also received additional information regarding the modus\noperandi employed by the Rapid Support Forces when selecting, detaining,\ntransporting or disappearing individuals.88 Survivors described men and boys being\nseparated from women, girls and elderly persons.89 Among men, former government\nemployees, including teachers and doctors, were at heightened risk, often separated\nfrom other captives and not seen again.90"},{"id":"a-hrc-62-crp-4-p0072","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"72","seq":71,"section":"2. Detention, torture, humiliation, extortion, ransom and","text":"The mission has continued to receive information regarding the treatment of\npersons who were detained at the former children's hospital in El Fasher and the\ncontracting of avoidable widespread illnesses. As a result of drinking contaminated\nwater, some detainees contracted cholera which reportedly resulted in multiple deaths\nin custody.91"},{"id":"a-hrc-62-crp-4-p0073","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"73","seq":72,"section":"2. Detention, torture, humiliation, extortion, ransom and","text":"Evidence of what was included in the report regarding extortion, ransom\ndemands and means of payment, including through a Bank app or outreach to family\nmembers on social media, in return for the release of detained persons or return of\nconfiscated items, and the consequences for those who did not pay, is cited here.92"},{"id":"a-hrc-62-crp-4-p0074","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"74","seq":73,"section":"J. Conditions of life calculated to bring about physical destruction","text":"Evidence of what was included in the report regarding conditions imposed in\nand around El Fasher, including deliberate starvation and destruction of the means of\nsurvival of the inhabitants, is cited here.93 The mission continues to receive additional\ninformation regarding the impact on survivors, following the takeover of El Fasher.\nAmongst the main concerns is the high number of people, perhaps - tens of thousands,\nwho remain missing or unaccounted for."},{"id":"a-hrc-62-crp-4-p0075","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"75","seq":74,"section":"J. Conditions of life calculated to bring about physical destruction","text":"Prior to the takeover of El Fasher, the city's population was estimated at\n260,000.94 Following the takeover, the International Organisation for Migration\nestimated that 127,162 individuals (28,044 households) had been displaced from\nlocations in El Fasher town and surrounding villages between 26 October 2025 and\n13 January 2026.95 On 29 October 2025 the International Rescue Committee (IRC)\nstated that, \"despite reports of large numbers of families attempting to flee towards\nTawila, IRC teams on the ground have seen fewer than 5,000 arrive\".96 Most civilians\nfled before, during or immediately after the takeover of El Fasher. Since that initial\nmovement, onward arrivals to locations such as Tawila have been minimal, mostly\ncomprising individuals released after the payment of ransom. Very few, in particular\nof the Zaghawa, Fur and other non-Arab remained in El Fasher after the takeover.97"},{"id":"a-hrc-62-crp-4-p0076","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"76","seq":75,"section":"J. Conditions of life calculated to bring about physical destruction","text":"Organisations that finally managed to access El-Fasher described it as a `ghost\ntown'. On 29 December 2025, the United Nations Resident and Humanitarian\nCoordinator for Sudan mentioned that \"it was not possible to give a precise number\nof those remaining in al-Fashir. Those who United Nations staff did see were living\ninside empty buildings or in rudimentary camps using basic plastic sheets\".98"},{"id":"a-hrc-62-crp-4-p0077","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"77","seq":76,"section":"J. Conditions of life calculated to bring about physical destruction","text":"On 29 January 2026, Doctors Without Borders visited El Fasher. It subsequently\nexpressed that, \"our fears are now growing that most of the civilians who were still\nalive when RSF seized the city have since been killed or displaced\".99 The\norganisation also noted that though \"the visit was too limited to allow us to get more\nthan a glimpse of El Fasher, yet this glimpse was a grim reminder of the sheer scale\nof the destruction that took place in the city as many of its residents were wiped\nout\".100"},{"id":"a-hrc-62-crp-4-p0078","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"78","seq":77,"section":"J. Conditions of life calculated to bring about physical destruction","text":"Evidence of what was included in the report regarding the harm suffered by\nthose who managed to leave El Fasher including reports of severe anxiety,\npsychological trauma, traumatic bereavement, and complicated grief resulting from\nthe violence they experienced and witnessed, and the severe and long-lasting physical\nand psychological consequences of sexual violence, are cited here.101 Access to\n93 FFMS-D-005021; FFMS-D-005020; FFMS-D-005019; FFMS-D-005014; FFMS-D-\n005011; FFMS-D-005010; FFMS-D-005009; FFMS-D-005005; FFMS-D-005002;\nFFMS-D-004997; FFMS-D-004995.\n94 https://news.un.org/en/story/2025/08/1165731; 27 August 2025 (Sudan: `Devastating\ntragedy' for children in El Fasher after 500 days of siege).\n95 DTM Sudan Flash Alert: Al Fasher (Al Fasher town), North Darfur; 02 November\n2025. International Organisation for Migration, Emergency Event Tracking Report |\nDisplacement Tracking Matrix (11 January to 4 May 2026).\n96 https://www.rescue.org/eu/press-release/darfur-irc-warns-civilians-trapped-or-\nfleeing-el-fasher-risk-being-killed-arrivals; 29 October 2025.\n97 FFMS-D-005521.\n98 https://www.reuters.com/world/africa/aid-workers-find-little-life-sudans-al-fashir-\nafter-paramilitary-takeover-2025-12-29/. See also FFMS-D-005065.\n99 https://www.doctorswithoutborders.org/latest/glimpse-ghost-town-el-fasher.\nmental health and psychosocial support remains limited to date, which aggravates and\nprolongs the harm."},{"id":"a-hrc-62-crp-4-p0079","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"79","seq":78,"section":"J. Conditions of life calculated to bring about physical destruction","text":"The mission has also continued to receive information on the impact on\nchildren. Many children arrived in displacement sites on their own or with one parent,\nfamily member or with strangers who picked them up along the way.102 The mission\nfurther notes that conflict embeds harm across generations and where trauma is left\nunaddressed, the legacy of war is not a memory, but renewed vulnerability to future\nviolence. For children, exposure to war, displacement and trauma during critical\nwindows of brain development can alter the foundations of learning, behaviour,\nattachment and long term physical and mental health.103"},{"id":"a-hrc-62-crp-4-p0080","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"80","seq":79,"section":"K. Acts by the leadership of the Rapid Support Forces","text":"The mission has continued to receive information regarding the involvement\nof senior members of the Rapid Support Forces leadership in the events relating to\nthe takeover of El Fasher. Verified video-footage, shared on the official Rapid\nSupport Forces' Telegram channel on 26 October 2025, placed Deputy Commander\nAbdelrahim Hamdan Dagalo at the 6th Infantry Division base in El Fasher giving a\nspeech around 10-11 am in the morning of 26 October 2025 after the Rapid Support\nForces had captured it alongside other key military installations in the city.104 The\nDeputy Commander was also identified in El Fasher two days after the takeover, and\nagain on 4 November 2025, according to verified footage.105"},{"id":"a-hrc-62-crp-4-p0081","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"81","seq":80,"section":"K. Acts by the leadership of the Rapid Support Forces","text":"Citing his \"pivotal role\" in the Rapid Support Forces' military campaign\nlaunched in Darfur by personally supervising operations that led to the killing and\nexecution of civilians, including during the advance on the city of El Fasher, the\nEuropean Union placed the Deputy Commander, Abdelrahim Hamdan Dagalo, on its\nsanctions list in November 2025.106 He was similarly placed on the sanction list of\nthe United Kingdom in December 2025,107 and the United Nations Security Council\nin February 2026, based on, amongst others, footage believed to be of Abdelrahim\nDagalo where he reportedly instructed his troops not to take any prisoners.108"},{"id":"a-hrc-62-crp-4-p0082","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"82","seq":81,"section":"K. Acts by the leadership of the Rapid Support Forces","text":"Evidence of what was included in the report regarding the identification of\nRapid Support Forces commanders issuing orders to kill, detain and loot, with allied\nArab militias operating under the same command structure, are cited in the\nfootnote.109 The presence of commanders at the scene, particularly where they offer\nwords of encouragement or otherwise signal approval while atrocities are being\ncommitted in plain view, may amount to aiding and abetting where such conduct\nprovides moral support with a substantial effect on the crimes.110 At the same time,\ntheir failure to intervene or take reasonable measures to prevent or repress these acts\nmay engage their responsibility under the doctrine of command responsibility.111"},{"id":"a-hrc-62-crp-4-p0083","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"83","seq":82,"section":"A. International Crimes","text":"In light of the overwhelming and consistent body of evidence the mission has\ncollected, the mission finds that serious violations of international humanitarian law\nand human rights amounting to international crimes have been committed by the\nRapid Support Forces in and around El Fasher. The events in and around El Fasher\nduring the prolonged 18-month siege and the subsequent takeover of the city by the\nRapid Support Forces and their allies on 26, 27 and 28 October 2025 should not be\nconsidered in isolation. They were the consolidation and culmination of a widespread\nand systematic pattern of conduct committed in Darfur and other parts of Sudan, since\nthe start of the conflict in mid-April 2023, carried out pursuant to a plan or policy,\nand with clear knowledge and intent."},{"id":"a-hrc-62-crp-4-p0084","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"84","seq":83,"section":"A. International Crimes","text":"The mission recalls the legal conclusions contained in its previous reports in\nwhich it found that the Rapid Support Forces and their allies committed war crimes\nand crimes against humanity, including in and around El Geneina and El Fasher.112\nIts continued investigations into El Fasher and its surroundings, as reflected in this\nconference room paper, confirm its previous findings. The mission recalls in\nparticular its finding of reasonable grounds to believe that the Rapid Support Forces\ncommitted the crime against humanity of persecution on gender, ethnic and political\ngrounds and the war crime of starvation as a method of warfare, which may also\namount to the crime against humanity of extermination.113"},{"id":"a-hrc-62-crp-4-p0085","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"85","seq":84,"section":"1. From starvation to extermination","text":"The mission finds that the Rapid Support Forces and allies committed the war\ncrime of starvation by imposing a prolonged siege of El Fasher and surroundings,\nincluding wilfully impeding relief supplies, accompanied by daily shelling and\ntargeted attacks on medical facilities, shelters, and food production systems that\ndeprived the civilian population of objects indispensable to their survival that would\nreasonably be expected to result in starvation conditions. While not a necessary\nelement to indicate starvation as a war crime, the mission recorded multiple accounts\nRahim Hamdan Dagalo (SDi.008), 24 Feb. 2026. At:\nhttps://main.un.org/securitycouncil/en/content/abdul-rahim-hamdan-dagalo.\nof civilians who died as a result of these starvation conditions.114 It notes that the full\nextent and number of such `slow deaths' has not been documented yet."},{"id":"a-hrc-62-crp-4-p0086","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"86","seq":85,"section":"1. From starvation to extermination","text":"Combined with multiple incidents of large-scale killings of civilians and\npersons hors de combat committed by the Rapid Support Forces during the takeover\nof El Fasher and its surroundings on 26, 27 and 28 October 2025 and thereafter, the\nmission concludes that they also committed the crime against humanity of\nextermination. The mission is guided by the jurisprudence considering extermination\nas the act of killing on a large scale committed as part of a widespread or systematic\nattack against the civilian population.115 It also notes that there is no numerical\nminimum for `large scale'116 and that killings may be committed directly or indirectly\n(`causing death'), including through the commission of rape and other forms of sexual\nviolence as another category of `slow deaths'.117"},{"id":"a-hrc-62-crp-4-p0087","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"87","seq":86,"section":"1. From starvation to extermination","text":"The mission considered in making this determination the overwhelming and\ndirect evidence of systematic and widespread direct and indirect killings of civilians\nand persons hors de combat committed on a large or mass scale and through different\nmeans. This included indiscriminate shootings, point blank executions, torture,\ncausing death by running civilians over with cars or dragging them behind cars\ncausing death, raping and gang-raping women and girls, in some cases resulting in\ntheir deaths or directly followed by their execution. The number of victims in single\nincidents of mass killings documented by the mission ranged from tens to hundreds\n� including men, women and children � and were frequently accompanied by\nstatements or utterances of perpetrators expressing their intent to kill on a mass scale.\nMoreover, individual members of the Rapid Support Forces who refused to follow\norders to kill or rape, or who objected to such acts, received punishment, including\nbeing killed themselves.118"},{"id":"a-hrc-62-crp-4-p0088","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"88","seq":87,"section":"2. Persecution through ethnic targeting","text":"The victims of the above crimes were not randomly chosen. They were\nselected mainly because the Rapid Support Forces perceived them as belonging to a\nparticular collective or group based on their intersecting gender, ethnicity and actual\nor perceived political affiliation to the opposing forces - whose leadership was of the\nsame ethnicity.119 The mission finds that the Rapid Support Forces targeted non-Arab\ncommunities in and around El Fasher, in particular the Zaghawa and Fur, imposing\nrestrictions on movements, and carrying out killings, torture, rape of women and girls,\narbitrary detention and enforced disappearances among other violations of\nfundamental rights with the deliberate intent to discriminate."},{"id":"a-hrc-62-crp-4-p0089","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"89","seq":88,"section":"2. Persecution through ethnic targeting","text":"This was highlighted not only through such acts but also their accompanying\nstatements and utterances labelling non-Arab communities, in particular the\nZaghawa, as slaves and enemies of the Rapid Support Forces interfering with their\nplans to create a new state. The mission inferred as expressions of discriminatory\nintent, among others, that where perpetrators believed fleeing victims to belong to an\nArab tribe they were spared and received assistance, and where they found them to\nbelong to a non-Arab tribe, in particular Zaghawa or Fur, they were subjected to\ninhumane and dehumanizing acts, including killings, torture, and rape. On this basis,\nthe mission confirms its previous finding in the report that the Rapid Support Forces\nand its allies committed the crime of persecution on gender, ethnic and political\ngrounds in and around El Fasher in connection with other crimes under the Rome\nStatute.120"},{"id":"a-hrc-62-crp-4-p0090","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"90","seq":89,"section":"3. The hallmarks of genocide","text":"Given these findings, the mission assessed, in the report, whether the body of\nfacts and evidence could satisfy the legal elements of the crime of genocide, including\nwhether the relevant acts were committed with genocidal intent.121 In answering this\nquestion, the mission considered whether any of the underlying acts of genocide were\ncommitted; whether or not the targeted victims belonged to a protected group; and,\nwhether or not the perpetrators of these acts possessed the special or genocidal intent\n(`dolus specialis') to destroy the protected group in whole or in part. While the crimes\nagainst humanity of extermination, persecution, rape, torture, imprisonment,\nenforced disappearance and other inhumane acts are independently established, the\nscale, nature and cumulative pattern of conduct documented by the mission also\nrequired consideration of whether the conduct crossed the threshold into genocide.\nThe legal analysis that follows therefore addresses, not whether atrocity crimes\noccurred, but whether the specific intent required for genocide can reasonably be\ninferred from the totality of the evidence."},{"id":"a-hrc-62-crp-4-p0091","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"91","seq":90,"section":"3. The hallmarks of genocide","text":"The mission finds that the widespread and systematic pattern of conduct of the\nRapid Support Forces, in particular large-scale killings committed through different\nmeans and methods, mass-scale rape, gang-rape and other forms of torture and cruel\ntreatment, and deliberate starvation conditions including the destruction of means of\nsurvival and denial of medical and humanitarian aid, imposed through the extended\nsiege, was committed pursuant to a plan or policy and with knowledge and intent.\nThis is established through numerous consistent survivor testimonies, utterances and\nstatements made by Rapid Support Forces commanders and fighters whilst\ncommitting atrocities, verified videos and satellite imagery, and warnings issued by\nthe Security Council and others that were ignored. It thus demonstrates that at least\nthree of the material crimes of genocide are overwhelmingly present, namely:\n(i) Killing members of the group;\n(ii) Causing serious bodily or mental harm to members of the group; and\n(iii) Deliberately inflicting conditions of life calculated to bring about\nphysical destruction, in whole or in part."},{"id":"a-hrc-62-crp-4-p0092","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"92","seq":91,"section":"3. The hallmarks of genocide","text":"The mission further considered whether the widespread pattern of sexual\nviolence, forced pregnancy, denial of reproductive healthcare and related harms could\nconstitute measures intended to prevent births within the group within the meaning\nof Article II(d) of the Genocide Convention. While investigations remain ongoing,\nthe available evidence warrants continued examination of this question."},{"id":"a-hrc-62-crp-4-p0093","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"93","seq":92,"section":"3. The hallmarks of genocide","text":"In the mission's assessment, the key constituent elements of the crime of\ngenocide, engaging both individual criminal responsibility and responsibility of\nStates under international law, are present regarding the events described in the report\nand this conference room paper. These include the existence of a protected group, the\ncommission of one or more of the underlying acts enumerated in the Genocide\nConvention and Article 6 of the Rome Statute, and the presence of specific intent to\ndestroy the protected group in whole or in part."},{"id":"a-hrc-62-crp-4-p0094","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"94","seq":93,"section":"3. The hallmarks of genocide","text":"With regard to the existence of protected groups, in the case of The Prosecutor\nv. Omar Hassan Ahmad Al Bashir, the International Criminal Court held that the Fur,\nMasalit, and Zaghawa constitute protected groups based on their ethnicity within the\nmeaning of Article 6 of the Rome Statute concerning the crime of genocide. The\nCourt found these groups to each have their own language, tribal customs, and\ntraditional links to their lands, and to be stable and identifiable, and perceived as such\nby both perpetrators and victims (`self-identification'). The Court considered this as\nthe decisive criterion for determining the existence of a protected group for the\npurposes of genocide.122 The mission concurs with this reasoning based on its factual\nfindings. It found in particular that both victims and perpetrators without hesitation\nidentified themselves and the others based on their distinct ethnicities."},{"id":"a-hrc-62-crp-4-p0095","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"95","seq":94,"section":"3. The hallmarks of genocide","text":"Regarding the material acts, under category I crimes, killings committed on a\nlarge scale and by different means, including pursuing victims along the exit routes\nand roads out of El Fasher to prevent escape and effect further executions. Category\nII crimes include mass rape and gang-rape and other forms of torture and cruel\ntreatment of victims, including acts committed in public buildings, on the roads, and\nin detention centres. While category III crimes concern the deliberate starvation of\nthe civilian population through the siege of El Fasher, including through deprivation\nbelow a minimum standard of housing, hygiene and medical care, and food and water\nfor a prolonged period of time, leading to death and `slow death'.123 All these acts\ntook place despite repeated warnings, issued by the United Nations Security Council\nand other key international and regional entities, to the Rapid Support Forces and\ntheir allies, of impending starvation and other atrocity crimes."},{"id":"a-hrc-62-crp-4-p0096","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"96","seq":95,"section":"3. The hallmarks of genocide","text":"The existence of the dolus specialis or specific intent to destroy the protected\ngroup in whole or in part is a distinct legal element of the crime of genocide. It has\nbeen established through jurisprudence of the international criminal tribunals, that\nrequiring direct statements by perpetrators stating their intent to commit genocide\nwould place the bar at an unattainable high level. Such intent can instead also be\ninferred from the body of evidence as a whole.124 In this regard, based on relevant\njurisprudence, consideration should be given to, among other factors, the general\ncontext, scale of atrocities, systematic targeting of victims � regardless of their status\nas civilian or person hors de combat - on account of their membership in the protected\ngroup, repetition of destructive or discriminatory acts, the existence of a plan or\npolicy, and displays of intent made during public speeches or in meetings.125"},{"id":"a-hrc-62-crp-4-p0097","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"97","seq":96,"section":"3. The hallmarks of genocide","text":"The mission's assessment is based on a careful consideration of all other\npossible explanations regarding intent. It finds that genocidal statements were uttered\nby leaders and commanders of the Rapid Support Forces, including, for example,\nAbdelrahim Dagalo and Abu Lulu.126 It therefore finds that the only reasonable\ninference that can be drawn from the pattern of conduct of the Rapid Support Forces\nin and around El Fasher, including the scale and sequence of events, patterns of\ntargeting, language used by commanders and direct perpetrators stating their intention\nto kill, eliminate, and destroy all Zaghawa and the Fur, and the cumulative impact of\ntheir acts on its victims individually and the protected group collectively, is that they\nacted with genocidal intent. That intent is inferred from the full body of evidence\ncollected by the mission."},{"id":"a-hrc-62-crp-4-p0098","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"98","seq":97,"section":"4. Previous international consideration of genocide allegations in Darfur","text":"The question of genocide has been associated with Sudan for decades. On 18\nSeptember 2004, the Security Council acting under Chapter VII of the Charter of the\nUnited Nations, adopted resolution 1564 (2004) and requested the Secretary-General\nto establish the International Commission of Inquiry on Darfur. Significantly, the\nCouncil expressly included within the Commission's mandate the determination of\nwhether acts of genocide had occurred in Darfur. Paragraph 12 of resolution 1564\nrequested the Commission to immediately \"investigate reports of violations of\ninternational humanitarian law and human rights law in Darfur by all parties, to\ndetermine also whether or not acts of genocide have occurred, and to identify the\nperpetrators of such violations with a view to ensuring that those responsible are held\naccountable.127"},{"id":"a-hrc-62-crp-4-p0099","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"99","seq":98,"section":"4. Previous international consideration of genocide allegations in Darfur","text":"The International Commission of Inquiry submitted its report to the Security\nCouncil on 25 January 2005.128 In section II of its report, the Commission addressed\nthe question of genocide directly. In paragraph 640, it concluded that \"the\nGovernment of the Sudan has not pursued a policy of genocide.\" At the same time,\nhowever, the Commission observed that two constituent elements of genocide could\narguably be deduced from the violations committed by Government forces and\nassociated militias. These were, first, the actus reus consisting of killing, causing\nserious bodily or mental harm, and deliberately inflicting conditions of life calculated\nto bring about physical destruction; and second, the targeting of protected groups by\nthe perpetrators of criminal conduct.129"},{"id":"a-hrc-62-crp-4-p0100","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"100","seq":99,"section":"4. Previous international consideration of genocide allegations in Darfur","text":"The Commission further recognised in paragraph 641 of its report that \"in\nsome instances, individuals, including Government officials, may commit acts with\ngenocidal intent.\" It added that whether this was the case in Darfur was a\ndetermination that would have to be made on a case-by-case basis.130 This careful\nformulation reflected the Commission's distinction between the identification of\ngenocidal acts and the determination of individual criminal responsibility for\ngenocide. It was also consistent with the Commission's principal recommendation\nthat the situation in Darfur be referred by the Security Council to the Prosecutor of\nthe International Criminal Court. The Security Council accepted this\nrecommendation and, acting under Chapter VII of the Charter, referred the situation\nin Darfur since 1 July 2002 to the Prosecutor of the International Criminal Court\nthrough resolution 1593 (2005)."},{"id":"a-hrc-62-crp-4-p0101","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"101","seq":100,"section":"4. Previous international consideration of genocide allegations in Darfur","text":"In 2009, the Prosecutor of the International Criminal Court applied for a\nwarrant of arrest against the then President, Omar Hassan Ahmad Al Bashir,\nincluding on charges of genocide.131 In its decision of 4 March 2009, Pre-Trial\nChamber I declined to include genocide charges, finding that genocidal intent was\nnot the only reasonable conclusion available from the evidence before it at that\nstage.132 On appeal, however, the Appeals Chamber reversed that decision on 3\nFebruary 2010, holding that the Pre-Trial Chamber had applied an excessively\ndemanding standard. The Appeals Chamber clarified that, at the arrest warrant stage,\nthe applicable standard is whether there are reasonable grounds to believe that the\nperson committed the crimes alleged.133"},{"id":"a-hrc-62-crp-4-p0102","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"102","seq":101,"section":"4. Previous international consideration of genocide allegations in Darfur","text":"The mission considers that this jurisprudential and historical context is of\ndirect relevance to the present situation in El Fasher. The legal and factual questions\nthat confronted previous international mechanisms in relation to Darfur continue to\narise today. The mission's findings concerning killings, serious bodily and mental\nharm, the deliberate infliction of conditions of life calculated to bring about physical\ndestruction, and evidence of genocidal intent, demonstrate both continuity with\nearlier patterns of violence in Darfur and an escalation of methods and consequences\ndocumented during the conflict that began in April 2023."},{"id":"a-hrc-62-crp-4-p0103","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"103","seq":102,"section":"5. Obligations of other States","text":"States that render logistical, material, financial or military support to the Rapid\nSupport Forces may also incur responsibility under international law, including under\nthe obligations arising from the Convention on the Prevention and Punishment of the\nCrime of Genocide. Under Article I of the Convention, States undertake not only to\npunish genocide but also to prevent it. The obligation to prevent arises at the instant\na State learns of, or should normally have learned of, the existence of a serious risk\nthat genocide may be committed. It is an obligation of conduct rather than result,\nrequiring States to employ all means reasonably available to them, within their\ncapacity to influence the relevant actors, to prevent the commission of genocide.134"},{"id":"a-hrc-62-crp-4-p0104","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"104","seq":103,"section":"5. Obligations of other States","text":"Where a State possessing the capacity to influence perpetrators continues to\nprovide military, financial, logistical, intelligence or political support despite\nknowledge of a serious risk of genocide, questions may arise concerning compliance\nwith its obligations under Article I of the Convention. Depending on the\ncircumstances, additional questions may arise regarding complicity in genocide under\nArticle III(e) of the Convention. The International Court of Justice distinguished in\nBosnia and Herzegovina v. Serbia and Montenegro between failure to prevent\ngenocide and complicity in genocide, noting that complicity requires positive action\ncontributing to the commission of genocide together with the requisite knowledge of\ngenocidal intent.135 Continued support that substantially facilitates the commission of\ngenocidal acts despite awareness of a serious risk of genocide may therefore engage\nnot only obligations of prevention but also the prohibition of complicity in genocide."},{"id":"a-hrc-62-crp-4-p0105","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"105","seq":104,"section":"5. Obligations of other States","text":"In addition, States providing aid or assistance in the commission of\ninternationally wrongful acts may incur responsibility under Article 16 of the Articles\non Responsibility of States for Internationally Wrongful Acts where they do so with\nknowledge of the circumstances of the wrongful act.136"},{"id":"a-hrc-62-crp-4-p0106","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"106","seq":105,"section":"5. Obligations of other States","text":"While the proceedings instituted by Sudan before the International Court of\nJustice against the United Arab Emirates under the Genocide Convention did not\nproceed because of the reservation entered by the United Arab Emirates to Article IX\nof the Convention concerning the Court's jurisdiction, proceedings against States that\nhave not entered comparable reservations would not necessarily encounter the same\njurisdictional obstacle. In this regard, the dissenting opinion of Judge Abdulqawi\nAhmed Yusuf deserves particular attention for its discussion of the obligations of\nthird States under the Convention and the implications of military and material\nsupport provided in the face of a serious risk of genocide.137"},{"id":"a-hrc-62-crp-4-p0107","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"107","seq":106,"section":"5. Obligations of other States","text":"Pronouncements by United Nations human rights investigative bodies\ncontribute directly to the foreseeability requirement to anticipate serious violations of\ninternational law in the context of protection of civilians. In its previous reports, the\nmission invoked Article 1 in its analysis of the current non-international armed\nconflict, recommending that other States and the international community respect,\nenforce and expand the Security Council arms embargo imposed in Darfur to all\nSudan and halt all material support to the parties, including via private actors and\ntransit routes. In the \"Hallmarks of Genocide\" report, the mission also called for the\nuse of all available diplomatic, political, and preventive tools to halt further mass\nviolence."},{"id":"a-hrc-62-crp-4-p0108","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"108","seq":107,"section":"B. Accountability","text":"Calls for accountability for international crimes committed in the ongoing\nconflict in Sudan, including Darfur, have continuously been issued by relevant actors\nat all levels, including the United Nations Security Council and the African Union\nPeace and Security Council. The mission has put forward a series of\nrecommendations for accountability measures.138"},{"id":"a-hrc-62-crp-4-p0109","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"109","seq":108,"section":"B. Accountability","text":"The accumulated legacy of unaddressed impunity continues to fuel the conflict\nand emboldens perpetrators to commit atrocities without fear of consequences. The\ndirect impact of this has been witnessed in and around El Fasher with perpetrators\nfilming their crimes and showcasing them on social media. Individual criminal\naccountability is essential. Breaking cycles of conflict and preventing further violence\nrequires accountability not only for direct perpetrators and co-perpetrators but also\nfor indirect ones such as institutional actors, economic interests, and business\nnetworks that enable, finance, benefit from, or sustain atrocities and the impunity that\nallows them to recur. This includes intermediaries, commercial entities,\ntransportation networks, arms suppliers, extractive industry actors and other similar\nentities."},{"id":"a-hrc-62-crp-4-p0110","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"110","seq":109,"section":"B. Accountability","text":"The mission has analysed the accountability landscape in its paper \"Paths to\njustice: accountability for atrocities in the Sudan\", and considers that the\nInternational Criminal Court is a key avenue for accountability.139 The Court's\njurisdiction, which is based on United Nations Security Council resolution 1593\n(2005), remains limited to the situation in Darfur since 1 July 2002.140 On 6 October\n2025, the Court issued its first judgment in the Darfur situation finding former\nJanjaweed leader Ali Muhammad Ali Abd-Al-Rahman (nickname Ali Kushayb)\nguilty of 27 counts of war crimes and crimes against humanity, including persecution\non ethnic, gender and political grounds, in relation to attacks carried out against\nmembers of the Fur ethnicity in Darfur, between August 2003 and April 2004.141 The\nOffice of the Prosecutor has confirmed it is investigating alleged crimes committed\nin the ongoing conflict, including the El Fasher and El Geneina incidents.142"},{"id":"a-hrc-62-crp-4-p0111","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"111","seq":110,"section":"B. Accountability","text":"The mission further recalls that under article III(e) of the Convention on the\nPrevention and Punishment of the Crime of Genocide, complicity in genocide\nconstitutes an autonomous international crime giving rise to individual criminal\nresponsibility.143 States, entities and individuals providing military, financial,\nlogistical, intelligence or other forms of support with knowledge of a serious risk that\nsuch support may contribute to genocidal acts may incur responsibility under\ninternational law. The mission encourages states to pursue accountability efforts for\nsuch acts, at the domestic level, pursuant to the universal jurisdiction principle."},{"id":"a-hrc-62-crp-4-p0112","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"112","seq":111,"section":"B. Accountability","text":"The mission is mandated to support accountability efforts inter alia by\nidentifying individuals and entities responsible for violations of international\nhumanitarian law and human rights, or other related crimes, in the Sudan, and\ncooperating with judicial and other entities, as appropriate.144 To this end, its\ninvestigative strategies include the identification of entities and persons of interest in\nrelation to the commission of international crimes with a view to developing\nconfidential lists and dossiers.145 It takes account of the different modes of liability\nrecognized in international criminal law including: direct and indirect, aiding and\nabetting, individual and joint, co-perpetration or contributing to the commission or\nattempted commission of international crimes by a group of persons acting with a\ncommon purpose, as well as command or other superior responsibility that is\ntriggered when commanders or superiors with effective command and control, or\ncontrol fail to prevent or punish crimes committed by their subordinates.146"},{"id":"a-hrc-62-crp-4-p0113","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"113","seq":112,"section":"B. Accountability","text":"The mission continues to cooperate with the International Criminal Court. It\nmay also cooperate with other judicial or related entities, for example at the domestic\nlevel, in the area of accountability, including in relation to regions of Sudan that\ncurrently fall outside of the jurisdiction of the Court. It has developed internal policies\non cooperation to ensure responses are provided in line with its mandate and guiding\nprinciples, including of informed consent, and best practices of the United Nations\nInvestigative Bodies. The mission is of the view that it can best support accountability\nthrough disclosure in concrete investigations and prosecutions before a competent\nand independent judicial body that upholds human rights standards, including fair\ntrial rights."},{"id":"a-hrc-62-crp-4-p0114","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"114","seq":113,"section":"B. Accountability","text":"Finally, the mission underlines that individual criminal responsibility and\nState responsibility for internationally wrongful acts are not mutually exclusive. It\nreiterates that all States are under obligation: to not provide aid or assistance in the\ncommission of internationally wrongful acts under any circumstances, to cooperate\nto end any serious breach involving a gross or systematic failure of another State to\nabide by its obligations, and to pursue accountability. The mission calls for the\nimmediate cessation of aid or assistance in any shape or form, in contravention of\nexisting embargos, including provision of weapons, ammunition and logistical\nsupport to the Rapid Support Forces and its allies, and for interim reparation measures\nto be awarded to victims and survivors.147"},{"id":"a-hrc-62-crp-4-p0115","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"115","seq":114,"section":"IV. Conclusion and Recommendations","text":"The mission reiterates the conclusions and recommendations contained\nin the report \"Hallmarks of Genocide in El-Fasher\" and notes that its continued\ninvestigations have only reinforced the urgency of those findings."},{"id":"a-hrc-62-crp-4-p0116","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"116","seq":115,"section":"IV. Conclusion and Recommendations","text":"The mission further notes that sustained access to medical, psychosocial,\nlivelihood and legal assistance is essential for survivors and affected\ncommunities. The harm caused by the violations documented in and around El\nFasher is profound, cumulative and generational, with consequences that will\nendure long after the immediate violence ends. These are not isolated harms;\nthey form part of systematic attacks on the survival, dignity, social fabric and\nfuture of affected communities. The impact of trauma must therefore be\naddressed in any justice, accountability or transitional justice process, not as a\nsecondary concern but as a central factor in understanding the root causes of\nthe conflict, rebuilding fractured communities and preventing recurrence. The\nprevention of future atrocities requires not only accountability for past crimes,\nbut also investment in healing, recognition, truth, reparations and institutional\ntransformation capable of restoring trust and safeguarding the dignity and\nrights of future generations."},{"id":"a-hrc-62-crp-4-p0117","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"117","seq":116,"section":"IV. Conclusion and Recommendations","text":"The mission reiterates the recommendations contained in the report,\nincluding the urgent need for an immediate cessation of attacks against civilians;\nunhindered humanitarian access and the lifting of restrictions impeding the\ndelivery of food, medicine and essential services; protection of civilians and safe\npassage for those seeking to flee areas of violence; full cooperation with\ninternational and regional accountability mechanisms, including the\nInternational Criminal Court; support for investigations and prosecutions\nunder universal jurisdiction; and measures to prevent further atrocity crimes,\nincluding compliance with and enforcement of the arms embargo on Darfur and\nthe cessation of all forms of support to parties responsible for serious violations\nof international human rights law and international humanitarian law."},{"id":"a-hrc-62-crp-4-p0118","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"118","seq":117,"section":"IV. Conclusion and Recommendations","text":"The mission further reiterates the importance of preserving evidence,\nprotecting victims, survivors and witnesses, and ensuring that accountability\nefforts are complemented by broader processes aimed at truth, reparations,\ninstitutional reform and guarantees of non-recurrence."},{"id":"a-hrc-62-crp-4-p0119","rec_id":"recXQq4WYpTlyv0k3","symbol":"A/HRC/62/CRP.4","n":"119","seq":118,"section":"IV. Conclusion and Recommendations","text":"The obligation to prevent atrocity crimes extends to addressing the\nconditions that allowed such crimes to occur and ensuring that affected\ncommunities can survive, recover and rebuild their lives in dignity and security."},{"id":"a-hrc-63-23-p0001","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"1","seq":0,"section":"I. Mandate, cooperation and protection concerns","text":"This report by the Independent International Fact-Finding Mission for the Sudan\n(\"the mission\") examines the impact of expanded military capabilities, particularly\nlong-range drones, the conduct of hostilities and civilian protection in Sudan and the\nrole of external support in sustaining and prolonging the conflict. It is submitted\npursuant to Human Rights Council resolution 60/3 of 6 October 2025,1 which\nrenewed the mission's mandate and expressed concern at the mission's findings that\nthere are reasonable grounds to believe that both the Sudanese Armed Forces and the\nRapid Support Forces violated international law, amounting to war crimes, and that\nthe Rapid Support Forces also committed crimes against humanity. It condemned all\nforms of external interference, called for an end to material support to both parties,\nand urged all states and entities to respect and enforce the Darfur arms embargo.2"},{"id":"a-hrc-63-23-p0002","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"2","seq":1,"section":"I. Mandate, cooperation and protection concerns","text":"Following its Urgent Debate of 6 July 2026, the Human Rights Council\nrequested the mission to conduct \"an urgent inquiry\" into the situation in and around\nEl-Obeid.3 It encouraged the mission to update the Council on the outcome of the\ninquiry at its sixty-third session and to update the General Assembly at its eighty-first\nsession."},{"id":"a-hrc-63-23-p0003","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"3","seq":2,"section":"I. Mandate, cooperation and protection concerns","text":"In preparing this report, the mission obtained extensive expert advice and first-\nhand accounts from witnesses and survivors and is grateful for their cooperation and\ncourage in sharing their experiences. It carried out two expert consultations on 5 June\n2026 and 17 August 2026 regarding the flow of weapons in Sudan and its impact on\nthe protection of human rights. The mission applied its established methodology and\nthe \"reasonable grounds to believe\" standard of proof, set out in Annex I.4"},{"id":"a-hrc-63-23-p0004","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"4","seq":3,"section":"I. Mandate, cooperation and protection concerns","text":"The mission remains concerned by the deteriorating protection environment and\nthe harassment and intimidation of survivors, experts, victims, witnesses, and others\nperceived as cooperating with documentation and accountability efforts, including\nwith the mission. Stakeholders described fear of surveillance, arrests, reprisals, and\nthreats against journalists, lawyers, and human rights defenders inside and outside\nSudan by both parties. Telecommunications disruptions imposed by the parties and\nlimited connectivity also constrained people in Sudan from connecting with the\noutside world."},{"id":"a-hrc-63-23-p0005","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"5","seq":4,"section":"I. Mandate, cooperation and protection concerns","text":"The mission continued engaging with international and regional entities,\nincluding the Office of the United Nations High Commissioner for Human Rights;\nthe Secretary General's Personal Envoy for the Sudan; the United Nations Special\nAdviser on the Prevention of Genocide; the African Union Special Envoy on the\nPrevention of Genocide and Other Mass Atrocities; the United Nations Working\nGroup on the Use of Mercenaries; the United Nations Panels of Experts on Sudan,\nLibya and South Sudan; and the International Criminal Court."},{"id":"a-hrc-63-23-p0006","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"6","seq":5,"section":"I. Mandate, cooperation and protection concerns","text":"The mission conducted several activities with the African Union Joint Fact-\nFinding Mission on the Human Rights Situation in the Sudan, including a side event\nin Geneva in March 2026 and a joint statement marking the conflict's anniversary on\n13 April 2026. In Banjul, The Gambia, the two missions participated in joint public\nand confidential civil society events on 12�13 May 2026 and issued a Joint\nDeclaration on 12 May 2026.5"},{"id":"a-hrc-63-23-p0007","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"7","seq":6,"section":"I. Mandate, cooperation and protection concerns","text":"The mission also engaged with member states, including Chad, Colombia,\nEthiopia, Libya, Somalia, South Sudan, Panama, and the United Arab Emirates,\n1 A/HRC/RES/60/3, para. 21.\n2 A/HRC/RES/60/3, para. 20.\n3 A/HRC/62/L.48, para. 17.\n4 See A/HRC/60/22; A/HRC/57/23.\n5 Joint Declaration on Sudan - Adopted by the Joint Fact-Finding Mission of the African\nCommission on Human and Peoples' Rights on the Human Rights Situation in the Sudan and\nthe United Nations Independent International Fact-Finding Mission for the Sudan | OHCHR.\nregarding allegations of support to the parties by entities, some of which are registered\nin these states. Chad, Colombia, and the United Arab Emirates provided written and\noral responses, for which the mission is grateful. No substantive response was\nreceived from Ethiopia, Libya, South Sudan or Somalia, while Panama requested\nadditional time to respond."},{"id":"a-hrc-63-23-p0008","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"8","seq":7,"section":"I. Mandate, cooperation and protection concerns","text":"Despite repeated efforts, Sudan continued its lack of cooperation with the\nmission. On 14 June 2026, the mission sent a note verbale to the Government of\nSudan through its Permanent Mission in Geneva, requesting a meeting and reiterating\nits request to visit Sudan. In accordance with standard practice, on 28 August 2026,\nthe mission also shared the final draft of the present report with the Government of\nSudan. No response was received."},{"id":"a-hrc-63-23-p0009","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"9","seq":8,"section":"I. Mandate, cooperation and protection concerns","text":"The mission also sought information from the Rapid Support Forces including\nthrough letters of 18 May and 12 August 2026 requesting meetings with its leadership\nand responses to outstanding and additional questions.6 On 8 June 2026 the Rapid\nSupport Forces proposed a roundtable discussion. The mission confirmed its\nreadiness to engage. No further response was received."},{"id":"a-hrc-63-23-p0010","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"10","seq":9,"section":"II. Legal framework","text":"The applicable legal framework is set out in previous mission reports.7 The\nparties are bound by international human rights law, international humanitarian law,\nincluding Common Article 3 to the Geneva Conventions and Additional Protocol II,\nand customary international law. International criminal law also applies, and the\nsituation in Darfur since 1 July 2002 is subject to the jurisdiction of the International\nCriminal Court."},{"id":"a-hrc-63-23-p0011","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"11","seq":10,"section":"II. Legal framework","text":"Common Article 1 of the Geneva Conventions requires States to respect and\nensure respect for international humanitarian law. Relevant legal frameworks\ngoverning external military support, where applicable, include the Arms Trade Treaty\nand the international and regional conventions on mercenaries, including the United\nNations International Convention Against the Recruitment, Use, Financing and\nTraining of Mercenaries, and the Organization of African Unity Convention for the\nElimination of Mercenarism in Africa."},{"id":"a-hrc-63-23-p0012","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"12","seq":11,"section":"II. Legal framework","text":"The Security Council sanctions regime for Darfur, including the arms embargo\nunder resolutions 1556(2004) and 1591(2005) is binding on all states. Corporations\nand private military and security companies providing military, logistical,\nintelligence, or training support may incur responsibilities under applicable\ninternational and domestic law, while their personnel may incur individual criminal\nresponsibility."},{"id":"a-hrc-63-23-p0013","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"13","seq":12,"section":"II. Legal framework","text":"The mission has identified foreign individuals and entities involved in networks\nproviding weapons, foreign fighters, and other military or logistical support to the\nparties. It publicly names only those designated by the relevant United Nations\nSecurity Council Sanctions Committee. The mission maintains confidential dossiers\non these and other individuals, which may be shared for accountability purposes,\nconsistent with its mandate."},{"id":"a-hrc-63-23-p0014","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"14","seq":13,"section":"II. Legal framework","text":"Accountability efforts continue before the International Criminal Court and in\nseveral domestic jurisdictions.8 The Office of the Prosecutor announced that it is\naccelerating its efforts concerning crimes committed in El Geneina and El-Fasher.9"},{"id":"a-hrc-63-23-p0015","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"15","seq":14,"section":"III. Redefining battlefields: the impact of advanced drone","text":"The use of technological advances, particularly expanded drone capabilities, has\nchanged the nature of the conflict, extending the geographical reach of hostilities and\nprolonging fighting without apparent lull, including during the rainy season."},{"id":"a-hrc-63-23-p0016","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"16","seq":15,"section":"III. Redefining battlefields: the impact of advanced drone","text":"Initially, the Sudanese Armed Forces retained an aerial advantage through\nconventional aircraft and military infrastructure, while the Rapid Support Forces\nrelied primarily on mobile ground forces. By 2025�2026, both parties possessed\nsystems capable of surveillance and attacks across front lines and at considerable\ndistance from their ground forces, ranging from shorter-range multirotor drones to\nreusable fixed-wing systems and one-way attack platforms. Evidence indicates that\nexternally sourced systems, components, personnel and munitions enabled this\nexpansion."},{"id":"a-hrc-63-23-p0017","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"17","seq":16,"section":"III. Redefining battlefields: the impact of advanced drone","text":"Rapid Support Forces' drones were used extensively in operations around El-\nFasher10 and in attacks on Merowe Dam, Port Sudan, Omdurman, Khartoum and El-\nObeid, while the locations were under Sudanese Armed Forces control. Drone\noperations were also documented in Blue Nile. More recently, Sudanese Armed\nForces' aerial operations, including drones, reached locations deep inside Rapid\nSupport Forces-held Darfur, including Ad-Da'ein and Nyala."},{"id":"a-hrc-63-23-p0018","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"18","seq":17,"section":"III. Redefining battlefields: the impact of advanced drone","text":"Aerial attacks, including by drones, on transport routes and essential\ninfrastructure compound the effects of siege or isolation, displacement, and degraded\nessential services. Damage to electricity, fuel, water, transport and health\ninfrastructure extended the consequences beyond the immediate strike site by\ndisrupting interconnected systems on which civilian survival depends."},{"id":"a-hrc-63-23-p0019","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"19","seq":18,"section":"III. Redefining battlefields: the impact of advanced drone","text":"Expanded drone warfare altered the geographical distribution and persistence of\ncivilian exposure to hostilities. The Office of the United Nations High Commissioner\nfor Human Rights documented more than 1,000 civilians killed in drone strikes\nbetween January and May 2026.11 The mission collected evidence and previously\nreported on attacks affecting health facilities, schools, places of worship, markets,\ndisplacement sites, civilian gatherings including weddings and funerals, and energy\ninfrastructure.12"},{"id":"a-hrc-63-23-p0020","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"20","seq":19,"section":"III. Redefining battlefields: the impact of advanced drone","text":"The emblematic cases presented below illustrate these patterns, including\nexpanded geographical reach, successive attacks, and impacts on interconnected\ncivilian infrastructure. They also show how drone operations compounded existing\nvulnerabilities linked to siege and isolation, displacement, restricted movement and\ndegraded essential services. The cases are illustrative rather than exhaustive."},{"id":"a-hrc-63-23-p0021","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"21","seq":20,"section":"1. El-Obeid: infrastructure degradation and interconnected civilian harm","text":"El-Obeid illustrates how repeated drone attacks progressively degraded\nessential infrastructure, in a city already under severe strain and partial siege.\nBetween May and July 2026, attacks damaged or disrupted electricity and fuel\ninfrastructure, affecting water supply, healthcare, transport and other essential\n10 A/HRC/61/77; A/HRC/62/CRP.4.\n11 Deputy High Commissioner Dabo: Sudan cannot be forgotten | OHCHR\n12 A/HRC/60/22, paras. 71-115.\nservices. Successive disruptions compounded one another, reducing the capacity of\nremaining services and infrastructure to compensate."},{"id":"a-hrc-63-23-p0022","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"22","seq":21,"section":"1. El-Obeid: infrastructure degradation and interconnected civilian harm","text":"El-Obeid, capital of North Kordofan and base of the Sudanese Armed Forces'\nFifth Infantry Division, remained under Sudanese Armed Forces control as Rapid\nSupport Forces' pressure intensified in June 2026. Witnesses described near-daily\ndrone attacks affecting military positions, residential areas, fuel supplies, electricity\nand water infrastructure, causing civilian casualties and further disruption to essential\nservices."},{"id":"a-hrc-63-23-p0023","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"23","seq":22,"section":"1. El-Obeid: infrastructure degradation and interconnected civilian harm","text":"Satellite imagery identified damage between 25 May and 25 June to El-Obeid's\nmain electricity substation, numerous fuel stations and the Grand Market assessed as\nconsistent with aerial bombardment. El-Obeid already faced chronic water scarcity,\nwith potable water supply substantially dependent on electrically powered pumping\nand treatment. Witnesses reported that attacks affecting electricity disrupted water\nservices forcing residents to reduce water consumption and increasingly rely on\nrainwater and unsafe sources."},{"id":"a-hrc-63-23-p0024","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"24","seq":23,"section":"1. El-Obeid: infrastructure degradation and interconnected civilian harm","text":"Repeated attacks on fuel stations and tankers disrupted civilian transport and\ncommercial activity and reduced fuel available for generators serving hospitals and\nwater services. The effects therefore extended beyond fuel supply to other essential\nservices. Witnesses described hospitals struggling to sustain oxygen supplies,\ndialysis, blood storage and emergency surgery. Pressure on these services was\ncompounded by displacement into El-Obeid."},{"id":"a-hrc-63-23-p0025","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"25","seq":24,"section":"1. El-Obeid: infrastructure degradation and interconnected civilian harm","text":"The mission documented attacks on tanker-type vehicles. In late June 2026, a\ndrone struck an empty tanker near Dar al-Fikr School. Witnesses described the\nvehicle as stationary and non-functional for years and reported civilian casualties,\nincluding a schoolgirl who later died from a severe head injury."},{"id":"a-hrc-63-23-p0026","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"26","seq":25,"section":"1. El-Obeid: infrastructure degradation and interconnected civilian harm","text":"The mission has reasonable grounds to believe that intensified Rapid Support\nForces drone operations in June 2026 repeatedly affected electricity, fuel and other\ninfrastructure serving El-Obeid, aggravating existing constraints on water, healthcare,\ntransport and civilian movement. Where such infrastructure constituted military\nobjectives, reasonably foreseeable civilian harm resulting from its disruption\nremained relevant to the conduct of the attack, particularly where successive attacks\nand documented consequences made those effects increasingly apparent."},{"id":"a-hrc-63-23-p0027","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"27","seq":26,"section":"2. Kalogi: successive attacks through the casualty-response chain","text":"The Kalogi attacks illustrate how successive drone strikes extended civilian\nharm beyond the initial strike, affecting responders, casualty evacuation and access\nto medical care."},{"id":"a-hrc-63-23-p0028","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"28","seq":27,"section":"2. Kalogi: successive attacks through the casualty-response chain","text":"On 4 December 2025, a drone strike hit Nabaa al-Hanan Kindergarten in Kalogi,\nSouth Kordofan, then under Sudanese Armed Forces control, while young children\nand a teacher were preparing for a school ceremony. Residents and parents gathered\nto assist the injured. Shortly after, a further strike hit the same location or its\nimmediate vicinity, killing and injuring responders."},{"id":"a-hrc-63-23-p0029","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"29","seq":28,"section":"2. Kalogi: successive attacks through the casualty-response chain","text":"Casualties were taken to Kalogi Rural Hospital, approximately 600 metres\naway. A further strike occurred as wounded persons and relatives arrived, close to a\nvehicle transporting wounded persons, killing its driver and occupants. Witnesses\ndescribed severe burns and blast injuries, among the children and responders. The\nattacks killed 114 people, including some 60 children, and injured 35.13 Schools\nremained closed for several months following the attacks, while the hospital ceased\noperating for approximately 45 days because staff and residents feared further strikes."},{"id":"a-hrc-63-23-p0030","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"30","seq":29,"section":"2. Kalogi: successive attacks through the casualty-response chain","text":"Witness accounts and other information available to the mission indicated no\nmilitary use of the kindergarten and no use of the hospital for acts harmful to the\nenemy at the time of the attacks."},{"id":"a-hrc-63-23-p0031","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"31","seq":30,"section":"2. Kalogi: successive attacks through the casualty-response chain","text":"Accordingly, the mission has reasonable grounds to believe that the Rapid\nSupport Forces carried out successive drone attacks striking Nabaa al-Hanan\nKindergarten, civilians responding to the initial strike, and Kalogi Rural Hospital,\nkilling and injuring large numbers of civilians, including children."},{"id":"a-hrc-63-23-p0032","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"32","seq":31,"section":"3. Kulba displacement site, Kadugli: renewed exposure after displacement","text":"By late October 2025, Kadugli, the capital of South Kordofan, remained under\nsiege, with access to food, healthcare and other essential supplies severely\nconstrained. On 31 October, a drone struck the former International Organization for\nMigration premises in Kulba, being used to shelter displaced families. Witnesses\ndescribed fire, damage to nearby houses and multiple civilian casualties. A medical\nworker reported that seven children were injured, five of whom subsequently died.\nAnother witness described a displaced relative whose leg was severed in the attack."},{"id":"a-hrc-63-23-p0033","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"33","seq":32,"section":"3. Kulba displacement site, Kadugli: renewed exposure after displacement","text":"Available information indicated no military use of the premises, with witnesses\nreporting no Sudanese Armed Forces presence at or near the site and the mission\nobtained no information indicating military use at the time of the attack. The mission\ntherefore finds that the premises retained their civilian character at the time of the\nattack."},{"id":"a-hrc-63-23-p0034","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"34","seq":33,"section":"3. Kulba displacement site, Kadugli: renewed exposure after displacement","text":"The mission has reasonable grounds to believe that a Rapid Support Forces\ndrone struck the former International Organization for Migration premises being used\nto shelter displaced families, killing at least five civilians, including children, and\ninjuring others."},{"id":"a-hrc-63-23-p0035","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"35","seq":34,"section":"4. Other attacks affecting civilian concentrations","text":"The mission documented additional Rapid Support Forces-attributed drone\nattacks affecting civilian concentrations and essential infrastructure across Kordofan\nand elsewhere in Sudan, including Omdurman, Khartoum and Blue Nile. In South\nKordofan, attacks occurred amid prolonged siege and isolation in Sudanese Armed\nForces-held Dilling and Kadugli, where access to food, healthcare and humanitarian\nassistance was already severely constrained."},{"id":"a-hrc-63-23-p0036","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"36","seq":35,"section":"4. Other attacks affecting civilian concentrations","text":"In February 2026, drone strikes hit Al-Shartai Health Centre in Kadugli, causing\ncivilian casualties. On 15 January 2026, a drone struck Dilling market, killing at least\n12 civilians and injuring others. The attack occurred while Dilling was under\nprolonged siege, which had severely restricted access to food, fuel, medicines and\nhealthcare. The mission found reasonable grounds to believe that the strike formed\npart of a broader pattern of Rapid Support Forces drone operations affecting civilian\nareas and infrastructure in the city."},{"id":"a-hrc-63-23-p0037","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"37","seq":36,"section":"4. Other attacks affecting civilian concentrations","text":"The mission also received evidence of repeated attacks affecting schools,\nmedical facilities, fuel and water infrastructure, markets and residential areas across\nSouth and North Kordofan, particularly from late 2025 onwards, following the Rapid\nSupport Forces' capture of El Fasher and Babanusa.\nConclusion"},{"id":"a-hrc-63-23-p0038","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"38","seq":37,"section":"4. Other attacks affecting civilian concentrations","text":"The above attacks occurred where civilians were already affected by siege,\nisolation and restricted access to essential services. By extending attacks to civilian\nconcentrations and infrastructure, drone operations deepened existing vulnerabilities\nthrough persistent aerial exposure. Attacks on El Obeid, Omdurman and Khartoum\nNorth in 2026 indicate that these patterns extended beyond Kordofan."},{"id":"a-hrc-63-23-p0039","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"39","seq":38,"section":"1. Ad-Da'ein Teaching Hospital: extended aerial reach and loss of referral","text":"Ad-Da'ein, the capital of East Darfur, lay approximately 400 kilometres from\nareas of active ground fighting in Kordofan. Its teaching hospital served as the\nprincipal public referral facility for more than two million people across East Darfur."},{"id":"a-hrc-63-23-p0040","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"40","seq":39,"section":"1. Ad-Da'ein Teaching Hospital: extended aerial reach and loss of referral","text":"On 20 March 2026, the first day of Eid al-Fitr, successive aerial strikes hit the\nhospital while patients, relatives and medical personnel were present. A medical\nworker placed two strikes approximately a few minutes apart. The first struck the\nemergency area, including the pharmacy, blood bank and laboratory. A further strike\noccurred after responders began assisting the injured, causing additional casualties\nand prompting some to withdraw for fear of further strikes. Witnesses described\nsevere blast injuries, fire and extensive casualties, including bodies identified only by\nclothing or personal effects."},{"id":"a-hrc-63-23-p0041","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"41","seq":40,"section":"1. Ad-Da'ein Teaching Hospital: extended aerial reach and loss of referral","text":"The hospital was rendered non-functional, disrupting emergency, intensive,\nsurgical, maternity, paediatric and other specialised care, removing critical referral\ncapacity from communities already facing severe shortages of functioning health\nfacilities. Patients requiring specialised care subsequently faced travel of more than\n150 kilometres to the next referral hospital."},{"id":"a-hrc-63-23-p0042","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"42","seq":41,"section":"1. Ad-Da'ein Teaching Hospital: extended aerial reach and loss of referral","text":"Satellite imagery identified at least three direct impact points within the hospital\ncomplex and no comparable visible damage to nearby police or government\nbuildings. The mission also examined reports that wounded Rapid Support Forces\nfighters were treated at the hospital and that vehicles were positioned outside. The\nmission obtained no information indicating weapons storage, attacks launched from\nthe hospital or other military use."},{"id":"a-hrc-63-23-p0043","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"43","seq":42,"section":"1. Ad-Da'ein Teaching Hospital: extended aerial reach and loss of referral","text":"Taken together, the evidence provides reasonable grounds to believe that the\nSudanese Armed Forces carried out successive drone strikes on Ad-Da'ein Teaching\nHospital, killing at least 70 people, injuring 146 and rendering the hospital non-\nfunctional. The attack on Ad-Da'ein Teaching Hospital illustrates the expanded reach\nof Sudanese Armed Forces drone operations into Rapid Support Forces-held territory\nand the consequences for major civilian infrastructure."},{"id":"a-hrc-63-23-p0044","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"44","seq":43,"section":"2. Abu Zaima market: civilian commercial activity exposed to drone attack","text":"On 6 June 2026, a munition struck a small metal-roofed shop inside Abu Zaima\nmarket in Hamrat El Sheikh, North Kordofan, where adolescents and young men\nrented and played video games. Witnesses described that civilians had gathered inside\nand around the premises and reported hearing a drone over Abu Zaima for\napproximately 30 minutes before the strike. The shop was destroyed and an adjoining\nbakery damaged. Nine bodies were reportedly recovered at the site, while three\ninjured persons subsequently died. Witnesses reported no armed personnel, positions\nor other apparent Rapid Support Forces' presence in or near the market at the time."},{"id":"a-hrc-63-23-p0045","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"45","seq":44,"section":"2. Abu Zaima market: civilian commercial activity exposed to drone attack","text":"The mission has reasonable grounds to believe that the Sudanese Armed Forces\ncarried out the drone strike on civilian commercial premises in Abu Zaima market\nwhile civilians were present."},{"id":"a-hrc-63-23-p0046","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"46","seq":45,"section":"3. Yabus market: civilian harm and disruption of essential services","text":"Yabus, in southern Blue Nile near the Ethiopian border, was a stronghold of the\nSudan People's Liberation Movement-North al-Hilu and had been subject to repeated\nSudanese Armed Forces' aerial attacks during 2026."},{"id":"a-hrc-63-23-p0047","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"47","seq":46,"section":"3. Yabus market: civilian harm and disruption of essential services","text":"On 29 or 30 March 2026, a drone attack attributed to the Sudanese Armed Forces\nstruck the main market and the nearby water-pump area. Witness testimony and other\ninformation received by the mission, including photographs and video-footage of\nmunition remnants, indicate that at least two munitions struck the densely populated\narea. One struck the main market, extensively damaging shops and market\ninfrastructure, while another struck near the water pump area, killing at least 13\ncivilians and injuring others, including women and children. The attack also damaged\nan adjacent medical facility, while the market remained closed for several weeks,\ndisrupting local commerce and access to services."},{"id":"a-hrc-63-23-p0048","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"48","seq":47,"section":"3. Yabus market: civilian harm and disruption of essential services","text":"On the evidence presently available, the mission has reasonable grounds to\nbelieve that the Sudanese Armed Forces carried out the drone attack on Yabus market\nand the nearby water-pump area, causing civilian casualties and disrupting commerce\nand essential services."},{"id":"a-hrc-63-23-p0049","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"49","seq":48,"section":"4. Other attacks affecting civilian concentrations","text":"The mission documented further drone attacks attributed to the Sudanese Armed\nForces on locations where civilian presence was substantial or readily foreseeable.\nThe cases below are illustrative and summarised briefly."},{"id":"a-hrc-63-23-p0050","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"50","seq":49,"section":"4. Other attacks affecting civilian concentrations","text":"On 8 April 2026, a strike on a wedding gathering in Kutum, North Darfur,\nreportedly killed around 30 civilians. On 27 April, a drone strike on Al-Hamidiya\ndisplacement camp in Zalingei killed at least five civilians and injured 12 others."},{"id":"a-hrc-63-23-p0051","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"51","seq":50,"section":"4. Other attacks affecting civilian concentrations","text":"On 2 August, a drone strike hit a customary court session in Ghara al-Zawiya\nvillage, North Darfur, attended by many civilians, including community leaders,\nelders and minors. A substantial number were killed or injured. Witnesses described\nthe court as a long-standing community dispute-resolution mechanism and reported\nno military activity or military presence at or near the site. Some reports indicated\nthat two individuals described as Rapid Support Forces officers were among those\nkilled; the mission could not independently verify their status. Even if established,\ntheir presence alone would not deprive the gathering of its civilian character or render\nthe court premises a military objective absent evidence of military activity or use.\nConclusion"},{"id":"a-hrc-63-23-p0052","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"52","seq":51,"section":"4. Other attacks affecting civilian concentrations","text":"Taken together, these cases indicate a pattern in which Sudanese Armed Forces'\ndrone operations exposed civilians and civilian infrastructure across multiple regions\nto the effects of aerial attack, causing casualties and disrupting essential services."},{"id":"a-hrc-63-23-p0053","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"53","seq":52,"section":"C. Differentiated impact on women and children","text":"The mission found that drone attacks interacted with pre-existing gender\ninequalities, displacement and barriers to essential services, to produce differentiated\nharms for women and girls. Women and children were repeatedly among those killed\nand injured in drone attacks documented by the mission."},{"id":"a-hrc-63-23-p0054","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"54","seq":53,"section":"1. Impact on maternal health","text":"Drone attacks on health facilities and critical infrastructure disrupted maternal\nhealth services. In El-Obeid, attacks affecting electricity and other infrastructure\nreduced already limited healthcare capacity, while the maternity hospital suspended\noperations after a nearby drone strike damaged operating theatres and the pharmacy.\nHealth personnel described shortages of medicines, qualified staff and specialised\nobstetric services, increasing risks of maternal and neonatal deaths where emergency\ncare, blood products, or emergency surgery were delayed or unavailable."},{"id":"a-hrc-63-23-p0055","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"55","seq":54,"section":"1. Impact on maternal health","text":"Repeated attacks also compounded maternal-health risks by disrupting access\nto obstetric care. Health professionals reported increases in miscarriages, stillbirths\nand pregnancy complications during periods of repeated aerial attack, which they\nassociated with acute stress, restricted movement and delayed access to care."},{"id":"a-hrc-63-23-p0056","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"56","seq":55,"section":"2. Impact on children","text":"Drone attacks had particular consequences for children, both as direct victims\nand through damage to civilian infrastructure necessary for their survival and\ndevelopment. Children were repeatedly among those killed and injured in attacks\nattributed to both parties."},{"id":"a-hrc-63-23-p0057","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"57","seq":56,"section":"2. Impact on children","text":"Attacks affecting hospitals, schools, water systems, and displacement sites also\ndisrupted healthcare, immunization, education, safe water and shelter, while\nprolonged displacement and interrupted schooling heightened protection risks;\nparticularly for girls, including child marriage, exploitation and other forms of\ngender-based harm."},{"id":"a-hrc-63-23-p0058","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"58","seq":57,"section":"D. Conclusion","text":"The mission finds that expanded and diversified drone capabilities altered the\ngeographical reach and civilian consequences of hostilities. Greater range and\noperational persistence, enabled both parties to strike far beyond front lines, reducing\nthe practical protection afforded by distance. Cases investigated by the mission\ndocumented civilians struck in places of residence, refuge, education, markets,\nmedical facilities and community gatherings, including where substantial civilian\npresence was readily foreseeable."},{"id":"a-hrc-63-23-p0059","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"59","seq":58,"section":"D. Conclusion","text":"The consequences extended beyond the point of impact. Fear of further strikes\ndelayed rescue and evacuation in some cases, while severe explosive injuries\noccurred where timely medical care was already constrained. Repeated attacks also\neroded the civilian systems on which survival depended, compounding the effects of\nconflict and deprivation. Drone strikes also caused extensive bodily destruction,\ncomplicating identification and burial of the dead, causing extreme distress to\nsurvivors, relatives and medical personnel."},{"id":"a-hrc-63-23-p0060","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"60","seq":59,"section":"1. Rapid Support Forces","text":"The mission finds reasonable grounds to believe that the Rapid Support Forces\ncarried out the drone strikes documented above, including those affecting El-Obeid,\nNabaa al-Hanan Kindergarten, Kalogi Rural Hospital, and the Kulba displacement\nshelter. It identified no military use that deprived the kindergarten, or displacement\nshelter of their civilian protection or the hospital of its special protection."},{"id":"a-hrc-63-23-p0061","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"61","seq":60,"section":"1. Rapid Support Forces","text":"The mission finds that these attacks failed to comply with obligations of target\nverification and precautions in attack. Where civilian or protected objects were\nthemselves the objects of attack, the attacks also violated distinction. The repeated\nstrikes affecting Kalogi Rural Hospital indicate a failure to respect the special\nprotection afforded to medical units."},{"id":"a-hrc-63-23-p0062","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"62","seq":61,"section":"1. Rapid Support Forces","text":"The mission finds reasonable grounds to believe that the Rapid Support Forces\ncommitted serious violations of international humanitarian law. Directing attacks\nagainst civilian objects, hospitals or educational facilities may amount to war\ncrimes.14"},{"id":"a-hrc-63-23-p0063","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"63","seq":62,"section":"2. Sudanese Armed Forces","text":"The mission finds reasonable grounds to believe that Sudanese Armed Forces\ncarried out the drone strikes documented above affecting Ad-Da'ein Teaching\nHospital, Abu Zaima market, and Yabus market."},{"id":"a-hrc-63-23-p0064","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"64","seq":63,"section":"2. Sudanese Armed Forces","text":"The mission established the civilian character of the affected locations and\nidentified no military objectives at the immediate impact sites. It finds reasonable\ngrounds to believe that the attacks were inconsistent with the principles of distinction\nand precaution."},{"id":"a-hrc-63-23-p0065","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"65","seq":64,"section":"2. Sudanese Armed Forces","text":"The mission finds reasonable grounds to believe that Ad-Da'ein Teaching\nHospital retained its protected status. Treating wounded Rapid Support Forces\nmembers did not remove the protection afforded to the sick and wounded hors de\ncombat under Common Article 3 of the Geneva Convention and Additional Protocol\nII."},{"id":"a-hrc-63-23-p0066","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"66","seq":65,"section":"2. Sudanese Armed Forces","text":"Taken together, these and other documented incidents provide reasonable\ngrounds to believe that Sudanese Armed Forces members committed serious\nviolations of international humanitarian law. Where civilian objects were\nintentionally targeted, such conduct may amount to war crimes."},{"id":"a-hrc-63-23-p0067","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"67","seq":66,"section":"V. Networks that enable the continuation and escalation of","text":"The mission continued to receive information indicating that external actors\nhave helped sustain the conflict through arms and military equipment, financial and\nlogistical support, foreign fighters and other assistance. This support enabled military\noperations during which serious violations of international human rights and\nhumanitarian law were committed, some of which may amount to international\ncrimes. The relationship between external support and military operations is\nparticularly significant in Darfur, including El-Fasher, where the mission found that\nthe Rapid Support Forces and allies displayed hallmarks of genocide, and\nincreasingly in the Kordofan states.15"},{"id":"a-hrc-63-23-p0068","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"68","seq":67,"section":"V. Networks that enable the continuation and escalation of","text":"In resolution 60/3, the Human Rights Council condemned external interference\nfuelling the conflict and reiterated the mission's call to halt material support to both\nparties and for all states and entities to respect and enforce the Darfur arms embargo,\nestablished under Security Council resolution 1556(2004) of 30 July 2004 and\nsubsequent resolutions.16"},{"id":"a-hrc-63-23-p0069","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"69","seq":68,"section":"V. Networks that enable the continuation and escalation of","text":"In this report, the mission focuses on external support to the Rapid Support\nForces. This reflects evidence arising from its investigations into violations and\ninternational crimes associated particularly with the takeover of El-Fasher and the\nsubsequent atrocities. The mission subsequently obtained substantial, converging\ninformation concerning external networks supplying the Rapid Support Forces with\nweapons, advanced military technology, foreign fighters, financing and other forms\nof support. The nature, scale and apparent continuity of this support, and its nexus to\nRapid Support Forces' operations in areas where the mission documented grave\nviolations and international crimes, warranted closer examination of these external\nnetworks and their possible contribution to the commission or facilitation of such\nviolations."},{"id":"a-hrc-63-23-p0070","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"70","seq":69,"section":"V. Networks that enable the continuation and escalation of","text":"The mission is also concerned by increasing information regarding external\nsupport to the Sudanese Armed Forces, including the acquisition and deployment of\nadvanced weapons and technologies capable of materially affecting the conduct of\nhostilities and civilian protection. Such support may engage international human\nrights law, international humanitarian law and international criminal law, including\nwhere external assistance contributes to the commission of violations or international\ncrimes. The mission is therefore expanding its investigations to examine external\nsupport to the Sudanese Armed Forces, including its sources, nature, scale and use.\n15 A/HRC/61/77; A/HRC/62/CRP.4.\n16 A/HRC/RES/60/3, para. 20.\nAt this stage the investigation is at its initial phase and the information below is\nconsequently preliminary."},{"id":"a-hrc-63-23-p0071","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"71","seq":70,"section":"V. Networks that enable the continuation and escalation of","text":"The mission will continue to investigate support to all parties in accordance with\nits mandate and evidentiary standards and will report further where the evidence\npermits."},{"id":"a-hrc-63-23-p0072","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"72","seq":71,"section":"1. External support networks","text":"Evidence verified by the mission, including from witnesses with first-hand\ninformation, provides reasonable grounds to believe that a transnational network\nfacilitated the military operations of the Rapid Support Forces through interconnected\nair, land, and maritime supply routes linking individuals and entities located in the\nUnited Arab Emirates, Chad, southeastern Libya, and Puntland in Somalia."},{"id":"a-hrc-63-23-p0073","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"73","seq":72,"section":"1. External support networks","text":"Evidence indicates that locations in Chad, southeastern Libya and Puntland\n(Somalia) functioned as transit and logistical hubs through which weapons, personnel\nand other military supplies were moved into Rapid Support Forces-controlled areas.\nThe mission also obtained evidence linking individuals and entities based in the\nUnited Arab Emirates to elements of these supply arrangements, as detailed below.\nThis support played an important role in advancing the Rapid Support Forces'\ncapacity to sustain operations in Darfur, Kordofan, and other regions in Sudan, of\nwhich the emblematic cases above are a few examples.17"},{"id":"a-hrc-63-23-p0074","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"74","seq":73,"section":"2. Weapons, drones and logistical support","text":"The mission received credible information indicating that, from at least April\n2025 through and beyond the takeover of El-Fasher, weapons, military equipment\nand other supplies transferred to the Rapid Support Forces included material\nconsistent with equipment previously exported to the United Arab Emirates."},{"id":"a-hrc-63-23-p0075","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"75","seq":74,"section":"2. Weapons, drones and logistical support","text":"Witnesses with first-hand knowledge and other independent sources described\nartillery systems (including \"NORINCO AH-4 155mm howitzers\"), air-defence\nsystems (including \"FK-2000\" systems), radars, armoured vehicles, Land Cruisers,\nuniforms, ammunition, weapons and medical supplies transferred through regional\nroutes involving Bosaso in Puntland (Somalia), Benghazi, Kufra and Jufra (Libya),\nand Chad before reaching Rapid Support Forces-controlled areas. Authenticated\nimagery corroborated these accounts, confirming the presence of NORINCO AH-4\n155mm howitzers among equipment recaptured by the Sudanese Armed Forces after\nretaking of Khartoum, and of FK-2000 systems in Dubeibat on at least 10 February\nand 7 July 2026."},{"id":"a-hrc-63-23-p0076","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"76","seq":75,"section":"2. Weapons, drones and logistical support","text":"Witnesses also informed the mission of drone-related equipment, transferred\nthrough regional routes to the Rapid Support Forces including CH-95 reconnaissance\nand strike drones, electronic warfare capabilities and associated technical support.\nWitnesses with first-hand knowledge described boxes containing weapons and\nammunition being offloaded from aircrafts at Nyala Airport and subsequently\ndistributed to Rapid Support Forces camps."},{"id":"a-hrc-63-23-p0077","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"77","seq":76,"section":"2. Weapons, drones and logistical support","text":"Multiple sources identified Nyala Airport as a principal entry point for supplies\ninto the Rapid Support Forces-controlled territory. The mission also received\ninformation indicating that Rapid Support Forces members supported by Colombian\ncontractors launched drones from Nyala against Sudanese Armed Forces-controlled\nareas, including Kordofan and Khartoum states. The mission further obtained\nevidence of drone command and control stations on Nyala airport runway reportedly\nimported through the same routes and repeatedly targeted by Sudanese Armed Forces\nmissiles between April and July 2025."},{"id":"a-hrc-63-23-p0078","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"78","seq":77,"section":"2. Weapons, drones and logistical support","text":"The mission compared weapons systems identified by witnesses among\nreported imports with authenticated imagery and footage. Several reported systems\nwere consistent with weapons and military equipment documented at Rapid Support\nForces operational sites."},{"id":"a-hrc-63-23-p0079","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"79","seq":78,"section":"2. Weapons, drones and logistical support","text":"The mission verified footage of drone remnant consistent with CH-95/FH-95\nsystems at multiple locations across Sudan, including El-Fasher, Nyala and El-Obeid.\nVerified footage recorded in El-Obeid on 28 February 2026 showed a downed drone\nassessed as an FH-95 on the roof of a civilian house in the city centre. On the same\nday, at least nine people were killed and several others injured in a series of drone\nattacks on El-Obeid. These alleged transfers are significant because they sustained\nthe Rapid Support Forces' capacity to conduct hostilities, while some of the\ncapabilities supplied or supported were used in operations affecting civilians and\ncivilian objects."},{"id":"a-hrc-63-23-p0080","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"80","seq":79,"section":"3. Transit and facilitation","text":"Multiple sources identified locations in Chad as a logistical corridor through\nwhich personnel and supplies moved towards Nyala and other Rapid Support Forces\ncontrolled areas of Darfur. Witnesses with first-hand knowledge described recurring\ncargo flights originating from locations in the United Arab Emirates to Chad and\nonward movement of military supplies and personnel, including foreign contractors,\ninto Rapid Support Forces-controlled areas in Sudan."},{"id":"a-hrc-63-23-p0081","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"81","seq":80,"section":"3. Transit and facilitation","text":"Witnesses, relevant experts, verified video and satellite imagery and other\nevidence identified locations in southeastern Libya, particularly Benghazi, Kufra, and\nJufra, as hubs for foreign personnel, and military supplies destined for the Rapid\nSupport Forces-controlled areas. Benghazi, Kufra and Jufra were described as hubs\nreceiving weapons, vehicles, fuel, food supplies, and military personnel prior to\nonward transfer to Sudan, with support from Libyan National Army Battalions,\nincluding the Subul al Salam Battalion.18"},{"id":"a-hrc-63-23-p0082","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"82","seq":81,"section":"3. Transit and facilitation","text":"The mission also obtained evidence of training facilities in Benghazi and Kufra\nwhere Rapid Support Forces' fighters received specialised technical training in the\noperation and maintenance of weapons, including AK-47 rifles, RPG launchers, and\nDShK heavy machine guns. Foreign trainers including Colombian nationals provided\ntechnical instructions. Training lasted up to three months, after which participants\nwere deployed to Rapid Support Forces' operations in Kordofan, Darfur, and\nelsewhere. Foreign trainers reportedly accompanied groups for at least a month\nfollowing deployment to provide advice."},{"id":"a-hrc-63-23-p0083","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"83","seq":82,"section":"3. Transit and facilitation","text":"Jufra reportedly hosted a military camp where fighters from Sudan, Chad and\nother countries received training for deployment with the Rapid Support Forces. Jufra\nfurther functioned as a transit hub for personnel travelling between Benghazi and\nSudan. Verified open-source material identified Rapid Support Forces' fighters\ntrained in Libya who subsequently participated in the attacks on Zamzam camp in\nApril 2025 and El-Fasher in October 2025."},{"id":"a-hrc-63-23-p0084","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"84","seq":83,"section":"3. Transit and facilitation","text":"The evidence identified Bosaso, Somalia, as a recurring logistical hub and\ntransit point used by external actors to date, including United Arab Emirates-based\nindividuals and entities, for personnel and cargo destined for Rapid Support Forces-\ncontrolled areas. Sources described Ilyushin-76 cargo flights linking Bosaso, Kufra,\nBenghazi, and Chad from which cargo and personnel were subsequently transferred\ninto Sudan. Witnesses further reported that United Arab Emirates-based individuals\n18 See also, Final Report of the UN Panel of Experts on Libya, S/2026/224.\nand entities maintained facilities in Bosaso, including a military base through which\nforeign contractors transited."},{"id":"a-hrc-63-23-p0085","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"85","seq":84,"section":"4. Recruitment of Colombian contractors","text":"From at least August 2024, the recruitment and deployment of foreign\ncontractors, particularly Colombian nationals, formed a significant component of the\ntransnational support network for Rapid Support Forces' operations. Multiple sources\ndescribed a structured system through which former Colombian military personnel\nwere recruited, trained and deployed to support the Rapid Support Forces. Estimates\nof the number of Colombian contractors varied considerably, ranging from 350 to\n2000 individuals. Based on credible independent sources, including information\nindicating that recruitment of Colombian contractors for deployment to Sudan\nremains ongoing, the mission assesses that the total number may approach 2000."},{"id":"a-hrc-63-23-p0086","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"86","seq":85,"section":"4. Recruitment of Colombian contractors","text":"Witness testimony and documentary evidence enabled the mission to identify\nkey entities, inter alia, registered in Colombia and the United Arab Emirates, as being\nlinked to this transnational network, and working closely together in the recruitment\nprocess and subsequent deployment to Sudan of Colombian contractors. The mission\nobtained credible evidence indicating that these entities played a significant role in\nfacilitating recruitment, contracting, transportation and deployment arrangements."},{"id":"a-hrc-63-23-p0087","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"87","seq":86,"section":"4. Recruitment of Colombian contractors","text":"The mission also received information that some contractors were not informed\nat the time of recruitment that they would be deployed to Sudan, while others\nreportedly received lower salaries than stipulated in their contracts."},{"id":"a-hrc-63-23-p0088","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"88","seq":87,"section":"4. Recruitment of Colombian contractors","text":"The founder of one of the key entities, Colonel �lvaro Andr�s Quijano Becerra,\nwas based in Abu Dhabi, while his wife, Ms. Claudia Viviana Oliveros Forero,\ncoordinated recruitment in Colombia. They were both sanctioned by the United\nNations Security Council Committee on 28 April 2026 for their role in recruiting and\ndeploying former Colombian military personnel to Sudan.19"},{"id":"a-hrc-63-23-p0089","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"89","seq":88,"section":"4. Recruitment of Colombian contractors","text":"While Colombia acknowledges the involvement of Colombian entities and\nindividuals in recruiting contractors for deployment to Sudan, the United Arab\nEmirates has disputed any claims that entities and individuals under its jurisdiction\nwere involved."},{"id":"a-hrc-63-23-p0090","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"90","seq":89,"section":"5. Transit routes, training, and operational deployment","text":"Witnesses described multiple routes used to deploy Colombian contractors to\nSudan. Initial groups reportedly went through the United Arab Emirates, Bosaso, and\nBenghazi before crossing southern Libyan desert corridors into Darfur.20 Subsequent\ngroups reportedly also travelled via Bosaso or the United Arab Emirates, transiting\nthrough Chad before entering Sudan via Nyala Airport. Witness testimony indicates\nthat upon arrival in Dubai or Abu Dhabi they were transported to a military-style\nfacility in Ghayathi for about two months of military training by instructors from\ndifferent countries alongside members of the Rapid Support Forces. The training\nreportedly covered drone operations, indirect fire systems, air-defence systems, and\nother advanced weapons systems."},{"id":"a-hrc-63-23-p0091","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"91","seq":90,"section":"6. Role in training, drone operations and advanced weapons systems","text":"Witnesses reported that Colombian contractors played a significant role in\noperating and maintaining surveillance, strike and one-way attack drones, supported\nartillery deployment and other advanced weapon systems, and provided intelligence\nsupport, technical maintenance and military instruction. Many were stationed in\ncamps in and around Nyala, including Nyala Airport, where they operated drones and\nair-defence systems."},{"id":"a-hrc-63-23-p0092","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"92","seq":91,"section":"6. Role in training, drone operations and advanced weapons systems","text":"In some cases, Colombian contractors remained responsible for operating and\nmaintaining drone systems without transferring their operation to Rapid Support\nForces' members. Witnesses indicated that some remained embedded alongside the\nsystems during operations because the necessary technical expertise was not widely\navailable within Rapid Support Forces' ranks. Drone-controllers were reportedly\nrecovered from a building in El-Fasher's Al-Thawra neighbourhood identified as\nhaving been used by Colombian contractors to launch drones."},{"id":"a-hrc-63-23-p0093","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"93","seq":92,"section":"6. Role in training, drone operations and advanced weapons systems","text":"Colombian contractors also reportedly provided specialised training in drones\nand other advanced weapons systems at camps in and around Nyala, and in Kufra and\nBenghazi in southeastern Libya."},{"id":"a-hrc-63-23-p0094","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"94","seq":93,"section":"7. Presence and operational role in El-Fasher","text":"Several sources indicated that Colombian contractors, particularly members of\nthe \"Desert Wolves\" Battalion, were present in and around El-Fasher before, during,\nand after its takeover by the Rapid Support Forces. They were reportedly deployed to\nsupport military operations to seize the city and surrounding areas. Verified open-\nsource material identified Spanish-speaking light-skinned contractors operating\nalongside Rapid Support Forces' units in Darfur during this period. Witness testimony\nindicates that Colombian nationals were captured in the El-Fasher area, before the\ntake-over, in possession of loitering munitions, surveillance drones and armed drones.\nOther sources indicated that Colombian contractors operated artillery systems, drone\nplatforms and other technical equipment during the offensive."},{"id":"a-hrc-63-23-p0095","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"95","seq":94,"section":"8. Other foreign fighters","text":"Witnesses also reported fighters from South Sudan, Chad and Ethiopia,\nincluding women, serving primarily in frontline, rather than technical roles. They\nwere identified in El-Fasher and elsewhere and identified by witnesses on the basis\nof language, accent, and, in some cases uniforms."},{"id":"a-hrc-63-23-p0096","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"96","seq":95,"section":"8. Other foreign fighters","text":"Witness testimony, corroborated by photographic, video and documentary\nevidence, indicates that foreign fighters, drone operators, technicians and military\nspecialists were integrated into Rapid Support Forces operations, particularly in the\nuse and support of advanced weapons systems and other technical capabilities.\nConclusion"},{"id":"a-hrc-63-23-p0097","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"97","seq":96,"section":"8. Other foreign fighters","text":"Viewed collectively, the evidence provides reasonable grounds to believe that\nthe Rapid Support Forces benefited from a transnational support network involving\nweapons and other military material, logistical assistance, training and foreign\npersonnel."},{"id":"a-hrc-63-23-p0098","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"98","seq":97,"section":"8. Other foreign fighters","text":"The mission has reasonable grounds to believe that private companies,\nintermediaries and associated individuals operating across multiple countries,\nincluding Colombia, the United Arab Emirates, Chad, Libya and Somalia, facilitated\nelements of this support network."},{"id":"a-hrc-63-23-p0099","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"99","seq":98,"section":"8. Other foreign fighters","text":"This support sustained Rapid Support Forces' military operations during a\nconflict marked by serious violations of international humanitarian law, international\nhuman rights law, and the commission of international crimes. This was particularly\nclear in El-Fasher."},{"id":"a-hrc-63-23-p0100","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"100","seq":99,"section":"8. Other foreign fighters","text":"The nature, scale and persistence of external support raise serious concerns\nregarding compliance with the Darfur arms embargo and other applicable\ninternational law obligations. They warrant further investigation, including by\ncompetent national authorities, regarding the responsibility of individuals and entities\nthat knowingly provided assistance contributing to international crimes."},{"id":"a-hrc-63-23-p0101","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"101","seq":100,"section":"B. Sudanese Armed Forces","text":"The mission's investigation into external support to the Sudanese Armed\nForces and its impact on respect for international law obligations, remains\npreliminary. Investigations on the origin of these systems, transfer modalities, and the\nentities and states involved, are ongoing."},{"id":"a-hrc-63-23-p0102","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"102","seq":101,"section":"B. Sudanese Armed Forces","text":"Available evidence indicates that, since late 2023, the Sudanese Armed Forces\nhas significantly expanded its drone capabilities through foreign-supplied systems.\nThese capabilities enhanced reconnaissance and precision-strikes capabilities."},{"id":"a-hrc-63-23-p0103","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"103","seq":102,"section":"B. Sudanese Armed Forces","text":"The mission verified open-source imagery and footage of drone strikes and\ndowned drones in Kordofan and Darfur from January 2026 onwards attributed to the\nSudanese Armed Forces. Technical analysis identified features consistent with\nBayraktar Akinci combat drones, including twin-turboprop propulsion components,\ndistinctive propeller assemblies, munition-release mechanisms, and manufacturer\nmarkings on recovered wreckage. Footage from Nyala, South Darfur, on 8 January\n2026, and Al-Farshaya, South Kordofan, on 24 January 2026, was assessed as likely\ndepicting Akinci platforms. As this system is not manufactured in Sudan, its\ndocumented presence indicates the use of foreign-supplied military equipment in\nlong-range precision-strike operations."},{"id":"a-hrc-63-23-p0104","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"104","seq":103,"section":"B. Sudanese Armed Forces","text":"The mission also received images regarding the attack on Yabus Market on 29\nor 30 March 2026, which military experts assessed as depicting components\nconsistent with a Yiha III loitering munition. The same munition type was identified\nin verified open-source footage relating to other incidents attributed to the Sudanese\nArmed Forces, including a strike in Abu Zabad, West Kordofan, on 6 July 2026. This\nfurther indicates Sudanese Armed Forces use of foreign-supplied drones."},{"id":"a-hrc-63-23-p0105","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"105","seq":104,"section":"B. Sudanese Armed Forces","text":"Based on the available information, the mission has reasonable grounds to\nbelieve that the Sudanese Armed Forces used foreign-supplied drones and loitering\nmunitions in attacks that struck civilian objects, including Yabus Market in Blue Nile,\nand may amount to a serious violation of international humanitarian law and a war\ncrime."},{"id":"a-hrc-63-23-p0106","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"106","seq":105,"section":"B. Sudanese Armed Forces","text":"The use of foreign-supplied drones in Darfur, including Nyala, raises concerns\nregarding compliance with applicable arms-transfer obligations and the Darfur arms\nembargo. Continued transfer of weapons, drones, or military assistance therefore\nrequires heightened due diligence. States and entities involved in such transfers\nshould refrain from supplying military materiel where there is a foreseeable risk that\nit could be used to commit or facilitate serious violations of international\nhumanitarian law and ensure full compliance with applicable international\nobligations, including, where applicable, the Arms Trade Treaty."},{"id":"a-hrc-63-23-p0107","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"107","seq":106,"section":"B. Sudanese Armed Forces","text":"The mission is continuing its investigation into this matter."},{"id":"a-hrc-63-23-p0108","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"108","seq":107,"section":"1. Corporate entities and the provision of logistical support and foreign personnel","text":"The United Nations International Convention on Mercenaries and the OAU\nConvention require states parties to prohibit and suppress mercenary activities,\nincluding recruitment, financing, training, organization and support."},{"id":"a-hrc-63-23-p0109","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"109","seq":108,"section":"1. Corporate entities and the provision of logistical support and foreign personnel","text":"The mission found that foreign contractors performed combat-support and\nspecialist functions, while associated companies and intermediaries supplied\nweapons, military materiel, logistical support and technical services. These activities\nsupported the Rapid Support Forces during a period marked by widespread and\npublicly documented violations of international humanitarian law, international\nhuman rights law and international crimes."},{"id":"a-hrc-63-23-p0110","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"110","seq":109,"section":"1. Corporate entities and the provision of logistical support and foreign personnel","text":"Under international law, aiding and abetting entails knowingly providing\npractical assistance, encouragement or moral support that substantially contributes to\nthe commission of a crime.21 The assistance need not be indispensable to the\ncommission of the crimes; it is sufficient that it materially enabled, facilitated,\nsustained or enhanced the capacity of the perpetrators to carry out the criminal\nconduct."},{"id":"a-hrc-63-23-p0111","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"111","seq":110,"section":"1. Corporate entities and the provision of logistical support and foreign personnel","text":"Corporations and private military and security companies supplying arms,\nmilitary services or logistical support in contravention of Security Council resolutions\n1556(2004) and 1591(2005) may be implicated in violations of the applicable\nsanctions regime. Under the United Nations Guiding Principles on Business and\nHuman Rights and the OECD Guidelines for Multinational Enterprises on\nResponsible Business Conduct, businesses operating in conflict-affected\nenvironments are expected to undertake heightened human rights due diligence to\nidentify, prevent, and mitigate adverse impacts linked to their operations and business\nrelationships."},{"id":"a-hrc-63-23-p0112","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"112","seq":111,"section":"1. Corporate entities and the provision of logistical support and foreign personnel","text":"The mission finds reasonable grounds to believe that entities and associated\nindividuals operating across several states were involved in the recruitment,\nfinancing, transportation, training and deployment of foreign fighters and the\nprovision of military supplies, logistical support and technical services to the Rapid\nSupport Forces, materially contributing to that group's operational capabilities. The\nevidence indicates that this support sustained Rapid Support Forces' military\noperations during a period marked by serious violations of international humanitarian\nand human rights law and international crimes."},{"id":"a-hrc-63-23-p0113","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"113","seq":112,"section":"2. Engagement with states","text":"The mission's investigation identified recruitment, financing, contracting,\ntransit and logistical activities supporting the Rapid Support Forces through the\nterritory of several states, including Chad, Colombia, Libya, Somalia, and the United\nArab Emirates. It also identified foreign fighters of Ethiopian and South Sudanese\nnationality. States are required to respect and ensure respect for international\nhumanitarian law in all circumstances. This obligation requires them not only to\nrefrain from contributing to violations, but also to exercise due diligence and take all\nreasonable measures within their power to prevent violations where there is a clear\nrisk that they will be committed, to bring ongoing violations to an end, and to prevent\nfurther violations where they have already occurred. The gravity of the violations,\nand the foreseeable risk of their recurrence has been well documented including in\nthis mission's reports on Sudan since 2024. States must take appropriate measures to\nensure accountability, including, as applicable, by investigating and prosecuting\nindividuals suspected of responsibility."},{"id":"a-hrc-63-23-p0114","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"114","seq":113,"section":"2. Engagement with states","text":"The mission sought information from the states concerned regarding activities\nidentified within or through their territories and summarizes their positions below."},{"id":"a-hrc-63-23-p0115","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"115","seq":114,"section":"3. Position of concerned states","text":"In its response of 16 June 2026 to the mission's request for information of 20\nMay 2026 and during a meeting with the mission on 18 June 2026, Chad reaffirmed\nits commitment to Sudan's sovereignty, international law and strict neutrality in the\nconflict. Chad stated that it had strengthened border surveillance and security\nmeasures to prevent the infiltration of armed elements, recruitment of Chadian\nnationals, and illicit trafficking of weapons, ammunition and other military materiel.\n21 See e.g. Prosecutor v. Furundzija, IT-95-17/1-T, ICTY Trial Chamber, Judgment, 10 December 1998, paras.\n209-249; Prosecutor v. Tadi, IT-94-1-A, ICTY Appeals Chamber, Judgment, 15 July 1999, para. 229;\nProsecutor v. Perisi, IT-04-81-A, ICTY Appeals Chamber, Judgment, 28 February 2013, paras. 26-28; 48.\nIt further stated that it had no knowledge of weapons, drones or military equipment\nbeing transferred through its territory and rejected allegations that its territory or\nfacilities had been used to provide military support to any party to the conflict."},{"id":"a-hrc-63-23-p0116","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"116","seq":115,"section":"3. Position of concerned states","text":"The mission appreciates Chad's cooperation and acknowledges the\nconsiderable humanitarian and security challenges it faces, including the large-scale\narrival of refugees and difficulties monitoring long borders."},{"id":"a-hrc-63-23-p0117","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"117","seq":116,"section":"3. Position of concerned states","text":"Evidence indicates, however, that private actors and transnational networks\nused portions of Chadian territory, particularly remote border areas, for transit and\nlogistical activities. While recognising the security, humanitarian and resource\nconstraints faced by Chad, the mission notes that the use of Chadian territory and\ntransit routes formed part of external support networks benefiting the Rapid Support\nForces. It encourages Chad to fully investigate these concerns, take measures to\nprevent and halt these illicit activities, and continue strengthening border monitoring\nand calls on the international community to assist these efforts.\n(b) Colombia"},{"id":"a-hrc-63-23-p0118","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"118","seq":117,"section":"3. Position of concerned states","text":"In its response of 8 May 2026 to the mission's 21 April 2026 letter requesting\ninformation and during meetings in Geneva of 10 September 2025 and 16 June 2026\nwith his Excellency, late Ambassador to the United Nations in Geneva, Gustavo\nGall�n Giraldo, Colombia reiterated its opposition to mercenarism and concern over\nColombian nationals' participation in foreign armed conflicts, including in Sudan. It\ndescribed measures, including an interinstitutional coordination mechanism\nestablished in June 2025, prevention campaigns and assistance to affected nationals\nand their families. Colombia referred to the March 2026 visit of the United Nations\nWorking Group on the Use of Mercenaries, steps towards accession to the\nInternational Convention on Mercenaries, and efforts to strengthen domestic criminal\nlegislation. It noted that three Colombian nationals had been listed under the United\nNations Security Council's sanctions regime for Sudan and that it was implementing\nthe applicable measures. Colombia further expressed readiness to cooperate with\nSudan through information-sharing, legal cooperation, and dialogue between military\nauthorities to support investigations, accountability, and prevention."},{"id":"a-hrc-63-23-p0119","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"119","seq":118,"section":"3. Position of concerned states","text":"The mission welcomes Colombia's cooperation and measures to address\nmercenary-related activities including efforts to strengthen prevention, regulation,\nand accountability and its stated commitment to criminalize mercenary-related\nactivities under domestic law. At the same time, the evidence indicates that networks\ninvolving Colombian nationals recruited, contracted, transported and deployed\npersonnel to support Rapid Support Forces operations in Sudan, including through\nprivate companies and intermediaries operating across multiple jurisdictions."},{"id":"a-hrc-63-23-p0120","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"120","seq":119,"section":"3. Position of concerned states","text":"The mission found no information indicating that the state of Colombia\ndirected, controlled, supported or endorsed such activities and therefore makes no\nfindings of state responsibility. However, the mission finds reasonable grounds to\nbelieve that private entities and individuals operating from or through Colombia\nparticipated in the recruitment, financing, contracting or deployment of foreign\npersonnel supporting the Rapid Support Forces. The mission encourages Colombia\nto continue investigating such activities and to cooperate with relevant international\naccountability mechanisms.\n(c) United Arab Emirates"},{"id":"a-hrc-63-23-p0121","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"121","seq":120,"section":"3. Position of concerned states","text":"In its responses of 24 February and 19 June 2026 to the mission's request for\ninformation on the alleged supply of weapons and mercenaries through the United\nArab Emirates and with the involvement of entities registered there, and during\nmeetings with the mission on 26 February and 19 June 2026, the United Arab\nEmirates rejected allegations that it provided military, logistical, financial or political\nsupport to the Rapid Support Forces. It maintained that it had remained neutral\nthroughout the conflict, had not supplied arms or ammunition, and had not recruited,\nfinanced or facilitated foreign fighters deployed to Sudan. It further emphasized its\ncommitment to international law, compliance with Security Council resolutions,\nsupport for peace initiatives, and humanitarian assistance to Sudan and neighbouring\ncountries."},{"id":"a-hrc-63-23-p0122","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"122","seq":121,"section":"3. Position of concerned states","text":"The United Arab Emirates maintained that allegations of arms transfers,\nrecruitment of foreign fighters and support to the Rapid Support Forces were\nunfounded and based on unverified or unreliable information. It stated that the 2025\nreport of the United Nations Panel of Experts on Sudan did not establish that the\nUnited Arab Emirates had supplied weapons to the Rapid Support Forces. It also\nstated that it conducted investigations into allegations relating to entities under their\njurisdiction and found no evidence linking such entities to mercenary activities or\nindividuals reportedly deployed in Sudan. The United Arab Emirates maintained that\nthe allegations formed part of what it characterised as a false media campaign led by\nthe Sudanese authorities in Port Sudan."},{"id":"a-hrc-63-23-p0123","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"123","seq":122,"section":"3. Position of concerned states","text":"The United Arab Emirates informed the mission of its legal and regulatory\nframeworks governing arms transfers, private security companies, anti-money\nlaundering, corporate conduct and international crimes. It highlighted the existence\nof domestic legislation criminalising war crimes, crimes against humanity and\ngenocide, including extra-territorially in certain circumstances. It also stated that\ncorporations registered in the country may incur criminal liability for offences\ncommitted by their representatives, directors or agents."},{"id":"a-hrc-63-23-p0124","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"124","seq":123,"section":"3. Position of concerned states","text":"The mission takes note of these submissions and welcomes the United Arab\nEmirates stated commitment to compliance with international law, regulation of\nprivate actors and accountability for unlawful conduct. It also acknowledges the\nhumanitarian assistance provided by the United Arab Emirates."},{"id":"a-hrc-63-23-p0125","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"125","seq":124,"section":"3. Position of concerned states","text":"Based on the totality of the evidence, however, the mission finds that\nindividuals and entities operating from, registered in, or linked to the United Arab\nEmirates played a significant role in networks involved in the recruitment, financing,\ntransportation and deployment of foreign military contractors and the provision of\nmilitary-related support benefiting the Rapid Support Forces."},{"id":"a-hrc-63-23-p0126","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"126","seq":125,"section":"3. Position of concerned states","text":"Given the evidence that some of the activities occurred over an extended\nperiod, concern the activities of entities registered in and involved operations within\nthe jurisdiction of the United Arab Emirates, the mission considers that further and\nstronger measures should be taken by the United Arab Emirates to prevent,\ninvestigate, and halt activities conducted from its territory that are foreseeably\ncapable of contributing to violations of international humanitarian law, international\nhuman rights law, and international crimes in Sudan."},{"id":"a-hrc-63-23-p0127","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"127","seq":126,"section":"3. Position of concerned states","text":"The mission notes the United Arab Emirates stated commitment to preventing\nmisuse of its territory for unlawful purposes and its assertion that robust regulatory\nand enforcement mechanisms are available to address such conduct. The mission\nfurther notes that in April 2026, the United Arab Emirates initiated proceedings\nconcerning alleged transfers of military materiel linked to the conflict in Sudan.\nAlthough those proceedings concern alleged support to the Sudanese Armed Forces\nrather than the Rapid Support Forces, they indicate the availability of domestic\nmechanisms capable of examining comparable conduct."},{"id":"a-hrc-63-23-p0128","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"128","seq":127,"section":"3. Position of concerned states","text":"The mission recommends that the United Arab Emirates investigate\nallegations concerning companies, intermediaries and individuals involved in\nsupplying military material, logistical support, training, financing or foreign\npersonnel to parties to the conflict, in particular the entities and individuals identified\nabove, and, where appropriate, take effective enforcement action.\n(d) Non-responsive states: Ethiopia, Libya, South Sudan and Somalia"},{"id":"a-hrc-63-23-p0129","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"129","seq":128,"section":"3. Position of concerned states","text":"The mission sent requests for information to Ethiopia, Libya, and Somalia on\n11 June 2026, and to Panama and South Sudan on 5 August 2026 but received no\nsubstantive responses. Libya responded on 16 June, stating that the Ambassador was\nunavailable to meet, but did not address the request for information. South Sudan\nresponded informally on 7 August, requesting more time, which was granted, but\nprovided no further response. Panama responded formally and requested a six-weeks\nextension, which was granted. Ethiopia and Somalia did not respond."},{"id":"a-hrc-63-23-p0130","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"130","seq":129,"section":"3. Position of concerned states","text":"The mission encourages the governments of Ethiopia, Libya, Somalia and\nSouth Sudan to engage with it particularly in light of evidence of illicit activities\nstemming from their territory as documented in this report."},{"id":"a-hrc-63-23-p0131","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"131","seq":130,"section":"VI. Conclusions and recommendations","text":"The mission finds that the Sudanese Armed Forces and the Rapid Support\nForces committed serious violations of international human rights law and\ninternational humanitarian law, in the course of drone operations, with some conduct\namounting to war crimes. Expanded range, persistence and increasingly sophisticated\ncapabilities enabled both parties to strike far beyond immediate ground front lines;\nyet greater technical precision did not translate into greater civilian protection. The\nmission documented repeated attacks affecting civilians, civilian objects and\nprotected infrastructure, including hospitals, markets, schools and displacement sites.\nDrone warfare changed where civilians could be reached, eroding the protection\nafforded by distance."},{"id":"a-hrc-63-23-p0132","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"132","seq":131,"section":"VI. Conclusions and recommendations","text":"External support is sustaining these military capabilities. The mission\nidentified a transnational network supplying the Rapid Support Forces with weapons,\nlogistical support, training and foreign personnel, while foreign-supplied drones\nexpanded the Sudanese Armed Forces' long-range strike capability. Continued\ntransfers and support amid well-documented violations raise serious concerns under\ninternational law. The concern is particularly acute where external support sustained\nRapid Support Forces operations in Darfur, including El-Fasher, where the mission\npreviously documented war crimes, crimes against humanity and conduct displaying\nhallmarks of genocide."},{"id":"a-hrc-63-23-p0133","rec_id":"recBkIQQWg1W4lclp","symbol":"A/HRC/63/23","n":"133","seq":132,"section":"VI. Conclusions and recommendations","text":"Despite repeated warnings, drone strikes and broader hostilities continue,\nincluding renewed drone strikes in El-Obeid and escalating violence in Blue Nile.\nThe weapons, financing, personnel and technology that sustain this war must be\nconstrained. The mission therefore calls for urgent action to:\n(a) Protect civilians in drone operations. Parties to the conflict must\nend the fighting, take all feasible precautions particularly where hospitals,\nschools, displacement sites and other concentrations of civilians may be affected.\nInternational mechanisms for the protection of civilians in Sudan must be\nseriously explored.\n(b) Efforts to preserve records relevant to accountability for drone\nstrike attacks on civilians must be supported and encouraged. This includes\npreserving targeting and authorization records, coordinates, imagery, platform\nand munition data, operator logs and post-strike assessments; investigate strikes\ncausing substantial civilian harm; and provide relevant records to independent\ninvestigative and judicial mechanisms.\n(c) Stop military support that risks fueling violations. States must\nenforce the Darfur arms embargo; trace and halt transfers of drones, weapons,\ncomponents, technical assistance and other military support where there is a\nsubstantial risk of their use in serious violations of international humanitarian\nlaw; implement applicable arms-transfer and personnel support obligations;\nstrengthen end-use monitoring and traceability; investigate individuals and\nentities involved in illicit military support to the parties, and impose targeted\nsanctions on those implicated in violations. The Security Council should extend\nthe arms embargo throughout Sudan.\n(d) Support and resource entities, including the UN Panel of Experts\non Sudan that record weapons transfers, military support and drone attacks.\n(e) Support victims. States and civil society should ensure immediate\nassistance to victims of attacks, including emergency care, rehabilitation,\nprosthetics and psychosocial support, without prejudice to their right to\nreparation.\n(f) Pursue accountability across the full chain of responsibility--\nincluding those who commit, order, finance, supply or otherwise facilitate\ninternational crimes--through domestic and international proceedings; support\nuniversal jurisdiction; cooperate fully with the International Criminal Court;\nand support extending its jurisdiction beyond Darfur to the whole of Sudan, and\nthe establishment of a specialized independent judicial mechanism in the form\nof a specialized court for Sudan working in tandem with the Court."}]});